  if(S.cfg==='mix'){ tag('ldis',630,156,co2?'Descarga BT → asp. MT':'Descarga negativa',160,[790,180],[808,230]);
    tag('smt',1228,398,'Aspiración positiva',146,[1228,415],[1200,390]); tag('slt',420,398,'Aspiración negativa',146,[566,415],[595,390]); }
  else { const m2=700+(S.grp[S.top].N-1)*120+40; tag(S.top==='MT'?'smt':'slt',1180,398,S.top==='MT'?'Aspiración positiva':'Aspiración negativa',146,[1180,415],[m2-6,390]); }
  // servicios
