    s+=I.poly([[x+3,y+3,h-7],[x+3,Y-3,h],[x+3,y+3,h+.1]],'#23465f')+I.poly([[x+3,y+3,h-7],[X-3,y+3,h],[x+3,y+3,h+.1]],'#1a3a52');   // paredes interiores
    const cols=['#e86a5a','#7cc4e8','#f3c84b','#9ed36a','#f4f4f0','#c6a2e8','#f0a14b','#5aa9e6'], nx=Math.max(3,Math.round((w-8)/14)), ny=2, pw=(w-8)/nx, pd=(d-8)/ny;
    for(let j=0;j<ny;j++) for(let i=0;i<nx;i++){ const c=cols[(i*3+j*5)%cols.length], ph=[4,5.5,3.5,5][(i+j)%4];
      { const x0=x+4+i*pw+.6, y0=y+4+j*pd+.6, zt=h-6+ph; s+=I.poly([[x0,y0,zt],[x0+pw-1.4,y0,zt],[x0+pw-1.4,y0+pd-1.4,zt],[x0,y0+pd-1.4,zt]],c)+I.poly([[x0,y0+pd-1.4,zt],[x0+pw-1.4,y0+pd-1.4,zt],[x0+pw-1.4,y0+pd-1.4,zt-1.2],[x0,y0+pd-1.4,zt-1.2]],hx(c,.78)); }
      s+=I.poly([[x+4+i*pw+1.4,y+4+j*pd+1.4,h-6+ph+.05],[x+4+i*pw+pw*.55,y+4+j*pd+1.4,h-6+ph+.05],[x+4+i*pw+pw*.55,y+4+j*pd+pd*.45,h-6+ph+.05],[x+4+i*pw+1.4,y+4+j*pd+pd*.45,h-6+ph+.05]],'#ffffff','opacity=".35"'); }  // etiqueta / escarcha
    // marco superior y dos tapas de cristal correderas
    const z=h+.4, rim=['#f4f6f8','#d9dfe4','#c4ccd3'];
