      s+=I.poly([[a+(b-a)*.15,y+2.4,zz],[a+(b-a)*.32,y+2.4,zz],[a+(b-a)*.12,Y-2.4,zz],[a+(b-a)*-.05+0,Y-2.4,zz]].map(p=>[Math.max(a,p[0]),p[1],p[2]]),'#ffffff','opacity=".28"');   // reflejo
