        +I.pipe([[255,43,24],[273,43,24],[273,142,24]],LIQ,4.5,1)+ball(264,43,24);
      s+=rack(I,100,o.acc,{n:o.n||3,scr:o.scr,pre,gauges:gauge(255,80,106)+gauge(262,128,77)});
