function recProbes(){ if(!REC.probes||REC.probes._cfg!==S.cfg+S.tab){ REC.probes=S.svcs.slice(0,4).map(s=>({name:s.name,hi:Math.round(s.SP+5),lo:Math.round(s.SP-5),del:30,en:true,off:0,rec:true})); REC.probes._cfg=S.cfg+S.tab; REC.alarm=[false,false,false,false]; REC.alSince=[null,null,null,null]; REC.alPrev=[false,false,false,false]; REC.ev=[]; REC.ev.push({t:S.t+REC.clkOff,msg:'Registrador en marcha'}); } return REC.probes; }
const fc=v=>(Math.round(v*10)/10).toFixed(1).replace('.',',');
const rClk=()=>S.t+REC.clkOff, rHM=t=>fmtT(t).split('· ')[1];
const rT=i=>{ const s=S.svcs[i], p=recProbes()[i]; return s? s.T+p.off : null; };
function recEv(msg){ REC.ev.unshift({t:rClk(),msg}); if(REC.ev.length>200) REC.ev.pop(); }
function recTick(){ if(!S) return; const P=recProbes();
  P.forEach((p,i)=>{ const s=S.svcs[i]; if(!s) return; const T=rT(i); const out=p.en&&(T>p.hi||T<p.lo);
    if(out){ REC.alSince[i]=REC.alSince[i]??S.t; if(!REC.alarm[i]&&S.t-REC.alSince[i]>=p.del*60){ REC.alarm[i]=true; REC.ack=false; logA('bad',`Registrador: alarma ${T>p.hi?'alta':'baja'} en T${i+1} (${p.name}).`); } }
    else { REC.alSince[i]=null; REC.alarm[i]=false; }
    if(REC.alarm[i]!==REC.alPrev[i]){ recEv(REC.alarm[i]?`Alarma T${i+1} ${fc(T)}°C`:`Fin alarma T${i+1}`); REC.alPrev[i]=REC.alarm[i]; } });
  // entradas digitales de puerta (DI1 = mueble de T1, DI2 = mueble de T2)
  REC.din.forEach((d,k)=>{ const s=S.svcs[k]; const open=!!(s&&s.door&&d.en);
    if(open!==REC.dPrev[k]){ recEv(`DI${k+1} puerta ${open?'abierta':'cerrada'}`); REC.dPrev[k]=open; }
    if(open){ REC.dSince[k]=REC.dSince[k]??S.t; if(!REC.dAl[k]&&S.t-REC.dSince[k]>=REC.dDel*60){ REC.dAl[k]=true; REC.ack=false; recEv(`Alarma puerta DI${k+1}`); logA('bad',`Registrador: alarma de puerta abierta (DI${k+1}, ${P[k].name}).`); } }
    else { REC.dSince[k]=null; REC.dAl[k]=false; } });
  const anyAl=REC.alarm.some(x=>x)||REC.dAl.some(x=>x); REC.relay=REC.rel.en&&anyAl; if(!anyAl) REC.ack=false; }
function recAny(){ return REC.alarm.some(x=>x)||REC.dAl.some(x=>x); }
function recMenus(){ const P=recProbes(), a=REC.arg|0, p=P[a]||P[0];
  const yn=b=>b?'Sí':'No';
  return {
    menu:{title:'MENÚ',items:[{l:'Consultar registros',go:'qlist'},{l:'Imprimir informe',go:'print'},{l:'Alarmas',go:'alist'},{l:'Eventos',go:'evlist'},{l:'Configuración',go:'conf',lock:true},{l:'Información',go:'info'}]},
    qlist:{title:'CONSULTAR',items:P.map((p,i)=>({l:`T${i+1} ${p.name}`,go:'graph',arg:i}))},
    alist:{title:'ALARMAS',items:P.map((p,i)=>({l:`T${i+1} ${p.name}`,go:'aprobe',arg:i}))},
    aprobe:{title:`ALARMA T${a+1}`,right:p.name.slice(0,12),items:[{l:'Máxima',v:()=>fc(p.hi)+' °C',ed:d=>{ p.hi+=d; }},{l:'Mínima',v:()=>fc(p.lo)+' °C',ed:d=>{ p.lo+=d; }},{l:'Retardo',v:()=>p.del+' min',ed:d=>{ p.del=Math.max(0,p.del+d*5); }},{l:'Alarma activa',v:()=>yn(p.en),ed:()=>{ p.en=!p.en; }}]},
    print:{title:'IMPRIMIR',items:[{l:'Lectura actual',pr:'now'},{l:'Últimas 8 horas',pr:'8h'},{l:'Entre dos horas…',go:'range'},{l:'Informe de alarmas',pr:'al'},{l:'Informe de eventos',pr:'ev'}]},
    range:{title:'ENTRE HORAS',items:[{l:'Desde',v:()=>rHM(rClk()+REC.rng.from*3600),ed:d=>{ REC.rng.from=Math.max(-8,Math.min(REC.rng.to-1,REC.rng.from+d)); }},{l:'Hasta',v:()=>rHM(rClk()+REC.rng.to*3600),ed:d=>{ REC.rng.to=Math.max(REC.rng.from+1,Math.min(0,REC.rng.to+d)); }},{l:'Imprimir',pr:'rng'}]},
    conf:{title:'CONFIGURACIÓN',items:[{l:'Intervalo de registro',v:()=>REC.interval+' min',ed:d=>{ const L=[1,2,5,10,15,30,60]; let k=L.indexOf(REC.interval); k=Math.max(0,Math.min(L.length-1,k+d)); REC.interval=L[k]; }},
      {l:'Hora del reloj',v:()=>rHM(rClk()),ed:d=>{ REC.clkOff+=d*600; }},
      {l:'Sondas',go:'plist'},{l:'Entradas de puerta',go:'din'},{l:'Relé de alarma',go:'relay'},{l:'Descargar a USB',go:'usb'},{l:'Wi-Fi',v:()=>'Conectado'}]},
    plist:{title:'SONDAS',items:P.map((p,i)=>({l:`T${i+1} ${p.name}`,go:'pconf',arg:i}))},
    pconf:{title:`SONDA T${a+1}`,items:[{l:'Nombre',v:()=>p.name.slice(0,12),nm:true},{l:'Calibración',v:()=>(p.off>=0?'+':'')+fc(p.off)+' K',ed:d=>{ p.off=Math.round((p.off+d*0.1)*10)/10; p.off=Math.max(-5,Math.min(5,p.off)); }},{l:'Registrar',v:()=>yn(p.rec),ed:()=>{ p.rec=!p.rec; }}]},
    din:{title:'ENTRADAS PUERTA',items:[{l:`DI1 (${P[0].name.slice(0,10)})`,v:()=>yn(REC.din[0].en),ed:()=>{ REC.din[0].en=!REC.din[0].en; }},{l:`DI2 (${P[1].name.slice(0,10)})`,v:()=>yn(REC.din[1].en),ed:()=>{ REC.din[1].en=!REC.din[1].en; }},{l:'Retardo alarma',v:()=>REC.dDel+' min',ed:d=>{ REC.dDel=Math.max(0,Math.min(60,REC.dDel+d)); }}]},
    relay:{title:'RELÉ DE ALARMA',items:[{l:'Relé de alarma',v:()=>yn(REC.rel.en),ed:()=>{ REC.rel.en=!REC.rel.en; }},{l:'Zumbador',v:()=>yn(REC.rel.buz),ed:()=>{ REC.rel.buz=!REC.rel.buz; }},{l:'Estado del relé',v:()=>REC.relay?'ACTIVADO':'reposo'}]},
    usb:{title:'USB',items:[{l:'Datos en Excel (CSV)',act:()=>recUsb('MR4_DATOS.CSV')},{l:'Informe en PDF',act:()=>recUsb('MR4_INFORME.PDF')},{l:'Eventos (CSV)',act:()=>recUsb('MR4_EVENTOS.CSV')}]},
    evlist:{title:'EVENTOS',list:true},
  }; }
function recUsb(f){ REC.usb=tNow()+2500; REC.usbTxt=f; recEv(`USB: ${f}`); logA('ok',`Registrador: datos copiados al USB (${f}).`); }
const SNAP=()=>JSON.stringify({i:REC.interval,c:REC.clkOff,p:REC.probes.map(p=>({...p})),d:REC.din,dd:REC.dDel,r:REC.rel,g:REC.rng});
function SNAPR(j){ const o=JSON.parse(j); REC.interval=o.i; REC.clkOff=o.c; o.p.forEach((x,k)=>Object.assign(REC.probes[k],x)); REC.din=o.d; REC.dDel=o.dd; REC.rel=o.r; REC.rng=o.g; }
function recScreen(){ const P=recProbes(), m=recMenus(); const sc=REC.scr; const rows=[]; let title='', right='';
  if(sc==='main'){ return {main:true}; }
  if(sc==='evlist'){ title='EVENTOS'; right=`${REC.ev.length}`; const st=Math.min(REC.cur,Math.max(0,REC.ev.length-7)); REC.ev.slice(st,st+7).forEach(e=>rows.push({t:`${rHM(e.t)} ${e.msg}`.slice(0,34),v:''})); if(!REC.ev.length) rows.push({t:'Sin eventos',v:''}); return {title,right,rows,hint:'▲▼ desplazar · ESC volver'}; }
  if(sc==='pw'){ return {pw:true}; }
  if(sc==='name'){ return {name:true}; }
  if(m[sc]){ const M=m[sc]; title=M.title; right=M.right||`${REC.cur+1}/${M.items.length}`; M.items.forEach((it,k)=>rows.push({t:it.l,v:it.v?it.v():'',sel:k===REC.cur,ed:REC.edit&&k===REC.cur})); }
  if(sc==='info'){ title='INFORMACIÓN'; [['Modelo','MR-4'],['Norma','EN 12830'],['Clase','0,5'],['Sondas','4 + 2 entradas'],['Intervalo',REC.interval+' min'],['Alimentación',REC.mains?'Red':'Batería'],['Memoria',Math.min(99,12+Math.floor(S.hist.length/40))+' %']].forEach(([l,v])=>rows.push({t:l,v})); }
  if(sc==='graph'){ title=`T${REC.arg+1} ${P[REC.arg].name}`; right='8 h'; }
  return {title,right,rows,graph:sc==='graph'}; }
