function recPrint(kind){ const P=recProbes(); const L=[]; const now=fmtT(rClk());
  const names={now:'LECTURA ACTUAL','8h':'ÚLTIMAS 8 HORAS',al:'ALARMAS',ev:'EVENTOS',rng:'ENTRE HORAS'};
  L.push('================================','     MR-4  REGISTRADOR TEMP.','       Certificado EN 12830','================================',
    `Fecha: ${now}`, `Informe: ${names[kind]}`, `Intervalo: ${REC.interval} min`,'--------------------------------');
  const stats=(i,t0,t1)=>{ const off=P[i].off; const v=S.hist.filter(h=>{ const t=h.t+REC.clkOff; return t>=t0&&t<=t1; }).map(h=>h.T[i]+off); if(t1>=rClk()-60) v.push(rT(i)); if(!v.length) return null; return {mn:Math.min(...v),mx:Math.max(...v),av:v.reduce((a,b)=>a+b,0)/v.length,n:v.length}; };
  if(kind==='now') P.forEach((p,i)=>L.push(`T${i+1} ${p.name.slice(0,18).padEnd(18)} ${fc(rT(i)).padStart(6)}°C`));
  else if(kind==='8h'||kind==='rng'){ const t0=kind==='8h'?rClk()-8*3600:rClk()+REC.rng.from*3600, t1=kind==='8h'?rClk():rClk()+REC.rng.to*3600;
    if(kind==='rng') L.push(`Desde ${rHM(t0)} hasta ${rHM(t1)}`);
    P.forEach((p,i)=>{ if(!p.rec){ L.push(`T${i+1} ${p.name}: no registra`); return; } const s=stats(i,t0,t1); if(!s){ L.push(`T${i+1} ${p.name}: sin datos`); return; }
      L.push(`T${i+1} ${p.name}`,`  mín ${fc(s.mn)}  máx ${fc(s.mx)}  med ${fc(s.av)}`,`  límites ${fc(p.lo)} / ${fc(p.hi)} °C`); }); }
  else if(kind==='ev'){ if(!REC.ev.length) L.push('Sin eventos.'); else REC.ev.slice(0,14).forEach(e=>L.push(`${rHM(e.t)} ${e.msg}`)); }
  else { const al=REC.ev.filter(e=>/Alarma|Fin alarma/.test(e.msg)); if(!al.length) L.push('Sin alarmas registradas.'); else al.slice(0,12).forEach(e=>L.push(`${rHM(e.t)} ${e.msg}`)); }
  L.push('--------------------------------','Firma: ______________________','','');
  REC.ticket=L; REC.printing=tNow()+L.length*140; REC.printShown=0; recEv(`Impreso: ${names[kind].toLowerCase()}`); logA('ok',`Registrador: informe impreso (${names[kind].toLowerCase()}).`); }
function recTicketRender(){ const t=$('rTicket'); if(!t) return; if(!REC.ticket.length){ t.hidden=true; return; } t.hidden=false;
  const n= REC.printing>tNow()? Math.max(1,REC.ticket.length-Math.ceil((REC.printing-tNow())/140)) : REC.ticket.length;
  if(t._n!==n){ t._n=n; t.querySelector('pre').textContent=REC.ticket.slice(0,n).join('\n'); } }
// teclas
function recKey(k){ const m=recMenus(); const sc=REC.scr; const P=recProbes();
  const go=(s,arg)=>{ REC.stack.push({scr:REC.scr,cur:REC.cur,arg:REC.arg}); REC.scr=s; REC.cur=0; if(arg!==undefined) REC.arg=arg; REC.edit=false; };
  const back=()=>{ if(REC.edit){ REC.edit=false; if(REC.old) SNAPR(REC.old); REC.old=null; return; } const p=REC.stack.pop(); if(p){ REC.scr=p.scr; REC.cur=p.cur; REC.arg=p.arg; } else REC.scr='main'; };
  if(k==='home'){ if(REC.edit&&REC.old) SNAPR(REC.old); REC.scr='main'; REC.stack=[]; REC.edit=false; REC.old=null; }
  else if(sc==='pw'){ const W=REC.pwd;
    if(k==='up'||k==='down'){ W.dg[W.d]=(W.dg[W.d]+(k==='up'?1:9))%10; }
    else if(k==='ok'){ if(W.d<3) W.d++; else { const v=+W.dg.join(''); if(v===REC.pw){ REC.pwOk=tNow()+10*60000; REC.scr=REC.pwNext; REC.cur=0; recEv('Acceso a configuración'); } else { REC.pwBad=tNow()+2500; W.d=0; W.dg=[0,0,0,0]; } } }
    else if(k==='esc'){ back(); } }
  else if(sc==='name'){ const n=REC.nm;
    if(k==='up'||k==='down'){ const c=NM_CH.indexOf(n.buf[n.pos]); n.buf[n.pos]=NM_CH[(c+(k==='up'?1:-1)+NM_CH.length)%NM_CH.length]; }
    else if(k==='ok'){ if(n.pos<n.buf.length-1) n.pos++; else { const nm=n.buf.join('').trim(); if(nm){ const p=P[n.i]; recEv(`T${n.i+1} renombrada`); p.name=nm.charAt(0)+nm.slice(1).toLowerCase(); } back(); } }
    else if(k==='esc'){ if(n.pos>0) n.pos--; else back(); } }
  else if(k==='esc'){ if(sc==='main'){ if(recAny()) REC.ack=true; } else back(); }
  else if(k==='print'){ if(sc==='print'&&m.print.items[REC.cur].pr){ recPrint(m.print.items[REC.cur].pr); } else if(sc==='range'){ recPrint('rng'); } else { REC.scr='main'; REC.stack=[]; go('print'); } }
  else if(k==='up'||k==='down'){ const d=k==='up'?1:-1;
    if(sc==='graph'){ REC.arg=(REC.arg+(d>0?3:1))%4; }
    else if(sc==='evlist'){ REC.cur=Math.max(0,Math.min(Math.max(0,REC.ev.length-7),REC.cur+(d>0?-1:1))); }
    else if(REC.edit){ const it=m[sc]&&m[sc].items[REC.cur]; it&&it.ed&&it.ed(d); }
    else { const n= m[sc]? m[sc].items.length : 0; if(n) REC.cur=(REC.cur+(d>0?-1:1)+n)%n; } }
  else if(k==='ok'){
    if(sc==='main') go('menu');
    else if(m[sc]&&m[sc].items){ const it=m[sc].items[REC.cur];
      if(it.go){ if(it.lock&&REC.pwOk<tNow()){ go('pw'); REC.pwNext=it.go; REC.pwd={d:0,dg:[0,0,0,0]}; } else go(it.go,it.arg); }
      else if(it.pr) recPrint(it.pr); else if(it.act) it.act();
      else if(it.nm){ const p=P[REC.arg|0]; const b=p.name.toUpperCase().slice(0,18).padEnd(18).split('').map(c=>NM_CH.includes(c)?c:' '); go('name'); REC.nm={i:REC.arg|0,buf:b,pos:0}; }
      else if(it.ed){ if(REC.edit){ REC.edit=false; REC.old=null; recEv(`Cambio: ${it.l}`); } else { REC.old=SNAP(); REC.edit=true; } } } }
  recRender(); }
function recPower(){ REC.mains=!REC.mains; if(!REC.mains){ REC.mainsOff=S.t; recEv('Fallo de alimentación'); logA('warn','Registrador: corte de corriente, sigue registrando con la batería.'); }
  else { const m=Math.round((S.t-REC.mainsOff)/60); recEv(`Alimentación OK (${m} min)`); logA('ok',`Registrador: vuelve la corriente (corte de ${m} min).`); } recRender(); }
function recInit(){ [['rEsc','esc'],['rUp','up'],['rOk','ok'],['rDn','down'],['rPrint','print'],['rHome','home']].forEach(([id,k])=>{ const b=$(id); if(b) b.addEventListener('click',()=>recKey(k)); });
  const x=$('rTicketClose'); if(x) x.addEventListener('click',()=>{ REC.ticket=[]; recTicketRender(); });
  const pw=$('rPower'); if(pw) pw.addEventListener('click',recPower); }

// ================= cuadro de cámara CR-5 (controlador de cámara frigorífica con doble pantalla) =================
const CRX=[ // parámetros propios del cuadro (además de los del termostato)
  ['dCt','Programación de desescarches: 0 = cada IdF horas · 1 = por horario (Ld1–Ld4)','',0,1,1,'dEF',0],
  ['Ld1','Hora del desescarche 1 (24 = sin usar)','h',0,24,1,'rtC',0],
  ['Ld2','Hora del desescarche 2 (24 = sin usar)','h',0,24,1,'rtC',0],
  ['Ld3','Hora del desescarche 3 (24 = sin usar)','h',0,24,1,'rtC',0],
  ['Ld4','Hora del desescarche 4 (24 = sin usar)','h',0,24,1,'rtC',0],
  ['bUz','Zumbador de alarma: 0 = no · 1 = sí','',0,1,1,'AL',0],
  ['HAC','Registro HACCP de alarmas de alta: 0 = no · 1 = sí','',0,1,1,'AL',0],
  ['dS2','Pantalla pequeña: 0 = sonda evaporador · 1 = consigna · 2 = hora · 3 = apagada','',0,3,1,'diS',1],
  ['AUt','Salida AUX: 0 = manual (tecla AUX) · 1 = resistencia del marco de puerta · 2 = relé de alarma','',0,2,1,'CnF',0],
];
const CRDEF={dCt:0,Ld1:2,Ld2:8,Ld3:14,Ld4:20,bUz:1,HAC:1,dS2:0,AUt:0};
const CRPAR=PAR.concat(CRX);
const CRFOLD=['CP','dEF','FAn','AL','diS','CnF','rtC','Add','FPr'];
const CRFOLDN=Object.assign({},TFOLDN,{rtC:'Reloj y horario de desescarches'});
const CR={idx:0,cfg:'',tm:'run',ml:'usr',ti:0,si:0,hi:0,pk:0,old:0,pw:0,until:0,msg:null,msgUntil:0,clkOff:0,ce:0,
  sos:false,mute:false,aux:false,haccp:[],haLast:null,pwrOff:0};
const crS=()=>S.svcs[CR.idx];
function crSync(){ if(!S) return; if(CR.st===S) return; CR.st=S;
  let i=S.svcs.findIndex(s=>/^Cámara/.test(s.name)&&s.g==='LT'); if(i<0) i=S.svcs.findIndex(s=>/^Cámara/.test(s.name)); CR.idx=Math.max(0,i);
  S.svcs.forEach(s=>{ for(const k in CRDEF) if(s.p[k]===undefined) s.p[k]=CRDEF[k]; });
  CR.haccp=[]; CR.haLast=null; CR.sos=false; CR.mute=false; CR.aux=false; CR.tm='run'; }
const crClk=()=>S.t+CR.clkOff;
const crHM=t=>{ const d=((t%86400)+86400)%86400; return [Math.floor(d/3600),Math.floor(d%3600/60)]; };
function crAl(){ const s=crS(), a=tAl(s); if(CR.sos) a.unshift('SOS'); return a; }
// lógica del cuadro (se llama en cada paso de simulación)
function coldStep(dt){ crSync(); const s=crS(); if(!s) return; const p=s.p;
  // desescarches por horario
  if(p.dCt===1 && !s.def){ const now=crClk(); let best=Infinity;
    ['Ld1','Ld2','Ld3','Ld4'].forEach(k=>{ const h=p[k]; if(h>=24) return; const day=Math.floor(now/86400)*86400; let t=day+h*3600; if(t<=now-1) t+=86400; best=Math.min(best,t); });
    if(best<Infinity) s.next=best-CR.clkOff; }
  // registro HACCP (alarmas de alta)
  if(p.HAC){ if(s.alarm==='HA'){ if(!CR.haLast){ CR.haLast={t0:crClk(),Tmax:s.Tm,dur:0}; CR.haccp.unshift(CR.haLast); if(CR.haccp.length>9) CR.haccp.pop(); }
      CR.haLast.Tmax=Math.max(CR.haLast.Tmax,s.Tm); CR.haLast.dur=Math.round((crClk()-CR.haLast.t0)/60); }
    else CR.haLast=null; }
  // salida AUX
  const anyAl=crAl().length>0;
  if(p.AUt===1) CR.aux=!s.off; else if(p.AUt===2) CR.aux=anyAl;
  if(!anyAl) CR.mute=false; }
function crBuzz(){ const s=crS(); return s.p.bUz===1 && crAl().length>0 && !CR.mute; }
// listas de menú
function crList(){ if(CR.ml==='fold') return CRFOLD.map(f=>({f}));
  if(CR.ml==='in') return CRPAR.map((P,k)=>({k})).filter(x=>CRPAR[x.k][6]===CR.fo);
  return CRPAR.map((P,k)=>({k})).filter(x=>CRPAR[x.k][7]).concat([{pa:1}]); }
function crStList(){ const L=['SEt','Pb1','Pb2','rtC','HAC','CC']; if(crAl().length) L.push('AL'); return L; }
function crMsg(t,ms){ CR.msg=t; CR.msgUntil=tNow()+(ms||1300); }
function crSetPar(k,d){ const s=crS(), P=CRPAR[k]; let v=s.p[P[0]]+d*P[5]; v=Math.max(P[3],Math.min(P[4],Math.round(v*10)/10)); const old=s.p[P[0]]; s.p[P[0]]=v;
  if(P[0]==='IdF'&&v!==old&&!s.def) s.next=S.t+Math.min(s.next-S.t,v*3600);
  if(P[0]==='LSE'&&s.p.LSE>s.p.HSE) s.p.HSE=s.p.LSE; if(P[0]==='HSE'&&s.p.HSE<s.p.LSE) s.p.LSE=s.p.HSE;
  if(P[0]==='LSE'||P[0]==='HSE') s.SP=Math.max(s.p.LSE,Math.min(s.p.HSE,s.SP)); }
// ---- pantalla: 4 dígitos naranja + 3 dígitos verdes + pilotos
let CRD=null;
function crBuild(){ const svg=$('crDisp'); if(!svg) return; svg.innerHTML=''; const off='var(--cr-off)';
  el('rect',{x:0,y:0,width:300,height:170,rx:6,fill:'var(--cr-glass)'},svg);
  const D={main:[],sec:[],ico:{},g:svg,off};
  for(let c=0;c<4;c++) D.main.push(segCell(svg,62+c*52,40,38,66,7.5,off));
  D.minus=el('rect',{x:24,y:70,width:24,height:7.5,rx:2.5,fill:off},svg);
  for(let c=0;c<3;c++) D.sec.push(segCell(svg,160+c*34,118,24,40,5,off));
  const ic=(n,x,d)=>{ D.ico[n]=el('path',{d:`M${x} 0 ${d}`,fill:'none',stroke:off,'stroke-width':2,'stroke-linecap':'round','stroke-linejoin':'round',transform:`translate(0 12)`},svg); };
  ic('cool',22,'M22 2 v16 M15 6 l14 8 M15 14 l14 -8');                        // copo: compresor/frío
  ic('def',50,'M44 4 c0 4 4 4 4 8 s-4 4 -4 8 M52 4 c0 4 4 4 4 8 s-4 4 -4 8'); // desescarche
  ic('fan',80,'M80 10 m-7 0 a7 7 0 1 0 14 0 a7 7 0 1 0 -14 0 M80 3 v14 M73 10 h14'); // ventilador
  ic('aux',112,'M104 4 h16 v12 h-16 z M108 10 h8');                         // salida AUX
  ic('lit',236,'M236 2 a6 6 0 0 1 4 10.5 v3 h-8 v-3 a6 6 0 0 1 4 -10.5 z M233 18 h6');
  ic('buz',258,'M252 7 h4 l5 -4 v14 l-5 -4 h-4 z M265 6 a5 5 0 0 1 0 8');
  ic('alm',284,'M284 2 l8 15 h-16 z M284 8 v4');
  D.unit=el('text',{x:282,y:100,'text-anchor':'end','font-family':'var(--f-mono)','font-size':12,'font-weight':700,fill:'var(--cr-on)'},svg);
  D.lab=el('text',{x:24,y:150,'font-family':'var(--f-mono)','font-size':11,'font-weight':700,fill:'var(--cr-sec)'},svg);
  CRD=D; }
function crShow(cells,str,col,off){ const chars=[]; for(const ch of String(str)){ if(ch==='.'&&chars.length) chars[chars.length-1].dp=true; else chars.push({ch,dp:false}); }
  while(chars.length<cells.length) chars.unshift({ch:' ',dp:false}); const use=chars.slice(-cells.length);
  use.forEach((o,i)=>{ const on=SEG[o.ch]??''; const c=cells[i]; for(const k of 'abcdefg') c[k].setAttribute('fill',on.includes(k)?col:off); c.dp.setAttribute('fill',o.dp?col:off); }); }
function crNum(v){ const a=Math.abs(v); return (a>=100||(S&&crS()&&crS().p.ndt===0)? String(Math.round(a)) : a.toFixed(1)); }
function crRender(){ if(!S||!$('crDisp')) return; crSync(); if(!CRD) crBuild(); const D=CRD, s=crS(), p=s.p;
  if(CR.tm!=='run'&&tNow()>CR.until){ CR.tm='run'; CR.ml='usr'; }
  const on='var(--cr-on)', sec='var(--cr-sec)', off=D.off, blink=Math.floor(tNow()/450)%2===0, slow=Math.floor(tNow()/1300)%2===0;
  const uT=v=>p.dro?v*1.8+32:v;
  let main='', neg=false, s2='', mainBlink=false, unit=p.dro?'°F':'°C', lab='';
  const T=v=>{ const x=uT(v); neg=x<0; return crNum(x); };
  const L=crList(); if(CR.ti>=L.length) CR.ti=0; const it=L[CR.ti]||{}; const sl=crStList(); if(CR.si>=sl.length) CR.si=0;
  const hm=crHM(crClk()), hmTxt=`${String(hm[0]).padStart(2,'0')}.${String(hm[1]).padStart(2,'0')}`;
  if(CR.msg&&tNow()<CR.msgUntil){ main=CR.msg; unit=''; s2=''; }
  else if(CR.tm==='st'||CR.tm==='stv'){ const lb=sl[CR.si]; s2=lb; unit='';
    if(lb==='SEt'){ main=T(s.SP); unit=p.dro?'°F':'°C'; mainBlink=CR.tm==='stv'; lab='consigna'; }
    else if(lb==='Pb1'){ main=s.e1?'E1':T(s.Tm); unit='°C'; lab='sonda cámara'; }
    else if(lb==='Pb2'){ main=s.e2?'E2':p.H42===0?'---':T(s.Tevm); unit='°C'; lab='sonda evaporador'; }
    else if(lb==='rtC'){ main=hmTxt; mainBlink=CR.tm==='stv'; lab=CR.tm==='stv'?(CR.ce===0?'cambia la hora':'cambia los minutos'):'reloj'; if(CR.tm==='stv'&&!blink){ main=CR.ce===0?`  .${hmTxt.slice(3)}`:`${hmTxt.slice(0,2)}.  `; } mainBlink=false; }
    else if(lb==='HAC'){ if(CR.tm==='st'){ main=String(CR.haccp.length); lab='alarmas HACCP guardadas'; } else { const r=CR.haccp[CR.hi]; if(!r){ main='----'; lab='sin registros'; } else { s2='H'+(CR.hi+1); if(slow){ main=T(r.Tmax); unit='°C'; lab='temperatura máxima'; } else { main='t'+String(Math.min(999,r.dur)).padStart(3,' '); lab=`duración (min) · empezó a las ${crHM(r.t0).map(x=>String(x).padStart(2,'0')).join(':')}`; } } } }
    else if(lb==='CC'){ main=s.cc?'on':'oFF'; mainBlink=CR.tm==='stv'; lab='ciclo continuo'; }
    else if(lb==='AL'){ const a=crAl(); main=a[CR.hi%Math.max(1,a.length)]||'----'; lab='alarmas activas'; } }
  else if(CR.tm==='menu'){ if(it.f){ s2=it.f; main='----'; lab=CRFOLDN[it.f]; } else if(it.pa){ s2='PA'; main='----'; lab='contraseña instalador'; } else { const P=CRPAR[it.k]; s2=P[0]; main=fmtP(p[P[0]],P); lab=P[1]; } unit=''; }
  else if(CR.tm==='edit'){ const P=CRPAR[CR.pk]; s2=P[0]; main=fmtP(p[P[0]],P); mainBlink=true; unit=P[2]==='°C'?'°C':''; lab=P[1]; }
  else if(CR.tm==='pa'){ s2='PA'; main=String(CR.pw); mainBlink=true; unit=''; lab='contraseña'; }
  else if(CR.tm==='max'||CR.tm==='min'){ s2=CR.tm==='max'?'HI':'LO'; main=T(CR.tm==='max'?s.Tmax:s.Tmin); lab=CR.tm==='max'?'temperatura máxima':'temperatura mínima'; }
  else if(s.off){ main='oFF'; unit=''; s2=''; }
  else { const a=crAl();
    if(s.e1) main=blink?'E1':'';
    else if(a.length&&!slow){ main=a[Math.floor(tNow()/2600)%a.length]; unit=''; }
    else if((s.def||s.drip>0||S.t-(s.defEnd??-1e9)<p.dAd*60)&&p.dFd===1){ main='dEF'; }
    else main=T(s.Tm);
    s2= p.dS2===0? (s.e2?'E2':p.H42===0?'---':String(Math.round(uT(s.Tevm)))) : p.dS2===1? String(Math.round(uT(s.SP))) : p.dS2===2? String(hm[0]*100+hm[1]).slice(-3) : ''; }
  if(main.startsWith('-')){ neg=true; main=main.slice(1); }
  const showMain=!(mainBlink&&!blink);
  crShow(D.main,showMain?main:'',on,off); D.minus.setAttribute('fill',showMain&&neg?on:off);
  let s2n=s2; if(s2n.startsWith('-')){ s2n=s2n.slice(1); } crShow(D.sec,s2n,sec,'var(--cr-off2)');
  D.unit.textContent=unit; D.lab.textContent=s2.startsWith('-')?'−':'';
  const I=(n,v)=>D.ico[n].setAttribute('stroke',v?(n==='alm'||n==='buz'?'#ff4a3a':on):off);
  I('cool',s.sv&&(!s.cc||blink)); I('def',s.def||s.drip>0); I('fan',s.fan); I('aux',CR.aux); I('lit',s.light); I('buz',crBuzz()&&blink); I('alm',crAl().length>0);
  const h=$('crHint'); if(h) h.textContent=lab||'';
  const db=$('crDoor'); if(db){ db.textContent=s.door?'Puerta ABIERTA':'Puerta cerrada'; db.setAttribute('aria-pressed',s.door); }
  const sb=$('crSos'); if(sb){ sb.setAttribute('aria-pressed',CR.sos); }
  const nm=$('crName'); if(nm) nm.textContent=s.name;
  const inf=$('crInfo'); if(inf){ const nx=Math.max(0,s.next-S.t); const o=(n,v)=>`<span class="out ${v?'on':''}">${n}</span>`;
    inf.innerHTML=`<div class="outs">${o('Compresor / solenoide',s.sv)}${o('Ventiladores',s.fan)}${o(['Resistencias','Gas caliente','Desescarche'][p.dtY],s.def)}${o('Luz',s.light)}${o('AUX',CR.aux)}${o('Zumbador',crBuzz())}</div>
      <span>Cámara <b>${s.e1?'E1':num(s.Tm)+' °C'}</b> · evaporador <b>${s.e2?'E2':num(s.Tevm)+' °C'}</b> · consigna <b>${num(s.SP)} °C</b> · reloj <b>${hmTxt.replace('.',':')}</b></span>
      <span>Próximo desescarche en <b>${Math.floor(nx/3600)} h ${Math.floor(nx%3600/60)} min</b> (${p.dCt?'por horario':'cada '+p.IdF+' h'})${crAl().length?` · alarmas: <b>${crAl().join(', ')}</b>`:''}</span>`; } }
function crInit(){ if(!$('crDisp')) return;
  const keep=()=>{ CR.until=tNow()+30000; }, R=()=>{ keep(); render(); }, run=()=>{ CR.tm='run'; CR.ml='usr'; };
  const s=()=>crS();
  bindKey($('crSet'),()=>{ CR.msg=null; const x=s();
    if(CR.tm==='run'||CR.tm==='max'||CR.tm==='min'){ CR.tm='st'; CR.si=0; }
    else if(CR.tm==='st'){ const lb=crStList()[CR.si]; if(lb==='Pb1'||lb==='Pb2'){ } else { CR.tm='stv'; CR.ce=0; CR.hi=0; } }
    else if(CR.tm==='stv'){ const lb=crStList()[CR.si]; if(lb==='rtC'&&CR.ce===0) CR.ce=1; else CR.tm='st'; }
    else if(CR.tm==='menu'){ const it=crList()[CR.ti]; if(it.pa){ CR.tm='pa'; CR.pw=0; } else if(it.f){ CR.ml='in'; CR.fo=it.f; CR.ti=0; } else { CR.tm='edit'; CR.pk=it.k; CR.old=x.p[CRPAR[it.k][0]]; } }
    else if(CR.tm==='edit'){ CR.tm='menu'; const c=CRPAR[CR.pk][0]; if(['UL','dL','Fr'].includes(c)&&x.p[c]===1){ x.p[c]=0; crMsg(keyAct(x,c)); } else logA('ok',`Cuadro de cámara: ${c} = ${fmtP(x.p[c],CRPAR[CR.pk])}.`); }
    else if(CR.tm==='pa'){ if(CR.pw===x.p.PA1){ CR.ml='fold'; CR.ti=0; CR.tm='menu'; } else { crMsg('Err'); CR.tm='menu'; CR.ml='usr'; CR.ti=0; } }
    R(); },()=>{ CR.msg=null; if(CR.tm==='menu'||CR.tm==='edit'||CR.tm==='pa') run(); else { CR.tm='menu'; CR.ml='usr'; CR.ti=0; } R(); });
  const arrow=d=>{ CR.msg=null; const x=s();
    if(CR.tm==='st'){ const n=crStList().length; CR.si=(CR.si+(d>0?-1:1)+n)%n; }
    else if(CR.tm==='stv'){ const lb=crStList()[CR.si];
      if(lb==='SEt'){ if(x.p.LOC) crMsg('LOC'); else x.SP=Math.max(x.p.LSE,Math.min(x.p.HSE,Math.round((x.SP+d*0.5)*10)/10)); }
      else if(lb==='rtC'){ CR.clkOff+=d*(CR.ce===0?3600:60); }
      else if(lb==='HAC'){ const n=Math.max(1,CR.haccp.length); CR.hi=(CR.hi+(d>0?-1:1)+n)%n; }
      else if(lb==='CC'){ if(x.off) return; x.cc=!x.cc; if(x.cc){ x.ccEnd=S.t+x.p.CCt*3600; if(x.p.CCt<=0) x.cc=false; else logA('ok',`${x.name}: ciclo continuo activado desde el cuadro.`); } }
      else if(lb==='AL') CR.hi++; }
    else if(CR.tm==='menu'){ const n=crList().length; CR.ti=(CR.ti+(d>0?-1:1)+n)%n; }
    else if(CR.tm==='edit') crSetPar(CR.pk,d);
    else if(CR.tm==='pa') CR.pw=(CR.pw+d+100)%100;
    else if(d>0&&crBuzz()){ CR.mute=true; logA('ok','Cuadro de cámara: zumbador silenciado.'); }
    else { CR.tm=d>0?'max':'min'; CR.until=tNow()+3000; render(); return; }
    R(); };
  bindKey($('crUp'),()=>arrow(1),()=>{ const x=s(); x.Tmax=x.Tm; x.Tmin=x.Tm; if(crAl().length){ x.alarm=null; x.hiSince=S.t; x.loSince=S.t; if(x.dAl){ x.dAl=false; x.doorSince=S.t; } if(CR.sos){ CR.sos=false; logA('ok','Cuadro de cámara: alarma de hombre encerrado reseteada.'); } logA('ok',`${x.name}: alarmas reseteadas desde el cuadro.`); } run(); render(); });
  bindKey($('crDn'),()=>arrow(-1),()=>{ const x=s(); if(x.p.AUt===0){ CR.aux=!CR.aux; logA('ok',`Cuadro de cámara: salida AUX ${CR.aux?'activada':'desactivada'}.`); } else crMsg('AUt'); run(); render(); });
  bindKey($('crEsc'),()=>{ CR.msg=null; const x=s();
    if(CR.tm==='edit'){ x.p[CRPAR[CR.pk][0]]=CR.old; CR.tm='menu'; keep(); }
    else if(CR.tm==='pa'){ CR.tm='menu'; keep(); }
    else if(CR.tm==='menu'&&CR.ml==='in'){ CR.ml='fold'; CR.ti=Math.max(0,CRFOLD.indexOf(CR.fo)); keep(); }
    else if(CR.tm==='stv'){ CR.tm='st'; keep(); }
    else run(); render(); },
    ()=>{ const x=s(); if(x.off) return; if(x.def) x.defT=x.p.ndF*60; else x.next=S.t; run(); render(); });
  bindKey($('crLight'),()=>{ const x=s(); if(x.off) return; x.lightMan=!x.lightMan; logA('ok',`${x.name}: luz ${x.lightMan?'encendida':'apagada'} desde el cuadro.`); render(); });
  bindKey($('crOnOff'),()=>{ crMsg(s().off?'oFF':'on',700); render(); },()=>{ const x=s(); x.off=!x.off; if(!x.off){ x.odoUntil=S.t+x.p.odo*60; x.paoUntil=S.t+x.p.PAO*60; if(x.p.dPo) x.next=x.odoUntil; } else x.cc=false; logA('ok',`${x.name}: ${x.off?'en espera (OFF)':'en marcha (ON)'} desde el cuadro.`); run(); render(); });
  $('crDoor').addEventListener('click',()=>{ const x=s(); x.door=!x.door; logA(x.door?'warn':'ok',`${x.name}: puerta ${x.door?'abierta':'cerrada'}.`); render(); });
  $('crSos').addEventListener('click',()=>{ if(!CR.sos){ CR.sos=true; CR.mute=false; logA('bad',`${crS().name}: ¡alarma de hombre encerrado! (pulsador dentro de la cámara).`); } render(); }); }

// ================= cuadro eléctrico del compresor 2 + polímetro y pinza =================
const EL={q0:true,mode:'V',red:null,black:null,val:'',lastPair:null,lastMode:null,lastVal:null,clamp:null,amp:'',log:[],warn:''};
const elComp=()=>{ const G=S.grp[S.top]; return {G,i:Math.min(1,G.N-1),name:(S.top==='LT'?'BT':'MT')+(Math.min(1,G.N-1)+1)}; };
const elSvc=()=>{ const L=S.svcs.map((s,i)=>({s,i})); const f=L.find(x=>x.s.g==='MT'&&!/Cámara/.test(x.s.name))||L[0]; return f.i; };
function elState(){ const af=activeFault(), {G,i}=elComp(), sv=S.svcs[elSvc()];
  const q1Trip= FX('comp')||FX('phase'), km= FX('kmcoil')||(FX('loose')&&G.trip[i]), fu= FX('fuse'), ph= FX('phase'), yv= FXs('sv',elSvc());
  const R1= EL.q0 && !S.pwrOff && G.mode[i]!=='off' && !FX('rel') && (G.on[i] || ['comp','kmcoil','fuse','phase','hpsw','loose'].some(FX));
  const HP= !(S.t<S.hpTrip) && !FX('hpsw'), LP= !(G.Te<G.p.LP), T= EL.q0 && sv.sv;
  return {q1Trip,km,fu,ph,yv,R1,HP,LP,T}; }
// cadena de mando: [nodo, elemento hasta el siguiente nodo]
const EL_CH=[['b1','F1'],['f','R1'],['r','HP'],['h','LP'],['l','Q1a'],['A1','KM'],['A2',null]];
function elPots(){ const st=elState(), P={};
  const ph=S.pwrOff?{L1:null,L2:null,L3:null}:{L1:'L1',L2:'L2',L3:st.ph?null:'L3'};
  P.a1=ph.L1; P.a2=ph.L2; P.a3=ph.L3; P.N=S.pwrOff?null:'N';
  P.b1=EL.q0?P.a1:null; P.b2=EL.q0?P.a2:null; P.b3=EL.q0?P.a3:null;
  P.c1=st.q1Trip?null:P.b1; P.c2=st.q1Trip?null:P.b2; P.c3=st.q1Trip?null:P.b3;
  const closed={F1:!st.fu,R1:st.R1,HP:st.HP,LP:st.LP,Q1a:!st.q1Trip};
  const nodes=['b1','f','r','h','l','A1'], els=['F1','R1','HP','LP','Q1a'];
  ['f','r','h','l','A1'].forEach(n=>P[n]=undefined);
  for(let j=0;j<els.length;j++){ const cur=P[nodes[j]]; if(cur&&cur!=='N'&&closed[els[j]]) P[nodes[j+1]]=cur; else break; }
  P.A2='N'; if(P.A1===undefined&&!st.km) P.A1='N';
  for(let j=els.length-1;j>=0;j--){ if(P[nodes[j+1]]==='N'&&closed[els[j]]&&P[nodes[j]]===undefined) P[nodes[j]]='N'; else if(P[nodes[j]]!==undefined) break; }
  nodes.forEach(n=>{ if(P[n]===undefined) P[n]=null; });
  // rama de la solenoide
  P.y2='N'; P.y1= (P.f&&P.f!=='N'&&st.T)? P.f : (!st.yv?'N':null);
  const kmIn= P.A1&&P.A1!=='N'&&!st.km;
  P.U=kmIn?P.c1:null; P.V=kmIn?P.c2:null; P.W=kmIn?P.c3:null;
  return {P,st,kmIn,run:kmIn&&!st.q1Trip&&P.c3!=null}; }
function elV(a,b,P){ const x=P[a], y=P[b]; if(!x||!y||x===y) return 0; if(x==='N'||y==='N') return 230; return 400; }
// resistencias (sin tensión)
function elR(a,b){ const st=elState(); const E=[['a1','b1',EL.q0?0:Infinity],['a2','b2',EL.q0?0:Infinity],['a3','b3',EL.q0?0:Infinity],
    ['b1','c1',st.q1Trip?Infinity:0],['b2','c2',st.q1Trip?Infinity:0],['b3','c3',st.q1Trip?Infinity:0],
    ['c1','U',Infinity],['c2','V',Infinity],['c3','W',Infinity],
    ['b1','f',st.fu?Infinity:0.1],['f','r',Infinity],['r','h',st.HP?0:Infinity],['h','l',st.LP?0:Infinity],['l','A1',st.q1Trip?Infinity:0],['A1','A2',st.km?Infinity:550],['A2','N',0],
    ['f','y1',Infinity],['y1','y2',st.yv?Infinity:1200],['y2','N',0]];
  const mot={'U-V':2.4,'V-W':2.4,'U-W':2.4}; const k=[a,b].sort().join('-'); if(mot[k]!=null) return mot[k];
  const adj={}; E.forEach(([x,y,w])=>{ (adj[x]=adj[x]||[]).push([y,w]); (adj[y]=adj[y]||[]).push([x,w]); });
  const seen=new Set([a]); const q=[[a,0]]; while(q.length){ const [n,d]=q.shift(); if(n===b) return d; (adj[n]||[]).forEach(([m,w])=>{ if(!seen.has(m)&&w<Infinity){ seen.add(m); q.push([m,d+w]); } }); }
  return Infinity; }
const EL_PTS={a1:[80,70],a2:[140,70],a3:[200,70],b1:[80,190],b2:[140,190],b3:[200,190],c1:[80,300],c2:[140,300],c3:[200,300],U:[95,425],V:[140,425],W:[185,425],
  f:[420,120],r:[520,120],h:[620,120],l:[720,120],A1:[800,200],A2:[800,320],N:[420,460],y1:[520,250],y2:[520,340]};
const EL_NM={a1:'L1 entrada',a2:'L2 entrada',a3:'L3 entrada',b1:'L1 tras Q0',b2:'L2 tras Q0',b3:'L3 tras Q0',c1:'L1 tras Q1',c2:'L2 tras Q1',c3:'L3 tras Q1',U:'Motor U',V:'Motor V',W:'Motor W',f:'Salida F1',r:'Salida relé C2',h:'Salida presostato HP',l:'Salida presostato LP',A1:'Bobina A1',A2:'Bobina A2',N:'Neutro N',y1:'Solenoide A1',y2:'Solenoide A2'};
function elSVG(){ const st=elState(), {P,kmIn,run}=elPots(); const ink='var(--ink)', mu='var(--muted)', on='#e0573c';
  const L=(x1,y1,x2,y2,c,w)=>`<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${c||ink}" stroke-width="${w||2}"/>`;
  const T=(x,y,t,o)=>`<text x="${x}" y="${y}" font-family="var(--f-body)" font-size="${(o&&o.s)||12}" font-weight="${(o&&o.w)||600}" fill="${(o&&o.c)||ink}" text-anchor="${(o&&o.a)||'middle'}">${t}</text>`;
  const live=n=>P[n]&&P[n]!=='N';
  const wc=(n)=>live(n)?on:ink;
  let s=`<svg viewBox="0 0 900 500" class="el-svg" id="elSvg">`;
  // potencia
  s+=T(140,22,'POTENCIA 400 V',{s:11,c:mu}); ['L1','L2','L3'].forEach((t,k)=>{ const x=80+k*60; s+=T(x,44,t,{s:12}); s+=L(x,50,x,150,live('a'+(k+1))?on:mu,2.5); });
  // Q0 seccionador
  s+=`<g id="el-Q0">`; [80,140,200].forEach((x,k)=>{ s+= EL.q0? L(x,150,x,180,live('a'+(k+1))?on:ink,2.5) : L(x,150,x+12,174,ink,2.5); s+=L(x,180,x,230,live('b'+(k+1))?on:ink,2.5); }); s+=`<rect x="60" y="146" width="160" height="38" rx="6" fill="none" stroke="${mu}" stroke-dasharray="4 3"/>`+T(240,170,'Q0',{a:'start'})+T(240,184,EL.q0?'cerrado':'abierto',{a:'start',s:10,c:mu,w:500})+`</g>`;
  // Q1 guardamotor
  s+=`<g id="el-Q1"><rect x="60" y="232" width="160" height="50" rx="6" fill="${st.q1Trip?'#fdecea':'var(--panel)'}" stroke="${st.q1Trip?'#c62f2f':ink}" stroke-width="1.6"/>`+T(140,254,'Q1 guardamotor',{s:11})+T(140,270,st.q1Trip?'DISPARADO':'en marcha',{s:10,c:st.q1Trip?'#c62f2f':mu})+`</g>`;
  [80,140,200].forEach((x,k)=>{ s+=L(x,282,x,330,live('c'+(k+1))?on:ink,2.5); });
  // KM1 contactor
  s+=`<g id="el-KM"><rect x="60" y="330" width="160" height="44" rx="6" fill="var(--panel)" stroke="${ink}" stroke-width="1.6"/>`+T(140,350,'KM1 contactor',{s:11})+T(140,365,kmIn?'ENTRADO':'abierto',{s:10,c:kmIn?'#1a8f4a':mu})+`</g>`;
  [80,140,200].forEach((x,k)=>{ const tx=[95,140,185][k]; s+=L(x,374,x,400,live(['U','V','W'][k])?on:ink,2.5)+L(x,400,tx,418,live(['U','V','W'][k])?on:ink,2.5); });
  s+=`<g id="el-M"><circle cx="140" cy="455" r="30" fill="${run?'#e7f6ee':'var(--panel)'}" stroke="${ink}" stroke-width="2"/>`+T(140,452,'M',{s:16,w:700})+T(140,468,'3~',{s:10})+T(185,470,elComp().name,{a:'start',s:11,c:mu})+`</g>`;
  // mando
  s+=T(600,22,'MANDO 230 V',{s:11,c:mu});
  s+=L(80,120,420,120,wc('b1'),1.6).replace('<line','<line stroke-dasharray="0"');
  const sw=(x,closed,id,lab,sub)=>`<g id="el-${id}">`+(closed?L(x,120,x+60,120,ink,2):L(x,120,x+52,104,ink,2))+`<circle cx="${x}" cy="120" r="3" fill="${ink}"/><circle cx="${x+60}" cy="120" r="3" fill="${ink}"/>`+T(x+30,96,lab,{s:11})+T(x+30,145,sub,{s:9.5,c:mu,w:500})+`</g>`;
  s+=`<g id="el-F1"><rect x="${360}" y="110" width="40" height="20" rx="3" fill="${st.fu?'#fdecea':'var(--panel)'}" stroke="${st.fu?'#c62f2f':ink}"/>`+(st.fu?L(366,116,394,124,'#c62f2f',2):L(360,120,400,120,ink,1.5))+T(380,96,'F1',{s:11})+T(380,145,st.fu?'fundido':'fusible 2 A',{s:9.5,c:st.fu?'#c62f2f':mu,w:500})+`</g>`+L(400,120,460,120,wc('f'));
  s+=sw(460,st.R1,'R1','Relé C2','controlador')+L(520,120,560,120,wc('r'));
  s+=sw(560,st.HP,'HP','HP','presostato alta')+L(620,120,660,120,wc('h'));
  s+=sw(660,st.LP,'LP','LP','presostato baja')+L(720,120,740,120,wc('l'));
  s+=sw(740,!st.q1Trip,'Q1a','Q1 13-14','aux. guardamotor')+L(800,120,800,200,wc('A1'));
  s+=`<g id="el-KMc"><rect x="775" y="210" width="50" height="100" rx="6" fill="${st.km?'#fdecea':'var(--panel)'}" stroke="${st.km?'#c62f2f':ink}" stroke-width="1.6"/>`+T(800,258,'KM1',{s:11})+T(800,274,'bobina',{s:9.5,c:mu,w:500})+`</g>`+L(800,310,800,460,ink)+L(420,460,800,460,ink);
  s+=T(420,488,'N',{s:12});
  // solenoide
  s+=`<path d="M440 120 V170 H470 V190" fill="none" stroke="${wc('f')}" stroke-width="1.6"/><path d="M470 230 V244 H520 V262" fill="none" stroke="${wc('y1')}" stroke-width="1.6"/>`;
  s+=`<g id="el-T">`+(st.T?L(470,190,470,230,ink,2):L(470,190,480,224,ink,2))+T(500,214,'Termostato',{s:9.5,c:mu,w:500,a:'start'})+`</g>`;
  s+=`<g id="el-YV"><rect x="495" y="262" width="50" height="70" rx="6" fill="${st.yv?'#fdecea':'var(--panel)'}" stroke="${st.yv?'#c62f2f':ink}" stroke-width="1.6"/>`+T(520,293,'YV1',{s:11})+T(520,308,'solenoide',{s:9,c:mu,w:500})+`</g>`+L(520,332,520,460,ink);
  s+=T(560,356,S.svcs[elSvc()].name,{a:'start',s:10,c:mu,w:500});
  // puntos de prueba
  Object.entries(EL_PTS).forEach(([k,[x,y]])=>{ const r=EL.red===k, b=EL.black===k; s+=`<circle class="el-tp${r?' red':''}${b?' black':''}" data-tp="${k}" cx="${x}" cy="${y}" r="${r||b?9:7}"><title>${EL_NM[k]}</title></circle>`; });
  return s+`</svg>`; }
function elRead(){ if(!EL.red||!EL.black){ EL.val='— —'; return; } const {P}=elPots();
  if(EL.mode==='V'){ const v=elV(EL.red,EL.black,P); EL.val=v+' V'; EL.lastVal=v; }
  else if(EL.mode==='R'){ const powered=Object.values(P).some(x=>x&&x!=='N'); if(powered&&EL.q0){ EL.val='¡TENSIÓN!'; EL.warn='Nunca midas resistencia con tensión: abre Q0 y comprueba ausencia de tensión.'; EL.lastVal=null; return; }
    const r=elR(EL.red,EL.black); EL.val= r===Infinity?'OL':(r<1?r.toFixed(1)+' Ω · pita':(r>=1000?(r/1000).toFixed(2)+' kΩ':Math.round(r*10)/10+' Ω')); EL.lastVal=r; }
  EL.lastPair=[EL.red,EL.black].sort().join('-'); EL.lastMode=EL.mode; EL.lastT=tNow(); }
function elRender(full){ const box=$('elecBox'); if(!box||!S) return; const vis=box.getBoundingClientRect().width>0; if(!vis&&!full) return;
  const st=elState(); if(EL.red&&EL.black) elRead();
  const key=JSON.stringify([st,EL.q0,EL.red,EL.black,EL.mode,EL.val,EL.amp,elPots().kmIn,S.fluid,S.cfg,TRN&&TRN.hlOn]);
  if(box._k===key) return; box._k=key;
  box.innerHTML=`<div class="el-grid"><div class="el-sch">${elSVG()}</div>
    <div class="el-side"><div class="el-mm"><div class="el-disp">${EL.mode==='OFF'?'':EL.val||'— —'}</div><div class="el-modes">${[['V','V~'],['R','Ω'],['OFF','OFF']].map(([k,t])=>`<button class="el-m" data-em="${k}" aria-pressed="${EL.mode===k}">${t}</button>`).join('')}</div>
      <p class="el-hint">${EL.warn?`<b class="el-warn">${EL.warn}</b>`:`Pulsa un punto del esquema para la <b style="color:#e0573c">punta roja</b> y otro para la <b>punta negra</b>.`}</p>
      <p class="el-pair">${EL.red?'<span class="r">●</span> '+EL_NM[EL.red]:''}${EL.black?'<br><span class="k">●</span> '+EL_NM[EL.black]:''}</p></div>
      <div class="el-clamp"><b>Pinza amperimétrica</b><div class="el-cl">${['U','V','W'].map(k=>`<button class="q-btn sm" data-clamp="${k}">${k}</button>`).join('')}<span>${EL.amp||'—'}</span></div></div>
      <div class="el-acts"><button class="q-btn" data-eq0>${EL.q0?'Abrir Q0 (quitar tensión)':'Cerrar Q0 (dar tensión)'}</button><button class="q-btn" data-eq1 ${st.q1Trip?'':'disabled'}>Rearmar Q1</button></div>
      <p class="el-st">Compresor ${elComp().name}: <b>${elPots().run?'en marcha':'parado'}</b> · Solenoide ${S.svcs[elSvc()].name}: <b>${elState().T&&!elState().yv?'abierta':'cerrada'}</b></p></div></div>`; }
function elInit(){ const box=$('elecBox'); if(!box) return;
  box.addEventListener('click',e=>{ const tp=e.target.closest('[data-tp]'); EL.warn='';
    if(tp){ const k=tp.dataset.tp; if(!EL.red||(EL.red&&EL.black)){ EL.red=k; EL.black=null; } else if(k!==EL.red) EL.black=k; box._k=null; elRender(true); return; }
    const m=e.target.closest('[data-em]'); if(m){ EL.mode=m.dataset.em; box._k=null; elRender(true); return; }
    if(e.target.closest('[data-eq0]')){ EL.q0=!EL.q0; logA(EL.q0?'ok':'warn',`Cuadro eléctrico: seccionador Q0 ${EL.q0?'cerrado (con tensión)':'abierto (sin tensión)'}.`); box._k=null; elRender(true); return; }
    if(e.target.closest('[data-eq1]')){ if(FX('comp')||FX('phase')){ EL.warn='Q1 vuelve a saltar: la causa sigue ahí. Mide antes de rearmar.'; } else EL.warn=''; box._k=null; elRender(true); return; }
    const c=e.target.closest('[data-clamp]'); if(c){ const {run}=elPots(); EL.amp= run? ((FX('valv')?6.4:11.2)+Math.random()*0.8).toFixed(1).replace('.',',')+' A' : '0,0 A'; EL.clamp=c.dataset.clamp; box._k=null; elRender(true); return; } });
  setInterval(()=>elRender(false),600); }

