Object.assign(TOOLS,{
  presos:{n:'Comprobar con el manómetro a qué presión abre el presostato y cambiarlo',ic:'🎚️'},
  relay:{n:'Revisar la salida del controlador (fusible de la tarjeta / relé) y repararla',ic:'🖲️'},
  dry:{n:'Cambiar el filtro secador, hacer vacío profundo y cargar refrigerante nuevo',ic:'💧'},
  purge:{n:'Recuperar el refrigerante, hacer vacío y volver a cargar por peso',ic:'♻️'}});
Object.assign(ECASES,{
 hpsw:{tool:'presos',ff:20,aviso:'«El compresor 2 no arranca; la alta presión está normal y el térmico no ha saltado».',
   pistas:['Sigue la tensión del mando con el polímetro (negra en neutro, roja moviéndose).','Antes del presostato de alta hay 230 V y después 0 V: su contacto está abierto.','La alta presión es normal: el presostato está averiado o mal ajustado.'],
   mirar:[['Cuadro eléctrico','m-elec'],['Manómetros','m-gauges']],
   why:'Si un presostato está abierto con la presión normal, está averiado o desajustado. Se comprueba con un manómetro a qué presión abre y cierra, se ajusta o se cambia. Nunca se puentea.'},
 rel:{tool:'relay',ff:20,aviso:'«El controlador muestra que pide el compresor 2, pero el compresor no arranca».',
   pistas:['Mide tensión a la salida del fusible F1: hay 230 V.','A la salida del relé C2 del controlador no hay tensión aunque el controlador lo pide.','El relé de salida del controlador no cierra (relé quemado o fusible de la tarjeta).'],
   mirar:[['Cuadro eléctrico','m-elec'],['Controlador','m-central']],
   why:'Si el controlador pide marcha y su relé no deja pasar la tensión, la salida está averiada: se revisa el fusible de la tarjeta, el relé o se cambia el módulo. Como emergencia se puede pasar a otra salida libre, nunca puentear sin control.'}});
const ECT2={hpsw:'El compresor 2 no arranca con la alta normal',rel:'El controlador pide marcha y no arranca'};
Object.entries(ECT2).forEach(([k,t],i)=>TRAIN.push({id:'ec'+(i+6),sec:'elec',n:t,d:ECASES[k].aviso,ref:'any',case:k,k,cdef:ECASES[k]}));
Object.assign(CASES,{
 humid:{tool:'dry',ff:120,aviso:'«Los muebles enfrían bien un rato, luego se calientan y después vuelven a ir bien sin tocar nada. Hace poco se cambió una tubería».',
   pistas:['Mira el visor de líquido: el punto indicador de humedad.','El problema va y viene: la válvula de expansión se tapa a ratos.','Tras una reparación sin buen vacío puede quedar humedad dentro.'],
   mirar:[['Esquema (visor)','m-diagram'],['Temperaturas','m-trend']],
   why:'La humedad se congela en la válvula de expansión y la tapa a ratos; además forma ácidos con el aceite. Se cambia el filtro secador (a veces varias veces), se hace vacío profundo y, si hace falta, se cambia el refrigerante y el aceite.'},
 noncond:{tool:'purge',ff:60,aviso:'«Desde la última reparación la alta presión está más alta que antes y la central gasta más».',
   pistas:['Compara la alta presión con la temperatura exterior: está más alta de lo normal.','El condensador está limpio y todos los ventiladores giran.','Si se hizo mal el vacío, puede haber aire (incondensables) dentro del circuito.'],
   mirar:[['Manómetros','m-gauges'],['Esquema','m-diagram']],
   why:'El aire no condensa y ocupa sitio en el condensador: sube la alta presión y el consumo. Se recupera el refrigerante, se hace buen vacío y se carga por peso.'}});
CASE_T.humid='Los muebles enfrían a ratos'; CASE_T.noncond='La alta está más alta desde la última reparación';
['humid','noncond'].forEach(k=>{ const idx=TRAIN.findIndex(l=>l.id==='ax'); TRAIN.splice(idx,0,{id:'a'+k,sec:'fault',k,n:CASE_T[k],d:'',ref:'any',case:k}); });

// ================= Escuela: puesta en marcha, diagnóstico por síntomas, exámenes, CO₂ y averías nuevas =================
// ---------- motor: varias averías, entorno y corte de luz
const CDEF=k=>CASES[k]||ECASES[k];
const _trFault0=trFault; trFault=function(k,svc){ _trFault0(k,svc); S.f2=null; S.f2svc=null; S.fT=S.t; };
function trFault2(k,svc){ S.f2=k; S.f2svc=svc??0; S.cache=highSide(); }
const _trFix0=trFix; trFix=function(){ _trFix0(); S.f2=null; S.f2svc=null; S.psvLoss=0; S.psvN=0; S.recX=0; S.pwrOff=false; S.cache=highSide(); };
function trFixOne(k){ if(S.f2===k){ S.f2=null; } else if(S.mystery===k){ if(S.f2){ S.mystery=S.f2; S.mysvc=S.f2svc; S.f2=null; } else S.mystery=null; }
  const C=CDEF(k); if(C&&C.fix) C.fix(); if(!S.mystery&&!S.f2){ const fs=$('fault'); if(fs) fs.disabled=false; } S.cache=highSide(); }
function envReset(){ S.tAmb=28; const e=$('sAmb'); if(e) e.value=28; S.tSala=22; const G=S.grp[S.top];
  if(TRN.mem.lp0!=null){ G.p.LP=TRN.mem.lp0; TRN.mem.lp0=null; } if(TRN.mem.idf0){ const [i,v]=TRN.mem.idf0; if(S.svcs[i]) S.svcs[i].p.IdF=v; TRN.mem.idf0=null; }
  S.svcs.forEach(s=>{ s.ice=0; s.door=false; }); S.pwrOff=false; S.recX=0; S.psvLoss=0; S.psvN=0; S.cache=highSide(); }
function pwrCut(){ S.pwrOff=true; logA('bad','Corte de luz: toda la instalación sin tensión.'); S.cache=highSide(); }
function pwrOn(){ S.pwrOff=false; S.svcs.forEach(s=>{ if(!s.off){ s.odoUntil=S.t+s.p.odo*60; s.paoUntil=S.t+s.p.PAO*60; if(s.p.dPo) s.next=s.odoUntil; } }); logA('ok','Vuelve la tensión: la instalación arranca.'); S.cache=highSide(); }
const prec=()=>S.cache&&S.cache.Prec?rel(S.cache.Prec):0;
const pick=(a,n)=>{ const c=a.slice(), o=[]; while(o.length<n&&c.length) o.push(c.splice(Math.floor(Math.random()*c.length),1)[0]); return o; };
// la verificación de los casos tiene en cuenta el hielo y los desescarches
const _cs0=caseSteps; caseSteps=function(k,sur,CD){ const r=_cs0(k,sur,CD); const v=r.find(x=>x.kind==='verify');
  if(v){ const ice=['heater','drain','nodef'].includes(k);
    v.check=()=>noFault()&&cAlarms().length===0&&(!ice||(S.svcs[TRN.mem.svc]?.ice||0)<0.15)&&(k!=='nodef'||(S.svcs[TRN.mem.svc]?.p.IdF||0)>0);
    v.extra=()=>k==='nodef'?' Programa los desescarches en ese termostato (IdF, por ejemplo 8 h) y haz un desescarche manual (mantén ▲) para quitar el hielo.':ice?' Haz también un desescarche manual (mantén ▲ en el termostato) para quitar el hielo.':''; }
  return r; };

