// ================= Prácticas con herramientas (páginas propias: analizador, cableado, montaje, equipo partido) =================
const TP={L:null,i:0,st:null,fb:'',ok:false,okAt:0,snap:null,key:'',errs:0,acted:null,ord:null,msg:''};
const TOOLSIM={};
const tpStep=()=>TP.L&&TP.L.steps[TP.i];
function tpOpen(L){ if(typeof TRN!=='undefined'&&TRN.L) trStop(); if(typeof LN!=='undefined'&&LN.dev){ lnLeave(); LN.dev=null; }
  Object.assign(TP,{L,i:0,fb:'',ok:false,okAt:0,snap:null,key:'',errs:0,acted:null,ord:null,msg:''}); TP.st=TOOLSIM[L.page].init(L);
  stSel.mode='tool'; $('start').hidden=false; document.body.classList.add('st-open'); renderStart(); window.scrollTo(0,0); const sb=$('stBody'); if(sb) sb.scrollTop=0; }
function tpErr(msg){ TP.errs++; TP.msg='✗ '+msg; tpTool(); if(typeof repAddTool==='function'&&TP.L.id!=='repaso') repAddTool(TP.L.id); }
function tpNote(msg){ TP.msg=msg; tpTool(); }
function tpTool(){ const el=$('tpTool'); if(!el||!TP.L) return; TOOLSIM[TP.L.page].render(el,TP.st); const m=$('tpMsg'); if(m){ m.innerHTML=TP.msg||''; m.className='tp-msg'+(TP.msg&&TP.msg[0]==='✗'?' bad':TP.msg?' ok':''); } }
function tpNext(){ TP.i++; TP.fb=''; TP.ok=false; TP.okAt=0; TP.snap=null; TP.ord=null; tpPane(); }
function tpNextLesson(){ const L=TP.L; const list=TRAIN.filter(l=>l.sec===L.sec); return list[list.findIndex(l=>l.id===L.id)+1]||null; }
function tpGoNext(){ const n=tpNextLesson(); if(n){ trStart(n.id,n.ref==='co2'||n.ref==='freon'?n.ref:(typeof trRefAuto==='function'?trRefAuto():'co2')); } else { stSel.mode='train'; TRN.view=tpNextSec()||TP.L.sec; renderStart(); } }
function renderTool(root){ const L=TP.L; const w=pkEl2('div','ln tp');
  const top=pkEl2('div','ln-top row'); const back=pkEl2('button','b2-back ln-back','← '+(TSEC[L.sec]?TSEC[L.sec][0]:'Escuela')); back.onclick=()=>{ stSel.mode='train'; TRN.view=L.sec; renderStart(); }; top.appendChild(back);
  top.appendChild(pkEl2('div','ln-title',`<small>${TSEC[L.sec]?TSEC[L.sec][0]:''}</small><b>${L.n}</b>`));
  const n=tpNextLesson(), sk=!n&&tpNextSec(); if(n||sk){ const nb=pkEl2('button','tp-nx',n?'Siguiente lección ›':'Siguiente sección ›'); nb.title=n?n.n:TSEC[sk][0]; nb.onclick=tpGoNext; top.appendChild(nb); }
  w.appendChild(top);
  const grid=pkEl2('div','ln-grid tp-grid'); const left=pkEl2('div','tp-left'); left.appendChild(pkEl2('div','tp-tool','<div id="tpTool"></div>')); left.appendChild(pkEl2('p','tp-msg','')); left.lastChild.id='tpMsg';
  grid.appendChild(left); const side=pkEl2('div','ln-side'); side.id='tpSide'; grid.appendChild(side); w.appendChild(grid); root.appendChild(w);
  tpTool(); tpPane(); }
function tpPane(){ const side=$('tpSide'); if(!side||!TP.L) return; const L=TP.L, st=tpStep(), N=L.steps.length; const key=L.id+'-'+TP.i;
  if(TP.key!==key){ TP.key=key; if(st&&st.act&&TP.acted!==key){ TP.acted=key; try{ st.act(TP.st); }catch(e){ console.error(e); } tpTool(); } if(st&&st.init) TP.snap=st.init(TP.st); }
  const T=x=>typeof x==='function'?x(TP.st):x;
  let h=N?`<div class="ln-bar">${L.steps.map((_,k)=>`<i class="${k<TP.i?'ok':k===TP.i?'cur':''}"></i>`).join('')}</div>`:'';
  if(!N){ if(L.id!=='repaso') trSave(L.id,100); let oth=TRAIN.filter(l=>l.page===L.page&&l.id!==L.id&&l.steps&&l.steps.length); if(!oth.length) oth=TRAIN.filter(l=>l.sec===L.sec&&l.id!==L.id); h+=`<p class="ln-num">Práctica libre</p><div class="ln-txt">${T(L.free)||'Usa la herramienta como quieras.'}</div>${oth.length?`<p class="tp-sub">¿Prefieres que te guíe? Elige una práctica:</p><div class="tp-list">${oth.map(l=>`<button class="tp-li" data-tpl="${l.id}"><b>${l.n}</b><small>${l.d||''}</small></button>`).join('')}</div>`:''}`; }
  else if(!st){ const sc=Math.max(0,100-10*TP.errs); trSave(L.id,sc);
    h+=`<div class="ln-fin"><b>¡Práctica completada!</b><p>${TP.errs?`Errores: ${TP.errs} · puntuación ${sc}`:'Sin errores.'}</p></div><div class="tp-acts">${n2btn()}<button class="q-btn" data-tp="again">Repetir</button><button class="q-btn" data-tp="back">Volver a la escuela</button></div>`; }
  else { h+=`<p class="ln-num">Paso ${TP.i+1} de ${N}</p><div class="ln-txt">${T(st.t)}</div>`;
    if(st.info) h+='<div class="tp-acts"><button class="q-btn pri" data-tp="next">Entendido →</button></div>';
    else if(st.quiz){ const o=T(st.opts); h+=`<div class="tr-opts">${o.map((x,k)=>`<button class="tr-opt" data-q="${k}">${x}</button>`).join('')}</div>${TP.fb?`<div class="tr-fb ${TP.ok?'ok':'bad'}">${TP.fb}</div>`:''}${TP.ok?'<div class="tp-acts"><button class="q-btn pri" data-tp="next">Siguiente →</button></div>':''}`; }
    else if(st.order){ if(!TP.ord) TP.ord={sel:[],shuf:st.items.map((_,k)=>k).sort(()=>Math.random()-.5)};
      h+=`<ol class="tr-ord-done">${TP.ord.sel.map(k=>`<li>${st.items[k]}</li>`).join('')}</ol><div class="tr-opts">${TP.ord.shuf.filter(k=>!TP.ord.sel.includes(k)).map(k=>`<button class="tr-opt" data-o="${k}">${st.items[k]}</button>`).join('')}</div>${TP.fb?`<div class="tr-fb ${TP.ok?'ok':'bad'}">${TP.fb}</div>`:''}${TP.ok?'<div class="tp-acts"><button class="q-btn pri" data-tp="next">Siguiente →</button></div>':''}`; }
    else { h+=`<div class="ln-wait ${TP.okAt?'ok':''}" id="tpWait">${TP.okAt?'✓ ¡Bien hecho!':st.hs?'Pulsa en el dibujo lo que parpadea en naranja…':'Hazlo en la herramienta de la izquierda…'}</div><div class="tp-acts">${st.ff?'<button class="q-btn" data-tp="ff">Adelantar 5 min</button>':''}<button class="tr-skip" data-tp="next">Saltar paso</button></div>`; } }
  side.innerHTML=h; }
const tpNextSec=()=>{ const ks=Object.keys(TSEC); return ks[ks.indexOf(TP.L.sec)+1]||null; };
const n2btn=()=>{ const n=tpNextLesson(), sk=!n&&tpNextSec(); return n?`<button class="q-btn pri" data-tp="nextL">Siguiente lección: ${n.n} →</button>`:sk?`<button class="q-btn pri" data-tp="nextL">Siguiente sección: ${TSEC[sk][0]} →</button>`:''; };
document.addEventListener('click',e=>{ const side=e.target.closest&&e.target.closest('#tpSide'); if(!side||!TP.L) return; const b=e.target.closest('button'); if(!b) return; const st=tpStep(), a=b.dataset.tp;
  if(b.dataset.tpl){ trStart(b.dataset.tpl); return; } if(a==='next'){ tpNext(); return; } if(a==='nextL'){ tpGoNext(); return; } if(a==='again'){ tpOpen(TP.L); return; } if(a==='back'){ stSel.mode='train'; TRN.view=TP.L.sec; renderStart(); return; }
  if(a==='ff'){ const T=TOOLSIM[TP.L.page]; if(T.tick) for(let k=0;k<300;k++) T.tick(TP.st,1); tpTool(); return; }
  if(b.dataset.q!=null&&st){ const ok=typeof st.ok==='function'?st.ok(TP.st):st.ok; if(+b.dataset.q===ok){ TP.ok=true; TP.fb='✓ '+(typeof st.why==='function'?st.why(TP.st):st.why); } else { TP.ok=false; TP.errs++; TP.fb='✗ No es correcto. Piénsalo otra vez.'; if(typeof repAdd==='function'&&TP.L.id!=='repaso') repAdd(TP.L.id,TP.i); } tpPane(); return; }
  if(b.dataset.o!=null&&st){ const k=+b.dataset.o; if(k===TP.ord.sel.length){ TP.ord.sel.push(k); TP.fb=''; if(TP.ord.sel.length===st.items.length){ TP.ok=true; TP.fb='✓ Orden correcto. '+(st.why||''); } } else { TP.errs++; TP.ord.sel=[]; TP.ok=false; TP.fb='✗ Ese paso no va ahí. Empieza otra vez.'; } tpPane(); return; } });
// avance automático de los pasos «hazlo» y tiempo de las herramientas
let tpLast=performance.now();
setInterval(()=>{ const now=performance.now(), dt=Math.min(1,(now-tpLast)/1000); tpLast=now; if(stSel.mode!=='tool'||!TP.L||$('start').hidden) return; const T=TOOLSIM[TP.L.page];
  if(T.tick){ T.tick(TP.st,dt*(T.speed||1)); if(T.live) T.live($('tpTool'),TP.st); }
  const st=tpStep(); if(!st||st.info||st.quiz||st.order||!st.check) return; let ok=false; try{ ok=!!st.check(TP.st,TP.snap); }catch(e){}
  if(ok&&!TP.okAt){ TP.okAt=now; const w=$('tpWait'); if(w){ w.textContent='✓ ¡Bien hecho!'; w.classList.add('ok'); } }
  if(TP.okAt&&now-TP.okAt>1100) tpNext(); },250);
// las lecciones con página propia se abren con trStart como las demás
const _trStartTP=trStart; trStart=function(id,ref){ const L0=TRAIN.find(l=>l.id===id); if(L0&&L0.page){ tpOpen(L0); return; } _trStartTP(id,ref); };
const _rsTP=renderStart; renderStart=function(){ if(stSel.mode!=='tool'){ _rsTP(); return; } const body=$('stBody'); body.innerHTML=''; body.className='st-body st-vq1'; const st=$('start'); st.dataset.sv='q1'; st.dataset.mode='learn';
  const top=pkEl2('header','q1-top',`<div class="q1-brand"><span class="q1-logo">${LOGO}</span><div><b>Simulador de central frigorífica</b><small>Escuela de centrales · prácticas</small></div></div>`);
  top.appendChild(pBtn('q-btn',`${pic('home','pa')} Inicio`,()=>{ stSel.mode=null; TP.L=null; renderStart(); })); body.appendChild(top); renderTool(body); };

// ================= Repaso de lo que has fallado =================
const REPK='rep_v1'; const REPD=[1,3,7,14];
function repGet(){ try{ return JSON.parse(localStorage.getItem(REPK)||'[]'); }catch(e){ return []; } }
function repPut(a){ try{ localStorage.setItem(REPK,JSON.stringify(a)); }catch(e){} }
function repAdd(id,i){ const a=repGet(); const k=id+'#'+i; const x=a.find(r=>r.k===k); if(x){ x.lvl=0; x.due=Date.now(); } else a.push({k,id,i,lvl:0,due:Date.now(),t:'q'}); repPut(a); }
function repAddCase(id){ const a=repGet(); const k='case#'+id; const x=a.find(r=>r.k===k); if(x){ x.lvl=0; x.due=Date.now(); } else a.push({k,id,lvl:0,due:Date.now(),t:'c'}); repPut(a); }
function repAddTool(id){ const a=repGet(); const k='tool#'+id; if(!a.find(r=>r.k===k)){ a.push({k,id,lvl:0,due:Date.now(),t:'c'}); repPut(a); } }
function repOk(k){ const a=repGet(); const x=a.find(r=>r.k===k); if(!x) return; x.lvl++; if(x.lvl>=REPD.length+1){ repPut(a.filter(r=>r!==x)); return; } x.due=Date.now()+REPD[x.lvl-1]*86400000; repPut(a); }
function repBad(k){ const a=repGet(); const x=a.find(r=>r.k===k); if(x){ x.lvl=0; x.due=Date.now()+3600000; repPut(a); } }
const repQ=()=>repGet().filter(r=>r.t==='q'&&r.due<=Date.now()&&TRAIN.find(l=>l.id===r.id)&&(TRAIN.find(l=>l.id===r.id).steps||[])[r.i]);
const repC=()=>repGet().filter(r=>r.t==='c'&&TRAIN.find(l=>l.id===r.id));
// apuntar fallos en las preguntas y en los diagnósticos de la escuela
document.addEventListener('click',e=>{ const b=e.target.closest&&e.target.closest('#trPanel button'); if(!b||!TRN.L) return; const st=trStep(); if(!st) return;
  if(b.dataset.q!=null&&st.quiz){ const ok=typeof st.ok==='function'?st.ok():st.ok; if(+b.dataset.q!==ok&&TRN.L.steps===((TRAIN.find(l=>l.id===TRN.L.id)||{}).steps)) repAdd(TRN.L.id,TRN.i); }
  if((b.dataset.a==='diag'||b.dataset.x==='dg')&&(TRN.L.case||TRN.L.k)) setTimeout(()=>{ if(!TRN.fbok&&TRN.L) repAddCase(TRN.L.id); },0); },true);
// sesión de repaso: preguntas que fallaste, en una página propia
TOOLSIM.rep={init(){ return {}; },render(el){ el.innerHTML=`<div class="tp-rep">${dr('method')}<p>Estas preguntas son las que fallaste. Cada vez que aciertas una, vuelve a salir más tarde (1, 3, 7 y 14 días) hasta que la sabes de memoria.</p></div>`; }};
function repStart(){ const items=repQ().slice(0,12); if(!items.length) return; const steps=items.map(r=>{ const L=TRAIN.find(l=>l.id===r.id); const s=L.steps[r.i];
    return {quiz:true,t:()=>`<small class="tp-from">${L.n}</small><br>${typeof s.t==='function'?s.t():s.t}`,opts:()=>typeof s.opts==='function'?s.opts():s.opts,ok:()=>typeof s.ok==='function'?s.ok():s.ok,why:()=>{ return (typeof s.why==='function'?s.why():s.why); },rk:r.k}; });
  tpOpen({id:'repaso',sec:'base',page:'rep',n:'Repaso de tus fallos',steps}); }
// en el repaso, acertar a la primera sube de nivel; fallar lo vuelve a poner pronto
document.addEventListener('click',e=>{ const b=e.target.closest&&e.target.closest('#tpSide button'); if(!b||!TP.L||TP.L.id!=='repaso') return; const st=tpStep(); if(!st||b.dataset.q==null||TP.ok) return; const ok=+b.dataset.q===st.ok(); if(ok&&!st.failed) repOk(st.rk); else if(!ok){ st.failed=true; repBad(st.rk); } },true);

// ================= Herramienta: analizador digital (puente de manómetros), bomba de vacío, botella, recuperadora y nitrógeno =================
const MG={R404A:'R-404A',R134a:'R-134a',R410A:'R-410A'};
const mPs=(g,t)=>rel(FL(g).satT(K(t)).P), mTs=(g,p)=>C(FL(g).satP((Math.max(p,-0.95)+1.013)*1e5).T);
function mNew(sc){ const st={gas:'R404A',agas:'R404A',blue:'-',red:'-',yel:'-',vL:false,vH:false,run:false,pump:false,rec:false,bOpen:false,bInv:false,n2Open:false,n2Reg:0,pinza:'-',
  m:4,mt:4,vac:760000,moist:0,leak:false,n2:0,air:0,bot:12,recB:0,hoseAir:true,t:0,flags:{},vent:0,tAmb:25};
  ({run:()=>{ st.run=true; },stop:()=>{},empty:()=>{ st.m=0; },moist:()=>{ st.m=0; st.moist=1; },leak:()=>{ st.m=0; st.leak=true; },vacdone:()=>{ st.m=0; st.vac=380; },agas:()=>{ st.agas='R134a'; }})[sc||'run']?.();
  if(sc==='agas') st.run=true; return st; }
const mHasR=st=>st.m>0.05, mOpenL=st=>st.vL&&st.blue!=='-', mOpenH=st=>st.vH&&st.red!=='-', mOpen=st=>mOpenL(st)||mOpenH(st);
function mPress(st){ // presiones relativas del equipo (baja, alta)
  if(mHasR(st)){ const r=Math.min(1,st.m/st.mt), ps=Math.min(1,st.m/1.2);
    if(st.run){ const te=-10-16*(1-r), tc=40-5*(1-r)+(st.air>0.02?8*Math.min(1,st.air*4):0); return [mPs(st.gas,te),mPs(st.gas,tc)]; }
    const p=mPs(st.gas,st.tAmb)*ps; return [p,p]; }
  if(st.n2>0.05) return [st.n2,st.n2];
  const p=st.vac/760000*1.013-1.013; return [p,p]; }
function mWarnOnce(st,k,msg){ if(st.flags[k]) return; st.flags[k]=1; tpErr(msg); }
function mTick(st,dt){ st.t+=dt; const [pl]=mPress(st);
  const open=mOpen(st), both=mOpenL(st)&&mOpenH(st);
  if(both&&st.run&&st.blue!==st.red) mWarnOnce(st,'bypass','Con el equipo en marcha has abierto las dos llaves: comunicas la alta con la baja a través del puente.');
  // latiguillo amarillo suelto con llaves abiertas: se escapa
  if(open&&st.yel==='-'&&(mHasR(st)||st.n2>0.05)){ if(mHasR(st)){ mWarnOnce(st,'vent','¡Estás soltando refrigerante por el latiguillo amarillo! Cierra las llaves.'); const d=Math.min(st.m,0.05*dt); st.m-=d; st.vent+=d; } else { st.n2=Math.max(0,st.n2-0.6*dt); if(st.n2<=0.05){ st.n2=0; st.vac=760000; } } }
  // bomba de vacío
  if(st.yel==='pump'&&st.pump&&open){
    if(mHasR(st)){ mWarnOnce(st,'pumpR','Nunca hagas vacío con refrigerante dentro: lo estás soltando a la atmósfera. Primero se recupera.'); const d=Math.min(st.m,0.04*dt); st.m-=d; st.vent+=d; if(st.m<=0.05){ st.m=0; st.vac=600000; } }
    else if(st.n2>0.05){ st.n2=Math.max(0,st.n2-0.4*dt); if(st.n2<=0.05) st.vac=700000; }
    else { const k=(both?0.0055:0.003); const floor=st.moist>0?1800:150; st.vac=Math.max(floor,st.vac*Math.exp(-k*dt)); if(st.moist>0&&st.vac<6000) st.moist=Math.max(0,st.moist-0.0005*dt*(both?1.4:1)); } }
  else if(!mHasR(st)&&st.n2<=0.05){ // aislado: el vacío sube si hay fuga o humedad
    if(st.leak) st.vac=Math.min(760000,st.vac+35*dt); else if(st.moist>0&&st.vac<2600) st.vac+=(2600-st.vac)*0.004*dt; else if(st.vac<760000) st.vac+=0.03*dt; }
  // recuperadora
  if(st.yel==='rec'&&st.rec&&open&&mHasR(st)){ const d=Math.min(st.m,0.012*dt*(both?1.6:1)); st.m-=d; st.recB+=d; if(st.m<=0.05){ st.recB+=st.m; st.m=0; st.vac=300000; } if(st.recB>8) mWarnOnce(st,'rec80','La botella de recuperación pasa del 80 %: hay que cambiarla.'); }
  if(st.run&&st.m<0.6){ st.run=false; tpNote('El presostato de baja ha parado el equipo: no hay refrigerante suficiente.'); }
  // botella de refrigerante
  if(st.yel==='bot'&&st.bOpen&&open&&st.bot>0.3){ const pb=mPs(st.gas,st.tAmb);
    if(st.hoseAir){ st.hoseAir=false; st.air+=0.08; mWarnOnce(st,'purge','No has purgado el latiguillo amarillo: has metido el aire que tenía dentro del circuito.'); }
    const liq=st.bInv; if(pl<pb-0.3||!mHasR(st)||liq){ if(!liq&&(st.gas==='R404A'||st.gas==='R410A')) mWarnOnce(st,'blend',`El ${MG[st.gas]} es una mezcla: se carga en líquido (botella boca abajo o con buzo). En gas cambia su composición.`);
      if(liq&&st.run&&mOpenL(st)&&!mOpenH(st)) mWarnOnce(st,'liqLP','Cargar líquido por la baja con el compresor en marcha puede dar golpe de líquido. Se hace por la alta con el equipo parado (o con mucho cuidado, poco a poco).');
      const d=Math.min(st.bot-0.3,(liq?(pl<pb-0.3?0.004:0.0025):0.003)*dt); st.bot-=d; st.m+=d; if(st.m>0.05&&st.vac<760000) st.vac=760000; } }
  // nitrógeno
  if(st.yel==='n2'&&st.n2Open&&open){ if(mHasR(st)) mWarnOnce(st,'n2R','Antes de meter nitrógeno hay que recuperar el refrigerante.'); else { st.n2+=Math.sign(st.n2Reg-st.n2)*Math.min(Math.abs(st.n2Reg-st.n2),2*dt); if(st.n2>0.05) st.vac=760000; } }
  else if(st.n2>0.05&&st.leak&&!(st.yel==='n2'&&st.n2Open&&open)) st.n2=Math.max(0,st.n2-0.004*dt);
}
function mRead(st){ const [sl,sh0]=mPress(st); const side=v=>v==='lp'?sl:v==='hp'?sh0:0; const pl=side(st.blue), ph=side(st.red); const g=st.agas; const tl=mTs(g,pl), th=mTs(g,ph); const r=Math.min(1,st.m/st.mt);
  const sh=st.run&&mHasR(st)? 7+28*Math.pow(1-r,1.3) : null, sc=st.run&&mHasR(st)? Math.max(0,5*Math.pow(r,3)-(1-r)*2) : null;
  const tsR=mTs(st.gas,sl), thR=mTs(st.gas,sh0); let pz=null;
  if(st.pinza==='asp') pz=st.run?tsR+sh:st.tAmb; if(st.pinza==='liq') pz=st.run?thR-sc:st.tAmb;
  return {pl,ph,tl,th,pz,sh:st.pinza==='asp'&&pz!=null&&st.run?pz-tl:null,sc:st.pinza==='liq'&&pz!=null&&st.run?th-pz:null,vac:(!mHasR(st)&&st.n2<=0.05&&st.blue!=='-')?st.vac:null}; }
const f1=v=>v==null||!isFinite(v)?'—':v.toFixed(1).replace('.',','), f0=v=>v==null?'—':Math.round(v).toLocaleString('es-ES');
function mSvg(st){ const R=mRead(st); const port={lp:[205,250],hp:[205,120]}, acc={pump:[600,110],bot:[700,95],rec:[600,250],n2:[705,245]};
  const hose=(from,to,c)=>{ if(!to) return `<path d="M${from[0]} ${from[1]} q -6 30 ${-14} 38" fill="none" stroke="${c}" stroke-width="5" stroke-linecap="round"/>`; const [x,y]=to; return `<path d="M${from[0]} ${from[1]} C ${from[0]} ${from[1]+70}, ${x} ${y+90}, ${x} ${y+12}" fill="none" stroke="${c}" stroke-width="5" stroke-linecap="round"/>`; };
  const tgt=v=>v==='lp'?port.lp:v==='hp'?port.hp:acc[v]||null;
  const knob=(x,c,o,l)=>`<g class="m-k" data-m="${l}" style="cursor:pointer"><circle cx="${x}" cy="222" r="22" fill="${c}" stroke="#14212c" stroke-width="2"/><rect x="${x-4}" y="${o?200:214}" width="8" height="${o?44:16}" rx="3" fill="#fff" transform="${o?'':`rotate(90 ${x} 222)`}"/><text x="${x}" y="262" text-anchor="middle" font-size="11" font-weight="700">${l==='vL'?'BAJA':'ALTA'}</text><text x="${x}" y="276" text-anchor="middle" font-size="10" fill="${o?'#0e8a3e':'#6b7c8a'}">${o?'abierta':'cerrada'}</text></g>`;
  return `<svg viewBox="0 0 760 360" class="m-svg" font-family="inherit">
  <rect x="10" y="20" width="200" height="290" rx="12" fill="#eef3f8" stroke="#8a97a5" stroke-width="1.5"/><text x="110" y="42" text-anchor="middle" font-size="12" font-weight="700">Equipo (${MG[st.gas]})</text>
  <rect x="30" y="56" width="120" height="44" rx="6" fill="#fde3dc" stroke="#e0573c"/><text x="90" y="83" text-anchor="middle" font-size="10.5" font-weight="700">condensador</text>
  <circle cx="80" cy="190" r="34" fill="${st.run?'#d7f2e1':'#fff'}" stroke="#14212c" stroke-width="2"/><text x="80" y="187" text-anchor="middle" font-size="10.5" font-weight="700">compresor</text><text x="80" y="202" text-anchor="middle" font-size="10" fill="${st.run?'#0e8a3e':'#6b7c8a'}">${st.run?'en marcha':'parado'}</text>
  <path d="M150 78 H190 V120" stroke="#e8a33a" stroke-width="5" fill="none"/><path d="M114 190 H190 V250" stroke="#2f6fd0" stroke-width="5" fill="none"/>
  <circle cx="${port.hp[0]}" cy="${port.hp[1]}" r="9" fill="#d64545"/><text x="190" y="140" text-anchor="end" font-size="10" fill="#c4371f" font-weight="700">toma de alta</text>
  <circle cx="${port.lp[0]}" cy="${port.lp[1]}" r="9" fill="#2f6fd0"/><text x="190" y="274" text-anchor="end" font-size="10" fill="#2f6fd0" font-weight="700">toma de baja</text>
  ${st.pinza!=='-'?`<rect x="${st.pinza==='asp'?150:160}" y="${st.pinza==='asp'?180:66}" width="18" height="22" rx="4" fill="#e0573c"/><text x="${st.pinza==='asp'?159:169}" y="${st.pinza==='asp'?222:108}" text-anchor="middle" font-size="9" fill="#e0573c" font-weight="700">pinza</text>`:''}
  <rect x="290" y="16" width="240" height="300" rx="16" fill="#1d2b38" stroke="#0f1a24" stroke-width="2"/>
  <rect x="304" y="30" width="212" height="146" rx="8" fill="#cfe0c8"/>
  <g font-family="ui-monospace,Menlo,Consolas,monospace" font-size="12.5" fill="#132018">
   <text x="314" y="50" font-weight="700">${MG[st.agas]}</text><text x="506" y="50" text-anchor="end">${R.vac!=null?'VACÍO':''}</text>
   <text x="314" y="74">BAJA ${f1(R.pl)} bar</text><text x="506" y="74" text-anchor="end">${f1(R.tl)}°C</text>
   <text x="314" y="96">ALTA ${f1(R.ph)} bar</text><text x="506" y="96" text-anchor="end">${f1(R.th)}°C</text>
   <text x="314" y="120">${R.vac!=null?'MICRAS '+f0(R.vac):'PINZA '+(R.pz==null?'—':f1(R.pz)+'°C')}</text>
   <text x="314" y="142">${R.sh!=null?'SH (recalent.) '+f1(R.sh)+' K':R.sc!=null?'SC (subenfr.) '+f1(R.sc)+' K':''}</text>
   <text x="314" y="164" font-size="10.5">${st.n2>0.05?'N₂ en el circuito':''}</text></g>
  ${knob(350,'#2f6fd0',st.vL,'vL')}${knob(470,'#d64545',st.vH,'vH')}
  <text x="410" y="298" text-anchor="middle" font-size="9" fill="#9fb2c4">azul · amarillo · rojo</text>
  ${hose([350,316],tgt(st.blue),'#2f6fd0')}${hose([410,316],tgt(st.yel),'#e6c419')}${hose([470,316],tgt(st.red),'#d64545')}
  <circle cx="350" cy="316" r="6" fill="#2f6fd0"/><circle cx="410" cy="316" r="6" fill="#e6c419"/><circle cx="470" cy="316" r="6" fill="#d64545"/>
  <g font-size="10" text-anchor="middle">
   <rect x="565" y="70" width="70" height="40" rx="6" fill="${st.pump?'#d7f2e1':'#fff'}" stroke="#14212c"/><text x="600" y="88" font-weight="700">bomba</text><text x="600" y="101">${st.pump?'en marcha':'parada'}</text>
   <rect x="682" y="30" width="36" height="58" rx="12" fill="#9ccff0" stroke="#14212c" transform="${st.bInv?'rotate(180 700 59)':''}"/><rect x="670" y="88" width="60" height="10" fill="#8a97a5"/><text x="700" y="114" font-weight="700">${f1(st.bot)} kg</text><text x="700" y="126">${st.bOpen?'abierta':'cerrada'} · ${st.bInv?'líquido':'gas'}</text>
   <rect x="565" y="210" width="70" height="40" rx="6" fill="${st.rec?'#d7f2e1':'#fff'}" stroke="#14212c"/><text x="600" y="227" font-weight="700">recuperadora</text><text x="600" y="240">${st.rec?'en marcha':'parada'}</text><text x="600" y="266">botella ${f1(st.recB)} kg</text>
   <rect x="690" y="200" width="30" height="60" rx="10" fill="#5b6b7a" stroke="#14212c"/><text x="705" y="276" font-weight="700">N₂ ${st.n2Reg} bar</text><text x="705" y="288">${st.n2Open?'abierta':'cerrada'}</text></g></svg>`; }
TOOLSIM.manif={speed:60,
  init(L){ return mNew(L.scen); },
  tick(st,dt){ for(let k=0;k<Math.ceil(dt);k++) mTick(st,Math.min(1,dt-k)); },
  live(el,st){ const s=el.querySelector('.m-svg'); if(s) s.outerHTML=mSvg(st); },
  render(el,st){ const seg=(lbl,key,opts)=>`<div class="m-row"><span>${lbl}</span><div class="m-seg">${opts.map(([v,t])=>`<button data-m="${key}" data-v="${v}" class="${st[key]===v?'on':''}">${t}</button>`).join('')}</div></div>`;
    const tg=(key,on,off)=>`<button data-m="${key}" class="m-tg ${st[key]?'on':''}">${st[key]?on:off}</button>`;
    el.innerHTML=mSvg(st)+`<div class="m-ctl">
      ${seg('Latiguillo azul','blue',[['-','suelto'],['lp','toma de baja'],['hp','toma de alta']])}
      ${seg('Latiguillo rojo','red',[['-','suelto'],['lp','toma de baja'],['hp','toma de alta']])}
      ${seg('Latiguillo amarillo','yel',[['-','suelto'],['pump','bomba de vacío'],['bot','botella'],['rec','recuperadora'],['n2','nitrógeno']])}
      <div class="m-row"><span>Llaves del puente</span><div class="m-btns">${tg('vL','Cerrar llave de BAJA','Abrir llave de BAJA')}${tg('vH','Cerrar llave de ALTA','Abrir llave de ALTA')}</div></div>
      <div class="m-row"><span>Equipo y accesorios</span><div class="m-btns">${tg('run','Parar el equipo','Arrancar el equipo')}${tg('pump','Parar la bomba','Arrancar la bomba')}${tg('rec','Parar la recuperadora','Arrancar la recuperadora')}</div></div>
      <div class="m-row"><span>Botella de refrigerante</span><div class="m-btns">${tg('bOpen','Cerrar la botella','Abrir la botella')}${tg('bInv','Ponerla boca arriba (gas)','Ponerla boca abajo (líquido)')}<button data-m="purge">Purgar el latiguillo amarillo</button></div></div>
      <div class="m-row"><span>Nitrógeno</span><div class="m-btns"><button data-m="n2d">− 5 bar</button><button data-m="n2u">+ 5 bar</button>${tg('n2Open','Cerrar el nitrógeno','Abrir el nitrógeno')}</div></div>
      ${seg('Pinza termométrica','pinza',[['-','quitada'],['asp','en la aspiración'],['liq','en la línea de líquido']])}
      ${seg('Gas del analizador','agas',[['R404A','R-404A'],['R134a','R-134a'],['R410A','R-410A']])}
      <div class="m-row"><span>Tiempo</span><div class="m-btns"><button data-m="ff">Adelantar 5 min</button><button data-m="ff2">Adelantar 15 min</button></div></div></div>`; }};
document.addEventListener('click',e=>{ const b=e.target.closest&&e.target.closest('#tpTool [data-m]'); if(!b||!TP.L||TP.L.page!=='manif') return; const st=TP.st, k=b.dataset.m; TP.msg='';
  if(b.dataset.v!=null){ const v=b.dataset.v; if(['blue','red','yel'].includes(k)&&st[k]!==v){ const side=k==='blue'?st.vL:k==='red'?st.vH:(st.vL||st.vH);
      if(side&&(mHasR(st)||st.n2>0.3)&&st[k]!=='-') tpErr('Has soltado un latiguillo con la llave abierta: se escapa gas. Cierra las llaves antes de desconectar.');
      if(k==='yel'){ st.hoseAir=true; if(v!=='pump') st.pump=false; if(v!=='rec') st.rec=false; } }
    st[k]=v; }
  else if(k==='purge'){ if(st.yel==='bot'&&st.bOpen){ st.hoseAir=false; tpNote('Latiguillo purgado: has echado el aire con un poco de gas antes de abrir la llave.'); } else tpNote('Para purgar, conecta el amarillo a la botella y ábrela.'); }
  else if(k==='n2u') st.n2Reg=Math.min(40,st.n2Reg+5); else if(k==='n2d') st.n2Reg=Math.max(0,st.n2Reg-5);
  else if(k==='ff'||k==='ff2'){ const n=k==='ff'?300:900; for(let i=0;i<n;i++) mTick(st,1); }
  else if(k==='run'){ if(!st.run&&st.m<0.6){ tpNote('No arranca: no hay refrigerante suficiente (presostato de baja).'); } else if(!st.run&&st.n2>0.05){ tpNote('Con nitrógeno dentro no se arranca el equipo.'); } else st.run=!st.run; }
  else if(k==='pump'){ if(!st.pump&&st.yel!=='pump'){ tpNote('Primero conecta el latiguillo amarillo a la bomba de vacío.'); } else st.pump=!st.pump; }
  else if(k==='rec'){ if(!st.rec&&st.yel!=='rec'){ tpNote('Primero conecta el latiguillo amarillo a la recuperadora.'); } else st.rec=!st.rec; }
  else if(['vL','vH','bOpen','bInv','n2Open'].includes(k)) st[k]=!st[k];
  tpTool(); });
// ---------- lecciones de herramientas
const mStep=(t,check,o)=>Object.assign({t,check},o||{});
[
 {id:'h1',n:'Conoce el analizador digital',d:'Qué es cada parte del puente de manómetros y cómo se elige el gas.',scen:'agas',steps:[
   {info:true,t:'El <b>analizador</b> (o puente de manómetros) tiene dos llaves: <b>BAJA</b> (azul) y <b>ALTA</b> (roja), y tres latiguillos: <b>azul</b> a la toma de baja, <b>rojo</b> a la toma de alta y <b>amarillo</b> al servicio (bomba, botella, recuperadora o nitrógeno).'},
   {info:true,t:'Con las llaves <b>cerradas</b>, cada manómetro lee su lado del equipo. Las llaves solo se abren para pasar gas por el amarillo: hacer vacío, cargar o recuperar.'},
   mStep('El analizador está puesto en R-134a, pero el equipo es de <b>R-404A</b>. Elige el gas correcto abajo, en «Gas del analizador».',st=>st.agas==='R404A'),
   {quiz:true,t:'¿Qué pasa si el analizador tiene puesto otro gas?',opts:['Nada','Las presiones salen bien pero las temperaturas de saturación (y el recalentamiento) salen mal','Se rompe'],ok:1,why:'El analizador pasa la presión a temperatura con la tabla del gas elegido: con el gas equivocado, todas las temperaturas están mal.'}]},
 {id:'h2',n:'Medir presiones con el equipo en marcha',d:'Conectar los latiguillos sin soltar gas y leer alta y baja.',scen:'run',steps:[
   mStep('Conecta el latiguillo <b>azul</b> a la <b>toma de baja</b>, con las llaves cerradas.',st=>st.blue==='lp'&&!st.vL),
   mStep('Conecta el latiguillo <b>rojo</b> a la <b>toma de alta</b>.',st=>st.red==='hp'&&!st.vH),
   {quiz:true,t:st=>{ const R=mRead(st); return `El analizador marca baja ${f1(R.pl)} bar (${f1(R.tl)} °C) y alta ${f1(R.ph)} bar (${f1(R.th)} °C). ¿Qué es ${f1(R.tl)} °C?`; },opts:['La temperatura de la cámara','La temperatura de evaporación','La temperatura del compresor'],ok:1,why:'La presión de baja pasada a temperatura es la temperatura a la que hierve el refrigerante en el evaporador.'},
   {quiz:true,t:'Para leer presiones, ¿tienes que abrir las llaves del puente?',opts:['Sí, las dos','No: con las llaves cerradas cada manómetro ya lee su lado','Solo la de alta'],ok:1,why:'Si abres las dos con el equipo en marcha comunicas alta y baja; si el amarillo está suelto, sueltas gas.'},
   mStep('Para terminar, desconecta los dos latiguillos (déjalos «sueltos»).',st=>st.blue==='-'&&st.red==='-')]},
 {id:'h3',n:'Recalentamiento y subenfriamiento con la pinza',d:'Poner la pinza termométrica y leerlos en el analizador.',scen:'run',steps:[
   mStep('Conecta el azul a la toma de baja y el rojo a la de alta.',st=>st.blue==='lp'&&st.red==='hp'),
   mStep('Pon la <b>pinza termométrica en la aspiración</b> (tubo que va al compresor).',st=>st.pinza==='asp'),
   {quiz:true,t:st=>{ const R=mRead(st); return `El analizador calcula el recalentamiento: ${f1(R.sh)} K. ¿Es correcto?`; },opts:['Sí, está entre 5 y 10 K','No, es muy alto','No, entra líquido'],ok:0,why:'Con el equipo bien cargado el recalentamiento está entre 5 y 10 K.'},
   mStep('Ahora pon la pinza en la <b>línea de líquido</b>.',st=>st.pinza==='liq'),
   {quiz:true,t:st=>{ const R=mRead(st); return `Subenfriamiento: ${f1(R.sc)} K. ¿Qué indica?`; },opts:['Que llega líquido sin burbujas a la válvula: carga correcta','Falta de gas','Exceso de aceite'],ok:0,why:'Entre 3 y 6 K de subenfriamiento la carga está bien.'}]},
 {id:'h4',n:'Hacer el vacío',d:'Del circuito abierto a menos de 500 micras.',scen:'empty',steps:[
   {info:true,t:'El equipo acaba de repararse: está abierto, lleno de aire y sin refrigerante. Antes de cargar hay que hacer <b>vacío</b> para sacar aire y humedad.'+dr('vacuum')},
   mStep('Conecta el azul a la toma de baja, el rojo a la de alta y el amarillo a la <b>bomba de vacío</b>.',st=>st.blue==='lp'&&st.red==='hp'&&st.yel==='pump'),
   mStep('Abre las <b>dos llaves</b> del puente (así se hace vacío por los dos lados, más rápido) y arranca la bomba.',st=>st.vL&&st.vH&&st.pump),
   mStep('Adelanta tiempo hasta bajar de <b>500 micras</b>.',st=>st.vac<500,{ff:true}),
   mStep('Ahora cierra las dos llaves y para la bomba (en este orden: primero las llaves).',st=>!st.vL&&!st.vH&&!st.pump),
   mStep('Espera 15 minutos (Adelantar) y mira si el vacío se mantiene.',(st,s)=>st.t-s>=880,{init:st=>st.t,ff:true}),
   {quiz:true,t:st=>`El vacío ha subido a ${f0(st.vac)} micras en 15 minutos. ¿Cómo está el circuito?`,opts:['Estanco y seco: se puede cargar','Tiene fuga','Tiene humedad'],ok:0,why:'Si se mantiene por debajo de unas 1000 micras, el circuito está bien.'}]},
 {id:'h5',n:'Vacío con humedad y con fuga',d:'Cómo distinguirlas mirando el vacuómetro.',scen:'moist',steps:[
   mStep('Este circuito tiene humedad. Conecta azul, rojo y amarillo a la bomba, abre las llaves y arranca la bomba.',st=>st.blue==='lp'&&st.red==='hp'&&st.yel==='pump'&&st.vL&&st.vH&&st.pump),
   mStep('Adelanta 15 minutos: verás que se queda parado alrededor de 1800 micras.',(st,s)=>st.t-s>=880,{init:st=>st.t,ff:true}),
   {quiz:true,t:'El vacío no baja de unas 1800 micras. ¿Qué hay?',opts:['Humedad: se está evaporando el agua','Una fuga grande','Está perfecto'],ok:0,why:'Con humedad el vacío se para un rato mientras el agua hierve. Hay que seguir (y a veces romper con nitrógeno seco y repetir).'},
   mStep('Sigue haciendo vacío hasta bajar de 500 micras.',st=>st.vac<500,{ff:true}),
   {quiz:true,t:'Si al cerrar las llaves el vacío subiera sin parar hasta la presión atmosférica, ¿qué sería?',opts:['Humedad','Fuga','Normal'],ok:1,why:'La humedad sube hasta un valor y se para; una fuga sigue subiendo.'}]},
 {id:'h6',n:'Cargar refrigerante por peso',d:'Con la báscula, en líquido y por la alta.',scen:'vacdone',steps:[
   {info:true,t:'El circuito tiene el vacío hecho. La placa del equipo dice: <b>4,0 kg de R-404A</b>. El R-404A es una mezcla: se carga <b>en líquido</b>, por la <b>alta</b> y con el equipo <b>parado</b>.'},
   mStep('Conecta el azul a la baja, el rojo a la alta y el amarillo a la <b>botella</b>.',st=>st.blue==='lp'&&st.red==='hp'&&st.yel==='bot'),
   mStep('Pon la botella <b>boca abajo (líquido)</b>, ábrela y <b>purga el latiguillo amarillo</b>.',st=>st.bInv&&st.bOpen&&!st.hoseAir),
   mStep('Abre la llave de <b>ALTA</b> y deja pasar hasta que la báscula marque 4 kg menos (de 12 a 8 kg). Usa «Adelantar».',st=>st.bot<=8.05,{ff:true}),
   mStep('Cierra la llave de alta y la botella.',st=>!st.vH&&!st.bOpen),
   mStep('Arranca el equipo y pon la pinza en la aspiración para ver el recalentamiento.',st=>st.run&&st.pinza==='asp'),
   {quiz:true,t:st=>{ const R=mRead(st); return `Recalentamiento: ${f1(R.sh)} K con ${f1(st.m)} kg dentro. ¿Está bien la carga?`; },opts:['Sí','No, falta mucho gas'],ok:st=>st.m>=3.6?0:1,why:st=>st.m>=3.6?'Has cargado lo que pide la placa: el recalentamiento sale normal.':'Con poca carga el recalentamiento sube mucho.'}]},
 {id:'h7',n:'Recuperar el refrigerante',d:'Vaciar el equipo sin soltar gas a la atmósfera.',scen:'stop',steps:[
   {info:true,t:'Hay que cambiar un componente: antes se <b>recupera</b> todo el refrigerante en una botella de recuperación (nunca más del 80 %).'},
   mStep('Conecta azul a la baja, rojo a la alta y amarillo a la <b>recuperadora</b>.',st=>st.blue==='lp'&&st.red==='hp'&&st.yel==='rec'),
   mStep('Abre las dos llaves y arranca la recuperadora.',st=>st.vL&&st.vH&&st.rec),
   mStep('Adelanta tiempo hasta que el equipo quede vacío (la presión baja de 0 bar).',st=>st.m<=0.05,{ff:true}),
   mStep('Cierra las llaves y para la recuperadora.',st=>!st.vL&&!st.vH&&!st.rec),
   {quiz:true,t:st=>`La botella de recuperación tiene ${f1(st.recB)} kg. ¿Qué se hace con ella?`,opts:['Se suelta al aire','Se etiqueta y se entrega a un gestor autorizado (o se reutiliza si es el mismo equipo y está limpio)','Se tira'],ok:1,why:'El refrigerante recuperado nunca se suelta: se etiqueta con el gas y se gestiona.'}]},
 {id:'h8',n:'Prueba de presión con nitrógeno',d:'Comprobar que no hay fugas antes del vacío.',scen:'empty',steps:[
   mStep('Conecta azul a la baja, rojo a la alta y amarillo al <b>nitrógeno</b>.',st=>st.blue==='lp'&&st.red==='hp'&&st.yel==='n2'),
   mStep('Sube el regulador a <b>15 bar</b>, abre el nitrógeno y las dos llaves.',st=>st.n2Reg===15&&st.n2Open&&st.vL&&st.vH),
   mStep('Espera a que la presión llegue a 15 bar y cierra las llaves y el nitrógeno.',st=>st.n2>=14.5&&!st.vL&&!st.vH&&!st.n2Open,{ff:true}),
   mStep('Espera 15 minutos y comprueba que la presión no baja.',(st,s)=>st.t-s>=880,{init:st=>st.t,ff:true}),
   {quiz:true,t:st=>`Después de 15 min marca ${f1(st.n2)} bar. ¿Hay fuga?`,opts:['No: se mantiene','Sí'],ok:0,why:'Si baja, se buscan las fugas con espuma. Ojo: la presión también cambia con la temperatura.'},
   mStep('Suelta el nitrógeno: conecta el amarillo «suelto» (con las llaves cerradas) y abre una llave para vaciar.',st=>st.n2<=0.1,{ff:true})]},
 {id:'h9',n:'Práctica libre con las herramientas',d:'Todo el material a mano para practicar lo que quieras.',scen:'run',steps:[],free:'Práctica libre. El equipo está cargado y en marcha. Prueba a medir, recuperar, hacer vacío, probar con nitrógeno y cargar. Si haces algo peligroso o mal, te avisa abajo.'},
].forEach(l=>TRAIN.push(Object.assign({sec:'herr',ref:'any',page:'manif',meta:'Práctica con el analizador'},l)));

// ================= Herramienta: cableado de un mueble (termostato TR-3, cargas y polímetro) =================
const WB=[[1,'L','alimentación'],[2,'N','alimentación'],[3,'FRÍO','salida'],[4,'DESC.','salida'],[5,'VENT.','salida'],[6,'Pb1',''],[7,'Pb1',''],[8,'Pb2',''],[9,'Pb2',''],[10,'PUERTA',''],[11,'PUERTA','']];
const WL=[['Lc','Fase L del cuadro'],['Nc','Neutro N del cuadro'],['YVa','Solenoide (cable 1)'],['YVb','Solenoide (cable 2)'],['Ra','Resistencias (cable 1)'],['Rb','Resistencias (cable 2)'],['Ma','Ventiladores (cable 1)'],['Mb','Ventiladores (cable 2)'],['P1a','Sonda cámara Pb1 (1)'],['P1b','Sonda cámara Pb1 (2)'],['P2a','Sonda evaporador Pb2 (1)'],['P2b','Sonda evaporador Pb2 (2)'],['Da','Contacto de puerta (1)'],['Db','Contacto de puerta (2)']];
const WOK={Lc:['b1'],Nc:['b2'],YVa:['b3'],Ra:['b4'],Ma:['b5'],YVb:['n'],Rb:['n'],Mb:['n'],P1a:['b6','b7'],P1b:['b6','b7'],P2a:['b8','b9'],P2b:['b8','b9'],Da:['b10','b11'],Db:['b10','b11']};
const WGOOD={Lc:'b1',Nc:'b2',YVa:'b3',YVb:'n1',Ra:'b4',Rb:'n2',Ma:'b5',Mb:'n3',P1a:'b6',P1b:'b7',P2a:'b8',P2b:'b9',Da:'b10',Db:'b11'};
const WOHM={YV:1200,R:46,M:180,P1:26000,P2:30000,D:0};
function wNew(L){ const st={con:{},sel:null,pwr:false,mode:'V',pa:null,pb:null,last:null,fault:L.fault||null,checked:false,demand:{3:true,4:false,5:true}};
  if(L.prewired){ Object.assign(st.con,WGOOD); } return st; }
const wPt=k=>{ if(k[0]==='b'){ const i=+k.slice(1); return [52+(i-1)*58,92]; } if(k[0]==='n'){ return [430+(+k.slice(1))*42,236]; } const i=WL.findIndex(x=>x[0]===k); const lx=[[60,300],[120,300],[40,370],[90,370],[160,370],[210,370],[280,370],[330,370],[400,370],[450,370],[520,370],[570,370],[640,370],[690,370]][i]; return lx; };
function wErrors(st){ const e=[]; WL.forEach(([k,n])=>{ const t=st.con[k]; if(!t) e.push(`${n}: sin conectar`); else if(!WOK[k].some(x=>x==='n'?t[0]==='n':x===t)) e.push(`${n}: mal conectado`); });
  const used={}; Object.values(st.con).forEach(t=>{ if(t[0]==='b') used[t]=(used[t]||0)+1; }); Object.entries(used).forEach(([t,c])=>{ if(c>1) e.push(`Borne ${t.slice(1)}: tiene ${c} cables`); });
  ['P1','P2','D'].forEach(p=>{ const a=st.con[p+'a'], b=st.con[p+'b']; if(a&&b&&a===b) e.push(`${p}: los dos cables en el mismo borne`); }); return e; }
// potenciales con tensión: 'L', 'N' o null
function wPot(st,k){ if(!st.pwr) return null; const f=st.fault; const L=st.con.Lc==='b1', N=st.con.Nc==='b2'; const on=L&&N;
  const term=t=>{ if(!t) return null; if(t[0]==='n') return 'N'; if(t==='b1') return L?'L':null; if(t==='b2') return N?'N':null; const i=+t.slice(1); if([3,4,5].includes(i)) return on&&st.demand[i]?'L':null; return null; };
  if(k[0]==='b'||k[0]==='n') return term(k);
  const load=k.replace(/[ab]$/,''), end=k.slice(-1); if(!['YV','R','M'].includes(load)) return null;
  let pa=term(st.con[load+'a']), pb=term(st.con[load+'b']);
  if(f==='yvcut'&&load==='YV') pa=null; if(f==='ncut'&&load==='M') pb=null;
  if(end==='a') return pa??(pb&&f!=='rburn'?pb:null); return pb??(pa&&!(f==='rburn'&&load==='R')?pa:null); }
function wV(st,a,b){ const x=wPot(st,a), y=wPot(st,b); if(!x||!y||x===y) return 0; return 230; }
function wR(st,a,b){ if(st.pwr) return null; const f=st.fault; // resistencia sin tensión: solo cuenta lo que hay entre los dos puntos
  const node=k=>{ if(k[0]==='b'||k[0]==='n') return k[0]==='n'?'n':k; return k; };
  const E=[]; Object.entries(st.con).forEach(([w,t])=>{ if(f==='yvcut'&&w==='YVa') return; if(f==='ncut'&&w==='Mb') return; E.push([w,t[0]==='n'?'n':t,0]); });
  [['YV',WOHM.YV],['R',f==='rburn'?Infinity:WOHM.R],['M',WOHM.M],['P1',WOHM.P1],['P2',WOHM.P2],['D',0]].forEach(([l,r])=>{ if(r<Infinity) E.push([l+'a',l+'b',r]); });
  const A=node(a), B=node(b); if(A===B) return 0; const adj={}; E.forEach(([x,y,w])=>{ (adj[x]=adj[x]||[]).push([y,w]); (adj[y]=adj[y]||[]).push([x,w]); });
  const dist={[A]:0}, q=[A]; while(q.length){ q.sort((u,v)=>dist[u]-dist[v]); const u=q.shift(); if(u===B) return dist[u]; (adj[u]||[]).forEach(([v,w])=>{ const d=dist[u]+w; if(dist[v]==null||d<dist[v]){ dist[v]=d; q.push(v); } }); } return Infinity; }
const wName=k=>k[0]==='b'?'borne '+k.slice(1):k[0]==='n'?'barra de neutro':WL.find(x=>x[0]===k)[1];
function wSvg(st){ let s=`<svg viewBox="0 0 760 420" class="w-svg"><rect x="20" y="20" width="660" height="110" rx="12" fill="#2a3440"/><text x="34" y="42" font-size="12" font-weight="700" fill="#fff">TR-3 · bornes traseros</text>`;
  WB.forEach(([i,t,g])=>{ const [x,y]=wPt('b'+i); const k='b'+i; s+=`<g class="w-t${st.sel?' can':''}" data-w="${k}"><rect x="${x-22}" y="${y-22}" width="44" height="40" rx="5" fill="#d9dee3" stroke="${st.pa===k||st.pb===k?'#ff8a00':'#14212c'}" stroke-width="${st.pa===k||st.pb===k?3:1}"/><circle cx="${x}" cy="${y}" r="8" fill="#9aa5b1" stroke="#14212c"/><text x="${x}" y="${y-28}" text-anchor="middle" font-size="12" font-weight="700" fill="#fff">${i}</text><text x="${x}" y="${y+33}" text-anchor="middle" font-size="9.5" font-weight="700" fill="#cfe0f2">${t}</text></g>`; });
  s+=`<text x="34" y="160" font-size="10" fill="#6b7c8a">Bornes 3, 4 y 5: salidas de relé que dan 230 V (fase) cuando se activan.</text>`;
  s+=`<rect x="440" y="214" width="190" height="44" rx="6" fill="#2f6fd0"/><text x="535" y="274" text-anchor="middle" font-size="10.5" font-weight="700">barra de neutro (N)</text>`;
  [1,2,3,4].forEach(j=>{ const k='n'+j, [x,y]=wPt(k); s+=`<g class="w-t" data-w="${k}"><circle cx="${x}" cy="${y}" r="10" fill="#cfe0f2" stroke="${st.pa===k||st.pb===k?'#ff8a00':'#14212c'}" stroke-width="${st.pa===k||st.pb===k?3:1}"/></g>`; });
  // cables conectados
  Object.entries(st.con).forEach(([w,t])=>{ const [x1,y1]=wPt(w), [x2,y2]=wPt(t); const col=w==='Lc'?'#8b4513':w==='Nc'||w.endsWith('b')&&['YVb','Rb','Mb'].includes(w)?'#2f6fd0':w.startsWith('P')?'#555':w.startsWith('D')?'#777':'#8b4513';
    const loose=(st.fault==='yvcut'&&w==='YVa')||(st.fault==='ncut'&&w==='Mb'); s+=`<path d="M${x1} ${y1-8} C ${x1} ${y1-80}, ${x2} ${y2+90}, ${x2} ${y2+(t[0]==='b'?18:10)}" fill="none" stroke="${col}" stroke-width="3.5" ${loose?'stroke-dasharray="2 5"':''}/>`; });
  // cargas
  const grp=[['L / N del cuadro',['Lc','Nc'],'#fff2dc'],['Solenoide',['YVa','YVb'],'#e6f0fb'],['Resistencias',['Ra','Rb'],'#fde3dc'],['Ventiladores',['Ma','Mb'],'#e3f6f3'],['Sonda Pb1',['P1a','P1b'],'#efe8ff'],['Sonda Pb2',['P2a','P2b'],'#efe8ff'],['Puerta',['Da','Db'],'#eef0f3']];
  grp.forEach(([n,ws,c])=>{ const [x1,y1]=wPt(ws[0]), [x2]=wPt(ws[1]); const work=st.pwr&&['YVa','Ra','Ma'].includes(ws[0])&&wV(st,ws[0],ws[1])===230; s+=`<rect x="${x1-26}" y="${y1+12}" width="${x2-x1+52}" height="36" rx="8" fill="${work?'#c9f1d6':c}" stroke="#14212c"/><text x="${(x1+x2)/2}" y="${y1+34}" text-anchor="middle" font-size="10" font-weight="700">${n}${work?' ✓':''}</text>`;
    ws.forEach(w=>{ const [x,y]=wPt(w); const on=st.sel===w; s+=`<g class="w-e" data-w="${w}" style="cursor:pointer"><circle cx="${x}" cy="${y}" r="${on?10:8}" fill="${on?'#ff8a00':st.con[w]?'#3aa65b':'#fff'}" stroke="${st.pa===w||st.pb===w?'#ff8a00':'#14212c'}" stroke-width="${st.pa===w||st.pb===w?3:1.5}"/></g>`; }); });
  if(st.pwr){ const dsp=wDisplay(st); s+=`<rect x="560" y="150" width="120" height="40" rx="6" fill="#140b07"/><text x="620" y="178" text-anchor="middle" font-size="20" font-weight="700" fill="#ff3b2f" font-family="ui-monospace,Menlo,monospace">${dsp}</text>`; }
  return s+'</svg>'; }
function wDisplay(st){ if(st.con.Lc!=='b1'||st.con.Nc!=='b2') return ''; const p1=['P1a','P1b'].every(w=>['b6','b7'].includes(st.con[w])), p1on8=['P1a','P1b'].every(w=>['b8','b9'].includes(st.con[w])); if(st.fault==='swap'||p1on8) return '-24'; if(!p1) return 'E1'; return '3.8'; }
function wMeter(st){ if(!st.pa||!st.pb) return '—'; if(st.mode==='V') return wV(st,st.pa,st.pb)+' V'; const r=wR(st,st.pa,st.pb); if(r==null) return '¡Quita tensión!'; return !isFinite(r)?'OL':r>=1000?(r/1000).toFixed(1).replace('.',',')+' kΩ':Math.round(r)+' Ω'; }
TOOLSIM.wire={
  init(L){ return wNew(L); },
  render(el,st){ const L=TP.L; const meter=L.meter;
    el.innerHTML=wSvg(st)+`<div class="m-ctl">
      ${L.meter?'':`<div class="m-row"><span>Cablear</span><div class="m-btns w-help">${st.sel?`Cable elegido: <b>${wName(st.sel)}</b> → ahora pulsa el borne o la barra de neutro`:'Pulsa el extremo de un cable (círculo de abajo) y luego el borne donde va.'}</div></div>
      <div class="m-row"><span>Comprobar</span><div class="m-btns"><button data-wb="check">Comprobar el cableado</button><button data-wb="clear">Quitar todos los cables</button></div></div>`}
      <div class="m-row"><span>Tensión</span><div class="m-btns"><button data-wb="pwr" class="m-tg ${st.pwr?'on':''}">${st.pwr?'Quitar tensión':'Dar tensión'}</button></div></div>
      ${meter?`<div class="m-row"><span>Polímetro</span><div class="m-seg"><button data-wb="mV" class="${st.mode==='V'?'on':''}">V (tensión)</button><button data-wb="mR" class="${st.mode==='R'?'on':''}">Ω (resistencia)</button></div></div>
      <div class="m-row"><span>Puntas</span><div class="m-btns w-help">Roja: <b>${st.pa?wName(st.pa):'—'}</b> · Negra: <b>${st.pb?wName(st.pb):'—'}</b> · pulsa bornes, cables o la barra N</div></div>
      <div class="w-meter">${wMeter(st)}</div>`:''}</div>`; }};
document.addEventListener('click',e=>{ if(!TP.L||TP.L.page!=='wire') return; const st=TP.st; const g=e.target.closest&&e.target.closest('#tpTool [data-w]'); const b=e.target.closest&&e.target.closest('#tpTool [data-wb]'); if(!g&&!b) return; TP.msg='';
  if(g){ const k=g.dataset.w;
    if(TP.L.meter){ if(!st.pa||st.pb){ st.pa=k; st.pb=null; } else { st.pb=k; st.last={a:st.pa,b:st.pb,mode:st.mode,val:wMeter(st)}; } }
    else if(g.classList.contains('w-e')){ st.sel=st.sel===k?null:k; }
    else if(st.sel){ if(st.pwr){ tpErr('Nunca cablees con tensión: quítala primero.'); }
      const w=st.sel; if(/^P|^D/.test(w)&&['b1','b2','b3','b4','b5'].includes(k)) tpErr('¡Una sonda o el contacto de puerta en un borne de 230 V se queman! Esos van a sus bornes de entrada (6 a 11).');
      st.con[w]=k; st.sel=null; st.checked=false; } }
  else { const a=b.dataset.wb;
    if(a==='check'){ const er=wErrors(st); st.checked=er.length===0; TP.msg=er.length?'✗ '+er.length+' fallo(s): '+er.slice(0,4).join(' · ')+(er.length>4?'…':''):'✓ Todo el cableado es correcto.'; if(er.length) TP.errs++; }
    if(a==='clear'){ st.con={}; st.sel=null; st.checked=false; }
    if(a==='pwr'){ if(!st.pwr&&!TP.L.meter){ const er=wErrors(st); if(er.length){ tpErr('Has dado tensión con el cableado mal: '+er[0]+'. Comprueba antes de dar tensión.'); } } st.pwr=!st.pwr; }
    if(a==='mV') st.mode='V'; if(a==='mR') st.mode='R'; if(st.pa&&st.pb) st.last={a:st.pa,b:st.pb,mode:st.mode,val:wMeter(st)}; }
  tpTool(); });
const wMeas=(a,b,mode)=>st=>st.last&&st.last.mode===mode&&[st.last.a,st.last.b].sort().join()===[a,b].sort().join();
const wIsN=k=>k&&k[0]==='n';
const wMeasN=(a,mode)=>st=>st.last&&st.last.mode===mode&&((st.last.a===a&&wIsN(st.last.b))||(st.last.b===a&&wIsN(st.last.a)));
[
 {id:'e19',n:'Las bornas de un termostato',d:'Qué va en cada borne de un termostato de mueble.',steps:[
   {info:true,t:'Por detrás el termostato tiene una <b>regleta de bornes</b>. En este TR-3: <b>1-2</b> alimentación (fase y neutro), <b>3</b> salida de frío (solenoide), <b>4</b> salida de desescarche (resistencias), <b>5</b> salida de ventiladores, <b>6-7</b> sonda de cámara, <b>8-9</b> sonda de evaporador y <b>10-11</b> contacto de puerta.'},
   {info:true,t:'Las salidas 3, 4 y 5 son <b>relés</b>: cuando se activan dan la fase (230 V). El otro cable de cada carga va a la <b>barra de neutro</b>. Las sondas y la puerta son <b>entradas</b>: van a sus bornes y nunca deben recibir 230 V.'},
   {quiz:true,t:'¿Dónde conectas el segundo cable de la solenoide?',opts:['En el borne 4','En la barra de neutro','En el borne 6'],ok:1,why:'El borne 3 le da la fase y el neutro le llega por la barra.'},
   {quiz:true,t:'¿Qué pasa si conectas una sonda en el borne 3?',opts:['Nada','Cuando se active el frío le llegan 230 V y se quema la sonda (y puede dañar el termostato)','Marca mejor'],ok:1,why:'Las sondas trabajan con muy poca tensión; 230 V las destruye.'}]},
 {id:'e20',n:'Cablea un mueble',d:'Conecta tú todos los cables del termostato y comprueba.',steps:[
   {info:true,t:'Vas a cablear el mueble desde cero. Pulsa el extremo de un cable (los círculos de abajo) y después el borne donde va. Los cables de vuelta de solenoide, resistencias y ventiladores van a la <b>barra de neutro</b>.'},
   {t:'Conecta todos los cables. Cuando termines, pulsa «Comprobar el cableado».',check:st=>st.checked},
   {t:'Ahora da tensión: el termostato se enciende y como pide frío se activan la solenoide y los ventiladores (se ponen en verde).',check:st=>st.pwr&&st.checked},
   {quiz:true,t:'¿Por qué no se activa la resistencia?',opts:['Porque está mal conectada','Porque ahora el termostato no está en desescarche: la salida 4 está abierta','Porque falta neutro'],ok:1,why:'Cada salida solo da tensión cuando el termostato la activa.'}]},
 {id:'e21',n:'Avería: la solenoide no abre',d:'Con el polímetro, encuentra dónde se pierde la tensión.',fault:'yvcut',prewired:true,meter:true,steps:[
   {info:true,t:'El mueble pide frío pero la solenoide no abre. Tienes el polímetro: pulsa un punto (punta roja) y luego otro (punta negra).'},
   {t:'Da tensión.',check:st=>st.pwr},
   {t:'En modo V, mide entre el <b>borne 3</b> y la <b>barra de neutro</b>.',check:wMeasN('b3','V')},
   {quiz:true,t:st=>`Marca ${wV(st,'b3','n1')} V. ¿Funciona la salida del termostato?`,opts:['Sí: da 230 V','No'],ok:0,why:'El relé de frío está cerrado y da tensión.'},
   {t:'Ahora mide entre el <b>cable 1 de la solenoide</b> y la barra de neutro.',check:wMeasN('YVa','V')},
   {quiz:true,t:'Marca 0 V. ¿Dónde está la avería?',opts:['En la bobina','En el cable entre el borne 3 y la solenoide: está suelto o cortado','En el neutro'],ok:1,why:'Sale tensión del borne pero no llega a la solenoide: el cable o su conexión. Se aprieta el borne o se cambia el cable (siempre sin tensión).'}]},
 {id:'e22',n:'Avería: los ventiladores no giran',d:'Fase sí, pero ¿y el neutro?',fault:'ncut',prewired:true,meter:true,steps:[
   {t:'Da tensión y mide entre el <b>cable 1 de los ventiladores</b> y la barra de neutro.',check:st=>st.pwr&&wMeasN('Ma','V')(st)},
   {t:'Ahora mide entre el <b>cable 2 de los ventiladores</b> y la barra de neutro.',check:wMeasN('Mb','V')},
   {quiz:true,t:'Los dos cables marcan 230 V respecto al neutro. ¿Qué pasa?',opts:['Todo bien','El neutro del ventilador está cortado: la fase atraviesa el motor y llega al otro cable, pero no tiene vuelta','El motor está quemado'],ok:1,why:'Si el neutro llegara, el cable 2 marcaría 0 V. Se revisa el cable de neutro y su borne.'}]},
 {id:'e23',n:'Avería: resistencias cortadas',d:'Medir en ohmios, siempre sin tensión.',fault:'rburn',prewired:true,meter:true,steps:[
   {info:true,t:'En el desescarche las resistencias no calientan. Para medir resistencia el circuito tiene que estar <b>sin tensión</b>.'},
   {t:'Con la tensión quitada, pon el polímetro en <b>Ω</b> y mide entre los dos cables de las resistencias.',check:st=>!st.pwr&&wMeas('Ra','Rb','R')(st)},
   {quiz:true,t:st=>`Marca ${st.last?st.last.val:'—'}. ¿Cómo están?`,opts:['Bien','Cortadas: hay que cambiarlas','En cortocircuito'],ok:1,why:'Unas resistencias de 1150 W a 230 V deberían marcar unos 46 Ω. OL es circuito abierto.'},
   {t:'Compara: mide la <b>solenoide</b> entre sus dos cables.',check:wMeas('YVa','YVb','R')},
   {quiz:true,t:'La bobina marca 1,2 kΩ. ¿Está bien?',opts:['Sí, una bobina buena da cientos o miles de ohmios','No'],ok:0,why:'OL sería bobina cortada y 0 Ω cortocircuito.'}]},
].forEach(l=>TRAIN.push(Object.assign({sec:'elec',ref:'any',page:'wire',meta:'Práctica de cableado'},l)));

Object.assign(DR,{
 weld:()=>`<svg viewBox="0 0 360 170" class="dr"><path d="M20 90 H170" stroke="#c9733b" stroke-width="16"/><path d="M160 90 H340" stroke="#c9733b" stroke-width="20"/><rect x="150" y="76" width="34" height="28" fill="#e0a070" opacity=".7"/>
  <path d="M30 90 H140" stroke="#5aa9e6" stroke-width="3" stroke-dasharray="8 6"/><text x="80" y="70" text-anchor="middle" font-size="10" fill="#2f6fd0" font-weight="700">N₂ por dentro (poco caudal)</text>
  <path d="M190 30 L172 70" stroke="#14212c" stroke-width="6" stroke-linecap="round"/><path d="M170 74 l-6 10 l14 -4z" fill="#ff8a00"/><text x="205" y="30" font-size="10" font-weight="700">soplete</text>
  <text x="250" y="130" text-anchor="middle" font-size="10">unión soldada sin óxido por dentro</text><text x="180" y="160" text-anchor="middle" font-size="9" fill="#6b7c8a">el nitrógeno sale por el otro extremo mientras se suelda y se enfría</text></svg>`,
 flare:()=>`<svg viewBox="0 0 360 160" class="dr"><path d="M20 80 H180" stroke="#c9733b" stroke-width="14"/><path d="M180 66 L205 52 V108 L180 94Z" fill="#c9733b"/><rect x="160" y="54" width="60" height="52" rx="4" fill="#b9c2cb" stroke="#14212c" opacity=".85"/><text x="190" y="125" text-anchor="middle" font-size="10" font-weight="700">tuerca</text>
  <rect x="215" y="62" width="70" height="36" rx="4" fill="#d9dee3" stroke="#14212c"/><text x="250" y="84" text-anchor="middle" font-size="10">racor</text><text x="90" y="60" text-anchor="middle" font-size="10" font-weight="700">tubo abocardado</text>
  <text x="300" y="30" text-anchor="end" font-size="10" fill="#0b6bcb" font-weight="700">llave dinamométrica: el par del fabricante</text><text x="180" y="150" text-anchor="middle" font-size="9" fill="#6b7c8a">la tuerca se mete ANTES de abocardar</text></svg>`,
 insul:()=>`<svg viewBox="0 0 360 160" class="dr"><rect x="20" y="62" width="320" height="36" rx="18" fill="#2b2b2b"/><path d="M20 80 H340" stroke="#c9733b" stroke-width="10"/><text x="180" y="50" text-anchor="middle" font-size="10" font-weight="700">coquilla aislante sin huecos (juntas pegadas)</text>
  <rect x="110" y="56" width="16" height="48" rx="3" fill="#8a97a5"/><rect x="250" y="56" width="16" height="48" rx="3" fill="#8a97a5"/><path d="M118 104 V130 M258 104 V130" stroke="#8a97a5" stroke-width="4"/><text x="188" y="146" text-anchor="middle" font-size="9.5">abrazaderas con goma cada poco</text></svg>`});
// ================= Montaje: colocar piezas, encontrar errores de montaje y buenas prácticas =================
const MP={comp:'Compresor',cond:'Condensador',rec:'Recipiente de líquido',filt:'Filtro secador',visor:'Visor',sol:'Solenoide',txv:'Válvula de expansión',evap:'Evaporador',sep:'Separador de aceite',sv:'Válvula de servicio',acum:'Separador de aspiración'};
// esquemas con huecos: [x,y] de cada hueco y la pieza que va
const MSLOT={
 cam:{t:'Equipo de una cámara',path:'M70 70 H690 V330 H70 Z',slots:[[70,200,'comp'],[230,70,'cond'],[420,70,'rec'],[600,70,'filt'],[690,200,'visor'],[600,330,'sol'],[420,330,'txv'],[230,330,'evap']],
  lab:[[380,48,'alta presión →'],[380,358,'← baja presión'],[36,200,'']]},
 cen:{t:'Central de freón (una línea)',path:'M70 70 H690 V330 H70 Z',slots:[[70,250,'comp'],[70,130,'sep'],[260,70,'cond'],[450,70,'rec'],[620,70,'filt'],[690,200,'visor'],[560,330,'sol'],[400,330,'txv'],[240,330,'evap'],[120,330,'acum']]}};
function mtSvg(st){ const D=MSLOT[st.lay]; let s=`<svg viewBox="0 0 760 400" class="mt-svg"><path d="${D.path}" fill="none" stroke="#c9d3dc" stroke-width="10" stroke-linejoin="round"/><path d="${D.path}" fill="none" stroke="#8a97a5" stroke-width="2" stroke-dasharray="8 6"/>
  <text x="380" y="40" text-anchor="middle" font-size="12" font-weight="700">${D.t} · el refrigerante gira en el sentido de las agujas del reloj desde el compresor</text>`;
  D.slots.forEach(([x,y,want],i)=>{ const v=st.pick[i]; const res=st.checked?(v===want?'ok':'bad'):''; s+=`<g class="mt-slot" data-sl="${i}" style="cursor:pointer"><rect x="${x-62}" y="${y-22}" width="124" height="44" rx="9" fill="${res==='ok'?'#d7f2e1':res==='bad'?'#fde3dc':st.sel===i?'#fff2dc':'#fff'}" stroke="${st.sel===i?'#ff8a00':'#14212c'}" stroke-width="${st.sel===i?3:1.5}"/><text x="${x}" y="${y-6}" text-anchor="middle" font-size="10" fill="#6b7c8a">hueco ${i+1}</text><text x="${x}" y="${y+11}" text-anchor="middle" font-size="11" font-weight="700">${v?MP[v]:'—'}</text></g>`; });
  return s+'</svg>'; }
// dibujos con errores: zonas que se pueden pulsar
const MSPOT={
 pipe:{t:'Tuberías de una cámara',draw:()=>`<rect x="40" y="200" width="200" height="150" rx="8" fill="#eef3f8" stroke="#8a97a5"/><text x="140" y="280" text-anchor="middle" font-size="11" font-weight="700">cámara · evaporador</text>
   <rect x="520" y="40" width="200" height="110" rx="8" fill="#fde3dc" stroke="#e0573c"/><text x="620" y="100" text-anchor="middle" font-size="11" font-weight="700">unidad condensadora (arriba, en el tejado)</text>
   <path d="M240 230 H330 V60 H520" fill="none" stroke="#2f6fd0" stroke-width="7"/><text x="340" y="215" font-size="10" fill="#2f6fd0">aspiración (sube 6 m)</text>
   <path d="M520 120 H420 L300 320 H240" fill="none" stroke="#e8a33a" stroke-width="5"/><text x="372" y="285" font-size="10" fill="#b4700d">línea de líquido</text>
   <rect x="380" y="200" width="30" height="16" rx="3" fill="#14212c"/><text x="395" y="234" text-anchor="middle" font-size="9">filtro</text><circle cx="455" cy="125" r="9" fill="#fff" stroke="#14212c" stroke-width="2"/><text x="455" y="110" text-anchor="middle" font-size="9">visor</text>
   <text x="380" y="385" text-anchor="middle" font-size="10" fill="#6b7c8a">la aspiración no lleva aislamiento en todo el recorrido</text>`,
   spots:[[330,230,30,'err','Una aspiración que sube varios metros necesita un <b>sifón</b> abajo (y cada pocos metros) para que el aceite pueda subir al compresor.'],[380,385,60,'err','La aspiración tiene que ir <b>aislada</b> en todo el recorrido: si no, condensa agua, gotea y coge calor.'],[455,125,22,'err','El visor va <b>después del filtro</b> (justo antes de la solenoide o la válvula): así ves el líquido que llega de verdad a la válvula.'],[395,208,22,'ok','El filtro en la línea de líquido está bien.'],[600,95,40,'ok','La unidad condensadora en el exterior está bien: tiene aire para el condensador.'],[140,270,40,'ok','El evaporador está bien colocado.']]},
 valve:{t:'Válvula de expansión y sondas',draw:()=>`<rect x="200" y="80" width="300" height="140" rx="10" fill="#e3f2fc" stroke="#5aa9e6" stroke-width="2"/><text x="350" y="155" text-anchor="middle" font-size="12" font-weight="700">EVAPORADOR</text>
   <path d="M40 120 H160" stroke="#e8a33a" stroke-width="6"/><path d="M160 104 L190 136 M160 136 L190 104" stroke="#14212c" stroke-width="3"/><rect x="160" y="104" width="30" height="32" fill="none" stroke="#14212c" stroke-width="2"/><path d="M190 120 H200" stroke="#5aa9e6" stroke-width="6"/>
   <path d="M500 180 H720" stroke="#2f6fd0" stroke-width="8"/><rect x="215" y="112" width="26" height="12" rx="3" fill="#14212c"/><path d="M175 104 V70 H228 V112" fill="none" stroke="#14212c" stroke-dasharray="4 3"/><text x="232" y="64" font-size="10">bulbo</text>
   <path d="M175 136 V260 H560 V188" fill="none" stroke="#6b45d8" stroke-width="2"/><text x="370" y="275" text-anchor="middle" font-size="10" fill="#6b45d8">tubo del ecualizador externo</text>
   <rect x="520" y="70" width="20" height="14" rx="3" fill="#e0573c"/><text x="530" y="62" text-anchor="middle" font-size="10">sonda de cámara</text><path d="M500 77 H520" stroke="#6b7c8a" stroke-dasharray="3 3"/><text x="548" y="114" font-size="9" fill="#6b7c8a">← sale el aire frío del evaporador</text>
   <rect x="470" y="96" width="18" height="12" rx="3" fill="#0e8a7e"/><text x="464" y="64" text-anchor="end" font-size="10" fill="#0e8a7e">sonda evaporador (Pb2)</text><path d="M470 70 V96" stroke="#0e8a7e" stroke-dasharray="3 3"/>`,
   spots:[[228,118,24,'err','El bulbo de la válvula termostática va en la <b>salida</b> del evaporador (en la aspiración, después del evaporador), bien sujeto y aislado, no a la entrada.'],[560,200,22,'err','El ecualizador externo se toma <b>después del bulbo</b> (más lejos del evaporador). Aquí está antes de donde debería ir el bulbo.'],[530,77,22,'err','La sonda de cámara va en el <b>retorno de aire</b> (aire que entra al evaporador), no en la salida del aire frío.'],[479,102,20,'ok','La sonda de evaporador entre las aletas, en la zona que más tarda en deshelarse, está bien.'],[175,120,24,'ok','La válvula de expansión a la entrada del evaporador está bien.']]},
 room:{t:'Montaje de una cámara de congelados',draw:()=>`<rect x="60" y="60" width="420" height="280" rx="6" fill="#f7f9fb" stroke="#8a97a5" stroke-width="3"/><text x="270" y="200" text-anchor="middle" font-size="12" font-weight="700">CÁMARA −20 °C</text>
   <rect x="300" y="70" width="160" height="50" rx="6" fill="#e3f2fc" stroke="#5aa9e6"/><text x="380" y="100" text-anchor="middle" font-size="10" font-weight="700">evaporador (pegado a la pared)</text><path d="M440 120 V360" stroke="#8a97a5" stroke-width="5"/><text x="450" y="370" font-size="9.5">desagüe sin resistencia ni sifón</text>
   <rect x="60" y="140" width="10" height="110" fill="#e0573c"/><text x="80" y="135" font-size="9.5" fill="#c4371f">puerta con resistencia de marco</text>
   <rect x="520" y="150" width="120" height="70" rx="6" fill="#eef3f8" stroke="#14212c"/><text x="580" y="180" text-anchor="middle" font-size="10" font-weight="700">cuadro eléctrico</text><text x="580" y="196" text-anchor="middle" font-size="9">con pulsador de</text><text x="580" y="208" text-anchor="middle" font-size="9">hombre encerrado ✕</text>
   <rect x="90" y="300" width="90" height="30" rx="4" fill="#d9c7a6"/><text x="135" y="320" text-anchor="middle" font-size="9">producto en el suelo</text>`,
   spots:[[380,95,40,'err','El evaporador necesita <b>espacio detrás</b> para que el aire circule (lo que diga el fabricante, normalmente medio metro o más).'],[440,330,30,'err','En congelados el desagüe lleva <b>resistencia</b> (si no se hiela) y un <b>sifón fuera de la cámara</b> para que no entre aire caliente.'],[580,205,30,'err','El pulsador de <b>hombre encerrado</b> va <b>dentro</b> de la cámara, junto a la puerta y con luz, no en el cuadro de fuera.'],[135,315,30,'err','El producto no se pone en el suelo: estanterías o palets, separado de paredes para que circule el aire.'],[70,195,24,'ok','La resistencia del marco en la puerta de congelados es correcta.']]}};
function mtSpotSvg(st){ const D=MSPOT[st.spot]; let s=`<svg viewBox="0 0 760 400" class="mt-svg"><text x="380" y="24" text-anchor="middle" font-size="12" font-weight="700">${D.t} · pulsa donde veas un error</text>${D.draw()}`;
  D.spots.forEach(([x,y,r,k],i)=>{ const f=st.found.includes(i); s+=`<circle class="mt-hot" data-sp="${i}" cx="${x}" cy="${y}" r="${r}" fill="${f?(k==='err'?'rgb(214 69 69/.18)':'rgb(58 166 91/.18)'):'transparent'}" stroke="${f?(k==='err'?'#c4371f':'#3aa65b'):'transparent'}" stroke-width="3" style="cursor:pointer"/>${f?`<text x="${x}" y="${y+5}" text-anchor="middle" font-size="16" font-weight="700" fill="${k==='err'?'#c4371f':'#3aa65b'}">${k==='err'?'✕':'✓'}</text>`:''}`; });
  return s+'</svg>'; }
TOOLSIM.mont={
  init(L){ return {lay:L.lay,spot:L.spot,pic:L.pic,pick:{},sel:null,checked:false,ok:false,found:[],notes:[]}; },
  render(el,st){ if(st.lay){ const D=MSLOT[st.lay]; el.innerHTML=mtSvg(st)+`<div class="m-ctl"><div class="m-row"><span>${st.sel!=null?'Pieza para el hueco '+(st.sel+1):'Elige un hueco'}</span><div class="m-btns">${st.sel!=null?[...new Set(D.slots.map(x=>x[2]))].sort((a,b)=>MP[a].localeCompare(MP[b])).map(k=>`<button data-mt="${k}">${MP[k]}</button>`).join(''):'Pulsa un hueco del esquema y luego la pieza que va ahí.'}</div></div><div class="m-row"><span>Comprobar</span><div class="m-btns"><button data-mt="check">Comprobar el montaje</button><button data-mt="reset">Empezar de nuevo</button></div></div></div>`; }
    else if(st.spot){ const D=MSPOT[st.spot]; const nErr=D.spots.filter(x=>x[3]==='err').length, f=st.found.filter(i=>D.spots[i][3]==='err').length; el.innerHTML=mtSpotSvg(st)+`<div class="m-ctl"><div class="m-row"><span>Errores encontrados</span><div class="m-btns"><b>${f} de ${nErr}</b></div></div>${st.notes.length?`<ul class="mt-notes">${st.notes.map(n=>`<li>${n}</li>`).join('')}</ul>`:''}</div>`; }
    else el.innerHTML=`<div class="tr-dr">${DR[st.pic]?DR[st.pic]():''}</div>`; }};
document.addEventListener('click',e=>{ if(!TP.L||TP.L.page!=='mont') return; const st=TP.st; const sl=e.target.closest&&e.target.closest('#tpTool [data-sl]'), b=e.target.closest&&e.target.closest('#tpTool [data-mt]'), sp=e.target.closest&&e.target.closest('#tpTool [data-sp]'); if(!sl&&!b&&!sp) return; TP.msg='';
  if(sl){ st.sel=+sl.dataset.sl; st.checked=false; }
  if(b){ const k=b.dataset.mt; if(k==='check'){ const D=MSLOT[st.lay]; const bad=D.slots.filter(([,,w],i)=>st.pick[i]!==w).length; st.checked=true; st.ok=bad===0; if(bad){ TP.errs++; TP.msg=`✗ Hay ${bad} pieza(s) mal colocadas (en rojo). Piensa por dónde va el refrigerante: sale del compresor caliente y a alta presión.`; } else TP.msg='✓ ¡Montaje correcto!'; }
    else if(k==='reset'){ st.pick={}; st.sel=null; st.checked=false; st.ok=false; } else if(st.sel!=null){ st.pick[st.sel]=k; const D=MSLOT[st.lay]; st.sel=st.sel+1<D.slots.length&&st.pick[st.sel+1]==null?st.sel+1:null; } }
  if(sp){ const i=+sp.dataset.sp, D=MSPOT[st.spot], s=D.spots[i]; if(!st.found.includes(i)){ st.found.push(i); st.notes.push((s[3]==='err'?'✕ ':'✓ Esto está bien: ')+s[4]); if(s[3]!=='err'){ TP.errs++; TP.msg='✗ Eso no es un error.'; } } }
  tpTool(); });
const mtAll=st=>{ const D=MSPOT[st.spot]; return D.spots.every(([,,,k],i)=>k!=='err'||st.found.includes(i)); };
[
 {id:'m1',n:'Las piezas en su sitio: equipo de una cámara',d:'Coloca cada pieza del circuito en su hueco.',lay:'cam',steps:[
   {info:true,t:'Cada pieza tiene su sitio en el circuito. Recuerda el orden: el <b>compresor</b> manda gas caliente al <b>condensador</b>; el líquido se guarda en el <b>recipiente</b>, pasa por el <b>filtro</b> y el <b>visor</b>, la <b>solenoide</b> lo deja pasar, la <b>válvula de expansión</b> baja la presión y el <b>evaporador</b> enfría.'},
   {t:'Coloca las 8 piezas y pulsa «Comprobar el montaje».',check:st=>st.ok}]},
 {id:'m2',n:'Las piezas en su sitio: una central',d:'Con separador de aceite y separador de aspiración.',lay:'cen',steps:[
   {info:true,t:'En una central hay dos piezas más: el <b>separador de aceite</b>, a la salida de los compresores, que devuelve el aceite al cárter; y el <b>separador de aspiración</b>, antes de los compresores, que recoge el líquido para que no llegue al compresor.'},
   {t:'Coloca las 10 piezas y pulsa «Comprobar el montaje».',check:st=>st.ok},
   {quiz:true,t:'¿Por qué el separador de aceite va justo después de los compresores?',opts:['Porque ahí el aceite sale mezclado con el gas de descarga y se recoge antes de que se vaya por la instalación','Para enfriar el gas','Da igual dónde vaya'],ok:0,why:'Así el aceite vuelve enseguida a los compresores y no se queda en evaporadores y tuberías.'}]},
 {id:'m3',n:'Tuberías: sifones, pendientes y aislamiento',d:'Encuentra los errores de montaje de las tuberías.',spot:'pipe',steps:[
   {info:true,t:'El aceite viaja con el refrigerante. En las subidas de aspiración necesita <b>velocidad</b> del gas y <b>sifones</b> (una curva en U) para poder subir. Los tramos horizontales de aspiración llevan una <b>pendiente</b> hacia el compresor.'},
   {t:'Encuentra los 3 errores del dibujo (pulsa encima de cada uno).',check:mtAll},
   {quiz:true,t:'¿Hacia dónde va la pendiente de una aspiración horizontal?',opts:['Hacia el compresor','Hacia el evaporador','Plana'],ok:0,why:'Así el aceite cae hacia el compresor y no se queda en el evaporador.'}]},
 {id:'m4',n:'El bulbo, el ecualizador y las sondas',d:'Dónde va cada cosa en el evaporador.',spot:'valve',steps:[
   {info:true,t:'El <b>bulbo</b> de una válvula termostática mide la salida del evaporador: se pone en un tramo horizontal, bien pegado (abrazadera de cobre) y aislado. En tubos finos arriba; en gruesos, a las 4 u 8 del reloj.'},
   {t:'Encuentra los 3 errores del dibujo.',check:mtAll}]},
 {id:'m5',n:'Montaje de una cámara de congelados',d:'Desagüe, evaporador, seguridad y carga del producto.',spot:'room',steps:[
   {t:'Encuentra los 4 errores del dibujo.',check:mtAll},
   {quiz:true,t:'¿Por qué el desagüe de congelados sale con un sifón por fuera de la cámara?',opts:['Para que no entre aire caliente y húmedo por el tubo (y no se hiele)','Para que salga más rápido','Por estética'],ok:0,why:'Y dentro de la cámara el tubo lleva resistencia para que el agua no se congele.'}]},
 {id:'m6',n:'Soldar con nitrógeno',d:'La soldadura fuerte sin cascarilla.',pic:'weld',steps:[
   {info:true,t:'Al soldar cobre, por dentro se forma <b>cascarilla</b> (óxido) que luego se suelta y tapa filtros y válvulas. Para evitarlo se pasa un <b>caudal pequeño de nitrógeno</b> por dentro mientras se suelda (barrido).'},
   {order:true,t:'Ordena los pasos para soldar una unión:',items:['Cortar el tubo con cortatubos y quitar la rebaba','Limpiar y encajar las piezas','Pasar un caudal pequeño de nitrógeno por dentro','Calentar de forma uniforme y aportar la varilla','Dejar enfriar con el nitrógeno pasando','Revisar la unión'],why:'Con el nitrógeno pasando hasta que se enfría, no se forma óxido dentro.'},
   {quiz:true,t:'¿Por qué no se corta el tubo con sierra?',opts:['Porque deja virutas dentro que acaban en el compresor o en las válvulas','Porque es más lento','Da igual'],ok:0,why:'Se usa cortatubos y escariador.'}]},
 {id:'m7',n:'Abocardar y apretar uniones',d:'Uniones mecánicas que no fuguen.',pic:'flare',steps:[
   {info:true,t:'El <b>abocardado</b> une un tubo de cobre a una tuerca sin soldar. Se corta recto, se escaría, se mete la tuerca <b>antes</b> de abocardar, se pone una gota de aceite del circuito en la cara del abocardado y se aprieta con <b>llave dinamométrica</b> al par que indica el fabricante.'},
   {quiz:true,t:'¿Qué pasa si aprietas un abocardado de más?',opts:['Fuga menos','Se adelgaza o se raja el cobre y acaba fugando','Nada'],ok:1,why:'Por eso se usa la llave dinamométrica.'},
   {quiz:true,t:'Te das cuenta de que no has metido la tuerca antes de abocardar. ¿Qué haces?',opts:['La meto por el otro lado','Corto el abocardado y lo vuelvo a hacer con la tuerca puesta','Lo dejo así'],ok:1,why:'Es el despiste más típico: hay que repetirlo.'}]},
 {id:'m8',n:'Aislamiento, soportes y vibraciones',d:'Lo que evita goteras, fugas y ruidos.',pic:'insul',steps:[
   {info:true,t:'La <b>aspiración</b> se aísla entera con coquilla (sin huecos, juntas pegadas). Las tuberías se sujetan con <b>abrazaderas con goma</b> cada poco, y cerca de los compresores se ponen <b>antivibratorios</b> o tramos flexibles para que la vibración no rompa tubos.'},
   {quiz:true,t:'Una tubería de aspiración gotea agua sobre el producto. ¿Por qué?',opts:['Por una fuga de refrigerante','Porque le falta aislamiento o tiene juntas abiertas: condensa la humedad del aire','Por exceso de aceite'],ok:1,why:'El tubo frío condensa el agua del aire si no está bien aislado.'},
   {quiz:true,t:'¿Dónde aparecen muchas fugas por vibración?',opts:['En tubos cerca de los compresores mal sujetos','En los evaporadores','En el visor'],ok:0,why:'Se revisan las sujeciones y se ponen antivibratorios.'}]},
 {id:'m9',n:'El orden de montaje de una central',d:'De la bancada a la puesta en marcha.',pic:'booster',steps:[
   {order:true,t:'Ordena el montaje de una central:',items:['Colocar la central y el condensador o gas cooler en su sitio (bancada, antivibratorios)','Tender y soldar las tuberías con nitrógeno','Montar muebles, válvulas, sondas y transductores','Prueba de presión con nitrógeno','Vacío','Aislar las tuberías','Cableado eléctrico y comunicación','Carga de refrigerante y puesta en marcha'],why:'El aislamiento va después de la prueba de presión, para poder ver las uniones.'},
   {quiz:true,t:'¿Por qué se aíslan las tuberías después de la prueba de presión?',opts:['Para poder ver y repasar las uniones con espuma si hay fuga','Porque es más barato','Da igual'],ok:0,why:'Con el aislamiento puesto no se ve una fuga en una unión.'}]},
 {id:'m10',n:'Pruebas antes de cerrar la obra',d:'Lo que hay que comprobar y apuntar.',pic:'method',steps:[
   {order:true,t:'Ordena las pruebas finales:',items:['Prueba de estanqueidad con nitrógeno y anotar presión y temperatura','Vacío por debajo de 500 micras y prueba de que se mantiene','Carga por peso según el cálculo','Puesta en marcha y ajuste de recalentamientos','Comprobar seguridades (presostatos, alarmas)','Etiquetar la instalación y rellenar la documentación'],why:'Todo queda anotado: es lo que se compara cuando algún día haya una avería.'},
   {quiz:true,t:'¿Qué se pone en la etiqueta de una instalación con gas fluorado?',opts:['El tipo de gas y la cantidad cargada','Nada','El nombre del técnico solo'],ok:0,why:'Es obligatorio indicar gas, carga y (según el caso) su equivalente en CO₂.'}]},
].forEach(l=>TRAIN.push(Object.assign({sec:'mont',ref:'any',page:'mont',meta:l.lay?'Coloca las piezas':l.spot?'Encuentra los errores':'Teoría de montaje'},l)));

// ================= Simulador: cámara con equipo partido (unidad condensadora, recogida de gas) =================
const UF={low:'Falta de refrigerante (fuga)',cond:'Condensador sucio',cfan:'Ventilador del condensador parado',efan:'Ventilador del evaporador parado',sol:'Solenoide que no abre',lp:'Presostato de baja mal ajustado',km:'Contactor del compresor que no entra'};
const UFIX={low:['leak','Buscar la fuga, repararla, vacío y cargar por peso'],cond:['clean','Limpiar el condensador'],cfan:['cfan','Cambiar el motor del ventilador del condensador'],efan:['efan','Cambiar el motor del ventilador del evaporador'],sol:['coil','Cambiar la bobina de la solenoide'],km:['km','Cambiar el contactor del compresor'],lp:['lpadj','Ajustar el presostato de baja (en sus mandos)']};
const uPs=t=>rel(FL('R404A').satT(K(t)).P), uTs=p=>C(FL('R404A').satP((Math.max(p,-0.9)+1.013)*1e5).T);
function uNew(L){ const st={T:L.T0??3,SP:L.SP??2,dif:2,Tamb:L.Tamb??30,run:false,sol:false,Te:0,Tc:32,Pl:4,Ph:14,lpOut:1.0,lpIn:2.5,hpOut:27,hpTrip:false,fault:L.fault||null,t:0,starts:[],def:false,defT:0,nextDef:6*3600,ice:0,log:[],fixed:null};
  if(st.fault==='lp'){ st.lpOut=3.5; st.lpIn=4.0; } st.Te=st.T; st.Pl=uPs(st.T-2); st.Tc=st.Tamb+2; st.Ph=uPs(st.Tc); return st; }
const uLog=(st,m)=>{ st.log.unshift({t:st.t,m}); if(st.log.length>8) st.log.pop(); };
const uClock=t=>{ const m=Math.floor(t/60); return String(Math.floor(m/60)%24).padStart(2,'0')+':'+String(m%60).padStart(2,'0'); };
function uTick(st,dt){ st.t+=dt; const f=st.fault;
  // termostato y desescarche
  if(!st.def&&st.t>=st.nextDef){ st.def=true; st.defT=0; uLog(st,'Inicio de desescarche'); }
  if(st.def){ st.defT+=dt; st.sol=false; if(st.defT>=20*60||st.ice<=0){ st.def=false; st.nextDef=st.t+6*3600; st.ice=Math.max(0,st.ice-0.6); uLog(st,'Fin de desescarche'); } }
  else { if(st.T>st.SP+st.dif) st.sol=true; else if(st.T<=st.SP) st.sol=false; }
  const solOpen=st.sol&&f!=='sol';
  // compresor: lo manda el presostato de baja (recogida de gas)
  if(!st.run&&!st.hpTrip&&st.Pl>=st.lpIn&&f!=='km'){ st.run=true; st.starts.push(st.t); uLog(st,'Arranca el compresor (presostato de baja cierra)'); }
  if(st.run&&st.Pl<=st.lpOut){ st.run=false; uLog(st,'Para el compresor (presostato de baja abre)'); }
  if(st.run&&st.Ph>=st.hpOut){ st.run=false; st.hpTrip=true; uLog(st,'¡Disparo del presostato de alta!'); }
  st.starts=st.starts.filter(t=>st.t-t<3600);
  // evaporación
  const fanE=f!=='efan'&&!st.def; let cool=0;
  if(st.run&&solOpen){ const dT=f==='low'?24:!fanE?22:10+st.ice*8; st.Te+=(st.T-dT-st.Te)*Math.min(1,dt/25); st.Pl=uPs(st.Te); cool=0.0013*(st.T-st.Te)*(f==='low'?0.18:!fanE?0.15:1)*(1-Math.min(0.7,st.ice))*(f==='cond'?0.85:1); if(st.Te<-2) st.ice+=dt/3600*(fanE?0.04:0.25); }
  else if(st.run){ st.Pl=Math.max(-0.3,st.Pl-0.12*dt); st.Te=uTs(st.Pl); }
  else if(solOpen){ st.Pl+=(uPs(st.T-3)-st.Pl)*Math.min(1,dt/20); st.Te=uTs(st.Pl); }
  else { const tg=st.lpOut+0.5; st.Pl+=(tg-st.Pl)*Math.min(1,dt/300); st.Te=uTs(st.Pl); }
  // condensación
  const tcRun=st.Tamb+12+(f==='cond'?12:0)+(f==='cfan'?24:0)-(f==='low'?4:0); st.Tc+=((st.run?tcRun:st.Tamb+2)-st.Tc)*Math.min(1,dt/(st.run?40:300)); st.Ph=uPs(st.Tc);
  // cámara
  const heat=0.00035*(22-st.T)+(st.def?0.004:0)+(fanE?0.0002:0); st.T+=(heat-cool)*dt; }
function uSH(st){ return st.run&&st.sol&&st.fault!=='sol'?(st.fault==='low'?24:st.fault==='efan'?2:7):null; }
function uSvg(st){ const on=st.run, so=st.sol&&st.fault!=='sol', fe=st.fault!=='efan'&&!st.def, fc=on&&st.fault!=='cfan';
  const fan=(x,y,r,spin)=>`<g transform="translate(${x} ${y})"><circle r="${r}" fill="#fff" stroke="#14212c" stroke-width="2"/><g class="${spin?'u-spin':''}"><path d="M0 0 L${r*.8} -${r*.25} L${r*.8} ${r*.25}Z M0 0 L-${r*.8} ${r*.25} L-${r*.8} -${r*.25}Z" fill="#5b6b7a"/></g></g>`;
  const sh=uSH(st);
  return `<svg viewBox="0 0 760 380" class="u-svg">
  <rect x="20" y="40" width="330" height="320" rx="10" fill="#eef6fc" stroke="#8a97a5" stroke-width="2"/><text x="36" y="62" font-size="12" font-weight="700">CÁMARA</text><text x="185" y="230" text-anchor="middle" font-size="44" font-weight="700" fill="${st.T>st.SP+5?'#c4371f':'#14212c'}">${f1(st.T)} °C</text><text x="185" y="252" text-anchor="middle" font-size="11" fill="#41556b">consigna ${f1(st.SP)} °C · diferencial ${st.dif} K</text>
  <rect x="80" y="80" width="210" height="64" rx="8" fill="${st.ice>0.3?'#f2f8ff':'#e3f2fc'}" stroke="#5aa9e6" stroke-width="2"/>${st.ice>0.25?`<rect x="84" y="84" width="202" height="56" rx="6" fill="#ffffff" opacity="${Math.min(.85,st.ice)}"/>`:''}<text x="150" y="117" text-anchor="middle" font-size="11" font-weight="700">evaporador</text>${fan(255,112,18,fe)}
  <text x="185" y="164" text-anchor="middle" font-size="10" fill="#41556b">${st.def?'DESESCARCHE':so?'enfriando':'parado'}${st.ice>0.3?' · hielo':''}</text>
  <rect x="34" y="290" width="110" height="52" rx="8" fill="#140b07"/><text x="89" y="324" text-anchor="middle" font-size="22" font-weight="700" fill="#ff3b2f" font-family="ui-monospace,Menlo,monospace">${st.T.toFixed(1)}</text><text x="89" y="285" text-anchor="middle" font-size="9.5">termostato</text>
  <path d="M290 98 H420" stroke="#e8a33a" stroke-width="5"/><path d="M290 126 H420" stroke="#2f6fd0" stroke-width="6"/>
  <g transform="translate(320 98)"><rect x="-12" y="-12" width="24" height="24" rx="4" fill="${so?'#3aa65b':'#c9d3dc'}" stroke="#14212c"/><text y="-18" text-anchor="middle" font-size="9.5" font-weight="700">solenoide</text></g>
  <text x="380" y="88" text-anchor="middle" font-size="9" fill="#b4700d">líquido</text><text x="380" y="142" text-anchor="middle" font-size="9" fill="#2f6fd0">aspiración ${sh!=null?'· SH '+sh+' K':''}</text>
  <rect x="420" y="40" width="320" height="320" rx="10" fill="#fbf4ee" stroke="#8a97a5" stroke-width="2"/><text x="436" y="62" font-size="12" font-weight="700">UNIDAD CONDENSADORA (fuera · ${st.Tamb} °C)</text>
  <rect x="440" y="76" width="280" height="80" rx="8" fill="#fde3dc" stroke="#e0573c"/><text x="480" y="120" font-size="11" font-weight="700">condensador</text>${fan(610,116,30,fc)}${fan(680,116,30,fc&&true)}
  <circle cx="520" cy="230" r="40" fill="${on?'#d7f2e1':'#fff'}" stroke="#14212c" stroke-width="2.5"/><text x="520" y="226" text-anchor="middle" font-size="11" font-weight="700">compresor</text><text x="520" y="242" text-anchor="middle" font-size="10" fill="${on?'#0e8a3e':'#6b7c8a'}">${on?'en marcha':st.hpTrip?'DISPARO ALTA':'parado'}</text>
  <g font-size="11" font-family="ui-monospace,Menlo,monospace"><rect x="590" y="180" width="140" height="96" rx="8" fill="#1d2b38"/><text x="600" y="200" fill="#9fc3ff">BAJA ${f1(st.Pl)} bar</text><text x="600" y="216" fill="#9fc3ff">   ${f1(st.Te)} °C</text><text x="600" y="240" fill="#ffb4a6">ALTA ${f1(st.Ph)} bar</text><text x="600" y="256" fill="#ffb4a6">   ${f1(st.Tc)} °C</text></g>
  <text x="440" y="300" font-size="10.5">Presostato de baja: para a <tspan font-weight="700">${f1(st.lpOut)}</tspan> bar · arranca a <tspan font-weight="700">${f1(st.lpIn)}</tspan> bar</text><text x="440" y="318" font-size="10.5">Presostato de alta: ${st.hpOut} bar ${st.hpTrip?'· <tspan fill="#c4371f" font-weight="700">DISPARADO</tspan>':''}</text><text x="440" y="336" font-size="10.5">Arranques en la última hora: <tspan font-weight="700">${st.starts.length}</tspan> · hora ${uClock(st.t+8*3600)}</text>
  </svg>`; }
TOOLSIM.unit={speed:30,
  init(L){ const st=uNew(L); for(let k=0;k<120;k++) uTick(st,1); return st; },
  tick(st,dt){ const n=Math.ceil(dt); for(let k=0;k<n;k++) uTick(st,dt/n); },
  live(el,st){ const s=el.querySelector('.u-svg'); if(s) s.outerHTML=uSvg(st); const lg=el.querySelector('.u-log'); if(lg) lg.innerHTML=st.log.map(l=>`<li><b>${uClock(l.t+8*3600)}</b> ${l.m}</li>`).join(''); },
  render(el,st){ const L=TP.L; const free=!L.steps.length;
    el.innerHTML=uSvg(st)+`<div class="m-ctl">
      <div class="m-row"><span>Termostato</span><div class="m-btns"><button data-u="sp-">Consigna −1</button><button data-u="sp+">Consigna +1</button><button data-u="def">Desescarche manual</button></div></div>
      <div class="m-row"><span>Presostato de baja</span><div class="m-btns"><button data-u="lo-">Paro −0,5</button><button data-u="lo+">Paro +0,5</button><button data-u="li-">Arranque −0,5</button><button data-u="li+">Arranque +0,5</button></div></div>
      <div class="m-row"><span>Presostato de alta</span><div class="m-btns"><button data-u="hpr">Rearmar el presostato de alta</button></div></div>
      <div class="m-row"><span>Exterior</span><div class="m-btns"><button data-u="ta-">−5 °C</button><button data-u="ta+">+5 °C</button></div></div>
      <div class="m-row"><span>Reparar</span><div class="m-btns u-fix">${Object.values(UFIX).map(([k,t])=>`<button data-ufix="${k}">${t}</button>`).join('')}</div></div>
      ${free?`<div class="m-row"><span>Avería</span><div class="m-btns"><button data-u="rnd">Poner una avería sorpresa</button>${st.fault?'<span class="w-help">Hay una avería oculta: encuéntrala y repárala.</span>':''}</div></div>`:''}
      <div class="m-row"><span>Tiempo</span><div class="m-btns"><button data-u="ff">Adelantar 5 min</button><button data-u="ff3">Adelantar 30 min</button></div></div>
      <div class="m-row"><span>Registro</span><ul class="u-log"></ul></div></div>`; this.live(el,st); }};
document.addEventListener('click',e=>{ if(!TP.L||TP.L.page!=='unit') return; const st=TP.st; const b=e.target.closest&&e.target.closest('#tpTool [data-u],#tpTool [data-ufix]'); if(!b) return; TP.msg=''; const k=b.dataset.u;
  if(k==='sp-') st.SP-=1; if(k==='sp+') st.SP+=1; if(k==='def'&&!st.def){ st.nextDef=st.t; }
  if(k==='lo-') st.lpOut=Math.max(-0.5,st.lpOut-0.5); if(k==='lo+') st.lpOut+=0.5; if(k==='li-') st.lpIn=Math.max(st.lpOut+0.5,st.lpIn-0.5); if(k==='li+') st.lpIn+=0.5; if(st.lpIn<=st.lpOut) st.lpIn=st.lpOut+0.5;
  if(k==='hpr'){ if(st.Ph>=st.hpOut-2){ TP.msg='Todavía hay mucha presión: espera a que baje y busca la causa antes de rearmar.'; } else { st.hpTrip=false; uLog(st,'Presostato de alta rearmado'); } }
  if(k==='ta-') st.Tamb-=5; if(k==='ta+') st.Tamb+=5;
  if(k==='ff'||k==='ff3'){ const n=k==='ff'?300:1800; for(let i=0;i<n;i++) uTick(st,1); }
  if(k==='rnd'){ const ks=Object.keys(UF); st.fault=ks[Math.floor(Math.random()*ks.length)]; if(st.fault==='lp'){ st.lpOut=3.5; st.lpIn=4.0; } TP.msg='Avería puesta. Investiga: temperaturas, presiones, presostatos, arranques y registro.'; }
  if(b.dataset.ufix){ const fx=b.dataset.ufix; const want=st.fault&&UFIX[st.fault][0];
    if(fx==='lpadj'){ TP.msg='El presostato de baja se ajusta con sus botones: para unos 1 bar, arranca unos 2,5 bar.'; }
    else if(st.fault&&fx===want){ uLog(st,'Reparación: '+UFIX[st.fault][1]); st.fixed=st.fault; st.fault=null; TP.msg='✓ Reparado: '+UFIX[st.fixed][1].toLowerCase()+'.'; if(st.fixed==='efan') st.ice=0; }
    else { tpErr(st.fault?'Esa reparación no arregla la avería. Mira bien los síntomas.':'No hay ninguna avería que reparar.'); } }
  tpTool(); });
const uDiag=(k)=>({quiz:true,t:'¿Qué avería tiene el equipo?',opts:Object.values(UF),ok:Object.keys(UF).indexOf(k),why:{low:'Baja muy baja, recalentamiento muy alto y la cámara no llega: falta refrigerante.',cond:'La alta está muy por encima de lo normal (más de 15 K sobre el aire) con los ventiladores girando.',cfan:'La alta se dispara y el ventilador del condensador no gira.',efan:'Baja muy baja, recalentamiento casi 0 y el evaporador se llena de hielo: no pasa aire.',sol:'El termostato pide frío, pero la baja no sube: no pasa refrigerante y el compresor no arranca.',lp:'El compresor para y arranca cada poco con la cámara caliente: el presostato de baja corta por encima de la presión de trabajo.',km:'El presostato de baja da permiso (presión alta), pero el compresor no arranca: el contactor no entra.'}[k]});
const uCase=(id,k,n,aviso,extra)=>({id,n,d:aviso,fault:k,T0:k==='sol'||k==='km'?6:3,Tamb:k==='cfan'||k==='cond'?33:30,steps:[
  {info:true,t:'<b>Aviso:</b> '+aviso},
  {t:'Investiga: adelanta al menos 30 minutos y mira temperaturas, presiones, presostatos, arranques y el registro.',check:(st,s)=>st.t-s>=1700,init:st=>st.t,ff:true},
  uDiag(k),
  {t:'Repara la avería (botones de «Reparar»'+(k==='lp'?'; este se ajusta con los botones del presostato de baja: paro 1 bar y arranque 2,5 bar)':')')+'.',check:st=>k==='lp'?(st.lpOut<=1.5&&st.lpIn>=st.lpOut+1&&st.lpIn<=3.5):!st.fault,act:st=>{ if(k==='lp') st.fault=null; }},
  {t:'Comprueba que el equipo vuelve a funcionar: la cámara baja hasta su consigna. Adelanta tiempo.'+(k==='cfan'?' Si el presostato de alta está disparado, rearma.':''),check:st=>st.T<=st.SP+st.dif&&!st.hpTrip,ff:true},...(extra||[])]});
[
 {id:'u1',n:'Cómo es un equipo partido',d:'Cámara con su evaporador y la unidad condensadora fuera.',steps:[
   {info:true,t:'Muchas cámaras no van a una central: llevan su propio equipo. Dentro, el <b>evaporador</b> con su ventilador, la <b>solenoide</b> y la válvula de expansión. Fuera, la <b>unidad condensadora</b>: compresor, condensador con ventiladores, recipiente y presostatos.'},
   {info:true,t:'El <b>termostato</b> no manda al compresor: abre o cierra la <b>solenoide</b>. El compresor lo manda el <b>presostato de baja</b>. Esto se llama <b>recogida de gas</b> (pump-down).'},
   {t:'Adelanta 30 minutos y mira cómo el compresor para y arranca él solo.',check:(st,s)=>st.t-s>=1700,init:st=>st.t,ff:true},
   {quiz:true,t:'¿Quién para el compresor en un equipo con recogida de gas?',opts:['El termostato directamente','El presostato de baja, cuando la solenoide cierra y la baja cae','El presostato de alta'],ok:1,why:'Al cerrar la solenoide el compresor vacía el evaporador, la presión baja y el presostato de baja lo para.'}]},
 {id:'u2',n:'El ciclo de recogida de gas',d:'Míralo paso a paso: solenoide, baja y compresor.',T0:5,steps:[
   {t:'Ahora la cámara está caliente: la solenoide está abierta y el compresor en marcha. Sube la consigna a 8 °C para que el termostato quede satisfecho.',check:st=>st.SP>=8},
   {t:'Mira: la solenoide cierra, la baja cae y el presostato de baja para el compresor. Espera a que pare.',check:st=>!st.run&&!st.sol,ff:true},
   {quiz:true,t:'¿Por qué es bueno parar así el compresor?',opts:['Porque el refrigerante queda guardado en el recipiente y no migra al cárter con el compresor parado','Porque gasta más','No tiene ventajas'],ok:0,why:'Así el compresor arranca sin líquido en el aceite.'},
   {t:'Baja la consigna a 2 °C: el termostato abre la solenoide, la baja sube y el compresor arranca.',check:st=>st.SP<=2&&st.run}]},
 {id:'u3',n:'Ajustar el presostato de baja',d:'Paro y arranque bien puestos para que no haga ciclos cortos.',fault:'lp',steps:[
   {t:'Este equipo para y arranca cada poco. Adelanta 30 minutos y mira los arranques en la última hora.',check:(st,s)=>st.t-s>=1700,init:st=>st.t,ff:true},
   {quiz:true,t:st=>`El presostato para a ${f1(st.lpOut)} bar y la baja trabaja a unos 3,5 bar enfriando. ¿Qué pasa?`,opts:['Está bien','Para mientras está enfriando: hace ciclos cortos y la cámara no llega','Le falta gas'],ok:1,why:'El paro tiene que estar bastante por debajo de la presión de trabajo.'},
   {t:'Ajústalo: paro a <b>1 bar</b> y arranque a <b>2,5 bar</b>.',check:st=>st.lpOut>=0.5&&st.lpOut<=1.5&&st.lpIn>=2&&st.lpIn<=3,act:st=>{ st.fault=null; }},
   {t:'Adelanta tiempo y comprueba que la cámara llega a su consigna con pocos arranques.',check:st=>st.T<=st.SP+st.dif,ff:true}]},
 uCase('u4','cfan','Avería: salta el presostato de alta','«En verano la cámara se calienta y el equipo hace un ruido de golpe y para».'),
 uCase('u5','cond','Avería: la alta muy alta y gasta mucho','«El equipo no para nunca y la alta está muy alta; los ventiladores giran».'),
 uCase('u6','low','Avería: la cámara no llega y la baja está muy baja','«La cámara va cada día más caliente y el compresor casi no para».'),
 uCase('u7','efan','Avería: el evaporador se llena de hielo','«La cámara no enfría y el evaporador está blanco de hielo».'),
 uCase('u8','sol','Avería: el compresor no arranca nunca','«La cámara está caliente, el termostato pide frío y el compresor está parado».'),
 uCase('u9','km','Avería: pide frío, la baja da permiso y no arranca','«La cámara está caliente y el compresor no arranca, pero la presión de baja es alta».'),
 {id:'u0',n:'Práctica libre con el equipo partido',d:'Cambia consigna, presostatos y temperatura, y ponte averías sorpresa.',steps:[],free:'Práctica libre. Cambia la consigna, los presostatos o la temperatura de fuera, y pulsa «Poner una avería sorpresa» para practicar diagnósticos. Repara con los botones de «Reparar».'},
].forEach(l=>TRAIN.push(Object.assign({sec:'equi',ref:'any',page:'unit',meta:'Simulador de equipo partido'},l)));

