(()=>{ const add={herr:['Herramientas','Analizador, vacío, carga por peso, recuperación y prueba con nitrógeno, paso a paso.'],mont:['Montaje','Dónde va cada pieza, tuberías, sifones, sondas, soldadura y pruebas antes de cerrar la obra.'],equi:['Cámaras con equipo partido','Simulador de una cámara con su unidad condensadora: recogida de gas, presostatos y averías.']};
  const ord=['base','fun','apar','herr','elec','mont','proc','equi','diag','fault','exam']; const all=Object.assign({},TSEC,add); const o={}; ord.forEach(k=>{ if(all[k]) o[k]=all[k]; }); Object.keys(all).forEach(k=>{ if(!o[k]) o[k]=all[k]; });
  Object.keys(TSEC).forEach(k=>delete TSEC[k]); Object.assign(TSEC,o); })();
