  const sb=pkEl2('div','q1-schb'); sb.appendChild(pBtn('q-btn pri',`${last?'Continuar':'Empezar'} ${pic('arrow','pa')}`,()=>{ if(last) navGo(last); else { stSel.mode='train'; TRN.view=null; renderStart(); } })); sb.appendChild(pBtn('q-btn ghost2','Ver las secciones',()=>{ stSel.mode='train'; TRN.view=null; renderStart(); })); sch.appendChild(sb); box.appendChild(sch);
  const grp=(t,c,L)=>{ const g=pkEl2('div','q1-grp'); g.appendChild(pkEl2('div','q1-gh',`<b style="color:${c}">${t}</b>`)); const l=pkEl2('div','q1-gl'); L.forEach(([ic,tt,s,fn])=>l.appendChild(pBtn('q1-sim',`<span class="q1-oi">${pic(ic)}</span><span><b>${tt}</b><small>${s}</small></span>${pic('arrow','pa')}`,fn))); g.appendChild(l); return g; };
  const two=pkEl2('div','q1-two');
  two.appendChild(grp('Simular instalaciones','#9fd0ff',[['co2','Central de CO₂','Booster transcrítico',()=>pGo('co2')],['freon','Central de freón','R-404A · R-134a · R-410A',()=>pGo('freon')],['cam','Cámara frigorífica','Con su equipo partido',()=>freeOpen('cam')],['cube','Central en 3D','Abre y cierra llaves, mira los manómetros',()=>v3Home('co2','mix')]]));
  two.appendChild(grp('Herramientas y aparatos','#ffc76b',[['gauge','Analizador','Vacío, carga y recuperación',()=>freeOpen('ana')],['bolt','Polímetro y cableado','El termostato de un mueble',()=>freeOpen('wire')],['dev','Aparatos sueltos','Termostato, controlador, registrador…',freeDevices],['photo','Fotos y vídeos reales','Piezas y trabajos de verdad',()=>galOpen()]]));
  box.appendChild(two); opts.replaceWith(box);
