// ===== Centro técnico: calculadoras con fórmula, procedimiento, ejemplo y explicación en los dos niveles =====
// Las tablas de saturación (PT_TAB) se generan en Python con CoolProp (datos/gen_tablas.py). Presiones absolutas en bar.
const KL=(es,eu)=>(typeof LANG!=='undefined'&&LANG==='eu'&&eu)?eu:es;
const KT={open:false,cur:'pt',q:''};
const P_ATM=1.01325;
// ---------- números con coma decimal
const kN=v=>{ if(typeof v==='number') return v; const s=String(v||'').trim().replace(/\s/g,'').replace(',','.'); return s===''?NaN:Number(s); };
const kF=(v,d=2)=>{ if(v==null||!isFinite(v)) return '—'; const a=Math.abs(v); const dd=a!==0&&a<0.01?4:d; return v.toLocaleString('es-ES',{maximumFractionDigits:dd,minimumFractionDigits:0}); };
// ---------- tablas presión-temperatura (interpolación lineal entre grados)
function ptP(ref,T,kind){ const R=PT_TAB[ref]; if(!R) return NaN; const a=kind==='b'?R.pb:R.pd; const x=T-R.t0; if(x<0||x>a.length-1) return NaN; const i=Math.min(a.length-2,Math.floor(x)), f=x-i; return a[i]+(a[i+1]-a[i])*f; }
function ptT(ref,P,kind){ const R=PT_TAB[ref]; if(!R) return NaN; const a=kind==='b'?R.pb:R.pd; if(!(P>=a[0]&&P<=a[a.length-1])) return NaN; let i=0; while(i<a.length-2&&a[i+1]<P) i++; return R.t0+i+(P-a[i])/(a[i+1]-a[i]); }
const ptMax=ref=>{ const R=PT_TAB[ref]; return R.t0+R.pb.length-1; };
const glide=ref=>{ const R=PT_TAB[ref]; const i=10-R.t0; return R.pb&&R.pd?Math.abs(ptT(ref,(R.pb[i]+R.pd[i])/2,'d')-ptT(ref,(R.pb[i]+R.pd[i])/2,'b')):0; };
// ---------- unidades
const U_P={bar:[1,'bar'],kPa:[0.01,'kPa'],MPa:[10,'MPa'],psi:[0.0689476,'psi'],kgcm2:[0.980665,'kgf/cm²'],atm:[1.01325,'atm'],mmHg:[0.00133322,'mmHg']};
const U_Q={m3h:[1,'m³/h'],m3s:[3600,'m³/s'],ls:[3.6,'L/s'],lmin:[0.06,'L/min'],lh:[0.001,'L/h'],gpm:[0.227125,'gpm (EE. UU.)'],cfm:[1.699011,'CFM (ft³/min)']};
const U_W={kW:[1,'kW'],W:[0.001,'W'],kcalh:[1/859.845,'kcal/h (frig/h)'],btuh:[1/3412.142,'BTU/h'],tr:[3.516853,'TR (tonelada de refrigeración)'],cv:[0.7354988,'CV']};
const TUBOS=[['1/4"',6.35],['3/8"',9.52],['1/2"',12.7],['5/8"',15.88],['3/4"',19.05],['7/8"',22.22],['1 1/8"',28.58],['1 3/8"',34.92],['1 5/8"',41.28],['2 1/8"',53.98],['2 5/8"',66.68],['3 1/8"',79.38]];
const AGUA={10:[999.7,1.307e-3],20:[998.2,1.002e-3],40:[992.2,0.653e-3],60:[983.2,0.467e-3]}; // densidad kg/m³, viscosidad Pa·s
const refs=()=>Object.keys(PT_TAB);
const refOpt=()=>refs().map(r=>[r,r+` (${PT_TAB[r].saf})`]);
// ---------- definición de las calculadoras
// in: [k, etiqueta, tipo('n'|'sel'), por defecto, opciones o unidad]
const KC=[
 {id:'pt',cat:'ref',t:['Tabla presión ⇄ temperatura','Presio ⇄ tenperatura taula'],
  in:[['ref',['Refrigerante','Hozgarria'],'sel','R-744',refOpt],['modo',['Calcular','Kalkulatu'],'sel','p2t',()=>[['p2t',KL('temperatura a partir de la presión','tenperatura presiotik')],['t2p',KL('presión a partir de la temperatura','presioa tenperaturatik')]]],
      ['v',['Valor','Balioa'],'n','25,5',v=>v.modo==='p2t'?KL('bar (manómetro)','bar (manometroa)'):'°C'],['tipo',['La presión es','Presioa da'],'sel','rel',()=>[['rel',KL('relativa (la del manómetro)','erlatiboa (manometroarena)')],['abs',KL('absoluta','absolutua')]]]],
  run(v){ const R=PT_TAB[v.ref], x=kN(v.v); if(!isFinite(x)) return null; const s=[]; let res=[];
    if(v.modo==='p2t'){ const Pa=v.tipo==='rel'?x+P_ATM:x; s.push(KL(`Presión absoluta = ${v.tipo==='rel'?`${kF(x)} + 1,013 = `:''}${kF(Pa,3)} bar`,`Presio absolutua = ${v.tipo==='rel'?`${kF(x)} + 1,013 = `:''}${kF(Pa,3)} bar`));
      const tb=ptT(v.ref,Pa,'b'), td=ptT(v.ref,Pa,'d'); if(!isFinite(td)) return {err:KL(`Fuera de la tabla de ${v.ref} (${R.t0} a ${ptMax(v.ref)} °C).${v.ref==='R-744'?' Por encima de 72,8 bar relativos el CO₂ es supercrítico: no hay temperatura de saturación.':''}`,`${v.ref} taulatik kanpo (${R.t0}tik ${ptMax(v.ref)} °C-ra).${v.ref==='R-744'?' 72,8 bar erlatibotik gora CO₂a superkritikoa da: ez dago asetasun-tenperaturarik.':''}`)};
      if(Math.abs(tb-td)<0.05) res=[[KL('Temperatura de saturación','Asetasun-tenperatura'),kF(td,1)+' °C',1]];
      else { res=[[KL('Temperatura de rocío (vapor) → para el recalentamiento','Ihintz-tenperatura (lurruna) → gainberotzerako'),kF(td,1)+' °C',1],[KL('Temperatura de burbuja (líquido) → para el subenfriamiento','Burbuila-tenperatura (likidoa) → azpihoztzerako'),kF(tb,1)+' °C',1],[KL('Deslizamiento a esta presión','Irristatzea presio honetan'),kF(td-tb,1)+' K']]; }
      s.push(KL(`Se busca ${kF(Pa,3)} bar en la tabla de saturación de ${v.ref} y se interpola entre los dos grados más cercanos.`,`${kF(Pa,3)} bar ${v.ref}(r)en asetasun-taulan bilatzen da eta gertuen dauden bi graduen artean interpolatzen da.`)); }
    else { const pb=ptP(v.ref,x,'b'), pd=ptP(v.ref,x,'d'); if(!isFinite(pd)) return {err:KL(`Fuera de la tabla de ${v.ref} (${R.t0} a ${ptMax(v.ref)} °C).`,`${v.ref} taulatik kanpo (${R.t0}tik ${ptMax(v.ref)} °C-ra).`)};
      const off=v.tipo==='rel'?P_ATM:0, u=v.tipo==='rel'?KL(' bar (relativa)',' bar (erlatiboa)'):KL(' bar (absoluta)',' bar (absolutua)');
      if(Math.abs(pb-pd)<0.005) res=[[KL('Presión de saturación','Asetasun-presioa'),kF(pd-off,2)+u,1]]; else res=[[KL('Presión de burbuja (empieza a hervir)','Burbuila-presioa (irakiten hasten da)'),kF(pb-off,2)+u,1],[KL('Presión de rocío (termina de hervir)','Ihintz-presioa (irakiten amaitzen da)'),kF(pd-off,2)+u,1]];
      s.push(KL(`Se lee la presión absoluta a ${kF(x,1)} °C en la tabla${v.tipo==='rel'?' y se resta la atmosférica (1,013 bar)':''}.`,`Presio absolutua ${kF(x,1)} °C-tan irakurtzen da taulan${v.tipo==='rel'?' eta atmosferikoa kentzen da (1,013 bar)':''}.`)); }
    return {res,steps:s}; },
  f:'T_sat = f(P_absoluta)  ·  P_abs = P_manómetro + 1,013 bar',
  pri:['Cada refrigerante hierve a una temperatura distinta según la presión que tenga, igual que el agua hierve a 100 °C en la cazuela y a 120 °C en la olla exprés. Con esta tabla, mirando el manómetro sabes a qué temperatura está hirviendo (en el evaporador) o condensando (en el condensador).','Hozgarri bakoitza tenperatura desberdinean irakiten da duen presioaren arabera, ura kazolan 100 °C-tan eta lapiko azkarrean 120 °C-tan irakiten den bezala. Taula honekin, manometroari begiratuta badakizu zein tenperaturatan irakiten ari den (lurrungailuan) edo kondentsatzen (kondentsadorean).'],
  pro:['Las curvas de saturación se han calculado con CoolProp 8.0 (ecuaciones de estado de referencia). El R-449A se ha comprobado frente a la tabla del fabricante, con diferencias menores del 0,5 %. Entre grados se interpola linealmente. En las mezclas zeotrópicas (R-407C, R-449A) se usa la temperatura de <b>rocío</b> para el recalentamiento y la de <b>burbuja</b> para el subenfriamiento. Las del R-404A, R-507A y R-410A tienen un deslizamiento muy pequeño. La tabla del CO₂ termina en el punto crítico (31 °C y 73,8 bar abs).','Asetasun-kurbak CoolProp 8.0rekin kalkulatu dira (erreferentziako egoera-ekuazioak). R-449A fabrikatzailearen taularekin egiaztatu da, % 0,5etik beherako desberdintasunekin. Graduen artean linealki interpolatzen da. Nahaste zeotropikoetan (R-407C, R-449A) <b>ihintz</b>-tenperatura erabiltzen da gainberotzerako eta <b>burbuila</b>-tenperatura azpihoztzerako. R-404A, R-507A eta R-410A nahasteek irristatze oso txikia dute. CO₂aren taula puntu kritikoan amaitzen da (31 °C eta 73,8 bar abs).'],
  ex:{ref:'R-744',modo:'p2t',v:'25,5',tipo:'rel'},exT:['Una central de CO₂ marca 25,5 bar en la aspiración de positiva. Absoluta: 26,5 bar → evapora a unos −10 °C.','CO₂ zentral batek 25,5 bar markatzen ditu positiboko xurgaketan. Absolutua: 26,5 bar → −10 °C inguruan lurruntzen da.']},
 {id:'sh',cat:'ref',t:['Recalentamiento','Gainberotzea'],
  in:[['ref',['Refrigerante','Hozgarria'],'sel','R-404A',refOpt],['p',['Presión de aspiración (manómetro)','Xurgaketa-presioa (manometroa)'],'n','2,0','bar'],['t',['Temperatura del tubo (pinza)','Hodiaren tenperatura (pintza)'],'n','-13','°C'],['val',['Tipo de válvula','Balbula mota'],'sel','vet',()=>[['vet',KL('termostática','termostatikoa')],['eev',KL('electrónica','elektronikoa')]]]],
  run(v){ const p=kN(v.p), t=kN(v.t); if(!isFinite(p)||!isFinite(t)) return null; const Pa=p+P_ATM, ts=ptT(v.ref,Pa,'d'); if(!isFinite(ts)) return {err:KL('Esa presión está fuera de la tabla de este refrigerante.','Presio hori hozgarri honen taulatik kanpo dago.')};
    const sh=t-ts; const lo=v.val==='eev'?5:5, hi=v.val==='eev'?8:10;
    const ev=sh<2?['bad',KL('Muy bajo: riesgo de que llegue líquido al compresor.','Oso baxua: likidoa konpresorera iristeko arriskua.')]:sh<lo-1?['warn',KL('Bajo: la válvula alimenta de más o la sonda/bulbo lee mal.','Baxua: balbulak gehiegi elikatzen du edo zundak/bulboak gaizki irakurtzen du.')]:sh<=hi?['ok',KL('Normal.','Normala.')]:sh<=15?['warn',KL('Algo alto: al evaporador le llega poco refrigerante.','Altu samarra: lurrungailura hozgarri gutxi iristen da.')]:['bad',KL('Muy alto: falta refrigerante en el evaporador (falta de gas, filtro o válvula obstruidos, válvula pequeña).','Oso altua: lurrungailuan hozgarria falta da (gas falta, iragazkia edo balbula buxatuta, balbula txikia).')];
    return {res:[[KL('Temperatura de evaporación (rocío)','Lurruntze-tenperatura (ihintza)'),kF(ts,1)+' °C'],[KL('Recalentamiento','Gainberotzea'),kF(sh,1)+' K',1]],ev,
      steps:[`P abs = ${kF(p)} + 1,013 = ${kF(Pa,3)} bar`,KL(`T evaporación (rocío de ${v.ref} a ${kF(Pa,3)} bar) = ${kF(ts,1)} °C`,`T lurruntzea (${v.ref} ihintza ${kF(Pa,3)} bar-etan) = ${kF(ts,1)} °C`),`SH = ${kF(t,1)} − (${kF(ts,1)}) = ${kF(sh,1)} K`]}; },
  f:'SH = T_tubo − T_sat,rocío(P_aspiración)',
  pri:['El recalentamiento dice si al evaporador le llega la cantidad justa de refrigerante. Cuando el refrigerante termina de hervir, el gas se sigue calentando unos grados: esos grados son el recalentamiento. Si sale casi 0, puede llegar líquido al compresor; si sale muy alto, el evaporador va medio vacío y enfría poco.','Gainberotzeak esaten du lurrungailura hozgarri kopuru zuzena iristen den. Hozgarria irakiten amaitzen duenean, gasa gradu batzuk gehiago berotzen da: gradu horiek gainberotzea dira. Ia 0 ateratzen bada, likidoa konpresorera irits daiteke; oso altua bada, lurrungailua erdi hutsik doa eta gutxi hozten du.'],
  pro:['Recalentamiento <b>en el evaporador</b>: presión y temperatura a la salida del evaporador, junto al bulbo o la sonda. Recalentamiento <b>total</b>: temperatura a la entrada del compresor. Si hay una caída de presión importante en la aspiración, la presión se toma cerca del evaporador. Con mezclas se usa la temperatura de rocío. Rangos orientativos: 5-10 K con VET y 5-8 K con EEV. Por debajo de 2 K hay riesgo de golpe de líquido y de dilución del aceite. Un recalentamiento alto sube la temperatura de descarga y baja la capacidad. La sonda tiene que ir bien apretada y aislada: una sonda suelta lee de más.','<b>Lurrungailuko</b> gainberotzea: presioa eta tenperatura lurrungailuaren irteeran, bulboaren edo zundaren ondoan. Gainberotze <b>osoa</b>: konpresorearen sarrerako tenperatura. Xurgaketan presio-jaitsiera handia badago, presioa lurrungailutik gertu hartzen da. Nahasteekin ihintz-tenperatura erabiltzen da. Tarte orientagarriak: 5-10 K VETarekin eta 5-8 K EEVarekin. 2 K-tik behera likido-kolpearen eta olioa diluitzearen arriskua dago. Gainberotze altuak deskarga-tenperatura igotzen du eta ahalmena jaisten du. Zundak ondo estututa eta isolatuta joan behar du: zunda solteak gehiago irakurtzen du.'],
  ex:{ref:'R-404A',p:'2,0',t:'-13',val:'vet'},exT:['R-404A, 2,0 bar en la aspiración (−20 °C de rocío) y el tubo a −13 °C → unos 7 K: normal.','R-404A, 2,0 bar xurgaketan (−20 °C ihintza) eta hodia −13 °C-tan → 7 K inguru: normala.']},
 {id:'sc',cat:'ref',t:['Subenfriamiento','Azpihoztea'],
  in:[['ref',['Refrigerante','Hozgarria'],'sel','R-404A',()=>refOpt().filter(r=>r[0]!=='R-744')],['p',['Presión de alta (manómetro)','Presio altua (manometroa)'],'n','18','bar'],['t',['Temperatura de la línea de líquido','Likido-lerroaren tenperatura'],'n','37','°C']],
  run(v){ const p=kN(v.p), t=kN(v.t); if(!isFinite(p)||!isFinite(t)) return null; const Pa=p+P_ATM, ts=ptT(v.ref,Pa,'b'); if(!isFinite(ts)) return {err:KL('Esa presión está fuera de la tabla de este refrigerante.','Presio hori hozgarri honen taulatik kanpo dago.')};
    const sc=ts-t; const ev=sc<1?['bad',KL('Sin subenfriamiento: llega mezcla con gas a la válvula (falta de carga, restricción o poco condensador).','Azpihozterik gabe: gasarekin nahastuta iristen da balbulara (karga falta, murrizketa edo kondentsadore gutxi).')]:sc<3?['warn',KL('Bajo: comprueba la carga y el visor.','Baxua: egiaztatu karga eta ikusgailua.')]:sc<=8?['ok',KL('Normal.','Normala.')]:['warn',KL('Alto: líquido acumulado en el condensador (exceso de carga o regulación de condensación en invierno).','Altua: likidoa kondentsadorean pilatuta (karga gehiegi edo neguko kondentsazio-erregulazioa).')];
    return {res:[[KL('Temperatura de condensación (burbuja)','Kondentsazio-tenperatura (burbuila)'),kF(ts,1)+' °C'],[KL('Subenfriamiento','Azpihoztea'),kF(sc,1)+' K',1]],ev,
      steps:[`P abs = ${kF(p)} + 1,013 = ${kF(Pa,3)} bar`,KL(`T condensación (burbuja de ${v.ref}) = ${kF(ts,1)} °C`,`T kondentsazioa (${v.ref} burbuila) = ${kF(ts,1)} °C`),`SC = ${kF(ts,1)} − ${kF(t,1)} = ${kF(sc,1)} K`]}; },
  f:'SC = T_sat,burbuja(P_alta) − T_línea',
  pri:['El subenfriamiento dice cuántos grados está el líquido por debajo de su temperatura de hervir. Si hay subenfriamiento, a la válvula le llega líquido «de verdad», sin burbujas. Si es 0, llega mezclado con gas y la instalación enfría mal.','Azpihozteak esaten du likidoa irakite-tenperaturatik zenbat gradu behera dagoen. Azpihoztea badago, balbulara «benetako» likidoa iristen da, burbuilarik gabe. 0 bada, gasarekin nahastuta iristen da eta instalazioak gaizki hozten du.'],
  pro:['Se mide con la presión lo más cerca posible del condensador y la temperatura antes de la válvula (subenfriamiento total) o a la salida del condensador. Con mezclas se usa la temperatura de burbuja. En el CO₂ transcrítico no hay subenfriamiento en el gas cooler: se controla la temperatura de salida y la presión del recipiente. Valores orientativos: 3-6 K en instalaciones con recipiente y un poco más en equipos sin recipiente. Si es alto, junto con una alta elevada, apunta a exceso de carga.','Presioa kondentsadoretik ahalik eta gertuen neurtzen da, eta tenperatura balbularen aurretik (azpihozte osoa) edo kondentsadorearen irteeran. Nahasteekin burbuila-tenperatura erabiltzen da. CO₂ transkritikoan ez dago azpihozterik gas-hozgailuan: irteerako tenperatura eta hartzailearen presioa kontrolatzen dira. Balio orientagarriak: 3-6 K hartzailedun instalazioetan eta pixka bat gehiago hartzailerik gabeko ekipoetan. Altua bada, altuko presio handiarekin batera, karga gehiegi adierazten du.'],
  ex:{ref:'R-404A',p:'18',t:'37'},exT:['R-404A: alta a 18 bar (unos 41,6 °C de burbuja) y líquido a 37 °C → unos 4,6 K: correcto.','R-404A: altua 18 bar-etan (41,6 °C inguruko burbuila) eta likidoa 37 °C-tan → 4,6 K inguru: zuzena.']},
 {id:'diag',cat:'ref',t:['Interpretar presiones y temperaturas','Presioak eta tenperaturak interpretatu'],
  in:[['te',['Temperatura de evaporación','Lurruntze-tenperatura'],'n','-10','°C'],['tc',['Temperatura de condensación','Kondentsazio-tenperatura'],'n','45','°C'],['ta',['Aire de entrada al condensador','Kondentsadorearen sarrerako airea'],'n','30','°C'],['sh',['Recalentamiento','Gainberotzea'],'n','6','K'],['sc',['Subenfriamiento','Azpihoztea'],'n','4','K'],['tcam',['Temperatura de la cámara o del mueble','Ganberaren edo altzariaren tenperatura'],'n','2','°C']],
  run(v){ const te=kN(v.te),tc=kN(v.tc),ta=kN(v.ta),sh=kN(v.sh),sc=kN(v.sc),tm=kN(v.tcam); if([te,tc,ta,sh,sc,tm].some(x=>!isFinite(x))) return null;
    const dc=tc-ta, de=tm-te, O=[], C=[];
    O.push([KL('Salto en el condensador (Tc − aire)','Kondentsadoreko jauzia (Tc − airea)'),kF(dc,1)+' K',dc>15?'bad':dc<5?'warn':'ok',dc>15?KL('alto (normal 8-15 K)','altua (normala 8-15 K)'):dc<5?KL('muy bajo','oso baxua'):KL('normal','normala')]);
    O.push([KL('Salto en el evaporador (cámara − Te)','Lurrungailuko jauzia (ganbera − Te)'),kF(de,1)+' K',de>12?'bad':de<4?'warn':'ok',de>12?KL('alto (normal 6-10 K)','altua (normala 6-10 K)'):de<4?KL('muy bajo','oso baxua'):KL('normal','normala')]);
    O.push([KL('Recalentamiento','Gainberotzea'),kF(sh,1)+' K',sh<2?'bad':sh>12?'bad':'ok',sh<2?KL('muy bajo','oso baxua'):sh>12?KL('alto','altua'):KL('normal','normala')]);
    O.push([KL('Subenfriamiento','Azpihoztea'),kF(sc,1)+' K',sc<1?'bad':sc>10?'warn':'ok',sc<1?KL('nulo','nulua'):sc>10?KL('alto','altua'):KL('normal','normala')]);
    const hiSH=sh>12, loSC=sc<1, hiSC=sc>10, hiDC=dc>15, hiDE=de>12, loSH=sh<2;
    if(hiSH&&loSC) C.push([KL('Falta de refrigerante (fuga)','Hozgarri falta (ihesa)'),KL('Recalentamiento alto y subenfriamiento nulo. Normalmente la alta y la baja también bajan. Comprueba: burbujas en el visor, nivel del recipiente, detector de fugas. No cargues sin encontrar la fuga.','Gainberotze altua eta azpihozte nulua. Normalean altua eta baxua ere jaisten dira. Egiaztatu: burbuilak ikusgailuan, hartzailearen maila, ihes-detektagailua. Ez kargatu ihesa aurkitu gabe.')]);
    if(hiSH&&!loSC) C.push([KL('Restricción en la línea de líquido o en la válvula','Murrizketa likido-lerroan edo balbulan'),KL('Recalentamiento alto con subenfriamiento normal: hay líquido, pero no pasa. Comprueba: diferencia de temperatura antes y después del filtro y de la solenoide, filtro de la válvula, bulbo o sonda de la válvula.','Gainberotze altua azpihozte normalarekin: likidoa badago, baina ez da pasatzen. Egiaztatu: tenperatura-aldea iragazkiaren eta solenoidearen aurretik eta ondoren, balbularen iragazkia, balbularen bulboa edo zunda.')]);
    if(hiDC&&hiSC) C.push([KL('Exceso de carga','Karga gehiegi'),KL('Salto alto en el condensador con mucho subenfriamiento: el líquido ocupa parte del condensador. Comprueba el nivel del recipiente y la carga de placa.','Kondentsadoreko jauzi altua azpihozte handiarekin: likidoak kondentsadorearen zati bat hartzen du. Egiaztatu hartzailearen maila eta plakako karga.')]);
    if(hiDC&&!hiSC) C.push([KL('Condensador con poco intercambio (sucio, ventilador parado o girando al revés, aire caliente que recircula) o incondensables','Truke gutxiko kondentsadorea (zikina, haizagailua geldituta edo alderantziz biraka, aire beroa birzirkulatzen) edo kondentsaezinak'),KL('Salto alto con subenfriamiento normal. Comprueba limpieza, ventiladores, sentido de giro y entrada de aire. Si todo está bien y se ha abierto el circuito hace poco, prueba de incondensables.','Jauzi altua azpihozte normalarekin. Egiaztatu garbitasuna, haizagailuak, biratze-noranzkoa eta aire-sarrera. Dena ondo badago eta zirkuitua duela gutxi ireki bada, kondentsaezinen proba.')]);
    if(hiDE&&!hiSH) C.push([KL('Evaporador con poco intercambio (hielo, ventilador parado, suciedad)','Truke gutxiko lurrungailua (izotza, haizagailua geldituta, zikinkeria)'),KL('Mucha diferencia entre el aire y la evaporación con recalentamiento normal o bajo: el refrigerante llega, pero el aire no le da calor. Comprueba hielo, ventiladores y desescarches.','Aldea handia airearen eta lurruntzearen artean gainberotze normal edo baxuarekin: hozgarria iristen da, baina aireak ez dio berorik ematen. Egiaztatu izotza, haizagailuak eta izotz-kentzeak.')]);
    if(loSH) C.push([KL('Válvula de expansión que alimenta de más (o bulbo/sonda mal colocados)','Gehiegi elikatzen duen hedapen-balbula (edo bulboa/zunda gaizki jarrita)'),KL('Recalentamiento casi nulo: riesgo de líquido al compresor. Comprueba el ajuste, la posición y el aislamiento del bulbo o la sonda, y el transductor.','Gainberotze ia nulua: likidoa konpresorera iristeko arriskua. Egiaztatu doikuntza, bulboaren edo zundaren kokapena eta isolamendua, eta transduktorea.')]);
    if(!C.length) C.push([KL('Valores dentro de lo normal','Balioak normalaren barruan'),KL('Con estos datos no aparece una avería del circuito frigorífico. Si la cámara no llega a su temperatura, revisa la carga térmica (puertas, producto caliente), las consignas y la parte eléctrica.','Datu hauekin ez da hozte-zirkuituko matxurarik agertzen. Ganbera bere tenperaturara iristen ez bada, berrikusi karga termikoa (ateak, produktu beroa), kontsignak eta zati elektrikoa.')]);
    return {obs:O,cands:C,steps:[`Tc − T_aire = ${kF(tc,1)} − ${kF(ta,1)} = ${kF(dc,1)} K`,`T_cámara − Te = ${kF(tm,1)} − (${kF(te,1)}) = ${kF(de,1)} K`]}; },
  f:'Comparar: Tc − T_aire · T_cámara − Te · SH · SC  con los valores normales',
  pri:['Con cuatro medidas (alta, baja, recalentamiento y subenfriamiento) y dos temperaturas de aire se pueden separar las averías más habituales. Esta herramienta no adivina la avería: te dice qué valores se salen de lo normal y qué averías encajan, y qué tienes que comprobar para estar seguro.','Lau neurrirekin (altua, baxua, gainberotzea eta azpihoztea) eta aireko bi tenperaturarekin ohiko matxura gehienak bereiz daitezke. Tresna honek ez du matxura asmatzen: esaten dizu zein balio dauden normaletik kanpo eta zein matxura datozen bat, eta zer egiaztatu behar duzun ziur egoteko.'],
  pro:['Lógica de diferenciación: <b>SH alto + SC ≈ 0</b> → falta de carga. <b>SH alto + SC normal</b> → restricción. <b>ΔT de condensación alta + SC alto</b> → exceso de carga. <b>ΔT de condensación alta + SC normal</b> → condensador o incondensables. <b>ΔT de evaporación alta + SH normal o bajo</b> → problema de aire en el evaporador. <b>SH &lt; 2 K</b> → sobrealimentación de la válvula. Los rangos son orientativos para aerocondensadores y servicios de positiva. Siempre se confirma con comprobaciones (visor, ΔT en el filtro, consumos, prueba de incondensables) antes de reparar.','Bereizteko logika: <b>SH altua + SC ≈ 0</b> → karga falta. <b>SH altua + SC normala</b> → murrizketa. <b>Kondentsazioko ΔT altua + SC altua</b> → karga gehiegi. <b>Kondentsazioko ΔT altua + SC normala</b> → kondentsadorea edo kondentsaezinak. <b>Lurruntzeko ΔT altua + SH normala edo baxua</b> → aire-arazoa lurrungailuan. <b>SH &lt; 2 K</b> → balbularen gainelikadura. Tarteak orientagarriak dira aerokondentsadore eta positiboko zerbitzuetarako. Beti egiaztapenekin baieztatzen da (ikusgailua, ΔT iragazkian, kontsumoak, kondentsaezinen proba) konpondu aurretik.'],
  ex:{te:'-14',tc:'38',ta:'30',sh:'22',sc:'0',tcam:'7'},exT:['Te −14 °C, Tc 38 °C con 30 °C fuera, recalentamiento 22 K, subenfriamiento 0 K y la cámara a 7 °C: todo apunta a falta de refrigerante.','Te −14 °C, Tc 38 °C kanpoan 30 °C-rekin, gainberotzea 22 K, azpihoztea 0 K eta ganbera 7 °C-tan: dena hozgarri faltara doa.']},
 {id:'rc',cat:'ref',t:['Relación de compresión','Konpresio-erlazioa'],
  in:[['pa',['Presión de alta (manómetro)','Presio altua (manometroa)'],'n','16','bar'],['pb',['Presión de baja (manómetro)','Presio baxua (manometroa)'],'n','2','bar']],
  run(v){ const a=kN(v.pa),b=kN(v.pb); if(!isFinite(a)||!isFinite(b)) return null; const A=a+P_ATM,B=b+P_ATM; if(B<=0) return {err:KL('La presión absoluta de baja no puede ser 0 o negativa.','Baxuko presio absolutua ezin da 0 edo negatiboa izan.')}; const rc=A/B;
    return {res:[[KL('Relación de compresión','Konpresio-erlazioa'),kF(rc,2),1]],ev:rc>10?['bad',KL('Muy alta para una sola etapa: descarga muy caliente y poco rendimiento.','Oso altua etapa bakarrerako: deskarga oso beroa eta errendimendu txikia.')]:rc>7?['warn',KL('Alta: vigila la temperatura de descarga.','Altua: zaindu deskarga-tenperatura.')]:['ok',KL('Normal.','Normala.')],steps:[`(${kF(a)} + 1,013) / (${kF(b)} + 1,013) = ${kF(A,3)} / ${kF(B,3)} = ${kF(rc,2)}`]}; },
  f:'RC = P_alta,abs / P_baja,abs',
  pri:['Dice cuántas veces aprieta el compresor el gas. Cuanto más alta, más le cuesta: gasta más, se calienta más y da menos frío.','Konpresoreak gasa zenbat aldiz estutzen duen esaten du. Zenbat eta altuagoa, orduan eta gehiago kostatzen zaio: gehiago kontsumitzen du, gehiago berotzen da eta hotz gutxiago ematen du.'],
  pro:['Siempre en presiones absolutas. Al subir la RC baja el rendimiento volumétrico (por la reexpansión del espacio muerto) y sube la temperatura de descarga. En compresores alternativos de una etapa se suele trabajar por debajo de 8-10. Para RC mayores se usa doble etapa o booster (CO₂).','Beti presio absolutuetan. RC igotzean, errendimendu bolumetrikoa jaisten da (espazio hilaren berrhedapenagatik) eta deskarga-tenperatura igotzen da. Etapa bakarreko konpresore alternatiboetan 8-10etik behera lan egin ohi da. RC handiagoetarako etapa bikoitza edo boosterra erabiltzen da (CO₂).'],
  ex:{pa:'16',pb:'2'},exT:['Alta 16 bar y baja 2 bar en el manómetro: 17,0 / 3,0 = 5,7.','Altua 16 bar eta baxua 2 bar manometroan: 17,0 / 3,0 = 5,7.']},
 {id:'co2eq',cat:'ref',t:['Toneladas de CO₂ equivalente y control de fugas','CO₂ baliokideko tonak eta ihes-kontrola'],
  in:[['kg',['Carga de refrigerante','Hozgarri-karga'],'n','20','kg'],['pca',['PCA (GWP) del refrigerante (etiqueta)','Hozgarriaren BEP (GWP) (etiketa)'],'n','3922',''],['det',['¿Tiene sistema de detección de fugas?','Ihes-detekzio sistemarik du?'],'sel','no',()=>[['no',KL('no','ez')],['si',KL('sí','bai')]]]],
  run(v){ const kg=kN(v.kg),g=kN(v.pca); if(!isFinite(kg)||!isFinite(g)) return null; const t=kg*g/1000, d=v.det==='si';
    const f=t<5?KL('sin control periódico obligatorio por carga','kargagatik derrigorrezko kontrol periodikorik gabe'):t<50?(d?KL('cada 24 meses','24 hilabetean behin'):KL('cada 12 meses','12 hilabetean behin')):t<500?(d?KL('cada 12 meses','12 hilabetean behin'):KL('cada 6 meses','6 hilabetean behin')):(d?KL('cada 6 meses','6 hilabetean behin'):KL('cada 3 meses','3 hilabetean behin'));
    return {res:[[KL('Carga en CO₂ equivalente','Karga CO₂ baliokidean'),kF(t,1)+' t CO₂-eq',1],[KL('Control de fugas','Ihes-kontrola'),f]],ev:t>=500&&!d?['bad',KL('A partir de 500 t CO₂-eq es obligatorio un sistema fijo de detección de fugas.','500 t CO₂-eq-tik aurrera ihes-detekzio sistema finkoa derrigorrezkoa da.')]:null,steps:[`${kF(kg)} kg × ${kF(g,0)} / 1000 = ${kF(t,1)} t CO₂-eq`]}; },
  f:'t CO₂-eq = kg × PCA / 1000',
  pri:['Sirve para saber cada cuánto hay que revisar las fugas de una instalación con gases fluorados. No depende de los kilos, sino de cuánto calentaría el planeta ese gas si se escapara.','Gas fluordunak dituen instalazio baten ihesak zenbatean behin berrikusi behar diren jakiteko balio du. Ez dago kiloen araberakoa, baizik eta gas horrek planeta zenbat berotuko lukeen ihes egingo balu.'],
  pro:['Frecuencias del Reglamento (UE) 2024/573 (art. 5): de 5 a menos de 50 t, cada 12 meses (24 con detección); de 50 a menos de 500 t, cada 6 meses (12 con detección); 500 t o más, cada 3 meses (6 con detección) y detección fija obligatoria. Se apuntan en el registro de la instalación. El CO₂ (R-744), los hidrocarburos y el amoniaco no son gases fluorados. Usa el PCA de la etiqueta del equipo o de la ficha del refrigerante: varía según la versión del informe del IPCC que use la norma.','(EB) 2024/573 Erregelamenduaren maiztasunak (5. art.): 5etik 50 t baino gutxiagora, 12 hilabetean behin (24 detekzioarekin); 50etik 500 t baino gutxiagora, 6 hilabetean behin (12 detekzioarekin); 500 t edo gehiago, 3 hilabetean behin (6 detekzioarekin) eta detekzio finkoa derrigorrezkoa. Instalazioaren erregistroan idazten dira. CO₂a (R-744), hidrokarburoak eta amoniakoa ez dira gas fluordunak. Erabili ekipoaren etiketako edo hozgarriaren fitxako BEPa: araudiak erabiltzen duen IPCC txostenaren bertsioaren arabera aldatzen da.'],
  ex:{kg:'20',pca:'3922',det:'no'},exT:['20 kg de R-404A (PCA 3922) = 78,4 t CO₂-eq → control cada 6 meses sin detector.','20 kg R-404A (BEP 3922) = 78,4 t CO₂-eq → kontrola 6 hilabetean behin detektagailurik gabe.']},
 {id:'cp',cat:'conv',t:['Conversión de presión','Presio-bihurketa'],
  in:[['v',['Valor','Balioa'],'n','10',''],['u',['Unidad','Unitatea'],'sel','bar',()=>Object.entries(U_P).map(([k,x])=>[k,x[1]])],['tipo',['Tipo','Mota'],'sel','rel',()=>[['rel',KL('relativa (manómetro)','erlatiboa (manometroa)')],['abs',KL('absoluta','absolutua')]]]],
  run(v){ const x=kN(v.v); if(!isFinite(x)) return null; const b=x*U_P[v.u][0], rel=v.tipo==='rel'?b:b-P_ATM, abs=rel+P_ATM;
    return {table:{h:[KL('Unidad','Unitatea'),KL('Relativa','Erlatiboa'),KL('Absoluta','Absolutua')],r:Object.values(U_P).map(([k,n])=>[n,kF(rel/k,3),kF(abs/k,3)])},steps:[KL(`En bar: ${kF(b,4)} ${v.tipo==='rel'?'relativos':'absolutos'} → absoluta = relativa + 1,01325 bar`,`Bar-etan: ${kF(b,4)} ${v.tipo==='rel'?'erlatibo':'absolutu'} → absolutua = erlatiboa + 1,01325 bar`)]}; },
  f:'1 bar = 100 kPa = 0,1 MPa = 14,504 psi = 1,0197 kgf/cm² · P_abs = P_rel + 1,01325 bar',
  pri:['Pasa una presión a otras unidades. Los manómetros americanos marcan en psi; las tablas a veces van en presión absoluta.','Presio bat beste unitate batzuetara pasatzen du. Manometro amerikarrek psi-tan markatzen dute; taulak batzuetan presio absolutuan daude.'],
  pro:['Factores exactos: 1 psi = 6,894757 kPa, 1 kgf/cm² = 98,0665 kPa, 1 atm = 101,325 kPa, 1 mmHg = 133,322 Pa. La presión atmosférica de referencia es la estándar al nivel del mar (1,01325 bar). En altura, la real es menor.','Faktore zehatzak: 1 psi = 6,894757 kPa, 1 kgf/cm² = 98,0665 kPa, 1 atm = 101,325 kPa, 1 mmHg = 133,322 Pa. Erreferentziako presio atmosferikoa itsas mailako estandarra da (1,01325 bar). Altueran, benetakoa txikiagoa da.'],
  ex:{v:'145',u:'psi',tipo:'rel'},exT:['145 psi en un manómetro americano son unos 10 bar relativos (11 bar absolutos).','145 psi manometro amerikar batean 10 bar erlatibo inguru dira (11 bar absolutu).']},
 {id:'ct',cat:'conv',t:['Conversión de temperatura','Tenperatura-bihurketa'],
  in:[['v',['Valor','Balioa'],'n','-18',''],['u',['Unidad','Unitatea'],'sel','C',()=>[['C','°C'],['F','°F'],['K','K']]]],
  run(v){ const x=kN(v.v); if(!isFinite(x)) return null; const c=v.u==='C'?x:v.u==='F'?(x-32)/1.8:x-273.15; if(c<-273.15) return {err:KL('Por debajo del cero absoluto.','Zero absolututik behera.')};
    return {res:[['°C',kF(c,2),v.u!=='C'],['°F',kF(c*1.8+32,2),v.u!=='F'],['K',kF(c+273.15,2),v.u!=='K']],steps:['°F = °C × 1,8 + 32','K = °C + 273,15']}; },
  f:'°F = °C × 1,8 + 32 · K = °C + 273,15 · una diferencia de 1 K = 1 °C = 1,8 °F',
  pri:['Pasa temperaturas entre grados Celsius, Fahrenheit y kelvin. Las diferencias de temperatura (por ejemplo, el recalentamiento) se dan en K, que es lo mismo que una diferencia en °C.','Tenperaturak Celsius, Fahrenheit eta kelvin graduen artean pasatzen ditu. Tenperatura-diferentziak (adibidez, gainberotzea) K-tan ematen dira, °C-tako diferentzia bera dena.'],
  pro:['Para un intervalo (ΔT) no se suma el 32: 10 K = 10 °C = 18 °F de diferencia. En las fórmulas termodinámicas (Carnot, gases ideales) la temperatura va siempre en kelvin.','Tarte baterako (ΔT) ez da 32 gehitzen: 10 K = 10 °C = 18 °F-ko diferentzia. Formula termodinamikoetan (Carnot, gas idealak) tenperatura beti kelvinetan doa.'],
  ex:{v:'0',u:'F'},exT:['0 °F son −17,8 °C.','0 °F −17,8 °C dira.']},
 {id:'cq',cat:'conv',t:['Conversión de caudal','Emari-bihurketa'],
  in:[['v',['Valor','Balioa'],'n','1',''],['u',['Unidad','Unitatea'],'sel','m3h',()=>Object.entries(U_Q).map(([k,x])=>[k,x[1]])]],
  run(v){ const x=kN(v.v); if(!isFinite(x)) return null; const m=x*U_Q[v.u][0]; return {table:{h:[KL('Unidad','Unitatea'),KL('Valor','Balioa')],r:Object.values(U_Q).map(([k,n])=>[n,kF(m/k,4)])},steps:[KL(`En m³/h: ${kF(m,4)}`,`m³/h-tan: ${kF(m,4)}`)]}; },
  f:'1 m³/h = 0,2778 L/s = 16,667 L/min = 4,403 gpm = 0,5886 CFM',
  pri:['Pasa un caudal (agua, aire) entre unidades. Por ejemplo, los ventiladores americanos dan el caudal en CFM y las bombas en litros por minuto o m³/h.','Emari bat (ura, airea) unitateen artean pasatzen du. Adibidez, haizagailu amerikarrek emaria CFM-tan ematen dute eta ponpek litro minutuko edo m³/h-tan.'],
  pro:['Factores: 1 gal (EE. UU.) = 3,785412 L; 1 ft³ = 28,31685 L. Para caudales másicos, multiplica por la densidad del fluido.','Faktoreak: 1 gal (AEB) = 3,785412 L; 1 ft³ = 28,31685 L. Masa-emarietarako, biderkatu fluidoaren dentsitateaz.'],
  ex:{v:'2000',u:'cfm'},exT:['Un ventilador de 2 000 CFM mueve unos 3 398 m³/h.','2 000 CFM-ko haizagailu batek 3 398 m³/h inguru mugitzen ditu.']},
 {id:'cw',cat:'conv',t:['Conversión de potencia','Potentzia-bihurketa'],
  in:[['v',['Valor','Balioa'],'n','5',''],['u',['Unidad','Unitatea'],'sel','kW',()=>Object.entries(U_W).map(([k,x])=>[k,x[1]])]],
  run(v){ const x=kN(v.v); if(!isFinite(x)) return null; const k=x*U_W[v.u][0]; return {table:{h:[KL('Unidad','Unitatea'),KL('Valor','Balioa')],r:Object.values(U_W).map(([f,n])=>[n,kF(k/f,3)])},steps:[KL(`En kW: ${kF(k,4)}`,`kW-tan: ${kF(k,4)}`)]}; },
  f:'1 kW = 859,85 kcal/h (frig/h) = 3 412,1 BTU/h · 1 TR = 3,5169 kW = 12 000 BTU/h',
  pri:['Pasa una potencia entre kilovatios, frigorías por hora, BTU/h y toneladas de refrigeración. Ojo: los kW de frío de un equipo no son los kW eléctricos que consume.','Potentzia bat kilowatt, frigoria orduko, BTU/h eta hozte-tonen artean pasatzen du. Kontuz: ekipo baten hotz-kW-ak ez dira kontsumitzen dituen kW elektrikoak.'],
  pro:['La frigoría es una kilocaloría que se quita (1 frig/h = 1 kcal/h = 1,163 W). La TR es el calor necesario para fundir una tonelada corta de hielo en 24 h (12 000 BTU/h). El CV es el caballo de vapor métrico (735,5 W).','Frigoria kentzen den kilokaloria bat da (1 frig/h = 1 kcal/h = 1,163 W). TR tona motz bat izotz 24 orduan urtzeko behar den beroa da (12 000 BTU/h). CV zaldi-potentzia metrikoa da (735,5 W).'],
  ex:{v:'2500',u:'kcalh'},exT:['Un equipo de 2 500 frig/h da unos 2,9 kW de frío.','2 500 frig/h-ko ekipo batek 2,9 kW inguru hotz ematen ditu.']},
 {id:'vel',cat:'tub',t:['Velocidad del fluido en una tubería','Fluidoaren abiadura hodi batean'],
  in:[['q',['Caudal','Emaria'],'n','2','m³/h'],['tubo',['Tubo de cobre (diámetro exterior)','Kobre-hodia (kanpo-diametroa)'],'sel','6',()=>TUBOS.map((t,i)=>[String(i),`${t[0]} · ${kF(t[1],2)} mm`]).concat([['otro',KL('otro (escribe el diámetro interior)','beste bat (idatzi barne-diametroa)')]])],['e',['Espesor de pared','Hormaren lodiera'],'n','1','mm'],['di',['Diámetro interior (si es «otro»)','Barne-diametroa («beste bat» bada)'],'n','','mm']],
  run(v){ const q=kN(v.q); let di; if(v.tubo==='otro') di=kN(v.di); else { const e=kN(v.e); di=TUBOS[+v.tubo][1]-2*e; } if(!isFinite(q)||!(di>0)) return null;
    const A=Math.PI*Math.pow(di/1000,2)/4, vel=q/3600/A; return {res:[[KL('Diámetro interior','Barne-diametroa'),kF(di,2)+' mm'],[KL('Sección','Sekzioa'),kF(A*1e4,3)+' cm²'],[KL('Velocidad','Abiadura'),kF(vel,2)+' m/s',1]],
      steps:[`A = π · (${kF(di,2)} / 1000)² / 4 = ${kF(A*1e6,1)} mm²`,`v = Q / A = (${kF(q,3)} / 3600) / ${kF(A,6)} = ${kF(vel,2)} m/s`]}; },
  f:'v = Q / A · A = π · D_int² / 4',
  pri:['Calcula a qué velocidad va un líquido o un gas por dentro de un tubo. Si va muy despacio, el aceite no vuelve al compresor (en la aspiración); si va muy deprisa, hace ruido, golpes de ariete y pierde mucha presión.','Likido edo gas bat hodi baten barrutik zein abiaduratan doan kalkulatzen du. Oso poliki badoa, olioa ez da konpresorera itzultzen (xurgaketan); oso azkar badoa, zarata, ariete-kolpeak eta presio-galera handia sortzen ditu.'],
  pro:['Velocidades orientativas en refrigeración: aspiración de 5 a 10 m/s (al menos unos 7 m/s en las subidas para arrastrar el aceite), descarga de 7,5 a 15 m/s y líquido de 0,5 a 1 m/s (como mucho 1,5). En agua o glicol, de 0,5 a 2 m/s según el diámetro. El espesor depende de la serie de tubo y de la presión de trabajo: compruébalo en el catálogo, sobre todo en CO₂ (K65). Para el caudal volumétrico de refrigerante necesitas el caudal másico y la densidad en ese punto.','Abiadura orientagarriak hoztean: xurgaketa 5etik 10 m/s-ra (gutxienez 7 m/s inguru igoeretan olioa arrastatzeko), deskarga 7,5etik 15 m/s-ra eta likidoa 0,5etik 1 m/s-ra (gehienez 1,5). Uretan edo glikolean, 0,5etik 2 m/s-ra diametroaren arabera. Lodiera hodi-seriearen eta lan-presioaren araberakoa da: egiaztatu katalogoan, batez ere CO₂an (K65). Hozgarriaren emari bolumetrikorako masa-emaria eta puntu horretako dentsitatea behar dituzu.'],
  ex:{q:'2',tubo:'6',e:'1',di:''},exT:['2 m³/h de agua por un tubo de 1 1/8" (28,58 mm, pared de 1 mm): diámetro interior de 26,58 mm → 1,0 m/s.','2 m³/h ur 1 1/8"-ko hodi batetik (28,58 mm, 1 mm-ko horma): 26,58 mm-ko barne-diametroa → 1,0 m/s.']},
 {id:'dp',cat:'tub',t:['Pérdida de carga (agua)','Karga-galera (ura)'],
  in:[['q',['Caudal','Emaria'],'n','2','m³/h'],['di',['Diámetro interior','Barne-diametroa'],'n','26,58','mm'],['L',['Longitud equivalente (tubo + accesorios)','Luzera baliokidea (hodia + osagarriak)'],'n','30','m'],['rug',['Material','Materiala'],'sel','cu',()=>[['cu',KL('cobre o plástico (0,0015 mm)','kobrea edo plastikoa (0,0015 mm)')],['ac',KL('acero comercial (0,045 mm)','altzairu komertziala (0,045 mm)')],['ga',KL('acero galvanizado (0,15 mm)','altzairu galbanizatua (0,15 mm)')]]],['tw',['Temperatura del agua','Uraren tenperatura'],'sel','20',()=>Object.keys(AGUA).map(k=>[k,k+' °C'])]],
  run(v){ const q=kN(v.q)/3600, d=kN(v.di)/1000, L=kN(v.L); if(!(q>0&&d>0&&L>0)) return null; const eps={cu:0.0015,ac:0.045,ga:0.15}[v.rug]/1000, [rho,mu]=AGUA[v.tw];
    const A=Math.PI*d*d/4, vel=q/A, Re=rho*vel*d/mu; let f, reg; if(Re<2300){ f=64/Re; reg=KL('laminar','laminarra'); } else { f=0.25/Math.pow(Math.log10(eps/(3.7*d)+5.74/Math.pow(Re,0.9)),2); reg=Re<4000?KL('transición (resultado aproximado)','trantsizioa (emaitza hurbildua)'):KL('turbulento','turbulentua'); }
    const dp=f*(L/d)*rho*vel*vel/2; return {res:[[KL('Velocidad','Abiadura'),kF(vel,2)+' m/s'],[KL('Número de Reynolds','Reynolds zenbakia'),kF(Re,0)+' ('+reg+')'],[KL('Factor de fricción','Marruskadura-faktorea'),kF(f,4)],[KL('Pérdida de carga','Karga-galera'),kF(dp/1000,2)+' kPa = '+kF(dp/(rho*9.81),2)+' m c.a.',1],[KL('Por metro','Metroko'),kF(dp/L,0)+' Pa/m']],
      steps:[`v = ${kF(vel,3)} m/s · Re = ρ·v·D/μ = ${kF(rho,1)}·${kF(vel,3)}·${kF(d,4)}/${kF(mu,6)} = ${kF(Re,0)}`,KL(`f (Swamee-Jain) = 0,25 / [log₁₀(ε/3,7D + 5,74/Re^0,9)]² = ${kF(f,4)}`,`f (Swamee-Jain) = 0,25 / [log₁₀(ε/3,7D + 5,74/Re^0,9)]² = ${kF(f,4)}`),`ΔP = f·(L/D)·ρ·v²/2 = ${kF(f,4)}·(${kF(L)}/${kF(d,4)})·${kF(rho,1)}·${kF(vel,3)}²/2 = ${kF(dp,0)} Pa`]}; },
  f:'ΔP = f · (L/D) · ρ · v² / 2  (Darcy-Weisbach) · f de Swamee-Jain (64/Re si es laminar)',
  pri:['Calcula cuánta presión pierde el agua por rozar con el tubo. Sirve para elegir la bomba de una enfriadora o de un circuito de glicol: la bomba tiene que dar al menos esa presión.','Urak hodiarekin igurtzean zenbat presio galtzen duen kalkulatzen du. Hozgailu baten edo glikol-zirkuitu baten ponpa aukeratzeko balio du: ponpak gutxienez presio hori eman behar du.'],
  pro:['Darcy-Weisbach con el factor de fricción explícito de Swamee-Jain (válido para Re entre 5·10³ y 10⁸; error inferior al 1 % frente a Colebrook). Propiedades del agua tabuladas a 10, 20, 40 y 60 °C. Los accesorios se suman como longitud equivalente (o con coeficientes K). Con mezclas de glicol la viscosidad es bastante mayor y la pérdida aumenta: usa los datos del fabricante del glicol.','Darcy-Weisbach Swamee-Jainen marruskadura-faktore esplizituarekin (Re 5·10³ eta 10⁸ artean balio du; Colebrookekin alderatuta % 1etik beherako errorea). Uraren propietateak 10, 20, 40 eta 60 °C-tan taulatuta. Osagarriak luzera baliokide gisa gehitzen dira (edo K koefizienteekin). Glikol-nahasteekin biskositatea dezente handiagoa da eta galera handitu egiten da: erabili glikolaren fabrikatzailearen datuak.'],
  ex:{q:'2',di:'26,58',L:'30',rug:'cu',tw:'20'},exT:['2 m³/h por 30 m de tubo de cobre de 26,58 mm por dentro, agua a 20 °C: 1 m/s y unos 0,46 kPa por metro, unos 13,7 kPa en total (1,4 m c.a.). Con la ecuación de Colebrook sale prácticamente lo mismo (13,73 kPa).','2 m³/h 30 m-ko kobre-hodi batetik 26,58 mm barnetik, ura 20 °C-tan: 1 m/s eta 0,46 kPa inguru metroko, 13,7 kPa inguru guztira (1,4 m c.a.). Colebrooken ekuazioarekin ia gauza bera ateratzen da (13,73 kPa).']},
 {id:'qaire',cat:'ter',t:['Potencia por caudal y salto de temperatura','Potentzia emariaren eta tenperatura-jauziaren arabera'],
  in:[['fl',['Fluido','Fluidoa'],'sel','agua',()=>[['agua',KL('agua','ura')],['aire',KL('aire (calor sensible)','airea (bero sentikorra)')]]],['q',['Caudal','Emaria'],'n','3','m³/h'],['dt',['Salto de temperatura (entrada − salida)','Tenperatura-jauzia (sarrera − irteera)'],'n','5','K']],
  run(v){ const q=kN(v.q), dt=kN(v.dt); if(!isFinite(q)||!isFinite(dt)) return null; const air=v.fl==='aire', rho=air?1.2:1000, cp=air?1.005:4.18; const m=q*rho/3600, Q=m*cp*dt;
    return {res:[[KL('Caudal másico','Masa-emaria'),kF(m,3)+' kg/s'],[KL('Potencia','Potentzia'),kF(Q,2)+' kW',1]],steps:[`ṁ = ${kF(q)} m³/h × ${kF(rho,1)} kg/m³ / 3600 = ${kF(m,4)} kg/s`,`Q = ṁ · cp · ΔT = ${kF(m,4)} × ${kF(cp,3)} × ${kF(dt)} = ${kF(Q,2)} kW`]}; },
  f:'Q = ṁ · cp · ΔT  (agua: cp ≈ 4,18 kJ/kg·K · aire: ρ ≈ 1,2 kg/m³, cp ≈ 1,005 kJ/kg·K)',
  pri:['Si sabes cuánta agua (o aire) pasa y cuántos grados se enfría, sabes cuánto frío está dando el equipo. Así se comprueba en la obra si una enfriadora da lo que dice su placa.','Zenbat ur (edo aire) pasatzen den eta zenbat gradu hozten den badakizu, badakizu ekipoak zenbat hotz ematen duen. Horrela egiaztatzen da obran hozgailu batek bere plakak dioena ematen duen.'],
  pro:['Para el aire solo se cuenta el calor sensible. Si hay condensación en la batería, la potencia total incluye el calor latente y hay que trabajar con entalpías (diagrama psicrométrico). La densidad del aire varía con la temperatura y la altitud (1,2 kg/m³ a 20 °C al nivel del mar). Si usas glicol, usa su cp y su densidad: ambos son menores que los del agua.','Airerako bero sentikorra bakarrik kontatzen da. Baterian kondentsazioa badago, potentzia osoak bero sorra ere badu eta entalpiekin lan egin behar da (diagrama psikrometrikoa). Airearen dentsitatea tenperaturarekin eta altuerarekin aldatzen da (1,2 kg/m³ 20 °C-tan itsas mailan). Glikola erabiltzen baduzu, erabili haren cp eta dentsitatea: biak uretakoak baino txikiagoak dira.'],
  ex:{fl:'agua',q:'3',dt:'5'},exT:['Una enfriadora con 3 m³/h de agua que entra a 12 °C y sale a 7 °C da unos 17,4 kW de frío.','12 °C-tan sartu eta 7 °C-tan ateratzen den 3 m³/h urekin hozgailu batek 17,4 kW hotz inguru ematen ditu.']},
 {id:'elp',cat:'ele',t:['Potencia e intensidad eléctrica','Potentzia eta intentsitate elektrikoa'],
  in:[['fase',['Suministro','Hornidura'],'sel','tri',()=>[['tri',KL('trifásico','trifasikoa')],['mono',KL('monofásico','monofasikoa')]]],['u',['Tensión (entre fases si es trifásico)','Tentsioa (faseen artean trifasikoa bada)'],'n','400','V'],['modo',['Calcular','Kalkulatu'],'sel','i2p',()=>[['i2p',KL('potencia a partir de la intensidad','potentzia intentsitatetik')],['p2i',KL('intensidad a partir de la potencia','intentsitatea potentziatik')]]],['x',['Intensidad (A) o potencia activa (kW)','Intentsitatea (A) edo potentzia aktiboa (kW)'],'n','10',''],['fp',['Factor de potencia (cos φ)','Potentzia-faktorea (cos φ)'],'n','0,85','']],
  run(v){ const U=kN(v.u), x=kN(v.x), fp=kN(v.fp); if(!(U>0&&isFinite(x)&&fp>0&&fp<=1)) return fp>1?{err:KL('El factor de potencia va de 0 a 1.','Potentzia-faktorea 0tik 1era doa.')}:null; const k=v.fase==='tri'?Math.sqrt(3):1, ks=v.fase==='tri'?'√3 · ':'';
    if(v.modo==='i2p'){ const S=k*U*x/1000, P=S*fp, Q=Math.sqrt(Math.max(0,S*S-P*P)); return {res:[[KL('Potencia activa','Potentzia aktiboa'),kF(P,2)+' kW',1],[KL('Potencia aparente','Potentzia itxurazkoa'),kF(S,2)+' kVA'],[KL('Potencia reactiva','Potentzia erreaktiboa'),kF(Q,2)+' kvar']],steps:[`P = ${ks}U · I · cos φ = ${ks}${kF(U,0)} · ${kF(x)} · ${kF(fp,2)} = ${kF(P*1000,0)} W`]}; }
    const I=x*1000/(k*U*fp); return {res:[[KL('Intensidad','Intentsitatea'),kF(I,2)+' A',1]],steps:[`I = P / (${ks}U · cos φ) = ${kF(x*1000,0)} / (${ks}${kF(U,0)} · ${kF(fp,2)}) = ${kF(I,2)} A`]}; },
  f:'Trifásica: P = √3 · U · I · cos φ · Monofásica: P = U · I · cos φ',
  pri:['Con la pinza amperimétrica mides los amperios; con esta calculadora sabes cuántos kilovatios está gastando el motor. O al revés: con la potencia de la placa sabes cuántos amperios debería consumir.','Pintza amperimetrikoarekin anperioak neurtzen dituzu; kalkulagailu honekin badakizu motorrak zenbat kilowatt kontsumitzen dituen. Edo alderantziz: plakako potentziarekin badakizu zenbat anperio kontsumitu beharko lituzkeen.'],
  pro:['En trifásica equilibrada, U es la tensión entre fases (400 V en la red de 230/400 V). La potencia de la placa de un motor es la mecánica en el eje: la eléctrica absorbida es P<sub>eje</sub>/η. El cos φ cambia con la carga del motor. Con variadores o armónicos el factor de potencia ya no es igual al cos φ, y para medir la potencia hace falta un analizador de redes.','Trifasiko orekatuan, U faseen arteko tentsioa da (400 V 230/400 V-ko sarean). Motor baten plakako potentzia ardatzeko potentzia mekanikoa da: xurgatutako potentzia elektrikoa P<sub>ardatza</sub>/η da. Cos φ motorraren kargarekin aldatzen da. Aldagailuekin edo harmonikoekin potentzia-faktorea ez da cos φ-ren berdina, eta potentzia neurtzeko sare-analizatzailea behar da.'],
  ex:{fase:'tri',u:'400',modo:'i2p',x:'10',fp:'0,85'},exT:['Un compresor trifásico a 400 V que consume 10 A con cos φ 0,85 absorbe unos 5,9 kW.','400 V-ko konpresore trifasiko batek 10 A kontsumitzen baditu cos φ 0,85ekin, 5,9 kW inguru xurgatzen ditu.']},
 {id:'cdt',cat:'ele',t:['Caída de tensión en un cable','Tentsio-jaitsiera kable batean'],
  in:[['fase',['Suministro','Hornidura'],'sel','tri',()=>[['tri',KL('trifásico','trifasikoa')],['mono',KL('monofásico','monofasikoa')]]],['u',['Tensión','Tentsioa'],'n','400','V'],['i',['Intensidad','Intentsitatea'],'n','16','A'],['L',['Longitud del cable (solo ida)','Kablearen luzera (joana bakarrik)'],'n','40','m'],['s',['Sección','Sekzioa'],'n','4','mm²'],['fp',['cos φ','cos φ'],'n','0,85',''],['g',['Temperatura del conductor','Eroalearen tenperatura'],'sel','48',()=>[['56',KL('20 °C (Cu: 56 m/Ω·mm²)','20 °C (Cu: 56 m/Ω·mm²)')],['48',KL('70 °C, PVC (Cu: 48)','70 °C, PVC (Cu: 48)')],['44',KL('90 °C, XLPE (Cu: 44)','90 °C, XLPE (Cu: 44)')]]]],
  run(v){ const U=kN(v.u),I=kN(v.i),L=kN(v.L),S=kN(v.s),fp=kN(v.fp),g=kN(v.g); if(!(U>0&&I>=0&&L>0&&S>0&&fp>0&&fp<=1)) return null; const tri=v.fase==='tri'; const du=(tri?Math.sqrt(3):2)*L*I*fp/(g*S), pc=du/U*100;
    return {res:[[KL('Caída de tensión','Tentsio-jaitsiera'),kF(du,2)+' V'],[KL('En porcentaje','Ehunekotan'),kF(pc,2)+' %',1]],ev:pc>5?['bad',KL('Más del 5 %: sube la sección o acorta el recorrido.','% 5 baino gehiago: handitu sekzioa edo laburtu ibilbidea.')]:pc>3?['warn',KL('Entre el 3 y el 5 %: revisa el límite que se aplica a tu instalación.','% 3 eta 5 artean: berrikusi zure instalazioari aplikatzen zaion muga.')]:['ok',KL('Caída pequeña.','Jaitsiera txikia.')],
      steps:[`ΔU = ${tri?'√3':'2'} · L · I · cos φ / (γ · S) = ${tri?'1,732':'2'} · ${kF(L)} · ${kF(I)} · ${kF(fp,2)} / (${kF(g,0)} · ${kF(S)}) = ${kF(du,2)} V`,`ΔU% = ${kF(du,2)} / ${kF(U,0)} · 100 = ${kF(pc,2)} %`]}; },
  f:'Monofásica: ΔU = 2·L·I·cos φ/(γ·S) · Trifásica: ΔU = √3·L·I·cos φ/(γ·S)  (sin reactancia)',
  pri:['Por un cable largo o fino se «pierde» tensión, y al motor le llega menos. Si la caída es grande, el motor se calienta y le cuesta arrancar.','Kable luze edo mehe batean tentsioa «galtzen» da, eta motorrera gutxiago iristen da. Jaitsiera handia bada, motorra berotu egiten da eta abiaraztea kostatzen zaio.'],
  pro:['Fórmula simplificada con la resistencia del conductor (sin la reactancia, que en secciones pequeñas apenas influye). Conductividad del cobre según la temperatura de servicio: 56 a 20 °C, 48 a 70 °C (PVC) y 44 a 90 °C (XLPE), como en la guía del REBT. Los límites de caída dependen del tipo de instalación (ITC-BT-19 e ITC-BT-47 para motores): compruébalos en el reglamento antes de elegir la sección. La sección se elige también por intensidad admisible y protección.','Formula sinplifikatua eroalearen erresistentziarekin (erreaktantziarik gabe, sekzio txikietan ia ez baitu eraginik). Kobrearen eroankortasuna zerbitzu-tenperaturaren arabera: 56 20 °C-tan, 48 70 °C-tan (PVC) eta 44 90 °C-tan (XLPE), REBTaren gidan bezala. Jaitsiera-mugak instalazio motaren araberakoak dira (ITC-BT-19 eta ITC-BT-47 motorretarako): egiaztatu erregelamenduan sekzioa aukeratu aurretik. Sekzioa intentsitate onargarriaren eta babesaren arabera ere aukeratzen da.'],
  ex:{fase:'tri',u:'400',i:'16',L:'40',s:'4',fp:'0,85',g:'48'},exT:['16 A trifásicos por 40 m de cable de 4 mm² a 70 °C: unos 4,9 V, el 1,2 %.','16 A trifasiko 4 mm²-ko 40 m-ko kable batetik 70 °C-tan: 4,9 V inguru, % 1,2.']},
 {id:'ohm',cat:'ele',t:['Resistencias y ley de Ohm','Erresistentziak eta Ohmen legea'],
  in:[['u',['Tensión','Tentsioa'],'n','230','V'],['p',['Potencia de la resistencia','Erresistentziaren potentzia'],'n','1150','W']],
  run(v){ const U=kN(v.u),P=kN(v.p); if(!(U>0&&P>0)) return null; const R=U*U/P, I=P/U; return {res:[[KL('Resistencia a la potencia nominal','Potentzia nominaleko erresistentzia'),kF(R,1)+' Ω',1],[KL('Intensidad','Intentsitatea'),kF(I,2)+' A']],steps:[`R = U² / P = ${kF(U,0)}² / ${kF(P,0)} = ${kF(R,1)} Ω`,`I = P / U = ${kF(P,0)} / ${kF(U,0)} = ${kF(I,2)} A`]}; },
  f:'R = U² / P · I = P / U · U = R · I',
  pri:['Con la tensión y la potencia de una resistencia de desescarche sabes cuántos ohmios tiene que marcar el polímetro. Si marca OL (infinito), está cortada; si marca casi 0, está en cortocircuito.','Izotz-kentzeko erresistentzia baten tentsioarekin eta potentziarekin badakizu polimetroak zenbat ohm markatu behar dituen. OL (infinitua) markatzen badu, etenda dago; ia 0 markatzen badu, zirkuitulaburrean dago.'],
  pro:['El cálculo da el valor a la temperatura de trabajo nominal. Las resistencias metálicas cambian algo con la temperatura, así que en frío la lectura puede ser ligeramente distinta. Si hay varias en paralelo, la total es menor. Además de la continuidad, se mide el aislamiento a tierra con el megóhmetro (500 V).','Kalkuluak lan-tenperatura nominaleko balioa ematen du. Erresistentzia metalikoak tenperaturarekin zertxobait aldatzen dira, beraz hotzean irakurketa pixka bat desberdina izan daiteke. Paraleloan hainbat badaude, guztizkoa txikiagoa da. Jarraitutasunaz gain, lurrarekiko isolamendua neurtzen da megohmetroarekin (500 V).'],
  ex:{u:'230',p:'1150'},exT:['Una resistencia de 1 150 W a 230 V debe marcar unos 46 Ω y consumir 5 A.','230 V-ko 1 150 W-eko erresistentzia batek 46 Ω inguru markatu eta 5 A kontsumitu behar ditu.']},
 {id:'ener',cat:'ele',t:['Consumo energético y coste','Energia-kontsumoa eta kostua'],
  in:[['modo',['Partir de','Abiapuntua'],'sel','elec',()=>[['elec',KL('potencia eléctrica','potentzia elektrikoa')],['frio',KL('potencia frigorífica y EER','hozte-potentzia eta EER')]]],['p',['Potencia (kW)','Potentzia (kW)'],'n','5','kW'],['eer',['EER (si partes del frío)','EER (hotzetik abiatzen bazara)'],'n','2,5',''],['h',['Horas de funcionamiento al día','Funtzionamendu-orduak eguneko'],'n','16','h'],['d',['Días','Egunak'],'n','365',''],['pr',['Precio de la energía','Energiaren prezioa'],'n','0,18','€/kWh']],
  run(v){ const p=kN(v.p),e=kN(v.eer),h=kN(v.h),d=kN(v.d),pr=kN(v.pr); if(![p,h,d,pr].every(isFinite)) return null; const pe=v.modo==='frio'?(e>0?p/e:NaN):p; if(!isFinite(pe)) return null; const E=pe*h*d;
    return {res:[[KL('Potencia eléctrica','Potentzia elektrikoa'),kF(pe,2)+' kW'],[KL('Energía','Energia'),kF(E,0)+' kWh',1],[KL('Coste','Kostua'),kF(E*pr,0)+' €',1]],steps:[...(v.modo==='frio'?[`P_eléctrica = ${kF(p)} / ${kF(e)} = ${kF(pe,3)} kW`]:[]),`E = ${kF(pe,3)} kW × ${kF(h)} h × ${kF(d,0)} = ${kF(E,0)} kWh`,`${KL('Coste','Kostua')} = ${kF(E,0)} × ${kF(pr,3)} = ${kF(E*pr,0)} €`]}; },
  f:'E = P_eléctrica · horas · días · P_eléctrica = Q_frío / EER',
  pri:['Calcula cuánta electricidad gasta un equipo y cuánto cuesta. Sirve para ver el ahorro de limpiar un condensador o de cambiar un equipo por otro más eficiente.','Ekipo batek zenbat elektrizitate kontsumitzen duen eta zenbat kostatzen den kalkulatzen du. Kondentsadore bat garbitzeak edo ekipo bat eraginkorrago batekin aldatzeak dakarren aurrezpena ikusteko balio du.'],
  pro:['Un cálculo con horas medias es una estimación. Para un dato real se mide con un analizador de redes o se leen los contadores. Como orden de magnitud, cada grado que baja la condensación mejora el EER en torno a un 3-4 %. El precio de la energía lo pones tú: depende de tu contrato.','Batez besteko orduekin egindako kalkulua estimazio bat da. Datu errealerako sare-analizatzailearekin neurtzen da edo kontagailuak irakurtzen dira. Magnitude-ordena gisa, kondentsazioa jaisten den gradu bakoitzak EERa % 3-4 inguru hobetzen du. Energiaren prezioa zuk jartzen duzu: zure kontratuaren araberakoa da.'],
  ex:{modo:'frio',p:'10',eer:'2,5',h:'16',d:'365',pr:'0,18'},exT:['10 kW de frío con EER 2,5 → 4 kW eléctricos; 16 h al día todo el año → 23 360 kWh, unos 4 205 € a 0,18 €/kWh.','10 kW hotz EER 2,5ekin → 4 kW elektriko; egunean 16 h urte osoan → 23 360 kWh, 4 205 € inguru 0,18 €/kWh-an.']},
 {id:'bomba',cat:'bom',t:['Potencia de una bomba y leyes de afinidad','Ponpa baten potentzia eta afinitate-legeak'],
  in:[['q',['Caudal','Emaria'],'n','10','m³/h'],['h',['Altura manométrica','Altuera manometrikoa'],'n','15','m c.a.'],['rho',['Densidad del fluido','Fluidoaren dentsitatea'],'n','1000','kg/m³'],['eta',['Rendimiento de la bomba','Ponparen errendimendua'],'n','0,6',''],['n1',['Velocidad actual','Uneko abiadura'],'n','2900','rpm'],['n2',['Velocidad nueva (variador)','Abiadura berria (aldagailua)'],'n','2000','rpm']],
  run(v){ const q=kN(v.q)/3600,H=kN(v.h),rho=kN(v.rho),eta=kN(v.eta),n1=kN(v.n1),n2=kN(v.n2); if(!(q>0&&H>0&&rho>0&&eta>0&&eta<=1)) return eta>1?{err:KL('El rendimiento va de 0 a 1.','Errendimendua 0tik 1era doa.')}:null;
    const Ph=rho*9.81*q*H/1000, Pe=Ph/eta; const r=n1>0&&n2>0?n2/n1:NaN; const res=[[KL('Potencia hidráulica','Potentzia hidraulikoa'),kF(Ph,2)+' kW'],[KL('Potencia en el eje','Ardatzeko potentzia'),kF(Pe,2)+' kW',1]];
    if(isFinite(r)) res.push([KL('A la velocidad nueva: caudal','Abiadura berrian: emaria'),kF(kN(v.q)*r,2)+' m³/h'],[KL('altura','altuera'),kF(H*r*r,2)+' m c.a.'],[KL('potencia en el eje','ardatzeko potentzia'),kF(Pe*r*r*r,2)+' kW']);
    return {res,steps:[`P_h = ρ · g · Q · H = ${kF(rho,0)} · 9,81 · ${kF(q,5)} · ${kF(H)} = ${kF(Ph*1000,0)} W`,`P_eje = P_h / η = ${kF(Ph,3)} / ${kF(eta,2)} = ${kF(Pe,3)} kW`,...(isFinite(r)?[KL(`Afinidad: Q ∝ n · H ∝ n² · P ∝ n³ (n₂/n₁ = ${kF(r,3)})`,`Afinitatea: Q ∝ n · H ∝ n² · P ∝ n³ (n₂/n₁ = ${kF(r,3)})`)]:[])]}; },
  f:'P_h = ρ·g·Q·H · P_eje = P_h/η · Q₂/Q₁ = n₂/n₁ · H₂/H₁ = (n₂/n₁)² · P₂/P₁ = (n₂/n₁)³',
  pri:['Calcula cuánta potencia necesita una bomba para mover un caudal a una altura. Y cuánto ahorra si se le pone un variador para que gire más despacio: a mitad de velocidad gasta la octava parte.','Ponpa batek emari bat altuera batera mugitzeko zenbat potentzia behar duen kalkulatzen du. Eta zenbat aurrezten duen aldagailu bat jartzen bazaio poliago bira dezan: abiaduraren erdian zortzirena kontsumitzen du.'],
  pro:['Las leyes de afinidad valen para una misma bomba en el mismo circuito, sin altura estática importante. Con mucha altura geométrica, el ahorro real es menor. La potencia eléctrica añade el rendimiento del motor (y del variador). Con glicol, usa su densidad. Para el NPSH y la cavitación hay que mirar las curvas del fabricante.','Afinitate-legeek ponpa berarentzat balio dute zirkuitu berean, altuera estatiko handirik gabe. Altuera geometriko handiarekin, benetako aurrezpena txikiagoa da. Potentzia elektrikoari motorraren (eta aldagailuaren) errendimendua gehitzen zaio. Glikolarekin, erabili haren dentsitatea. NPSHrako eta kabitaziorako fabrikatzailearen kurbak begiratu behar dira.'],
  ex:{q:'10',h:'15',rho:'1000',eta:'0,6',n1:'2900',n2:'2000'},exT:['10 m³/h a 15 m c.a. con rendimiento 0,6: unos 0,68 kW en el eje. Bajando de 2 900 a 2 000 rpm: 6,9 m³/h, 7,1 m y unos 0,22 kW.','10 m³/h 15 m c.a.-ra 0,6ko errendimenduarekin: 0,68 kW inguru ardatzean. 2 900etik 2 000 rpm-ra jaitsiz: 6,9 m³/h, 7,1 m eta 0,22 kW inguru.']}
];
const KCAT={ref:['Refrigeración','Hozkuntza'],conv:['Conversiones','Bihurketak'],tub:['Tuberías','Hodiak'],ter:['Potencia térmica','Potentzia termikoa'],ele:['Electricidad y energía','Elektrizitatea eta energia'],bom:['Bombas','Ponpak']};
const KV={}; // valores actuales por calculadora
// ---------- interfaz
function ktOpen(id,tab){ if(tab) KT.tab=tab; if(id){ if(KT.tab==='calc') KT.cur=id; else KT.ccur=id; } let o=document.getElementById('kt'); if(!o){ o=document.createElement('div'); o.id='kt'; document.body.appendChild(o); ktCss(); }
  o.hidden=false; KT.open=true; document.body.classList.add('kt-open'); ktRender(); }
function ktClose(){ const o=document.getElementById('kt'); if(o) o.hidden=true; KT.open=false; document.body.classList.remove('kt-open'); }
const KTABS={calc:{t:['Calculadoras','Kalkulagailuak'],ph:['Buscar calculadora…','Bilatu kalkulagailua…'],
  list:q=>Object.keys(KCAT).map(c=>{ const L=KC.filter(k=>k.cat===c&&(!q||KL(...k.t).toLowerCase().includes(q))); if(!L.length) return ''; return `<h4>${KL(...KCAT[c])}</h4>`+L.map(k=>`<button class="kt-li${k.id===KT.cur?' on':''}" data-k="${k.id}">${KL(...k.t)}</button>`).join(''); }).join(''),
  render:main=>ktCalc(main)}};
KT.tab='calc';
function ktRender(){ const o=document.getElementById('kt'); if(!o) return; const q=KT.q.trim().toLowerCase(); const T=KTABS[KT.tab]||KTABS.calc;
  const list=T.list(q)||`<p class="kt-none">${KL('No hay nada con esa palabra.','Ez dago ezer hitz horrekin.')}</p>`;
  const tabs=Object.entries(KTABS).map(([k,x])=>`<button class="kt-tab${k===KT.tab?' on':''}" data-tab="${k}">${KL(...x.t)}</button>`).join('');
  o.innerHTML=`<header class="kt-top"><button class="kt-back" data-a="close">← ${KL('Volver','Itzuli')}</button><div class="kt-tt"><small>${KL('Centro técnico','Zentro teknikoa')}</small><b>${KL(...T.t)}</b></div><nav class="kt-tabs">${tabs}</nav><span class="kt-sp"></span></header>
  <div class="kt-body"><nav class="kt-nav"><input type="search" class="kt-q" placeholder="${KL(...T.ph)}" value="${KT.q.replace(/"/g,'&quot;')}">${list}</nav><main class="kt-main"></main></div>`;
  const sp=o.querySelector('.kt-sp'); if(typeof i18nToggle==='function') sp.appendChild(i18nToggle()); // el selector de nivel se pone solo al lado
  T.render(o.querySelector('.kt-main')); }
document.addEventListener('click',e=>{ if(!KT.open) return; const b=e.target.closest&&e.target.closest('#kt [data-tab]'); if(!b) return; KT.tab=b.dataset.tab; KT.q=''; ktRender(); });
function ktVals(k){ if(!KV[k.id]){ KV[k.id]={}; k.in.forEach(([key,,,def])=>KV[k.id][key]=def); } return KV[k.id]; }
function ktCalc(main){ const k=KC.find(x=>x.id===KT.cur)||KC[0]; const v=ktVals(k);
  const inp=k.in.map(([key,lab,ty,def,opt])=>{ const id='kti_'+key; if(ty==='sel'){ const os=opt(); return `<label class="kt-in"><span>${KL(...lab)}</span><select id="${id}" data-i="${key}">${os.map(([a,b])=>`<option value="${a}"${String(v[key])===a?' selected':''}>${b}</option>`).join('')}</select></label>`; }
    const u=typeof opt==='function'?opt(v):(opt||''); return `<label class="kt-in"><span>${KL(...lab)}</span><span class="kt-iu"><input id="${id}" data-i="${key}" inputmode="decimal" value="${v[key]??''}"><em>${u}</em></span></label>`; }).join('');
  main.innerHTML=`<h2>${KL(...k.t)}</h2><div class="kt-grid"><section class="kt-card"><div class="kt-ins">${inp}</div><div class="kt-btns"><button class="kt-b" data-a="ex">${KL('Cargar el ejemplo','Kargatu adibidea')}</button></div></section><section class="kt-card kt-res" aria-live="polite"></section></div>
   <div class="kt-exp"></div>`;
  ktOut(main,k,v); }
function ktOut(main,k,v){ let r; try{ r=k.run(v); }catch(e){ r={err:String(e.message||e)}; } const R=main.querySelector('.kt-res');
  if(!r) R.innerHTML=`<p class="kt-wait">${KL('Rellena los datos para ver el resultado.','Bete datuak emaitza ikusteko.')}</p>`;
  else if(r.err) R.innerHTML=`<p class="kt-err">${r.err}</p>`;
  else { let h=''; if(r.res) h+=`<dl class="kt-dl">${r.res.map(([a,b,big])=>`<div class="${big?'big':''}"><dt>${a}</dt><dd>${b}</dd></div>`).join('')}</dl>`;
    if(r.table) h+=`<table class="kt-tb"><thead><tr>${r.table.h.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${r.table.r.map(row=>`<tr>${row.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table>`;
    if(r.obs) h+=`<table class="kt-tb"><tbody>${r.obs.map(([a,b,c,d])=>`<tr class="${c}"><td>${a}</td><td><b>${b}</b></td><td>${d}</td></tr>`).join('')}</tbody></table><h4 class="kt-h4">${KL('Averías que encajan con estos datos','Datu hauekin bat datozen matxurak')}</h4>${r.cands.map(([a,b])=>`<div class="kt-cand"><b>${a}</b><p>${b}</p></div>`).join('')}`;
    if(r.ev) h+=`<p class="kt-ev ${r.ev[0]}">${r.ev[1]}</p>`; R.innerHTML=h; }
  const pro=nvPro(), proc=`<div class="kt-f"><b>${KL('Fórmula','Formula')}</b><code>${k.f}</code>${r&&r.steps?`<b>${KL('Procedimiento con tus datos','Prozedura zure datuekin')}</b><ol>${r.steps.map(s=>`<li>${s}</li>`).join('')}</ol>`:''}</div>`;
  const ex=`<div class="kt-exb"><b>${KL('Ejemplo práctico','Adibide praktikoa')}</b><p>${KL(...k.exT)}</p></div>`;
  const bP=`<div class="nv-box pro"><b class="nv-h">🔧 ${KL('Explicación profesional','Azalpen profesionala')}</b>${KL(...k.pro)}</div>`, bB=`<div class="nv-box pri"><b class="nv-h">💡 ${KL('Explicado fácil','Erraz azalduta')}</b>${KL(...k.pri)}</div>`;
  main.querySelector('.kt-exp').innerHTML=pro?(proc+bP+`<details class="nv-box pri"><summary>💡 ${KL('Ver la explicación sencilla','Ikusi azalpen erraza')}</summary><div>${KL(...k.pri)}</div></details>`+ex)
    :(bB+ex+`<details class="kt-det"><summary>${KL('Ver la fórmula y el procedimiento','Ikusi formula eta prozedura')}</summary>${proc}</details><details class="nv-box pro"><summary>🔧 ${KL('Ampliar: explicación profesional','Zabaldu: azalpen profesionala')}</summary><div>${KL(...k.pro)}</div></details>`); }
document.addEventListener('input',e=>{ const t=e.target; if(!KT.open||!t.closest||!t.closest('#kt')) return; if(t.classList.contains('kt-q')){ KT.q=t.value; const pos=t.selectionStart; ktRender(); const n=document.querySelector('#kt .kt-q'); if(n){ n.focus(); try{ n.setSelectionRange(pos,pos); }catch(_){} } return; }
  if(t.dataset.i){ const k=KC.find(x=>x.id===KT.cur); KV[k.id][t.dataset.i]=t.value; const main=document.querySelector('#kt .kt-main'); if(t.tagName==='SELECT'){ ktCalc(main); } else ktOut(main,k,KV[k.id]); } });
document.addEventListener('change',e=>{ const t=e.target; if(!KT.open||!t.closest||!t.closest('#kt')||t.tagName!=='SELECT'||!t.dataset.i) return; const k=KC.find(x=>x.id===KT.cur); KV[k.id][t.dataset.i]=t.value; ktCalc(document.querySelector('#kt .kt-main')); });
document.addEventListener('click',e=>{ if(!KT.open) return; const b=e.target.closest&&e.target.closest('#kt [data-a],#kt [data-k]'); if(!b) return;
  if(b.dataset.k){ KT.cur=b.dataset.k; ktRender(); const m=document.querySelector('#kt .kt-main'); if(m&&window.innerWidth<900) m.scrollIntoView({behavior:'smooth'}); return; }
  const a=b.dataset.a; if(a==='close') return ktClose(); if(a==='ex'){ const k=KC.find(x=>x.id===KT.cur); KV[k.id]=Object.assign({},k.ex); ktCalc(document.querySelector('#kt .kt-main')); } });
document.addEventListener('keydown',e=>{ if(KT.open&&e.key==='Escape'&&!(typeof MDLB!=='undefined'&&MDLB)) ktClose(); },true);
document.addEventListener('nivel',()=>{ if(!KT.open) return; if(KT.tab==='calc'){ const k=KC.find(x=>x.id===KT.cur); ktOut(document.querySelector('#kt .kt-main'),k,ktVals(k)); } else (KTABS[KT.tab]||KTABS.calc).render(document.querySelector('#kt .kt-main')); });
function ktCss(){ const s=document.createElement('style'); s.textContent=`#kt{position:fixed;inset:0;z-index:9000;background:#f3f5f7;display:flex;flex-direction:column;color:#14212c;font-family:var(--f-body,system-ui,sans-serif)}
body.kt-open{overflow:hidden}
.kt-top{display:flex;align-items:center;gap:14px;padding:10px 18px;background:#fff;border-bottom:1px solid #dfe5ea}
.kt-back{border:1px solid #c9d3dc;background:#fff;border-radius:10px;padding:8px 12px;font:600 14px inherit;cursor:pointer}
.kt-tt small{display:block;font-size:11px;letter-spacing:.06em;text-transform:uppercase;color:#5b6b7a}.kt-tt b{font-size:18px}
.kt-tabs{display:flex;gap:4px;margin-left:18px}.kt-tab{border:0;background:none;padding:8px 12px;border-radius:9px;font:600 14px inherit;color:#33424f;cursor:pointer}.kt-tab:hover{background:#eef3f8}.kt-tab.on{background:#e3edf8;color:#0e3d6e}
.kt-sp{margin-left:auto;display:flex;align-items:center;gap:8px}.kt-sp .lang-sw{margin-left:8px}
.kt-body{flex:1;display:grid;grid-template-columns:270px minmax(0,1fr);min-height:0}
.kt-nav{overflow:auto;padding:14px;border-right:1px solid #dfe5ea;background:#fbfcfd}
.kt-q{width:100%;box-sizing:border-box;padding:9px 11px;border:1px solid #c9d3dc;border-radius:10px;font:inherit;margin-bottom:6px}
.kt-nav h4{margin:14px 4px 6px;font-size:11px;letter-spacing:.06em;text-transform:uppercase;color:#5b6b7a}
.kt-li{display:block;width:100%;text-align:left;border:0;background:none;padding:8px 10px;border-radius:9px;font:500 14px inherit;color:#14212c;cursor:pointer}
.kt-li:hover{background:#eef3f8}.kt-li.on{background:#0e2236;color:#fff}
.kt-none{color:#5b6b7a;font-size:13px;padding:6px}
.kt-main{overflow:auto;padding:20px 24px 40px}
.kt-main h2{margin:0 0 14px;font-size:22px}
.kt-grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:16px;align-items:start}
.kt-card{background:#fff;border:1px solid #dfe5ea;border-radius:14px;padding:16px}
.kt-ins{display:grid;gap:12px}.kt-in span:first-child{display:block;font-size:13px;font-weight:600;margin-bottom:4px;color:#33424f}
.kt-in select,.kt-iu input{width:100%;box-sizing:border-box;padding:9px 10px;border:1px solid #c9d3dc;border-radius:9px;font:inherit;background:#fff}
.kt-iu{display:flex;align-items:center;gap:8px}.kt-iu input{flex:1;min-width:0}.kt-iu em{font-style:normal;color:#5b6b7a;font-size:13px;flex:0 1 auto;max-width:45%;line-height:1.2}
.kt-btns{margin-top:14px}.kt-b{border:1px solid #c9d3dc;background:#f7f9fb;border-radius:9px;padding:8px 12px;font:600 13px inherit;cursor:pointer}
.kt-dl{margin:0;display:grid;gap:8px}.kt-dl div{display:flex;justify-content:space-between;gap:12px;border-bottom:1px solid #eef1f4;padding-bottom:6px}.kt-dl dt{color:#33424f;font-size:14px}.kt-dl dd{margin:0;font-weight:700;white-space:nowrap}
.kt-dl div.big dd{font-size:22px;color:#0e5aa7}
.kt-tb{width:100%;border-collapse:collapse;font-size:14px;margin:4px 0}.kt-tb th,.kt-tb td{border-bottom:1px solid #eef1f4;padding:6px 8px;text-align:left!important;white-space:normal!important}.kt-tb td:nth-child(2){white-space:nowrap!important}.kt-tb th{font-size:12px;color:#5b6b7a}
.kt-tb tr.bad td:first-child{border-left:4px solid #d23b2c}.kt-tb tr.warn td:first-child{border-left:4px solid #e0a020}.kt-tb tr.ok td:first-child{border-left:4px solid #2e9d57}
.kt-h4{margin:14px 0 6px;font-size:14px}.kt-cand{border:1px solid #dfe5ea;border-radius:10px;padding:9px 12px;margin:6px 0;background:#fbfcfd}.kt-cand p{margin:4px 0 0;font-size:13.5px;line-height:1.45}
.kt-ev{margin:12px 0 0;padding:9px 12px;border-radius:10px;font-weight:600;font-size:14px}.kt-ev.ok{background:#e8f6ed;color:#1d6f42}.kt-ev.warn{background:#fff4e0;color:#8a5a00}.kt-ev.bad{background:#fdecea;color:#a3271c}
.kt-wait{color:#5b6b7a}.kt-err{color:#a3271c;font-weight:600}
.kt-exp{margin-top:16px;max-width:900px}.kt-f{background:#fff;border:1px solid #dfe5ea;border-radius:12px;padding:12px 14px;margin:10px 0}.kt-f b{display:block;font-size:12px;letter-spacing:.05em;text-transform:uppercase;color:#5b6b7a;margin:6px 0 4px}.kt-f code{display:block;white-space:normal;font-size:13.5px;background:#f3f5f7;padding:8px 10px;border-radius:8px}.kt-f ol{margin:4px 0;padding-left:20px;font-size:14px}.kt-f li{margin:3px 0;font-family:ui-monospace,Consolas,monospace;font-size:13px}
.kt-exb{background:#eef4fb;border:1px solid #cfe0f2;border-radius:12px;padding:10px 14px;margin:10px 0}.kt-exb b{font-size:12px;letter-spacing:.05em;text-transform:uppercase;color:#0e5aa7}.kt-exb p{margin:4px 0 0}
.kt-det{margin:10px 0}.kt-det>summary{cursor:pointer;font-weight:700;font-size:13px;color:#0e5aa7;padding:6px 0}
@media(max-width:900px){.kt-body{grid-template-columns:minmax(0,1fr);overflow:auto}.kt-main,.kt-nav{min-width:0}.kt-tb td{white-space:normal!important;word-break:break-word}.kt-tb td:first-child{width:46%}.kt-nav{border-right:0;border-bottom:1px solid #dfe5ea;max-height:none}.kt-main{overflow:visible;padding:16px}.kt-grid{grid-template-columns:1fr}.kt-top{flex-wrap:wrap}.kt-tabs{order:5;width:100%;margin-left:0;overflow-x:auto;flex-wrap:nowrap;scrollbar-width:thin}.kt-tab{white-space:nowrap;flex:none;padding:7px 10px}.kt-sp{margin-left:0;width:100%;justify-content:flex-end}}`; document.head.appendChild(s); }
// ---------- entradas: tarjeta en el inicio y botón en la escuela
(function(){ const _rs=renderStart; renderStart=function(){ _rs.apply(this,arguments); try{
    const g=[...document.querySelectorAll('#stBody .q1-grp')][1]; const gl=g&&g.querySelector('.q1-gl'); if(gl&&!gl.querySelector('.kt-card0')){ const b=document.createElement('button'); b.type='button'; b.className='q1-sim kt-card0';
      b.innerHTML=`<span class="q1-oi"><svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"><rect x="5" y="3" width="14" height="18" rx="2"/><path d="M8 7h8M8 11h2M12 11h2M16 11h0M8 15h2M12 15h2M8 18h2M12 18h4"/></svg></span><span><b>${KL('Centro técnico','Zentro teknikoa')}</b><small>${KL('Calculadoras, componentes, averías paso a paso, glosario y buscador','Kalkulagailuak, osagaiak, matxurak urratsez urrats, glosarioa eta bilatzailea')}</small></span><svg class="pa" viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2"><path d="M5 12h14M13 6l6 6-6 6"/></svg>`; b.onclick=()=>ktOpen(); gl.appendChild(b); }
    const nav=document.querySelector('#stBody .sc-nav .sc-box'); if(nav&&!nav.querySelector('.sc-kt')){ const b=document.createElement('button'); b.type='button'; b.className='sc-rep sc-kt'; b.textContent='🧰 '+KL('Centro técnico','Zentro teknikoa'); b.onclick=()=>ktOpen(); const gal=nav.querySelector('.sc-gal'); if(gal) gal.after(b); else nav.prepend(b); }
  }catch(e){ console.error(e); } }; })();

// ===== Centro técnico · Biblioteca de componentes (etapa 3): una ficha por componente, con los dos niveles =====
// Cada ficha: qué es (sencillo y profesional), función, funcionamiento, dónde va, conexiones, relación con otros componentes,
// averías habituales, comprobaciones y seguridad. Las fotos son las de la galería (licencia libre) y SOLO del componente de la ficha.
const CCAT={comp:['Compresores','Konpresoreak'],int:['Intercambiadores','Trukagailuak'],exp:['Expansión y regulación','Hedapena eta erregulazioa'],lin:['Línea de líquido y accesorios','Likido-lerroa eta osagarriak'],seg:['Seguridad y control','Segurtasuna eta kontrola'],ele:['Electricidad','Elektrizitatea']};
const COMP=[
 {id:'semi',cat:'comp',t:['Compresor semihermético','Konpresore erdi-hermetikoa'],img:['cond_2'],
  pri:['Es la «bomba» de la instalación: aspira el gas frío que sale de los muebles y lo empuja comprimido hacia el condensador. Sin compresor el refrigerante no circula y no hay frío. Se llama semihermético porque el motor y el compresor van dentro de la misma carcasa atornillada, que se puede abrir para repararlo.','Instalazioaren «ponpa» da: altzarietatik ateratzen den gas hotza xurgatzen du eta konprimituta kondentsadorera bultzatzen du. Konpresorerik gabe hozgarria ez da zirkulatzen eta ez dago hotzik. Erdi-hermetikoa deitzen zaio motorra eta konpresorea karkasa torlojutu berean doazelako, eta konpontzeko ireki daitekeelako.'],
  pro:['Compresor alternativo de 2 a 8 cilindros con el motor refrigerado por el gas de aspiración. Aspira vapor recalentado y lo descarga a la presión de condensación (o de gas cooler). Caudal: ṁ = V<sub>barrido</sub>·η<sub>vol</sub>·ρ<sub>asp</sub>. Lubricación por bomba de aceite (presión diferencial vigilada) o por salpicadura en los pequeños. Arranque directo, part-winding o estrella-triángulo; regulación por etapas, descargadores de cilindros o variador.','2tik 8 zilindrora bitarteko konpresore alternatiboa, motorra xurgaketa-gasarekin hoztua. Lurrun gainberotua xurgatzen du eta kondentsazio-presioan (edo gas-hozgailuarenean) deskargatzen du. Emaria: ṁ = V<sub>ekortua</sub>·η<sub>bol</sub>·ρ<sub>xurg</sub>. Olio-ponpa bidezko lubrifikazioa (presio diferentziala zainduta) edo zipriztin bidezkoa txikietan. Abiaraztea zuzena, part-winding edo izar-triangelua; erregulazioa etapaka, zilindro-deskargagailuekin edo aldagailuarekin.'],
  fun:['Crear la diferencia de presión entre la baja y la alta para que el refrigerante circule y pueda llevar el calor de dentro a fuera.','Baxuaren eta altuaren arteko presio-aldea sortzea, hozgarria zirkulatu eta beroa barrutik kanpora eraman dezan.'],
  como:['Los pistones bajan y aspiran por las láminas de aspiración; al subir comprimen el gas y lo sacan por las láminas de descarga de la culata.','Pistoiak jaistean xurgaketa-xafletatik xurgatzen dute; igotzean gasa konprimitu eta kulatako deskarga-xafletatik ateratzen dute.'],
  donde:['En la sala de máquinas, en la bancada de la central, entre el colector de aspiración y el colector de descarga.','Makina-gelan, zentralaren bankadan, xurgaketa-kolektorearen eta deskarga-kolektorearen artean.'],
  con:['Aspiración con llave de servicio (lado motor), descarga con llave y antirretorno, retorno de aceite al cárter, alimentación trifásica y cadena de seguridades.','Xurgaketa zerbitzu-giltzarekin (motorraren aldean), deskarga giltzarekin eta atzera-ezinarekin, olioaren itzulera karterrera, elikadura trifasikoa eta segurtasun-katea.'],
  rel:['Separador de aceite, regulador de nivel de aceite, presostatos de alta y baja, controlador de la central, contactor y guardamotor.','Olio-bereizgailua, olio-mailaren erregulatzailea, altuko eta baxuko presostatoak, zentralaren kontrolagailua, kontaktorea eta motor-babeslea.'],
  ave:[['Golpe de líquido o retorno de líquido: rompe láminas y bielas.','Likido-kolpea edo likido-itzulera: xaflak eta bielak hausten ditu.'],['Falta de aceite o aceite diluido: desgaste y gripado.','Olio falta edo olio diluitua: higadura eta gripatzea.'],['Descarga muy caliente: aceite carbonizado y láminas que no cierran.','Deskarga oso beroa: olio karbonizatua eta ixten ez diren xaflak.'],['Motor quemado o derivado a tierra.','Motor erreta edo lurrera deribatua.']],
  chk:[['Presiones de aspiración y descarga, y relación de compresión.','Xurgaketa- eta deskarga-presioak, eta konpresio-erlazioa.'],['Temperatura de descarga (en HFC, por debajo de unos 110-120 °C en el tubo).','Deskarga-tenperatura (HFCetan, hodian 110-120 °C ingurutik behera).'],['Recalentamiento a la entrada del compresor.','Konpresorearen sarrerako gainberotzea.'],['Intensidad de las tres fases frente a la placa; aislamiento del motor con megóhmetro (sin tensión).','Hiru faseetako intentsitatea plakarekin alderatuta; motorraren isolamendua megohmetroarekin (tentsiorik gabe).'],['Nivel de aceite en el visor y presión diferencial de aceite.','Olio-maila ikusgailuan eta olio-presio diferentziala.']],
  seg:['Antes de abrirlo: quitar tensión, bloquear y comprobar; aislarlo con sus llaves y recuperar su refrigerante. La culata y la descarga queman.','Ireki aurretik: tentsioa kendu, blokeatu eta egiaztatu; bere giltzekin isolatu eta bere hozgarria berreskuratu. Kulatak eta deskargak erre egiten dute.']},
 {id:'scroll',cat:'comp',t:['Compresor scroll','Scroll konpresorea'],img:['scroll_0','comp_1'],
  pri:['Un compresor hermético (cerrado, no se abre) que comprime el gas con dos espirales: una fija y otra que se mueve en círculos. Es silencioso y se usa en equipos pequeños y medianos.','Konpresore hermetikoa (itxia, ez da irekitzen), gasa bi espiralekin konprimitzen duena: bat finkoa eta bestea zirkuluetan mugitzen dena. Isila da eta ekipo txiki eta ertainetan erabiltzen da.'],
  pro:['Compresión continua entre una espiral fija y una orbitante, sin válvulas de aspiración (alto rendimiento volumétrico). Muy sensible al <b>sentido de giro</b>: girando al revés no comprime, hace ruido y su consumo baja. Tolera algo de líquido mejor que un alternativo, pero no lo admite de forma continua. Las versiones «digitales» modulan separando las espirales con una solenoide (PWM).','Konpresio jarraitua espiral finko baten eta orbitatzaile baten artean, xurgaketa-balbularik gabe (errendimendu bolumetriko handia). Oso sentikorra da <b>biratze-noranzkoarekin</b>: alderantziz biratzean ez du konprimitzen, zarata ateratzen du eta kontsumoa jaisten zaio. Likido pixka bat alternatibo batek baino hobeto jasaten du, baina ez modu jarraituan. Bertsio «digitalek» espiralak solenoide batekin bereiziz modulatzen dute (PWM).'],
  fun:['Igual que cualquier compresor: subir la presión del gas para que circule el refrigerante.','Edozein konpresorek bezala: gasaren presioa igotzea hozgarria zirkula dadin.'],
  como:['El gas entra por fuera de las espirales y queda atrapado en bolsas que se van haciendo pequeñas hacia el centro, por donde sale comprimido.','Gasa espiralen kanpoaldetik sartzen da eta erdialderantz txikitzen doazen poltsetan harrapatuta geratzen da; erdigunetik ateratzen da konprimituta.'],
  donde:['En unidades condensadoras, enfriadoras y centrales pequeñas.','Unitate kondentsatzaileetan, hozgailuetan eta zentral txikietan.'],
  con:['Aspiración (normalmente lateral) y descarga (arriba), caja de bornes, resistencia de cárter si la lleva.','Xurgaketa (normalean alboan) eta deskarga (goian), borne-kaxa, karter-erresistentzia badarama.'],
  rel:['Presostatos, protección de motor (a menudo interna o módulo electrónico) y, si es digital, su controlador.','Presostatoak, motorraren babesa (askotan barnekoa edo modulu elektronikoa) eta, digitala bada, bere kontrolagailua.'],
  ave:[['Gira al revés tras conectar mal las fases.','Alderantziz biratzen du faseak gaizki konektatu ondoren.'],['Temperatura de descarga alta por falta de carga o recalentamiento excesivo.','Deskarga-tenperatura altua karga faltagatik edo gainberotze gehiegigatik.'],['Motor quemado por ciclos cortos.','Motor erreta ziklo laburrengatik.']],
  chk:[['En la puesta en marcha: que suba la alta y baje la baja en segundos, y que el consumo coincida con la placa.','Abiaraztean: altua igo eta baxua segundo gutxitan jaistea, eta kontsumoa plakarekin bat etortzea.'],['Secuencia de fases y protección del motor.','Fase-sekuentzia eta motorraren babesa.']],
  seg:['Es hermético: no se abre. La carcasa superior se calienta mucho.','Hermetikoa da: ez da irekitzen. Goiko karkasa asko berotzen da.']},
 {id:'cond',cat:'int',t:['Condensador de aire (y gas cooler)','Aire-kondentsadorea (eta gas-hozgailua)'],img:[],
  pri:['Es el «radiador» de la instalación. Está fuera, al aire, y por él pasa el gas caliente que sale del compresor. Los ventiladores le soplan aire y el gas se enfría y se convierte en líquido. Así se echa a la calle el calor que se ha sacado de los muebles.','Instalazioaren «erradiadorea» da. Kanpoan dago, airean, eta konpresoretik ateratzen den gas beroa pasatzen da bertatik. Haizagailuek airea botatzen diote eta gasa hoztu eta likido bihurtzen da. Horrela botatzen da kalera altzarietatik ateratako beroa.'],
  pro:['Intercambiador de tubos de cobre con aletas de aluminio. Evacua Q<sub>cond</sub> = Q<sub>evap</sub> + P<sub>comp</sub> en tres zonas: desrecalentamiento, condensación y subenfriamiento. Salto de diseño de 8-15 K sobre el aire. La regulación de ventiladores (etapas, corte de fase o EC 0-10 V) mantiene la condensación flotante sin bajar del mínimo que necesitan las válvulas. En el <b>CO₂ transcrítico</b> es un <b>gas cooler</b>: no condensa por encima de 31 °C, la aproximación es de 2-5 K y la presión la fija la HPV.','Kobrezko hodiz eta aluminiozko hegalez egindako trukagailua. Q<sub>kond</sub> = Q<sub>lurr</sub> + P<sub>konp</sub> botatzen du hiru zonatan: gainberotzea kentzea, kondentsazioa eta azpihoztea. Diseinuko jauzia 8-15 K airearen gainetik. Haizagailuen erregulazioak (etapak, fase-mozketa edo EC 0-10 V) kondentsazio flotatzailea mantentzen du balbulek behar duten gutxienekotik jaitsi gabe. <b>CO₂ transkritikoan</b> <b>gas-hozgailua</b> da: ez da kondentsatzen 31 °C-tik gora, hurbilketa 2-5 K da eta presioa HPVk finkatzen du.'],
  fun:['Sacar fuera el calor que el refrigerante ha cogido en los muebles más el calor que le ha metido el compresor.','Hozgarriak altzarietan hartutako beroa eta konpresoreak sartutakoa kanpora ateratzea.'],
  como:['El gas caliente entra por arriba, recorre los tubos y, al ceder calor al aire, se condensa; el líquido sale por abajo hacia el recipiente.','Gas beroa goitik sartzen da, hodietan barrena ibiltzen da eta, aireari beroa ematean, kondentsatu egiten da; likidoa behetik ateratzen da hartzailerantz.'],
  donde:['En el exterior (cubierta, patio): necesita aire fresco y que el aire caliente no vuelva a entrar.','Kanpoaldean (estalkia, patioa): aire freskoa behar du eta aire beroa berriro ez sartzea.'],
  con:['Entrada de gas de descarga (arriba), salida de líquido (abajo), alimentación y control de los ventiladores.','Deskarga-gasaren sarrera (goian), likidoaren irteera (behean), haizagailuen elikadura eta kontrola.'],
  rel:['Compresores (le llega su descarga), recipiente de líquido, transductor de alta y controlador; en CO₂, la HPV.','Konpresoreak (haien deskarga iristen zaio), likido-hartzailea, altuko transduktorea eta kontrolagailua; CO₂an, HPV.'],
  ave:[['Suciedad en las aletas: sube la alta y el consumo.','Zikinkeria hegaletan: altua eta kontsumoa igotzen dira.'],['Ventilador parado o girando al revés.','Haizagailua geldituta edo alderantziz biraka.'],['Recirculación de aire caliente o algo que tapa la entrada.','Aire beroaren birzirkulazioa edo sarrera tapatzen duen zerbait.'],['Incondensables en el circuito.','Kondentsaezinak zirkuituan.']],
  chk:[['Salto entre la condensación y el aire de entrada (normal 8-15 K).','Kondentsazioaren eta sarrerako airearen arteko jauzia (normala 8-15 K).'],['Limpieza y estado de las aletas.','Hegalen garbitasuna eta egoera.'],['Consumo y sentido de giro de cada ventilador.','Haizagailu bakoitzaren kontsumoa eta biratze-noranzkoa.']],
  seg:['Antes de limpiar: quitar tensión a los ventiladores y bloquear (pueden arrancar solos por presión). Cuidado con las aletas: cortan.','Garbitu aurretik: haizagailuei tentsioa kendu eta blokeatu (presioagatik bakarrik abia daitezke). Kontuz hegalekin: ebaki egiten dute.']},
 {id:'evap',cat:'int',t:['Evaporador de aire forzado','Aire behartuko lurrungailua'],img:['evap_0','evap_2'],
  pri:['Es la parte que enfría: está dentro de la cámara o del mueble. Por dentro de sus tubos hierve el refrigerante y le quita el calor al aire, que los ventiladores hacen pasar entre las aletas.','Hozten duen zatia da: ganberaren edo altzariaren barruan dago. Hodien barruan hozgarria irakiten da eta aireari beroa kentzen dio; haizagailuek airea hegalen artetik pasarazten dute.'],
  pro:['Batería de tubos de cobre con aletas (separación mayor en negativa, 6-12 mm, por la escarcha). Potencia según el salto térmico DT1 (aire de entrada − evaporación): un salto pequeño seca menos el producto. Necesita desescarche (aire, resistencias o gas caliente) con fin por temperatura con una sonda en el último punto que se deshiela. Con varios circuitos lleva distribuidor e igualador externo en la válvula.','Hegaldun kobre-hodiz egindako bateria (tarte handiagoa negatiboan, 6-12 mm, izarragatik). Potentzia DT1 jauzi termikoaren araberakoa (sarrerako airea − lurruntzea): jauzi txikiak gutxiago lehortzen du produktua. Izotz-kentzea behar du (airea, erresistentziak edo gas beroa), azkena urtzen den puntuan dagoen zunda batekin tenperaturagatik amaituta. Zirkuitu batzuekin banagailua eta balbulan kanpo-berdingailua darama.'],
  fun:['Coger el calor del aire de la cámara para que se enfríe.','Ganberako airearen beroa hartzea hozteko.'],
  como:['El refrigerante entra como mezcla fría de líquido y gas, hierve a lo largo de los tubos y sale como gas un poco recalentado.','Hozgarria likido eta gas nahaste hotz gisa sartzen da, hodietan zehar irakiten da eta gas gisa ateratzen da, pixka bat gainberotuta.'],
  donde:['En el techo o la pared de la cámara, o dentro del mueble; con bandeja y desagüe para el agua del desescarche.','Ganberaren sabaian edo hormetan, edo altzariaren barruan; izotz-kentzeko urarentzako erretilu eta hustubidearekin.'],
  con:['Entrada de líquido desde la válvula de expansión, salida a la aspiración, ventiladores, resistencias, sondas y desagüe.','Likidoaren sarrera hedapen-balbulatik, irteera xurgaketara, haizagailuak, erresistentziak, zundak eta hustubidea.'],
  rel:['Válvula de expansión, solenoide, termostato o controlador, sonda de evaporador (fin de desescarche) y resistencias.','Hedapen-balbula, solenoidea, termostatoa edo kontrolagailua, lurrungailuaren zunda (izotz-kentzearen amaiera) eta erresistentziak.'],
  ave:[['Bloque de hielo: desescarche que no termina, resistencia cortada o sonda mal colocada.','Izotz-blokea: amaitzen ez den izotz-kentzea, erresistentzia etenda edo zunda gaizki jarrita.'],['Ventilador parado: baja la evaporación y el recalentamiento.','Haizagailua geldituta: lurruntzea eta gainberotzea jaisten dira.'],['Desagüe helado o atascado.','Hustubidea izoztuta edo buxatuta.']],
  chk:[['Diferencia entre el aire de la cámara y la evaporación (normal 6-10 K).','Ganberako airearen eta lurruntzearen arteko aldea (normala 6-10 K).'],['Recalentamiento a la salida.','Irteerako gainberotzea.'],['Que el desescarche acabe por temperatura y no por tiempo máximo.','Izotz-kentzea tenperaturagatik amaitzea eta ez gehieneko denboragatik.']],
  seg:['Quitar tensión antes de tocar ventiladores o resistencias. En cámaras de negativa, no quedarse encerrado: comprobar el pulsador interior de apertura.','Haizagailuak edo erresistentziak ukitu aurretik tentsioa kendu. Negatiboko ganberetan ez geratu itxita: egiaztatu barruko irekitze-pultsadorea.']},
 {id:'ucond',cat:'int',t:['Unidad condensadora','Unitate kondentsatzailea'],img:['cond_1'],
  pri:['Es un «kit» que trae juntos el compresor, el condensador con su ventilador, el recipiente y sus seguridades. Se pone fuera y se une con tubos al evaporador de la cámara.','Konpresorea, haizagailudun kondentsadorea, hartzailea eta haien segurtasunak batera dakartzan «kit» bat da. Kanpoan jartzen da eta hodiekin ganberako lurrungailuarekin lotzen da.'],
  pro:['Conjunto montado en fábrica: compresor (hermético, scroll o semihermético), condensador, recipiente, presostato doble, filtro, visor y cuadro. Se elige por refrigerante, temperatura de evaporación y temperatura ambiente máxima. En Europa los refrigerantes permitidos dependen del PCA y del tipo de equipo (Reglamento 2024/573).','Fabrikan muntatutako multzoa: konpresorea (hermetikoa, scroll edo erdi-hermetikoa), kondentsadorea, hartzailea, presostato bikoitza, iragazkia, ikusgailua eta koadroa. Hozgarriaren, lurruntze-tenperaturaren eta gehieneko giro-tenperaturaren arabera aukeratzen da. Europan baimendutako hozgarriak BEParen eta ekipo motaren araberakoak dira (2024/573 Erregelamendua).'],
  fun:['Dar el frío a una cámara o un mueble que no está conectado a una central.','Zentral bati konektatuta ez dagoen ganbera edo altzari bati hotza ematea.'],
  como:['Trabaja como una máquina completa; el termostato abre la solenoide y el presostato de baja arranca y para el compresor (recogida de gas).','Makina oso batek bezala lan egiten du; termostatoak solenoidea irekitzen du eta baxuko presostatoak konpresorea abiarazi eta gelditzen du (gas-bilketa).'],
  donde:['En el exterior, en una cubierta o sobre soportes en la fachada, con buen paso de aire.','Kanpoaldean, estalki batean edo fatxadako euskarrien gainean, aire-pasabide onarekin.'],
  con:['Línea de líquido y línea de aspiración al evaporador; alimentación eléctrica y mando del termostato.','Likido-lerroa eta xurgaketa-lerroa lurrungailura; elikadura elektrikoa eta termostatoaren agindua.'],
  rel:['Evaporador, válvula de expansión, solenoide y termostato de la cámara.','Lurrungailua, hedapen-balbula, solenoidea eta ganberako termostatoa.'],
  ave:[['Las del compresor y el condensador, y ciclos cortos por presostato de baja mal ajustado.','Konpresorearenak eta kondentsadorearenak, eta ziklo laburrak baxuko presostatoa gaizki doituta dagoelako.']],
  chk:[['Ajuste del presostato de baja (paro bastante por debajo de la presión de trabajo).','Baxuko presostatoaren doikuntza (gelditzea lan-presiotik dezente behera).'],['Presiones, recalentamiento, subenfriamiento y consumo.','Presioak, gainberotzea, azpihoztea eta kontsumoa.']],
  seg:['Seccionador local bloqueable antes de tocarla; cuidado con los ventiladores, que pueden arrancar solos.','Ukitu aurretik tokiko seksionagailu blokeagarria; kontuz haizagailuekin, bakarrik abia baitaitezke.']},
 {id:'vet',cat:'exp',t:['Válvula de expansión termostática','Hedapen-balbula termostatikoa'],img:['txv_2','txv_1','n_txv_0'],
  pri:['Es un grifo automático que deja pasar al evaporador el refrigerante justo. Tiene un «termómetro» (el bulbo) pegado a la salida del evaporador: si allí el gas sale demasiado caliente, abre más; si sale frío, cierra.','Lurrungailura behar den hozgarria pasatzen uzten duen txorrota automatikoa da. «Termometro» bat du (bulboa) lurrungailuaren irteerari itsatsita: han gasa beroegi ateratzen bada, gehiago irekitzen du; hotz ateratzen bada, ixten du.'],
  pro:['Regula el <b>recalentamiento</b>, no la temperatura: P<sub>bulbo</sub> = P<sub>evap</sub> + P<sub>muelle</sub>. El tornillo ajusta el recalentamiento estático (apretar = más recalentamiento). Lleva igualador externo con distribuidor o mucha pérdida de carga. Cargas del bulbo: universal, MOP (limita la presión de aspiración; el bulbo debe estar siempre más frío que la cabeza) o con lastre. Orificio intercambiable: debe trabajar sobre el 75 % de su capacidad.','<b>Gainberotzea</b> erregulatzen du, ez tenperatura: P<sub>bulboa</sub> = P<sub>lurr</sub> + P<sub>malgukia</sub>. Torlojuak gainberotze estatikoa doitzen du (estutu = gainberotze gehiago). Kanpo-berdingailua darama banagailuarekin edo karga-galera handiarekin. Bulboaren kargak: unibertsala, MOP (xurgaketa-presioa mugatzen du; bulboak beti burua baino hotzago egon behar du) edo lastreduna. Orifizio aldagarria: bere ahalmenaren % 75 inguruan lan egin behar du.'],
  fun:['Bajar la presión del líquido y dosificar el refrigerante que entra al evaporador.','Likidoaren presioa jaistea eta lurrungailura sartzen den hozgarria dosifikatzea.'],
  como:['La presión del bulbo empuja la membrana para abrir; la presión del evaporador y el muelle empujan para cerrar.','Bulboaren presioak mintza bultzatzen du irekitzeko; lurrungailuaren presioak eta malgukiak ixteko bultzatzen dute.'],
  donde:['A la entrada del evaporador. El bulbo, a la salida, en un tramo horizontal (arriba en tubos finos; a las 4 u 8 del reloj en gruesos), bien sujeto y aislado.','Lurrungailuaren sarreran. Bulboa irteeran, tarte horizontal batean (goian hodi meheetan; erlojuaren 4 edo 8etan lodietan), ondo lotuta eta isolatuta.'],
  con:['Entrada de líquido (abocardada o soldada), salida al distribuidor o al evaporador, capilar al bulbo y, si lo lleva, tubo del igualador después del bulbo.','Likidoaren sarrera (abokardatua edo soldatua), irteera banagailura edo lurrungailura, bulborako kapilarra eta, badarama, berdingailuaren hodia bulboaren ondoren.'],
  rel:['Evaporador, solenoide, filtro y visor (necesita líquido sin burbujas), y el subenfriamiento de la instalación.','Lurrungailua, solenoidea, iragazkia eta ikusgailua (burbuilarik gabeko likidoa behar du), eta instalazioaren azpihoztea.'],
  ave:[['Bulbo suelto o sin aislar: abre de más.','Bulbo askatuta edo isolatu gabe: gehiegi irekitzen du.'],['Pérdida de la carga del bulbo: se cierra (recalentamiento muy alto).','Bulboaren karga galtzea: itxi egiten da (gainberotze oso altua).'],['Orificio o filtro de entrada obstruidos.','Orifizioa edo sarrerako iragazkia buxatuta.'],['Válvula sobredimensionada: oscila (bombea).','Neurriz gaineko balbula: oszilatu egiten du (ponpatu).']],
  chk:[['Recalentamiento a la salida del evaporador (5-10 K orientativo).','Lurrungailuaren irteerako gainberotzea (5-10 K orientagarria).'],['Posición, sujeción y aislamiento del bulbo.','Bulboaren kokapena, lotura eta isolamendua.'],['Subenfriamiento y visor antes de la válvula.','Azpihoztea eta ikusgailua balbularen aurretik.']],
  seg:['Para cambiar el orificio o la válvula hay que aislar y recuperar el refrigerante del tramo; el líquido que sale quema por frío.','Orifizioa edo balbula aldatzeko tartea isolatu eta bertako hozgarria berreskuratu behar da; ateratzen den likidoak hotzez erretzen du.']},
 {id:'eev',cat:'exp',t:['Válvula de expansión electrónica','Hedapen-balbula elektronikoa'],img:[],
  pri:['Hace lo mismo que la termostática, pero la mueve un motor que manda un controlador. El controlador mide la presión y la temperatura a la salida del evaporador y decide cuánto abrir.','Termostatikoak egiten duen gauza bera egiten du, baina kontrolagailu batek agintzen duen motor batek mugitzen du. Kontrolagailuak lurrungailuaren irteerako presioa eta tenperatura neurtzen ditu eta zenbat ireki erabakitzen du.'],
  pro:['Motor paso a paso (modulante; se queda en su posición si falta tensión, por eso lleva solenoide antes o módulo de cierre) o de pulsos PWM (solenoide en ciclos de unos 6 s). El controlador calcula SH = T<sub>salida</sub> − T<sub>sat</sub>(P) con la tabla del refrigerante configurado y regula con un PID, con recalentamiento adaptativo (MSS). Se monta primero la sonda y después el transductor, por encima del tubo. En CO₂ siempre se usan electrónicas.','Urrats-motorrekoa (modulatzailea; tentsioa falta bada bere posizioan geratzen da, horregatik solenoidea darama aurretik edo ixte-modulua) edo PWM pultsuduna (6 s inguruko zikloetako solenoidea). Kontrolagailuak SH = T<sub>irteera</sub> − T<sub>ase</sub>(P) kalkulatzen du konfiguratutako hozgarriaren taularekin eta PID batekin erregulatzen du, gainberotze moldagarriarekin (MSS). Lehenengo zunda muntatzen da eta gero transduktorea, hodiaren gainetik. CO₂an beti elektronikoak erabiltzen dira.'],
  fun:['Dosificar el refrigerante al evaporador para mantener el recalentamiento con más precisión que una termostática.','Lurrungailura hozgarria dosifikatzea, gainberotzea termostatiko batek baino zehaztasun handiagoz mantentzeko.'],
  como:['El controlador lee la sonda y el transductor, calcula el recalentamiento y abre o cierra el motor poco a poco.','Kontrolagailuak zunda eta transduktorea irakurtzen ditu, gainberotzea kalkulatzen du eta motorra pixkanaka ireki edo ixten du.'],
  donde:['A la entrada del evaporador; la sonda y el transductor, a la salida.','Lurrungailuaren sarreran; zunda eta transduktorea, irteeran.'],
  con:['Líquido de entrada, salida al evaporador, cable del motor al controlador, sonda NTC/Pt1000 y transductor (4-20 mA o ratiométrico).','Sarrerako likidoa, irteera lurrungailura, motorraren kablea kontrolagailura, NTC/Pt1000 zunda eta transduktorea (4-20 mA edo ratiometrikoa).'],
  rel:['Controlador del mueble o de la válvula, solenoide de líquido, transductor de presión y sonda.','Altzariaren edo balbularen kontrolagailua, likido-solenoidea, presio-transduktorea eta zunda.'],
  ave:[['Transductor o sonda que leen mal: recalentamiento falso.','Gaizki irakurtzen duten transduktorea edo zunda: gainberotze faltsua.'],['Refrigerante mal configurado en el controlador.','Hozgarria gaizki konfiguratuta kontrolagailuan.'],['Motor que pierde pasos o cable cortado.','Urratsak galtzen dituen motorra edo kable etena.']],
  chk:[['Comparar la presión del transductor con un manómetro y la sonda con un termómetro patrón.','Transduktorearen presioa manometro batekin eta zunda erreferentziako termometro batekin alderatzea.'],['Grado de apertura frente al recalentamiento.','Irekiera-maila gainberotzearekin alderatuta.']],
  seg:['Trabajar sin tensión en el controlador; en CO₂, no dejar líquido atrapado al aislar el tramo.','Kontrolagailuan tentsiorik gabe lan egitea; CO₂an, tartea isolatzean ez utzi likidorik harrapatuta.']},
 {id:'sol',cat:'exp',t:['Electroválvula (solenoide)','Elektrobalbula (solenoidea)'],img:['sol_5','sol_2','sol_3'],
  pri:['Es una llave que se abre y se cierra sola con electricidad. Cuando el termostato pide frío, le da corriente a la bobina y la válvula deja pasar el líquido; cuando la cámara llega a su temperatura, se cierra.','Elektrizitatearekin bakarrik irekitzen eta ixten den giltza da. Termostatoak hotza eskatzen duenean, bobinari korrontea ematen dio eta balbulak likidoa pasatzen uzten du; ganbera bere tenperaturara iristen denean, itxi egiten da.'],
  pro:['Normalmente cerrada y, en tamaños medianos y grandes, servoaccionada: necesita una diferencia de presión mínima para abrir del todo. Tiene una MOPD (diferencia máxima a la que puede abrir) que depende de la bobina. Se elige por Kv y caída de presión, no por el diámetro de la conexión. Se monta con la flecha en el sentido del flujo.','Normalean itxia eta, tamaina ertain eta handietan, zerbo bidez eragina: gutxieneko presio-diferentzia bat behar du erabat irekitzeko. MOPD bat du (ireki dezakeen gehieneko diferentzia), bobinaren araberakoa. Kv-aren eta presio-jaitsieraren arabera aukeratzen da, ez konexioaren diametroagatik. Gezia fluxuaren noranzkoan duela muntatzen da.'],
  fun:['Cortar o dejar pasar el refrigerante según mande el termostato o el controlador.','Hozgarria moztea edo pasatzen uztea termostatoak edo kontrolagailuak agintzen duenaren arabera.'],
  como:['La bobina crea un campo magnético que levanta el émbolo; sin tensión, un muelle lo cierra.','Bobinak eremu magnetikoa sortzen du eta enboloa altxatzen du; tentsiorik gabe, malguki batek ixten du.'],
  donde:['En la línea de líquido, antes de la válvula de expansión de cada servicio.','Likido-lerroan, zerbitzu bakoitzeko hedapen-balbularen aurretik.'],
  con:['Entrada y salida de líquido (respetando la flecha) y bobina a 230 V (o 24 V) desde el termostato.','Likidoaren sarrera eta irteera (gezia errespetatuz) eta 230 V-ko (edo 24 V-ko) bobina termostatotik.'],
  rel:['Termostato o controlador, válvula de expansión y presostato de baja (recogida de gas).','Termostatoa edo kontrolagailua, hedapen-balbula eta baxuko presostatoa (gas-bilketa).'],
  ave:[['Bobina quemada: no abre.','Bobina erreta: ez da irekitzen.'],['Montada al revés: no cierra bien.','Alderantziz muntatuta: ez da ondo ixten.'],['Suciedad en el asiento: deja pasar con la válvula cerrada.','Zikinkeria eserlekuan: balbula itxita dagoela pasatzen uzten du.']],
  chk:[['Tensión en la bobina cuando el termostato pide frío.','Tentsioa bobinan termostatoak hotza eskatzen duenean.'],['Resistencia de la bobina (sin tensión): cientos o miles de ohmios.','Bobinaren erresistentzia (tentsiorik gabe): ehunka edo milaka ohm.'],['Con un destornillador se nota el magnetismo de la bobina cuando está alimentada.','Bihurkin batekin bobinaren magnetismoa nabaritzen da elikatuta dagoenean.']],
  seg:['No desmontar la bobina con tensión (se quema en segundos) ni quitar el cuerpo con presión en la línea.','Ez desmuntatu bobina tentsioarekin (segundotan erretzen da) eta ez kendu gorputza lerroan presioa dagoela.']},
 {id:'rec',cat:'lin',t:['Recipiente de líquido','Likido-hartzailea'],img:[],
  pri:['Es un depósito donde se guarda el refrigerante líquido que sale del condensador. Hace de «despensa»: hay épocas en que la instalación necesita más líquido y otras menos.','Kondentsadoretik ateratzen den hozgarri likidoa gordetzen den biltegia da. «Jaki-gela» gisa egiten du: badaude garaiak instalazioak likido gehiago behar duena eta beste batzuk gutxiago.'],
  pro:['Equipo a presión (Directiva 2014/68/UE y RSIF): placa con PS y volumen, válvula de seguridad y, si tiene 100 L o más, doble válvula sobre válvula de cambio (IF-08). Permite la recogida de gas (pump-down) sin pasar del 80 % de llenado. Nivel por visores o sonda. En el CO₂ booster es el depósito de media presión (unos 35 bar), con la FGBV y la unidad auxiliar para las paradas.','Presiopeko ekipoa (2014/68/EB Zuzentaraua eta RSIF): PS eta bolumena dituen plaka, segurtasun-balbula eta, 100 L edo gehiago baditu, balbula bikoitza aldaketa-balbula baten gainean (IF-08). Gas-bilketa (pump-down) ahalbidetzen du % 80ko betetzetik pasatu gabe. Maila ikusgailuen edo zundaren bidez. CO₂ boosterrean presio ertaineko biltegia da (35 bar inguru), FGBVarekin eta geldialdietarako unitate laguntzailearekin.'],
  fun:['Guardar el líquido que sobra y asegurar que a las válvulas siempre les llegue líquido.','Soberan dagoen likidoa gordetzea eta balbulei beti likidoa iristen zaiela ziurtatzea.'],
  como:['El líquido entra por arriba desde el condensador y sale por un tubo que llega al fondo.','Likidoa goitik sartzen da kondentsadoretik eta hondoraino iristen den hodi batetik ateratzen da.'],
  donde:['Después del condensador, en la sala de máquinas, más bajo que el condensador para que el líquido baje por gravedad.','Kondentsadorearen ondoren, makina-gelan, kondentsadorea baino beherago, likidoa grabitatez jaits dadin.'],
  con:['Entrada de líquido, salida de líquido con llave, válvulas de seguridad, toma de servicio y, a veces, visor de nivel.','Likido-sarrera, likido-irteera giltzarekin, segurtasun-balbulak, zerbitzu-hartunea eta, batzuetan, maila-ikusgailua.'],
  rel:['Condensador, filtro deshidratador, válvulas de seguridad y presostato de alta.','Kondentsadorea, iragazki lehorgailua, segurtasun-balbulak eta altuko presostatoa.'],
  ave:[['Nivel bajo (fuga) o demasiado alto (exceso de carga).','Maila baxua (ihesa) edo altuegia (karga gehiegi).'],['Válvula de seguridad que pierde.','Ihes egiten duen segurtasun-balbula.']],
  chk:[['Nivel con la instalación estable.','Maila instalazioa egonkor dagoenean.'],['Estado y fecha de las válvulas de seguridad.','Segurtasun-balbulen egoera eta data.'],['Corrosión exterior.','Kanpoko korrosioa.']],
  seg:['No llenar nunca por encima del 80 %: el líquido se dilata con el calor. No anular nunca su válvula de seguridad.','Ez bete inoiz % 80tik gora: likidoa beroarekin dilatatu egiten da. Ez baliogabetu inoiz bere segurtasun-balbula.']},
 {id:'filtro',cat:'lin',t:['Filtro deshidratador','Iragazki lehorgailua'],img:[],
  pri:['Es un filtro que limpia el refrigerante: le quita el agua, los ácidos y la suciedad. El agua dentro del circuito es muy mala: se congela en la válvula y estropea el aceite.','Hozgarria garbitzen duen iragazkia da: ura, azidoak eta zikinkeria kentzen dizkio. Zirkuitu barruko ura oso txarra da: balbulan izozten da eta olioa hondatzen du.'],
  pro:['Núcleo de tamiz molecular (retiene agua) y, en los antiácidos, alúmina activada. Se elige por capacidad de secado (disminuye al subir la temperatura del líquido) y por pérdida de carga. Se cambia cada vez que se abre el circuito. Tras quemarse un compresor, filtro antiácido en la aspiración y test de acidez del aceite. Una diferencia de temperatura entre la entrada y la salida indica obstrucción.','Bahe molekularreko nukleoa (ura atxikitzen du) eta, antiazidoetan, alumina aktibatua. Lehortze-ahalmenaren (likidoaren tenperatura igotzean jaisten da) eta karga-galeraren arabera aukeratzen da. Zirkuitua irekitzen den bakoitzean aldatzen da. Konpresore bat erre ondoren, iragazki antiazidoa xurgaketan eta olioaren azidotasun-testa. Sarreraren eta irteeraren arteko tenperatura-aldeak buxadura adierazten du.'],
  fun:['Retener humedad, ácidos y partículas.','Hezetasuna, azidoak eta partikulak atxikitzea.'],
  como:['El refrigerante atraviesa el bloque filtrante, que absorbe el agua y retiene la suciedad.','Hozgarriak iragazteko blokea zeharkatzen du, urak xurgatzen ditu eta zikinkeria atxikitzen du.'],
  donde:['En la línea de líquido, después del recipiente y antes del visor y la solenoide.','Likido-lerroan, hartzailearen ondoren eta ikusgailuaren eta solenoidearen aurretik.'],
  con:['Entrada y salida de líquido (respetar la flecha); en las centrales, cartuchos recambiables con llaves.','Likidoaren sarrera eta irteera (gezia errespetatu); zentraletan, kartutxo ordezkagarriak giltzekin.'],
  rel:['Visor indicador de humedad (dice cuándo cambiarlo) y válvula de expansión (la protege).','Hezetasun-adierazledun ikusgailua (noiz aldatu esaten du) eta hedapen-balbula (babesten du).'],
  ave:[['Obstruido: salida más fría que la entrada, burbujas después del filtro, recalentamientos altos.','Buxatuta: irteera sarrera baino hotzago, burbuilak iragazkiaren ondoren, gainberotze altuak.'],['Saturado de agua: el visor marca humedad.','Urez asea: ikusgailuak hezetasuna markatzen du.']],
  chk:[['Diferencia de temperatura entre la entrada y la salida (debe ser prácticamente cero).','Sarreraren eta irteeraren arteko tenperatura-aldea (ia zero izan behar du).'],['Color del indicador de humedad del visor.','Ikusgailuaren hezetasun-adierazlearen kolorea.']],
  seg:['Para cambiarlo, aislar y recuperar el tramo; después, prueba de presión y vacío.','Aldatzeko, tartea isolatu eta berreskuratu; ondoren, presio-proba eta hutsa.']},
 {id:'visor',cat:'lin',t:['Visor de líquido','Likido-ikusgailua'],img:[],
  pri:['Es una «ventanita» en el tubo del líquido. Por ella ves si pasa líquido limpio o con burbujas, y su punto de color te dice si hay humedad: verde, seco; amarillo, húmedo.','Likidoaren hodiko «leihotxo» bat da. Bertatik ikusten duzu likido garbia ala burbuilekin pasatzen den, eta bere kolore-puntuak hezetasuna dagoen esaten dizu: berdea, lehorra; horia, hezea.'],
  pro:['Las burbujas solo son un síntoma con la instalación estable: pueden indicar falta de carga, una restricción antes del visor (filtro) o poco subenfriamiento. En la arrancada o con la carga cambiando son normales. El umbral del indicador de humedad está calibrado para cada refrigerante (ppm de agua).','Burbuilak sintoma dira instalazioa egonkor dagoenean bakarrik: karga falta, ikusgailuaren aurreko murrizketa (iragazkia) edo azpihozte gutxi adieraz dezakete. Abiaraztean edo karga aldatzen ari denean normalak dira. Hezetasun-adierazlearen atalasea hozgarri bakoitzerako kalibratuta dago (ur ppm).'],
  fun:['Ver el estado del líquido y la humedad del circuito.','Likidoaren egoera eta zirkuituko hezetasuna ikustea.'],
  como:['Un cristal deja ver el interior; el elemento indicador cambia de color con la humedad.','Kristal batek barrualdea ikusten uzten du; elementu adierazleak kolorea aldatzen du hezetasunarekin.'],
  donde:['En la línea de líquido, después del filtro y antes de la solenoide o la válvula.','Likido-lerroan, iragazkiaren ondoren eta solenoidearen edo balbularen aurretik.'],
  con:['Roscado, soldado o abocardado en línea.','Lerroan harilkatua, soldatua edo abokardatua.'],
  rel:['Filtro deshidratador, carga de refrigerante y subenfriamiento.','Iragazki lehorgailua, hozgarri-karga eta azpihoztea.'],
  ave:[['Indicador amarillo: humedad (cambiar filtro y revisar el vacío).','Adierazle horia: hezetasuna (iragazkia aldatu eta hutsa berrikusi).'],['Cristal sucio que no deja ver.','Ikusten uzten ez duen kristal zikina.']],
  chk:[['Con la instalación estable: lleno de líquido y sin burbujas.','Instalazioa egonkor dagoenean: likidoz beteta eta burbuilarik gabe.'],['Comparar con el subenfriamiento antes de cargar refrigerante.','Azpihoztearekin alderatu hozgarria kargatu aurretik.']],
  seg:['No se carga refrigerante «hasta que se quiten las burbujas»: la carga se hace por peso.','Ez da hozgarria kargatzen «burbuilak kendu arte»: karga pisuz egiten da.']},
 {id:'sepac',cat:'lin',t:['Separador de aceite','Olio-bereizgailua'],img:[],
  pri:['El compresor siempre suelta un poco de aceite con el gas. El separador lo recoge a la salida del compresor y lo devuelve, para que no se quede repartido por los tubos y los muebles.','Konpresoreak beti askatzen du olio pixka bat gasarekin. Bereizgailuak konpresorearen irteeran biltzen du eta itzuli egiten du, hodietan eta altzarietan banatuta gera ez dadin.'],
  pro:['Separación por cambio de dirección, reducción de velocidad y mallas o filtros coalescentes. En centrales devuelve el aceite a un depósito, que lo reparte a los cárteres mediante reguladores de nivel; el depósito se ventea a la aspiración con una válvula diferencial (unos 1,4 bar por encima del cárter). Con la central parada hay que evitar que condense refrigerante dentro (antirretorno hacia el condensador).','Norabide-aldaketa, abiadura-murrizketa eta sare edo iragazki koaleszenteen bidezko bereizketa. Zentraletan olioa biltegi batera itzultzen du, eta biltegiak karterrei banatzen die maila-erregulatzaileen bidez; biltegia xurgaketara aireztatzen da balbula diferentzial batekin (karterraren gainetik 1,4 bar inguru). Zentrala geldituta dagoenean, saihestu behar da barruan hozgarria kondentsatzea (atzera-ezina kondentsadorerantz).'],
  fun:['Recuperar el aceite que sale con la descarga y devolverlo a los compresores.','Deskargarekin ateratzen den olioa berreskuratzea eta konpresoreei itzultzea.'],
  como:['El gas entra, frena y cambia de dirección; las gotas de aceite caen al fondo y un flotador las devuelve.','Gasa sartu, frenatu eta norabidez aldatzen da; olio-tantak hondora erortzen dira eta flotagailu batek itzultzen ditu.'],
  donde:['En la descarga, justo después del colector de descarga y antes del condensador.','Deskargan, deskarga-kolektorearen ondoren eta kondentsadorearen aurretik.'],
  con:['Entrada de descarga, salida al condensador, retorno de aceite (al depósito o al cárter).','Deskarga-sarrera, irteera kondentsadorera, olio-itzulera (biltegira edo karterrera).'],
  rel:['Compresores, depósito de aceite y reguladores de nivel.','Konpresoreak, olio-biltegia eta maila-erregulatzaileak.'],
  ave:[['Flotador atascado: no devuelve aceite o deja pasar gas caliente al retorno.','Flotagailua trabatuta: ez du oliorik itzultzen edo gas beroa pasatzen uzten du itzulerara.'],['Refrigerante condensado dentro en las paradas.','Hozgarria barruan kondentsatuta geldialdietan.']],
  chk:[['Temperatura de la línea de retorno (ciclos de caliente a templado).','Itzulera-lerroaren tenperatura (beroa eta epela txandakatuz).'],['Nivel del depósito de aceite y alarmas de los reguladores.','Olio-biltegiaren maila eta erregulatzaileen alarmak.']],
  seg:['Trabaja a la presión y la temperatura de descarga: quema y no se abre sin aislar y despresurizar.','Deskargaren presioan eta tenperaturan lan egiten du: erre egiten du eta ez da irekitzen isolatu eta presioa kendu gabe.']},
 {id:'psv',cat:'seg',t:['Válvula de seguridad','Segurtasun-balbula'],img:[],
  pri:['Es el «último recurso»: si la presión sube tanto que algo podría reventar, se abre sola y suelta refrigerante hasta que la presión baja. Nunca se tapa ni se anula.','«Azken baliabidea» da: presioa zerbait lehertzeko adina igotzen bada, bakarrik irekitzen da eta hozgarria askatzen du presioa jaitsi arte. Ez da inoiz tapatzen ni baliogabetzen.'],
  pro:['Válvula de resorte tarada y precintada de fábrica, como mucho a la PS de lo que protege (IF-08). En recipientes de 100 L o más, dos sobre una válvula de cambio. Descarga al lado de baja (preferida en alta) o a la atmósfera por tubería a un sitio seguro. No puede haber llaves entre la válvula y lo que protege, salvo de caperuza precintadas abiertas. Si ha disparado se cambia; se verifica en las revisiones periódicas (IF-14). En CO₂, salida canalizada al exterior y bien sujeta.','Fabrikan taratutako eta zigilatutako malguki-balbula, gehienez babesten duenaren PSra (IF-08). 100 L edo gehiagoko hartzaileetan, bi aldaketa-balbula baten gainean. Baxuko aldera deskargatzen du (altuan hobetsia) edo atmosferara hodi bidez leku seguru batera. Ezin da giltzarik egon balbularen eta babesten duenaren artean, zigilatuta irekita dauden txanodunak izan ezik. Jauzi egin badu aldatu egiten da; aldizkako berrikuspenetan egiaztatzen da (IF-14). CO₂an, irteera kanporantz bideratuta eta ondo lotuta.'],
  fun:['Proteger recipientes, tramos y equipos contra una presión excesiva.','Hartzaileak, tarteak eta ekipoak presio gehiegiaren aurka babestea.'],
  como:['Un muelle mantiene cerrado el asiento; si la presión vence la fuerza del muelle, abre.','Malguki batek eserlekua itxita mantentzen du; presioak malgukiaren indarra gainditzen badu, ireki egiten da.'],
  donde:['Sobre los recipientes, en la parte alta (zona de gas); en compresores grandes y en tramos de líquido que pueden quedar encerrados.','Hartzaileen gainean, goiko aldean (gas-zona); konpresore handietan eta itxita gera daitezkeen likido-tarteetan.'],
  con:['Entrada roscada al equipo y salida a la tubería de descarga (al exterior o al lado de baja).','Sarrera harilkatua ekipora eta irteera deskarga-hodira (kanpora edo baxuko aldera).'],
  rel:['Recipiente, válvula de cambio, presostato de alta y controlador (que debe actuar antes).','Hartzailea, aldaketa-balbula, altuko presostatoa eta kontrolagailua (lehenago jardun behar duena).'],
  ave:[['Pierde después de disparar.','Ihes egiten du jauzi egin ondoren.'],['Corrosión o precinto roto.','Korrosioa edo zigilua hautsita.']],
  chk:[['Placa con presión de tarado, refrigerante y fecha.','Tarazio-presioa, hozgarria eta data dituen plaka.'],['Que no haya escarcha ni pérdida en la salida.','Irteeran izarrik edo ihesik ez egotea.']],
  seg:['No se prueba haciéndola disparar ni se reajusta en obra. Nunca se pone otra válvula detrás para que «no pierda».','Ez da probatzen jauzi eraginez eta ez da obran berriro doitzen. Ez da inoiz beste balbula bat jartzen atzean «ihes egin ez dezan».']},
 {id:'presos',cat:'seg',t:['Presostatos de alta y baja','Altuko eta baxuko presostatoak'],img:['presos_0','presos_3'],
  pri:['Son interruptores que se abren con la presión. El de <b>alta</b> para el compresor si la presión sube demasiado (por ejemplo, con el condensador sucio). El de <b>baja</b> lo para si la presión de aspiración cae demasiado.','Presioarekin irekitzen diren etengailuak dira. <b>Altukoak</b> konpresorea gelditzen du presioa gehiegi igotzen bada (adibidez, kondentsadorea zikin dagoenean). <b>Baxukoak</b> gelditzen du xurgaketa-presioa gehiegi jaisten bada.'],
  pro:['El de alta es de seguridad: rearme manual y tarado por debajo de la válvula de seguridad (en máquinas grandes, de doble fuelle, que falla hacia el lado seguro). El de baja hace de protección y, en equipos con recogida de gas, de control (paro y arranque con diferencial). Contactos en serie con la bobina del contactor. Se comprueban con manómetro y, si es posible, provocando la condición de forma controlada.','Altukoa segurtasunekoa da: eskuzko berrarmatzea eta segurtasun-balbularen azpitik taratua (makina handietan, hauspo bikoitzekoa, alde seguruaren alde huts egiten duena). Baxukoak babes gisa egiten du eta, gas-bilketa duten ekipoetan, kontrol gisa (gelditzea eta abiaraztea diferentzialarekin). Kontaktuak kontaktorearen bobinarekin seriean. Manometroarekin egiaztatzen dira eta, ahal bada, egoera modu kontrolatuan eraginez.'],
  fun:['Parar el compresor cuando las presiones salen de los límites seguros.','Konpresorea gelditzea presioak muga seguruetatik ateratzen direnean.'],
  como:['La presión empuja un fuelle o una membrana contra un muelle ajustable; al pasar del punto de tarado, abre el contacto.','Presioak hauspo edo mintz bat malguki doigarri baten aurka bultzatzen du; tarazio-puntua gainditzean, kontaktua irekitzen du.'],
  donde:['En la culata o la aspiración del compresor (o en los colectores), con capilar o latiguillo.','Konpresorearen kulatan edo xurgaketan (edo kolektoreetan), kapilarrarekin edo latiguilloarekin.'],
  con:['Toma de presión y contacto eléctrico (NC) en la cadena de seguridades.','Presio-hartunea eta kontaktu elektrikoa (NC) segurtasun-katean.'],
  rel:['Contactor del compresor, controlador, válvula de seguridad y condensador.','Konpresorearen kontaktorea, kontrolagailua, segurtasun-balbula eta kondentsadorea.'],
  ave:[['Tarado incorrecto (ciclos cortos o protección que no actúa).','Tarazio okerra (ziklo laburrak edo jarduten ez duen babesa).'],['Capilar roto (fuga) o contacto quemado.','Kapilarra hautsita (ihesa) edo kontaktua erreta.']],
  chk:[['Punto de disparo con manómetro.','Jauzi-puntua manometroarekin.'],['Continuidad del contacto sin tensión.','Kontaktuaren jarraitutasuna tentsiorik gabe.']],
  seg:['Nunca se puentea una seguridad para dejar la máquina en marcha.','Ez da inoiz segurtasun bat zubitzen makina martxan uzteko.']},
 {id:'contactor',cat:'ele',t:['Contactor','Kontaktorea'],img:['contactor_1','contactor_0','contactor_3'],
  pri:['Es un interruptor grande que se mueve con un electroimán. Con una corriente pequeña (la del termostato o el controlador) conecta la corriente grande que necesita el motor del compresor.','Elektroiman batekin mugitzen den etengailu handia da. Korronte txiki batekin (termostatoarena edo kontrolagailuarena) konpresorearen motorrak behar duen korronte handia konektatzen du.'],
  pro:['Tres contactos principales (L1-L2-L3 → T1-T2-T3) y auxiliares (13-14 NA, 21-22 NC). La bobina (A1-A2) debe ser de la tensión de mando correcta. Se elige por la categoría de empleo (AC-3 para motores) y la intensidad. Los contactos se desgastan con cada arranque: un contacto picado da caída de tensión y desequilibrio entre fases.','Hiru kontaktu nagusi (L1-L2-L3 → T1-T2-T3) eta laguntzaileak (13-14 NA, 21-22 NC). Bobinak (A1-A2) agintzeko tentsio zuzenekoa izan behar du. Erabilera-kategoriaren (AC-3 motorretarako) eta intentsitatearen arabera aukeratzen da. Kontaktuak higatu egiten dira abiarazte bakoitzarekin: kontaktu zulatu batek tentsio-jaitsiera eta faseen arteko desoreka sortzen ditu.'],
  fun:['Conectar y desconectar el motor según mande el circuito de mando.','Motorra konektatzea eta deskonektatzea agintzeko zirkuituak agintzen duenaren arabera.'],
  como:['Al alimentar la bobina, el núcleo atrae la parte móvil y cierra los contactos; sin tensión, un muelle los abre.','Bobina elikatzean, nukleoak zati mugikorra erakartzen du eta kontaktuak ixten ditu; tentsiorik gabe, malguki batek irekitzen ditu.'],
  donde:['En el cuadro eléctrico, en carril DIN, después del guardamotor de cada compresor o ventilador.','Koadro elektrikoan, DIN errailean, konpresore edo haizagailu bakoitzaren motor-babeslearen ondoren.'],
  con:['Fuerza: tres fases de entrada y salida al motor. Mando: bobina A1-A2 y contactos auxiliares.','Indarra: hiru fase sarreran eta irteera motorrera. Agintea: A1-A2 bobina eta kontaktu laguntzaileak.'],
  rel:['Guardamotor, relé del controlador, presostatos (en serie con la bobina) y motor.','Motor-babeslea, kontrolagailuaren errelea, presostatoak (bobinarekin seriean) eta motorra.'],
  ave:[['Bobina cortada: no entra.','Bobina etenda: ez da sartzen.'],['Contactos picados o pegados.','Kontaktuak zulatuta edo itsatsita.'],['Bornes flojos que se calientan.','Berotzen diren borne askeak.']],
  chk:[['Tensión en A1-A2 cuando hay orden de marcha.','Tentsioa A1-A2n martxa-agindua dagoenean.'],['Resistencia de la bobina (sin tensión).','Bobinaren erresistentzia (tentsiorik gabe).'],['Tensión entre fases a la salida con el contactor entrado, y temperatura de los bornes (termografía).','Faseen arteko tentsioa irteeran kontaktorea sartuta dagoenean, eta borneen tenperatura (termografia).']],
  seg:['Trabajar sin tensión: cortar, bloquear, señalizar y comprobar ausencia de tensión (RD 614/2001). La bobina puede estar alimentada desde otro circuito de mando.','Tentsiorik gabe lan egin: moztu, blokeatu, seinaleztatu eta tentsiorik ez dagoela egiaztatu (614/2001 ED). Bobina beste agintze-zirkuitu batetik elika daiteke.']},
 {id:'guarda',cat:'ele',t:['Guardamotor','Motor-babeslea'],img:['guardamotor_1'],
  pri:['Protege al motor: si consume más corriente de la que debe durante un rato (porque se atasca o le falta una fase), salta y lo desconecta antes de que se queme.','Motorra babesten du: denbora batez behar baino korronte gehiago kontsumitzen badu (trabatzen delako edo fase bat falta zaiolako), jauzi egin eta deskonektatu egiten du erre baino lehen.'],
  pro:['Interruptor magnetotérmico para motores: disparo térmico regulable (se ajusta a la intensidad nominal de la placa a la tensión de conexión) y magnético fijo para cortocircuitos. Su contacto auxiliar va en la cadena de seguridades o a una alarma. En part-winding, uno por devanado ajustado a su parte de la corriente.','Motorretarako etengailu magnetotermikoa: jauzi termiko doigarria (plakako intentsitate nominalera doitzen da konexio-tentsioan) eta magnetiko finkoa zirkuitulaburretarako. Bere kontaktu laguntzailea segurtasun-katean edo alarma batera doa. Part-windingean, bat harilkatu bakoitzeko, korrontearen bere zatira doituta.'],
  fun:['Proteger el motor contra sobrecargas, falta de fase y cortocircuitos, y servir de seccionamiento.','Motorra gainkargen, fase-faltaren eta zirkuitulaburren aurka babestea, eta seksionatzeko balio izatea.'],
  como:['Unas láminas bimetálicas se calientan con la corriente y disparan; una bobina dispara al instante con un cortocircuito.','Xafla bimetaliko batzuk korrontearekin berotu eta jauzi egiten dute; bobina batek berehala jauzi egiten du zirkuitulabur batekin.'],
  donde:['En el cuadro, al principio de cada salida de motor, antes del contactor.','Koadroan, motor-irteera bakoitzaren hasieran, kontaktorearen aurretik.'],
  con:['Tres fases de entrada y de salida, y contacto auxiliar a la maniobra o a la alarma.','Hiru fase sarreran eta irteeran, eta kontaktu laguntzailea maniobrara edo alarmara.'],
  rel:['Contactor, motor y controlador (alarma de guardamotor).','Kontaktorea, motorra eta kontrolagailua (motor-babeslearen alarma).'],
  ave:[['Mal ajustado (salta sin motivo o no protege).','Gaizki doituta (arrazoirik gabe jauzi egiten du edo ez du babesten).'],['Salta repetidamente: sobrecarga, alta presión, falta de fase o bobina del motor dañada.','Behin eta berriz jauzi egiten du: gainkarga, presio altua, fase falta edo motorraren harilkatua hondatuta.']],
  chk:[['Ajuste frente a la placa del motor.','Doikuntza motorraren plakarekin alderatuta.'],['Intensidad de las tres fases con pinza.','Hiru faseetako intentsitatea pintzarekin.'],['Antes de rearmar, buscar la causa del disparo.','Berrarmatu aurretik, jauziaren arrazoia bilatu.']],
  seg:['No subir el ajuste para que «no salte»: el motor se quemaría.','Ez igo doikuntza «jauzi egin ez dezan»: motorra erreko litzateke.']}
];
const COMP_PEND=['cond','eev','rec','filtro','visor','sepac','psv']; // fichas a las que les falta una foto real correcta
KT.ccur='semi';
function compImgs(c){ return (c.img||[]).map(id=>typeof mdById==='function'?mdById(id):null).filter(m=>m&&m.img); }
function compRender(main){ const c=COMP.find(x=>x.id===KT.ccur)||COMP[0]; const pro=nvPro(); const ims=compImgs(c);
  const sec=(ic,t,body,open)=>`<details class="cp-sec"${open?' open':''}><summary>${ic} ${t}</summary><div>${body}</div></details>`;
  const ul=a=>`<ul>${a.map(x=>`<li>${KL(...x)}</li>`).join('')}</ul>`;
  const gal=ims.length?`<div class="cp-gal">${ims.map((m,i)=>`<button class="cp-im" data-cpi="${i}" title="${KL('Ver grande','Handiago ikusi')}"><img src="${m.img}" alt="${MDT(m.t)}"><small>${MDT(m.t)}</small></button>`).join('')}</div><p class="cp-cred">${ims.map(m=>`${m.author||'—'} · ${m.lic}`).join(' — ')} · Wikimedia Commons</p>`
    :`<div class="cp-nofoto">📷 ${KL('Todavía no hay una foto real correcta de este componente. Si nos la mandas (sin marcas visibles), la añadimos.','Oraindik ez dago osagai honen benetako argazki zuzenik. Bidaltzen badiguzu (marka ikusgarririk gabe), gehituko dugu.')}</div>`;
  const qB=`<div class="nv-box pri"><b class="nv-h">💡 ${KL('Qué es, explicado fácil','Zer den, erraz azalduta')}</b>${KL(...c.pri)}</div>`, qP=`<div class="nv-box pro"><b class="nv-h">🔧 ${KL('Explicación profesional','Azalpen profesionala')}</b>${KL(...c.pro)}</div>`;
  main.innerHTML=`<div class="cp"><h2>${KL(...c.t)}</h2><div class="cp-top"><div>${gal}</div><div>${pro?qP+`<details class="nv-box pri"><summary>💡 ${KL('Ver la explicación sencilla','Ikusi azalpen erraza')}</summary><div>${KL(...c.pri)}</div></details>`:qB+`<details class="nv-box pro"><summary>🔧 ${KL('Ampliar: explicación profesional','Zabaldu: azalpen profesionala')}</summary><div>${KL(...c.pro)}</div></details>`}</div></div>
   <div class="cp-grid">${sec('🎯',KL('Para qué sirve','Zertarako balio du'),`<p>${KL(...c.fun)}</p>`,true)}${sec('⚙️',KL('Cómo funciona','Nola dabilen'),`<p>${KL(...c.como)}</p>`,true)}${sec('📍',KL('Dónde va en la instalación','Instalazioan non doan'),`<p>${KL(...c.donde)}</p>`,true)}
   ${sec('🔌',KL('Conexiones','Konexioak'),`<p>${KL(...c.con)}</p>`,pro)}${sec('🔗',KL('Con qué se relaciona','Zerekin lotzen den'),`<p>${KL(...c.rel)}</p>`,pro)}${sec('⚠️',KL('Averías habituales','Ohiko matxurak'),ul(c.ave),pro)}${sec('🔍',KL('Comprobaciones','Egiaztapenak'),ul(c.chk),pro)}${sec('🦺',KL('Seguridad','Segurtasuna'),`<p>${KL(...c.seg)}</p>`,true)}</div>
   ${pro?'':`<p class="cp-tip">${KL('Pulsa en cada apartado para abrirlo o cerrarlo. En el modo profesional se abren todos.','Sakatu atal bakoitzean irekitzeko edo ixteko. Modu profesionalean denak irekitzen dira.')}</p>`}</div>`;
  main.querySelectorAll('[data-cpi]').forEach(b=>b.onclick=()=>mdOpen(ims,+b.dataset.cpi)); }
KTABS.comp={t:['Componentes','Osagaiak'],ph:['Buscar componente…','Bilatu osagaia…'],
  list:q=>Object.keys(CCAT).map(cat=>{ const L=COMP.filter(c=>c.cat===cat&&(!q||(KL(...c.t)+' '+KL(...c.pri)).toLowerCase().includes(q))); if(!L.length) return ''; return `<h4>${KL(...CCAT[cat])}</h4>`+L.map(c=>`<button class="kt-li${c.id===KT.ccur?' on':''}" data-c="${c.id}">${KL(...c.t)}</button>`).join(''); }).join(''),
  render:main=>compRender(main)};
document.addEventListener('click',e=>{ if(!KT.open) return; const b=e.target.closest&&e.target.closest('#kt [data-c]'); if(!b) return; KT.ccur=b.dataset.c; ktRender(); const m=document.querySelector('#kt .kt-main'); if(m&&window.innerWidth<900) m.scrollIntoView({behavior:'smooth'}); });
(function(){ const s=document.createElement('style'); s.textContent=`.cp h2{margin:0 0 14px;font-size:22px}
.cp-top{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.2fr);gap:18px;align-items:start}
.cp-gal{display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:8px}
.cp-im{border:1px solid #dfe5ea;border-radius:10px;overflow:hidden;background:#fff;padding:0;cursor:zoom-in;text-align:left}.cp-im img{display:block;width:100%;height:120px;object-fit:cover}.cp-im small{display:block;padding:5px 8px;font-size:12px;color:#33424f}
.cp-cred{font-size:11px;color:#6b7c8a;margin:6px 0 0}
.cp-nofoto{border:1px dashed #c9d3dc;border-radius:12px;padding:18px;color:#5b6b7a;background:#fbfcfd;font-size:14px}
.cp-top .nv-box{margin-top:0}
.cp-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;margin-top:16px}
.cp-sec{background:#fff;border:1px solid #dfe5ea;border-radius:12px}.cp-sec>summary{cursor:pointer;padding:10px 14px;font-weight:700;font-size:14.5px;list-style:none}.cp-sec>summary::-webkit-details-marker{display:none}
.cp-sec>div{padding:0 14px 12px;font-size:14.5px;line-height:1.5}.cp-sec ul{margin:0;padding-left:20px}.cp-sec li{margin:3px 0}.cp-sec p{margin:0}
.cp-tip{color:#5b6b7a;font-size:13px;margin-top:12px}
@media(max-width:900px){.cp-top,.cp-grid{grid-template-columns:minmax(0,1fr)}}`; document.head.appendChild(s); })();

// ===== Biblioteca de componentes · 2.ª parte (etapa 3): protecciones eléctricas, variador, cuadro, tubería, bomba e intercambiador de placas =====
CCAT.hid=['Tuberías e hidráulica','Hodiak eta hidraulika'];
COMP.push(
 {id:'fusible',cat:'ele',t:['Fusible y portafusibles','Fusiblea eta fusible-euskarria'],img:['fusible_0'],
  pri:['Es la protección más sencilla: un hilo calibrado dentro de un cartucho. Si pasa demasiada corriente (por ejemplo, por un cortocircuito), el hilo se funde y corta el circuito. Una vez fundido hay que cambiarlo por otro igual.','Babesik errazena da: kartutxo baten barruko hari kalibratu bat. Korronte gehiegi pasatzen bada (adibidez, zirkuitulabur batengatik), haria urtu eta zirkuitua mozten du. Behin urtuta, berdin-berdina den beste batekin aldatu behar da.'],
  pro:['Se elige por calibre (In), tensión, poder de corte y <b>tipo</b>: gG (uso general, protege cables contra sobrecarga y cortocircuito) o aM (acompañamiento de motor: solo cortocircuito, aguanta el arranque; necesita un relé térmico o guardamotor). Cortan muy rápido y limitan la energía de un cortocircuito (I²t), por eso se usan delante de variadores o como protección de respaldo. El portafusibles seccionable sirve además para dejar sin tensión una salida.','Kalibrearen (In), tentsioaren, etete-ahalmenaren eta <b>motaren</b> arabera aukeratzen da: gG (erabilera orokorra, kableak gainkargaren eta zirkuitulaburraren aurka babesten ditu) edo aM (motorraren laguntza: zirkuitulaburra bakarrik, abiaraztea jasaten du; erreleo termikoa edo motor-babeslea behar du). Oso azkar mozten dute eta zirkuitulabur baten energia mugatzen dute (I²t); horregatik erabiltzen dira aldagailuen aurrean edo babes osagarri gisa. Fusible-euskarri seksionagarriak, gainera, irteera bat tentsiorik gabe uzteko balio du.'],
  fun:['Cortar la corriente cuando hay un cortocircuito o, según el tipo, una sobrecarga.','Korrontea moztea zirkuitulabur bat dagoenean edo, motaren arabera, gainkarga bat.'],
  como:['El elemento fusible se calienta con la corriente; si pasa del límite, se funde y abre el circuito. La arena del cartucho apaga el arco.','Elementu fusiblea korrontearekin berotzen da; muga gainditzen badu, urtu eta zirkuitua irekitzen du. Kartutxoko hareak arkua itzaltzen du.'],
  donde:['En el cuadro, al principio de una línea o delante de un equipo (variador, transformador de maniobra, alimentación de controladores).','Koadroan, linea baten hasieran edo ekipo baten aurrean (aldagailua, maniobra-transformadorea, kontrolagailuen elikadura).'],
  con:['Entrada desde la línea de alimentación y salida hacia el equipo que protege; en trifásico, un fusible por fase.','Sarrera elikadura-linetik eta irteera babesten duen ekipora; trifasikoan, fusible bat fase bakoitzeko.'],
  rel:['Cable que protege, guardamotor o relé térmico (con fusibles aM), variador e interruptor general.','Babesten duen kablea, motor-babeslea edo erreleo termikoa (aM fusibleekin), aldagailua eta etengailu nagusia.'],
  ave:[['Fusible fundido: el equipo no tiene tensión.','Fusible urtua: ekipoak ez du tentsiorik.'],['Una sola fase fundida en trifásico: el motor trabaja en dos fases y se calienta.','Trifasikoan fase bakarra urtuta: motorrak bi fasetan lan egiten du eta berotu egiten da.'],['Portafusibles flojo o quemado por mal contacto.','Fusible-euskarria askatuta edo erreta kontaktu txarragatik.']],
  chk:[['Sin tensión y con el portafusibles abierto: continuidad del cartucho con el polímetro.','Tentsiorik gabe eta fusible-euskarria irekita: kartutxoaren jarraitutasuna polimetroarekin.'],['Con tensión (personal cualificado): tensión a la entrada y a la salida de cada fase.','Tentsioarekin (langile kualifikatuak): tentsioa fase bakoitzaren sarreran eta irteeran.'],['Que el repuesto sea del mismo calibre y tipo.','Ordezkoa kalibre eta mota berekoa izatea.']],
  seg:['Nunca se pone un fusible de más calibre ni se puentea. Antes de cambiarlo, buscar por qué se ha fundido.','Ez da inoiz kalibre handiagoko fusiblerik jartzen ezta zubitzen ere. Aldatu aurretik, bilatu zergatik urtu den.']},
 {id:'magneto',cat:'ele',t:['Interruptor magnetotérmico','Etengailu magnetotermikoa'],img:[],
  pri:['Es el «automático» que hay en todos los cuadros. Protege los cables: salta si pasa más corriente de la que aguanta el cable o si hay un cortocircuito. A diferencia del fusible, se vuelve a subir con la palanca.','Koadro guztietan dagoen «automatikoa» da. Kableak babesten ditu: jauzi egiten du kableak jasaten duena baino korronte gehiago pasatzen bada edo zirkuitulabur bat badago. Fusiblea ez bezala, palankarekin berriro igotzen da.'],
  pro:['Dos disparos: <b>térmico</b> (bimetal, sobrecargas, tiempo inverso) y <b>magnético</b> (bobina, cortocircuitos, instantáneo). Curva según el disparo magnético: B (3-5·In), C (5-10·In, uso general y motores pequeños) y D (10-20·In, arranques fuertes). Se elige para que In no supere la intensidad admisible del cable (REBT, ITC-BT-19 e ITC-BT-22) y con poder de corte suficiente para la corriente de cortocircuito del punto donde va (p. ej., 6 o 10 kA).','Bi jauzi: <b>termikoa</b> (bimetala, gainkargak, alderantzizko denbora) eta <b>magnetikoa</b> (bobina, zirkuitulaburrak, berehalakoa). Kurba jauzi magnetikoaren arabera: B (3-5·In), C (5-10·In, erabilera orokorra eta motor txikiak) eta D (10-20·In, abiarazte gogorrak). In kablearen intentsitate onargarria gainditu gabe aukeratzen da (REBT, ITC-BT-19 eta ITC-BT-22), eta jarriko den puntuko zirkuitulabur-korronterako etete-ahalmen nahikoarekin (adib., 6 edo 10 kA).'],
  fun:['Proteger la línea contra sobrecargas y cortocircuitos y permitir cortarla a mano.','Linea gainkargen eta zirkuitulaburren aurka babestea eta eskuz mozteko aukera ematea.'],
  como:['Un bimetal se curva con el calor de la corriente y dispara (sobrecarga); una bobina atrae un núcleo y dispara al instante (cortocircuito).','Bimetal bat korrontearen beroarekin okertu eta jauzi egiten du (gainkarga); bobina batek nukleo bat erakarri eta berehala jauzi egiten du (zirkuitulaburra).'],
  donde:['En el cuadro, en carril DIN, al principio de cada circuito (alumbrado, maniobra, resistencias, ventiladores…).','Koadroan, DIN errailean, zirkuitu bakoitzaren hasieran (argiak, maniobra, erresistentziak, haizagailuak…).'],
  con:['Entrada desde el embarrado o el general, salida al circuito; 1, 2, 3 o 4 polos.','Sarrera barra-multzotik edo nagusitik, irteera zirkuitura; 1, 2, 3 edo 4 polo.'],
  rel:['Diferencial, cable que protege, contactores y equipos aguas abajo.','Diferentziala, babesten duen kablea, kontaktoreak eta beherago dauden ekipoak.'],
  ave:[['Salta al conectar: cortocircuito o arranque demasiado fuerte para su curva.','Konektatzean jauzi egiten du: zirkuitulaburra edo bere kurbarako abiarazte gogorregia.'],['Salta tras un rato: sobrecarga (resistencia, motor frenado).','Denbora baten ondoren jauzi egiten du: gainkarga (erresistentzia, motor balaztatua).'],['Bornes flojos que se calientan.','Berotzen diren borne askeak.']],
  chk:[['Intensidad del circuito con pinza frente al calibre.','Zirkuituaren intentsitatea pintzarekin kalibrearekin alderatuta.'],['Aislamiento del circuito (sin tensión) para buscar derivaciones o cortos.','Zirkuituaren isolamendua (tentsiorik gabe) deribazioak edo laburrak bilatzeko.'],['Temperatura de bornes (termografía).','Borneen tenperatura (termografia).']],
  seg:['Si salta, primero se busca la causa; no se rearma repetidamente. No se cambia por uno de más calibre sin comprobar el cable.','Jauzi egiten badu, lehenengo arrazoia bilatzen da; ez da behin eta berriz berrarmatzen. Ez da kalibre handiagoko batekin aldatzen kablea egiaztatu gabe.']},
 {id:'difer',cat:'ele',t:['Interruptor diferencial','Etengailu diferentziala'],img:[],
  pri:['Protege a las personas. Compara la corriente que sale por un cable con la que vuelve por el otro; si falta un poco es porque se está escapando a tierra (quizá a través de una persona) y corta en milisegundos.','Pertsonak babesten ditu. Kable batetik ateratzen den korrontea bestetik itzultzen denarekin alderatzen du; pixka bat falta bada, lurrera ihes egiten ari delako da (agian pertsona baten bidez), eta milisegundo gutxitan mozten du.'],
  pro:['Detecta la corriente diferencial residual con un toroidal. Sensibilidad IΔn de 30 mA (protección complementaria de personas) o 300 mA y más (protección contra incendios y selectividad). Tipos: AC (alterna senoidal), A (además continua pulsante), F (además frecuencias mixtas, monofásico con variador) y B (además continua lisa, variadores trifásicos). Con variadores y filtros EMC hay corrientes de fuga permanentes que provocan disparos: se reparte la carga entre diferenciales o se usan los tipos y sensibilidades que indique el fabricante. Se prueba con su botón «T» y, en las revisiones, con un comprobador (tiempo de disparo).','Korronte diferentzial hondarra detektatzen du toroidal batekin. IΔn sentikortasuna 30 mA (pertsonen babes osagarria) edo 300 mA eta gehiago (suteen aurkako babesa eta selektibitatea). Motak: AC (alterno sinusoidala), A (gainera korronte jarraitu pultsatzailea), F (gainera maiztasun mistoak, aldagailudun monofasikoa) eta B (gainera korronte jarraitu leuna, aldagailu trifasikoak). Aldagailuekin eta EMC iragazkiekin etengabeko ihes-korronteak daude, eta jauziak eragiten dituzte: karga diferentzialen artean banatzen da edo fabrikatzaileak adierazten dituen motak eta sentikortasunak erabiltzen dira. Bere «T» botoiarekin probatzen da eta, berrikuspenetan, egiaztagailu batekin (jauzi-denbora).'],
  fun:['Cortar cuando hay una fuga de corriente a tierra, para evitar electrocuciones e incendios.','Lurrera korronte-ihes bat dagoenean moztea, elektrokuzioak eta suteak saihesteko.'],
  como:['Las fases y el neutro pasan por un toro; si la suma de corrientes no es cero, el toro induce una señal que dispara el mecanismo.','Faseak eta neutroa toro batetik pasatzen dira; korronteen batura zero ez bada, toroak seinale bat induzitzen du eta mekanismoak jauzi egiten du.'],
  donde:['En el cuadro, delante de grupos de circuitos; en instalaciones grandes, en cabecera de cada línea importante.','Koadroan, zirkuitu-taldeen aurrean; instalazio handietan, linea garrantzitsu bakoitzaren buruan.'],
  con:['Fases y neutro entran y salen por él (el neutro también); la tierra NO pasa por el diferencial.','Faseak eta neutroa bertatik sartu eta ateratzen dira (neutroa ere bai); lurra EZ da diferentzialetik pasatzen.'],
  rel:['Toma de tierra de la instalación, magnetotérmicos, variadores y resistencias de desescarche (fugas típicas con humedad).','Instalazioaren lur-hartunea, magnetotermikoak, aldagailuak eta izotz-kentzeko erresistentziak (hezetasunarekin ohiko ihesak).'],
  ave:[['Salta en cada desescarche: resistencia con el aislamiento dañado o agua en una caja.','Izotz-kentze bakoitzean jauzi egiten du: isolamendu hondatua duen erresistentzia edo ura kaxa batean.'],['Saltos sin motivo claro: suma de fugas de variadores y filtros.','Arrazoi argirik gabeko jauziak: aldagailuen eta iragazkien ihesen batura.'],['Neutro de dos diferenciales mezclado.','Bi diferentzialen neutroa nahastuta.']],
  chk:[['Pulsar el botón de prueba periódicamente.','Proba-botoia aldizka sakatzea.'],['Con comprobador: corriente y tiempo de disparo.','Egiaztagailuarekin: jauzi-korrontea eta -denbora.'],['Buscar la fuga desconectando circuitos uno a uno y midiendo aislamiento con megóhmetro (sin tensión y sin electrónica conectada).','Ihesa bilatu zirkuituak banan-banan deskonektatuz eta isolamendua megohmetroarekin neurtuz (tentsiorik gabe eta elektronikarik konektatu gabe).']],
  seg:['Nunca se anula ni se puentea un diferencial. Si salta, hay que encontrar la fuga.','Ez da inoiz diferentzial bat baliogabetzen ezta zubitzen ere. Jauzi egiten badu, ihesa aurkitu behar da.']},
 {id:'vfd',cat:'ele',t:['Variador de frecuencia','Maiztasun-aldagailua'],img:['variador_0'],
  pri:['Es un aparato electrónico que cambia la velocidad de un motor. Así el compresor o el ventilador van más despacio cuando hace falta poco frío y gastan menos electricidad.','Motor baten abiadura aldatzen duen aparatu elektronikoa da. Horrela, konpresorea edo haizagailua polikiago doaz hotz gutxi behar denean, eta elektrizitate gutxiago kontsumitzen dute.'],
  pro:['Rectificador → bus de continua (unos 560 V DC con red de 400 V) → inversor de IGBT que genera una tensión PWM de frecuencia variable. Control V/f o vectorial. En compresores se respeta la frecuencia mínima y máxima del fabricante (lubricación y vibraciones). Necesita cable de motor apantallado y bien conectado a tierra, y el diferencial adecuado (tipo B o el que indique el fabricante). Recibe la consigna por 0-10 V, 4-20 mA o bus de comunicaciones desde el controlador de la central.','Zuzentzailea → korronte jarraituko busa (560 V DC inguru 400 V-ko sarearekin) → maiztasun aldakorreko PWM tentsioa sortzen duen IGBT inbertsorea. V/f edo bektore-kontrola. Konpresoreetan fabrikatzailearen gutxieneko eta gehieneko maiztasuna errespetatzen dira (lubrifikazioa eta bibrazioak). Motorrerako kable blindatua behar du, lurrera ondo konektatuta, eta diferentzial egokia (B motakoa edo fabrikatzaileak adierazten duena). Kontsigna 0-10 V, 4-20 mA edo komunikazio-bus bidez jasotzen du zentralaren kontrolagailutik.'],
  fun:['Ajustar la potencia del compresor o de los ventiladores a la demanda real y arrancar el motor suavemente.','Konpresorearen edo haizagailuen potentzia benetako eskarira egokitzea eta motorra leun abiaraztea.'],
  como:['Convierte la alterna de la red en continua y después la vuelve a convertir en alterna con la frecuencia que pide el controlador.','Sareko korronte alternoa jarraitu bihurtzen du eta gero berriro alterno bihurtzen du kontrolagailuak eskatzen duen maiztasunarekin.'],
  donde:['En el cuadro de la central, con ventilación suficiente para su disipador.','Zentralaren koadroan, bere disipadorerako aireztapen nahikoarekin.'],
  con:['Entrada de red (L1-L2-L3), salida al motor (U-V-W), tierra, señal de consigna y marcha, relé de alarma.','Sare-sarrera (L1-L2-L3), irteera motorrera (U-V-W), lurra, kontsigna- eta martxa-seinalea, alarma-errelea.'],
  rel:['Compresor líder de la central, controlador, fusibles o protección de entrada y diferencial.','Zentralaren konpresore buruzagia, kontrolagailua, fusibleak edo sarrerako babesa eta diferentziala.'],
  ave:[['Alarma de sobrecorriente o sobretensión del bus.','Gainkorronte-alarma edo busaren gaintentsio-alarma.'],['Sobretemperatura: ventilador del variador parado o filtro sucio.','Gaintenperatura: aldagailuaren haizagailua geldituta edo iragazkia zikin.'],['Disparos del diferencial por corrientes de fuga.','Diferentzialaren jauziak ihes-korronteengatik.']],
  chk:[['Leer el código de alarma y el historial del variador.','Aldagailuaren alarma-kodea eta historiala irakurtzea.'],['Frecuencia y corriente de salida frente a la consigna.','Irteerako maiztasuna eta korrontea kontsignarekin alderatuta.'],['Limpieza del disipador y del ventilador.','Disipadorearen eta haizagailuaren garbiketa.']],
  seg:['Después de cortar la tensión, los condensadores del bus siguen cargados unos minutos: esperar el tiempo que marca el aparato y medir que no hay tensión antes de tocar. No medir aislamiento con el megóhmetro con el variador conectado.','Tentsioa moztu ondoren, busaren kondentsadoreak minutu batzuez kargatuta jarraitzen dute: itxaron aparatuak markatzen duen denbora eta ukitu aurretik egiaztatu tentsiorik ez dagoela. Ez neurtu isolamendua megohmetroarekin aldagailua konektatuta dagoela.']},
 {id:'cuadro',cat:'ele',t:['Cuadro eléctrico de la central','Zentralaren koadro elektrikoa'],img:['cuadro_1'],
  pri:['Es el armario donde están todas las protecciones, contactores y controladores de la instalación. Desde ahí llega la corriente a cada compresor y ventilador, y ahí está el interruptor general para dejarlo todo sin tensión.','Instalazioaren babes, kontaktore eta kontrolagailu guztiak dauden armairua da. Handik iristen da korrontea konpresore eta haizagailu bakoitzera, eta han dago dena tentsiorik gabe uzteko etengailu nagusia.'],
  pro:['Partes: interruptor general seccionador, embarrado, protecciones por salida (guardamotores, magnetotérmicos, diferenciales), contactores, transformador o fuente de maniobra (230 V CA / 24 V), controladores, relés de seguridad, bornas numeradas y esquema. La serie de seguridades (alta, baja, térmicos, aceite) corta la bobina de cada contactor. Grado IP y ventilación según el sitio. La instalación eléctrica la hace y la modifica una empresa habilitada según el REBT.','Zatiak: etengailu nagusi seksionagailua, barra-multzoa, irteerako babesak (motor-babesleak, magnetotermikoak, diferentzialak), kontaktoreak, maniobrako transformadorea edo iturria (230 V AC / 24 V), kontrolagailuak, segurtasun-erreleak, borne zenbakidunak eta eskema. Segurtasun-kateak (altua, baxua, termikoak, olioa) kontaktore bakoitzaren bobina mozten du. IP maila eta aireztapena tokiaren arabera. Instalazio elektrikoa REBTren arabera gaitutako enpresa batek egiten eta aldatzen du.'],
  fun:['Repartir y proteger la alimentación de todos los equipos y hacer la maniobra (quién arranca y cuándo).','Ekipo guztien elikadura banatzea eta babestea, eta maniobra egitea (nor abiarazten den eta noiz).'],
  como:['El controlador da órdenes a los relés; estos alimentan las bobinas de los contactores a través de la cadena de seguridades.','Kontrolagailuak erreleei aginduak ematen dizkie; hauek kontaktoreen bobinak elikatzen dituzte segurtasun-katearen bidez.'],
  donde:['En la sala de máquinas, junto a la central, con espacio libre delante para trabajar.','Makina-gelan, zentralaren ondoan, aurrean lan egiteko leku librearekin.'],
  con:['Acometida, salidas a motores, ventiladores y resistencias, sondas y transductores, bus de comunicaciones y alarmas.','Hartunea, irteerak motorretara, haizagailuetara eta erresistentzietara, zundak eta transduktoreak, komunikazio-busa eta alarmak.'],
  rel:['Todos los elementos eléctricos de la instalación y el controlador de la central.','Instalazioaren elementu elektriko guztiak eta zentralaren kontrolagailua.'],
  ave:[['Bornes flojos y calentamientos.','Borne askeak eta berotzeak.'],['Polvo y humedad en el interior.','Hautsa eta hezetasuna barruan.'],['Ventilación del cuadro parada (alarmas de variadores).','Koadroaren aireztapena geldituta (aldagailuen alarmak).']],
  chk:[['Termografía con carga y reapriete de bornes sin tensión.','Termografia kargarekin eta borneen berrestutzea tentsiorik gabe.'],['Que el esquema esté en el cuadro y coincida con lo instalado.','Eskema koadroan egotea eta instalatutakoarekin bat etortzea.'],['Prueba de cada seguridad.','Segurtasun bakoitzaren proba.']],
  seg:['Las cinco reglas de oro antes de trabajar: cortar, bloquear, comprobar ausencia de tensión, poner a tierra y en cortocircuito (cuando proceda) y señalizar (RD 614/2001). Los trabajos en tensión solo los hace personal cualificado.','Lan egin aurretik bost urrezko arauak: moztu, blokeatu, tentsiorik ez dagoela egiaztatu, lurrera konektatu eta zirkuitulaburrean jarri (behar denean) eta seinaleztatu (614/2001 ED). Tentsiopeko lanak langile kualifikatuek bakarrik egiten dituzte.']},
 {id:'tubo',cat:'hid',t:['Tubería frigorífica y aislamiento','Hozte-hodiak eta isolamendua'],img:['aislam_1','aislam_0'],
  pri:['Son los «caminos» del refrigerante: tubos de cobre que unen la central con los muebles y las cámaras. La aspiración, que va fría, se aísla con espuma para que no gotee agua ni coja calor por el camino.','Hozgarriaren «bideak» dira: zentrala altzariekin eta ganberekin lotzen duten kobrezko hodiak. Xurgaketa, hotz doana, aparrarekin isolatzen da, urik tantaka ez dezan eta bidean berorik har ez dezan.'],
  pro:['Cobre deshidratado y tapado para refrigeración (EN 12735-1); en CO₂ de alta presión, aleaciones o espesores para esa presión (p. ej., cobre-hierro K65 o acero). Soldadura fuerte con nitrógeno circulando para no formar óxido. El diámetro se elige equilibrando la pérdida de carga y la velocidad mínima para arrastrar el aceite (sobre todo en subidas de aspiración, con sifones). Aislamiento de espuma elastomérica de célula cerrada, con el espesor según la temperatura y la humedad para evitar condensación; juntas pegadas y sin aplastar en los soportes.','Hozte-lanetarako kobre deshidratatua eta tapatua (EN 12735-1); presio altuko CO₂an, presio horretarako aleazioak edo lodierak (adib., K65 kobre-burdina edo altzairua). Soldadura gogorra nitrogenoa zirkulatzen dela, oxidorik sor ez dadin. Diametroa karga-galera eta olioa arrastatzeko gutxieneko abiadura orekatuz aukeratzen da (batez ere xurgaketa-igoeretan, sifoiekin). Gelaxka itxiko apar elastomerikozko isolamendua, lodiera tenperaturaren eta hezetasunaren araberakoa, kondentsazioa saihesteko; juntura itsatsiak eta euskarrietan zapaldu gabe.'],
  fun:['Llevar el refrigerante entre los equipos con pocas pérdidas y, en la aspiración, sin ganar calor ni gotear.','Hozgarria ekipoen artean galera gutxirekin eramatea eta, xurgaketan, berorik irabazi gabe eta tantarik gabe.'],
  como:['Hay tres líneas: descarga (gas caliente), líquido (templado) y aspiración (gas frío). Cada una tiene su diámetro y su aislamiento.','Hiru lerro daude: deskarga (gas beroa), likidoa (epela) eta xurgaketa (gas hotza). Bakoitzak bere diametroa eta isolamendua ditu.'],
  donde:['Por bandejas, falsos techos y patinillos, con soportes cada cierta distancia y con las pendientes hacia la central.','Erretiluetatik, sabai faltsuetatik eta patinilloetatik, distantzia batera euskarriekin eta zentralerantz maldarekin.'],
  con:['Uniones soldadas, abocardados o racores de compresión según el caso; llaves de servicio en los tramos que se aíslan.','Juntura soldatuak, abokardatuak edo konpresio-errakorrak kasuaren arabera; zerbitzu-giltzak isolatzen diren tarteetan.'],
  rel:['Compresores (retorno de aceite), válvulas, recipiente y la calculadora de velocidad y pérdida de carga.','Konpresoreak (olioaren itzulera), balbulak, hartzailea eta abiaduraren eta karga-galeraren kalkulagailua.'],
  ave:[['Fugas en soldaduras, abocardados o roces con soportes.','Ihesak soldaduretan, abokardatuetan edo euskarriekiko marruskaduretan.'],['Aislamiento roto o mojado: gotea, se forma hielo y sube el recalentamiento.','Isolamendua hautsita edo bustita: tantaka ari da, izotza sortzen da eta gainberotzea igotzen da.'],['Aceite atrapado en tramos sin pendiente o sin sifón.','Olioa harrapatuta maldarik edo sifoirik gabeko tarteetan.']],
  chk:[['Prueba de presión con nitrógeno y prueba de estanqueidad antes de cargar.','Presio-proba nitrogenoarekin eta estankotasun-proba kargatu aurretik.'],['Estado del aislamiento y de los soportes.','Isolamenduaren eta euskarrien egoera.'],['Velocidades con la calculadora del Centro técnico.','Abiadurak Zentro teknikoko kalkulagailuarekin.']],
  seg:['Al soldar: nitrógeno con manorreductor, extintor cerca, permiso de trabajos en caliente si lo exige el sitio y nunca soldar un tubo con refrigerante dentro.','Soldatzean: nitrogenoa manoerreduktorearekin, suitzalgailua gertu, beroko lanetarako baimena tokiak eskatzen badu, eta inoiz ez soldatu barruan hozgarria duen hodirik.']},
 {id:'bomba',cat:'hid',t:['Bomba de circulación','Zirkulazio-ponpa'],img:['n_pump_0'],
  pri:['Mueve agua o agua con anticongelante (glicol) por un circuito: por ejemplo, para llevar el calor recuperado a un depósito o para enfriar con un circuito secundario. Su rodete gira y empuja el líquido.','Ura edo izozgarri-uradun ura (glikola) mugitzen du zirkuitu batean zehar: adibidez, berreskuratutako beroa biltegi batera eramateko edo zirkuitu sekundario batekin hozteko. Bere errotorea biratu eta likidoa bultzatzen du.'],
  pro:['Bomba centrífuga: el rodete da velocidad al líquido y la voluta la convierte en presión. Trabaja en el punto donde su curva H-Q corta la curva de la instalación. Hay que evitar la <b>cavitación</b> (NPSH disponible mayor que el requerido): presión suficiente en la aspiración y temperatura lejos de la de ebullición. Con glicol cambian la viscosidad y el calor específico, así que cambian el caudal necesario y la pérdida de carga. Puede llevar variador o motor electrónico para regular el caudal.','Ponpa zentrifugoa: errotoreak abiadura ematen dio likidoari eta bolutak presio bihurtzen du. Bere H-Q kurbak instalazioaren kurba ebakitzen duen puntuan lan egiten du. <b>Kabitazioa</b> saihestu behar da (NPSH erabilgarria behar dena baino handiagoa): presio nahikoa xurgaketan eta tenperatura irakite-tenperaturatik urrun. Glikolarekin biskositatea eta bero espezifikoa aldatzen dira; beraz, behar den emaria eta karga-galera aldatzen dira. Aldagailua edo motor elektronikoa eraman dezake emaria erregulatzeko.'],
  fun:['Hacer circular el fluido secundario o el agua de recuperación con el caudal necesario.','Fluido sekundarioa edo berreskuratze-ura behar den emariarekin zirkularaztea.'],
  como:['El líquido entra por el centro del rodete, sale despedido hacia fuera y la carcasa lo dirige a la salida con presión.','Likidoa errotorearen erdigunetik sartzen da, kanporantz jaurtitzen da eta karkasak presioarekin irteerara bideratzen du.'],
  donde:['En los circuitos de agua o glicol, con válvulas de corte, filtro y vaso de expansión cerca.','Ur- edo glikol-zirkuituetan, itxiera-balbulekin, iragazkiarekin eta hedapen-ontziarekin gertu.'],
  con:['Aspiración y impulsión hidráulicas, alimentación eléctrica, a veces señal de velocidad y alarma.','Xurgaketa eta bultzada hidraulikoak, elikadura elektrikoa, batzuetan abiadura-seinalea eta alarma.'],
  rel:['Intercambiador de placas, depósito, vaso de expansión, interruptor de flujo y la calculadora de bombas.','Plaka-trukagailua, biltegia, hedapen-ontzia, emari-etengailua eta ponpen kalkulagailua.'],
  ave:[['Aire en el circuito: ruido y poco caudal.','Airea zirkuituan: zarata eta emari gutxi.'],['Cavitación: ruido de grava y desgaste del rodete.','Kabitazioa: legar-zarata eta errotorearen higadura.'],['Sentido de giro invertido o rodete bloqueado.','Biratze-noranzkoa alderantziz edo errotorea blokeatuta.'],['Fuga por el cierre mecánico.','Ihesa itxiera mekanikotik.']],
  chk:[['Presión antes y después (altura) y consumo eléctrico.','Presioa aurretik eta ondoren (altuera) eta kontsumo elektrikoa.'],['Salto térmico del intercambiador para estimar el caudal.','Trukagailuaren jauzi termikoa emaria kalkulatzeko.'],['Purgado y presión del circuito.','Zirkuituaren purgatzea eta presioa.']],
  seg:['No hacerla funcionar en seco. Antes de abrirla, cortar tensión, cerrar las válvulas y quitar la presión del tramo.','Ez ibili lehorrean. Ireki aurretik, tentsioa moztu, balbulak itxi eta tarteko presioa kendu.']},
 {id:'phx',cat:'int',t:['Intercambiador de placas','Plaka-trukagailua'],img:['hx_2'],
  pri:['Es un paquete de chapas onduladas muy juntas. Por un lado de cada chapa pasa un fluido y por el otro lado, otro. Así se pasan el calor sin mezclarse. Ocupa muy poco para todo el calor que mueve.','Elkarrengandik oso gertu dauden xafla uhindu sorta bat da. Xafla bakoitzaren alde batetik fluido bat pasatzen da, eta beste aldetik beste bat. Horrela, beroa pasatzen diote elkarri nahastu gabe. Oso leku gutxi hartzen du mugitzen duen bero guztiarentzat.'],
  pro:['Placas con juntas (desmontables, para agua) o soldadas por soldadura fuerte (para refrigerante). Se conectan a <b>contracorriente</b> para que la aproximación de temperaturas sea pequeña. Usos: evaporador de enfriadoras de glicol, condensador por agua, recuperación de calor y subenfriador. Como evaporador, el lado de agua o glicol puede <b>congelarse</b> y romper las placas: interruptor de flujo, protección antihielo por temperatura o presión y concentración de glicol suficiente. La suciedad aumenta la aproximación y la pérdida de carga.','Junturadun plakak (desmuntagarriak, urerako) edo soldadura gogorrez soldatuak (hozgarrirako). <b>Kontrakorrontean</b> konektatzen dira, tenperatura-hurbilketa txikia izan dadin. Erabilerak: glikol-hozgailuen lurrungailua, urezko kondentsadorea, bero-berreskurapena eta azpihozgailua. Lurrungailu gisa, ur- edo glikol-aldea <b>izoztu</b> eta plakak hautsi daitezke: emari-etengailua, izotzaren aurkako babesa tenperaturagatik edo presioagatik, eta glikol-kontzentrazio nahikoa. Zikinkeriak hurbilketa eta karga-galera handitzen ditu.'],
  fun:['Pasar el calor de un fluido a otro sin que se mezclen.','Beroa fluido batetik bestera pasatzea nahastu gabe.'],
  como:['Los dos fluidos van por canales alternos entre las placas, normalmente en sentidos contrarios.','Bi fluidoak plaken arteko kanal txandakatuetatik doaz, normalean aurkako noranzkoetan.'],
  donde:['En la sala de máquinas: en la descarga (recuperación de calor), en la línea de líquido (subenfriador) o en el circuito secundario.','Makina-gelan: deskargan (bero-berreskurapena), likido-lerroan (azpihozgailua) edo zirkuitu sekundarioan.'],
  con:['Cuatro conexiones: entrada y salida de cada fluido, señaladas en la placa de características.','Lau konexio: fluido bakoitzaren sarrera eta irteera, ezaugarri-plakan adierazita.'],
  rel:['Bomba, interruptor de flujo, válvulas de tres vías, sondas de temperatura y depósito de inercia.','Ponpa, emari-etengailua, hiru bideko balbulak, tenperatura-zundak eta inertzia-biltegia.'],
  ave:[['Congelación por falta de caudal o poco glicol.','Izoztea emari faltagatik edo glikol gutxigatik.'],['Ensuciamiento: rinde menos y pierde más presión.','Zikintzea: gutxiago errenditzen du eta presio gehiago galtzen du.'],['Fuga interna (se mezclan los fluidos): aparece refrigerante en el agua o agua en el circuito.','Barne-ihesa (fluidoak nahasten dira): hozgarria agertzen da uretan edo ura zirkuituan.']],
  chk:[['Temperaturas de entrada y salida de los dos fluidos (aproximación).','Bi fluidoen sarrera- eta irteera-tenperaturak (hurbilketa).'],['Pérdida de carga del lado de agua frente a la de puesta en marcha.','Ur-aldeko karga-galera abian jartzekoarekin alderatuta.'],['Concentración de glicol con refractómetro.','Glikol-kontzentrazioa errefraktometroarekin.']],
  seg:['El lado de agua puede estar a presión y caliente. En evaporadores, no vaciar el circuito con el compresor en marcha.','Ur-aldea presiopean eta bero egon daiteke. Lurrungailuetan, ez hustu zirkuitua konpresorea martxan dagoela.']}
);

// ===== Biblioteca de componentes · 3.ª parte: tornillo, separador de líquido, regulador de aceite, retención, tres vías, HPV y FGBV =====
COMP.push(
 {id:'tornillo',cat:'comp',t:['Compresor de tornillo','Torloju-konpresorea'],img:['n_screw_0'],
  pri:['Un compresor grande que comprime el gas con dos tornillos que giran engranados. El gas queda atrapado entre las roscas y se va apretando hasta salir por el otro extremo. Se usa en instalaciones grandes e industriales.','Elkarri txertatuta biratzen duten bi torlojurekin gasa konprimitzen duen konpresore handia. Gasa harien artean harrapatuta geratzen da eta estutuz doa beste muturretik atera arte. Instalazio handi eta industrialetan erabiltzen da.'],
  pro:['Rotores macho y hembra con compresión continua y sin válvulas. Tiene una <b>relación de volumen interna (Vi)</b> fija o variable: si no coincide con la relación de presiones real, hay sobrecompresión o subcompresión y baja el rendimiento. La capacidad se regula con una <b>corredera</b> (o con variador). El aceite se inyecta en los rotores para sellar, lubricar y enfriar, por eso necesita un separador de aceite grande y, a menudo, enfriador de aceite. Puede llevar <b>economizador</b> (aspiración intermedia) para subenfriar el líquido y ganar capacidad.','Errotore arra eta emea, konpresio jarraituarekin eta balbularik gabe. <b>Barne-bolumen erlazio (Vi)</b> finkoa edo aldakorra du: benetako presio-erlazioarekin bat ez badator, gainkonpresioa edo azpikonpresioa dago eta errendimendua jaisten da. Ahalmena <b>irristagailuarekin</b> (edo aldagailuarekin) erregulatzen da. Olioa errotoreetan injektatzen da zigilatzeko, lubrifikatzeko eta hozteko; horregatik olio-bereizgailu handia eta, askotan, olio-hozgailua behar ditu. <b>Ekonomizagailua</b> (tarteko xurgaketa) eraman dezake likidoa azpihozteko eta ahalmena irabazteko.'],
  fun:['Comprimir grandes caudales de gas de forma continua y con regulación de capacidad.','Gas-emari handiak modu jarraituan konprimitzea, ahalmenaren erregulazioarekin.'],
  como:['Al girar, el espacio entre los lóbulos de los rotores se llena de gas por la aspiración y se va reduciendo hasta la lumbrera de descarga.','Biratzean, errotoreen lobuluen arteko espazioa gasez betetzen da xurgaketatik eta txikituz doa deskarga-leihoraino.'],
  donde:['En salas de máquinas industriales y centrales grandes, sobre una bancada con su separador de aceite.','Makina-gela industrialetan eta zentral handietan, bankada baten gainean bere olio-bereizgailuarekin.'],
  con:['Aspiración, descarga al separador de aceite, inyección y retorno de aceite, economizador (si lo lleva), motor y corredera.','Xurgaketa, deskarga olio-bereizgailura, olio-injekzioa eta -itzulera, ekonomizagailua (badarama), motorra eta irristagailua.'],
  rel:['Separador y enfriador de aceite, filtro de aceite, economizador, variador y controlador.','Olio-bereizgailua eta -hozgailua, olio-iragazkia, ekonomizagailua, aldagailua eta kontrolagailua.'],
  ave:[['Presión diferencial de aceite baja: filtro sucio o bomba.','Olio-presio diferentzial baxua: iragazki zikina edo ponpa.'],['Temperatura de descarga alta por poca inyección de aceite.','Deskarga-tenperatura altua olio-injekzio gutxigatik.'],['Corredera que no se mueve: no regula la capacidad.','Mugitzen ez den irristagailua: ez du ahalmena erregulatzen.'],['Desgaste de rodamientos: ruido y vibraciones.','Errodamenduen higadura: zarata eta bibrazioak.']],
  chk:[['Presión diferencial y temperatura del aceite.','Olioaren presio diferentziala eta tenperatura.'],['Posición de la corredera frente a la carga.','Irristagailuaren posizioa kargarekin alderatuta.'],['Vibraciones y análisis de aceite periódico.','Bibrazioak eta aldizkako olio-analisia.']],
  seg:['Equipo grande con mucho aceite caliente a presión: aislar, despresurizar y dejar enfriar antes de abrir. Bloquear el motor.','Ekipo handia, presiopeko olio bero askorekin: isolatu, presioa kendu eta hozten utzi ireki aurretik. Motorra blokeatu.']},
 {id:'seplic',cat:'lin',t:['Separador de líquido de aspiración','Xurgaketako likido-bereizgailua'],img:[],
  pri:['Un depósito en la tubería de aspiración que retiene el refrigerante líquido que pueda volver de los evaporadores, para que no llegue al compresor. Es como un «colador» que deja pasar el gas y se queda el líquido.','Xurgaketa-hodiko biltegi bat, lurrungailuetatik itzul daitekeen hozgarri likidoa atxikitzen duena, konpresorera irits ez dadin. Gasa pasatzen uzten duen eta likidoa gordetzen duen «iragazki» bat bezalakoa da.'],
  pro:['En equipos de expansión directa es el <b>acumulador de aspiración</b>: el gas sale por un tubo en U con un pequeño orificio que devuelve el aceite y una cantidad dosificada de líquido. Se elige por caudal y temperatura de evaporación. En instalaciones industriales (amoníaco, CO₂ bombeado) el <b>separador de líquido</b> es un recipiente grande que alimenta los evaporadores inundados por gravedad o con bomba, y de su parte alta aspiran los compresores.','Espantsio zuzeneko ekipoetan <b>xurgaketa-metagailua</b> da: gasa U formako hodi batetik ateratzen da, olioa eta likido-kopuru dosifikatu bat itzultzen dituen orifizio txiki batekin. Emariaren eta lurruntze-tenperaturaren arabera aukeratzen da. Instalazio industrialetan (amoniakoa, CO₂ ponpatua) <b>likido-bereizgailua</b> hartzaile handi bat da, lurrungailu urpekoak grabitatez edo ponparekin elikatzen dituena, eta haren goiko aldetik xurgatzen dute konpresoreek.'],
  fun:['Proteger el compresor del retorno de líquido.','Konpresorea likido-itzuleratik babestea.'],
  como:['El líquido cae al fondo por gravedad al bajar la velocidad; el gas sale por arriba.','Likidoa grabitatez hondora erortzen da abiadura jaistean; gasa goitik ateratzen da.'],
  donde:['En la aspiración, cerca del compresor o del colector de aspiración.','Xurgaketan, konpresoretik edo xurgaketa-kolektoretik gertu.'],
  con:['Entrada y salida de aspiración; en los industriales, salida de líquido a bombas o evaporadores y control de nivel.','Xurgaketaren sarrera eta irteera; industrialetan, likido-irteera ponpetara edo lurrungailuetara eta maila-kontrola.'],
  rel:['Compresores, válvulas de expansión y, en desescarches por gas caliente, el retorno de líquido.','Konpresoreak, hedapen-balbulak eta, gas beroko izotz-kentzeetan, likido-itzulera.'],
  ave:[['Orificio de retorno de aceite obstruido: el aceite se queda dentro.','Olio-itzulerako orifizioa buxatuta: olioa barruan geratzen da.'],['Lleno de líquido por un fallo continuo de las válvulas.','Likidoz beteta balbulen etengabeko akats batengatik.']],
  chk:[['Escarcha en el separador y en la aspiración del compresor.','Izarra bereizgailuan eta konpresorearen xurgaketan.'],['Recalentamiento a la entrada del compresor.','Gainberotzea konpresorearen sarreran.']],
  seg:['Recipiente a presión: no taponar su válvula de seguridad (si la lleva) ni dejarlo aislado lleno de líquido.','Presiopeko hartzailea: ez tapatu bere segurtasun-balbula (badarama) eta ez utzi isolatuta likidoz beteta.']},
 {id:'regoil',cat:'lin',t:['Regulador de nivel de aceite','Olio-mailaren erregulatzailea'],img:[],
  pri:['En una central con varios compresores, cada uno tiene en el cárter un aparato que vigila el nivel de aceite y lo rellena desde un depósito común cuando baja.','Hainbat konpresoredun zentral batean, bakoitzak karterrean olio-maila zaintzen duen eta jaisten denean biltegi komun batetik betetzen duen aparatu bat du.'],
  pro:['Mecánico (flotador) o electrónico (sensor óptico o capacitivo con solenoide y contacto de alarma). Recibe el aceite del depósito, que está a una presión algo mayor que el cárter (válvula diferencial, del orden de 1-2 bar sobre la aspiración según el sistema). Si no consigue recuperar el nivel en el tiempo ajustado, abre el contacto y para el compresor. En CO₂ se usan versiones para alta presión.','Mekanikoa (flotagailua) edo elektronikoa (sentsore optiko edo kapazitiboa, solenoidearekin eta alarma-kontaktuarekin). Olioa biltegitik jasotzen du, karterra baino presio pixka bat handiagoan dagoena (balbula diferentziala, sistemaren arabera 1-2 bar ingurukoa xurgaketaren gainetik). Doitutako denboran maila berreskuratzen ez badu, kontaktua ireki eta konpresorea gelditzen du. CO₂an presio altuko bertsioak erabiltzen dira.'],
  fun:['Mantener el nivel correcto de aceite en cada compresor de la central.','Zentraleko konpresore bakoitzean olio-maila zuzena mantentzea.'],
  como:['Cuando el nivel baja del punto de consigna, abre la entrada de aceite; cuando sube, la cierra.','Maila kontsigna-puntutik jaisten denean, olio-sarrera irekitzen du; igotzen denean, ixten du.'],
  donde:['Atornillado en el visor del cárter de cada compresor.','Konpresore bakoitzaren karterreko ikusgailuan torlojututa.'],
  con:['Entrada de aceite desde el depósito, alimentación eléctrica y contacto de alarma al controlador.','Olio-sarrera biltegitik, elikadura elektrikoa eta alarma-kontaktua kontrolagailura.'],
  rel:['Separador de aceite, depósito de aceite, válvula diferencial y controlador de la central.','Olio-bereizgailua, olio-biltegia, balbula diferentziala eta zentralaren kontrolagailua.'],
  ave:[['Alarma de nivel: falta aceite en el sistema o el aceite se queda en la instalación.','Maila-alarma: olioa falta da sisteman edo olioa instalazioan geratzen da.'],['Filtro de entrada obstruido.','Sarrerako iragazkia buxatuta.'],['Sensor sucio que da falsas alarmas.','Alarma faltsuak ematen dituen sentsore zikina.']],
  chk:[['Nivel del depósito de aceite.','Olio-biltegiaren maila.'],['Presión diferencial del depósito sobre la aspiración.','Biltegiaren presio diferentziala xurgaketaren gainetik.'],['Que el contacto de alarma pare el compresor.','Alarma-kontaktuak konpresorea gelditzen duela.']],
  seg:['El aceite está a presión: aislar y despresurizar antes de desmontarlo.','Olioa presiopean dago: isolatu eta presioa kendu desmuntatu aurretik.']},
 {id:'retencion',cat:'lin',t:['Válvula de retención (antirretorno)','Atzera-ezineko balbula'],img:[],
  pri:['Una válvula que deja pasar el refrigerante en un solo sentido. Si intenta volver hacia atrás, se cierra sola.','Hozgarria norabide bakarrean pasatzen uzten duen balbula. Atzera itzultzen saiatzen bada, bakarrik ixten da.'],
  pro:['Un muelle o el propio peso mantienen el obturador cerrado; abre con una diferencia de presión mínima. Usos típicos: descarga de cada compresor en paralelo (que no condense refrigerante en el compresor parado), salida del condensador cuando hay recuperación de calor, líneas de desescarche por gas caliente. Se monta con la flecha en el sentido del flujo y bien dimensionada: sobredimensionada vibra y golpetea.','Malguki batek edo pisuak berak obturadorea itxita mantentzen du; gutxieneko presio-alde batekin irekitzen da. Ohiko erabilerak: paraleloko konpresore bakoitzaren deskarga (geldirik dagoen konpresorean hozgarria kondentsa ez dadin), kondentsadorearen irteera bero-berreskurapena dagoenean, gas beroko izotz-kentze lerroak. Gezia fluxuaren noranzkoan duela muntatzen da eta ondo dimentsionatuta: neurriz gainekoa bada, bibratu eta kolpeka egiten du.'],
  fun:['Impedir que el refrigerante circule al revés.','Hozgarria alderantziz zirkula dadin eragoztea.'],
  como:['El flujo empuja el obturador y abre; si el flujo se invierte, el obturador vuelve a su asiento.','Fluxuak obturadorea bultzatu eta irekitzen du; fluxua alderantzikatzen bada, obturadorea bere eserlekura itzultzen da.'],
  donde:['En la descarga de cada compresor, a la salida del condensador y en las líneas de desescarche.','Konpresore bakoitzaren deskargan, kondentsadorearen irteeran eta izotz-kentze lerroetan.'],
  con:['Soldada o roscada en línea, respetando la flecha.','Lerroan soldatua edo harilkatua, gezia errespetatuz.'],
  rel:['Compresores, separador de aceite, condensador y recuperador de calor.','Konpresoreak, olio-bereizgailua, kondentsadorea eta bero-berreskuragailua.'],
  ave:[['No cierra (suciedad en el asiento): pasa refrigerante hacia atrás.','Ez da ixten (zikinkeria eserlekuan): hozgarria atzerantz pasatzen da.'],['Golpeteo por estar sobredimensionada.','Kolpeak neurriz gainekoa delako.'],['Montada al revés: bloquea el paso.','Alderantziz muntatuta: pasabidea blokeatzen du.']],
  chk:[['Temperatura a ambos lados con el compresor parado.','Tenperatura bi aldeetan konpresorea geldituta dagoela.'],['Ruido de golpeteo en marcha.','Kolpe-zarata martxan.']],
  seg:['En la descarga trabaja caliente y a alta presión: no tocar sin protección.','Deskargan bero eta presio altuan lan egiten du: ez ukitu babesik gabe.']},
 {id:'tresvias',cat:'exp',t:['Válvula de tres vías','Hiru bideko balbula'],img:[],
  pri:['Una válvula con una entrada y dos salidas (o dos entradas y una salida). Sirve para mandar el refrigerante o el agua por un camino o por otro.','Sarrera bat eta bi irteera (edo bi sarrera eta irteera bat) dituen balbula. Hozgarria edo ura bide batetik edo bestetik bidaltzeko balio du.'],
  pro:['En refrigeración se usa para la <b>recuperación de calor</b> (desvía la descarga al recuperador antes que al condensador) y en el desescarche por gas caliente. En circuitos de agua o glicol hay de mezcla y de desvío, con actuador todo/nada o modulante (0-10 V) gobernado por el controlador según una temperatura. Se elige por Kv, presión de trabajo y tipo de fluido.','Hozte-lanetan <b>bero-berreskurapenerako</b> erabiltzen da (deskarga berreskuragailura desbideratzen du kondentsadorera baino lehen) eta gas beroko izotz-kentzean. Ur- edo glikol-zirkuituetan nahastekoak eta desbideratzekoak daude, dena/ezer edo modulatzailea den eragingailuarekin (0-10 V), kontrolagailuak tenperatura baten arabera agintzen duena. Kv-aren, lan-presioaren eta fluido motaren arabera aukeratzen da.'],
  fun:['Desviar o mezclar caudales según lo que pida el control.','Emariak desbideratzea edo nahastea kontrolak eskatzen duenaren arabera.'],
  como:['El obturador o la bola abre un paso y cierra el otro, o los reparte en proporción.','Obturadoreak edo bolak bide bat ireki eta bestea ixten du, edo proportzioan banatzen ditu.'],
  donde:['En la descarga de la central (recuperación de calor) o en circuitos de agua y glicol.','Zentralaren deskargan (bero-berreskurapena) edo ur- eta glikol-zirkuituetan.'],
  con:['Tres conexiones marcadas (A, B, AB) y el actuador eléctrico.','Markatutako hiru konexio (A, B, AB) eta eragingailu elektrikoa.'],
  rel:['Recuperador de calor, condensador, controlador y sondas de temperatura.','Bero-berreskuragailua, kondentsadorea, kontrolagailua eta tenperatura-zundak.'],
  ave:[['Actuador averiado: se queda en una posición.','Eragingailua matxuratuta: posizio batean geratzen da.'],['Fuga interna: pasa por las dos vías a la vez.','Barne-ihesa: bi bideetatik pasatzen da batera.']],
  chk:[['Señal de mando y posición real del actuador.','Agindu-seinalea eta eragingailuaren benetako posizioa.'],['Temperaturas en las dos salidas.','Tenperaturak bi irteeretan.']],
  seg:['Cortar tensión al actuador antes de desmontarlo; la línea de descarga quema.','Eragingailuari tentsioa moztu desmuntatu aurretik; deskarga-lerroak erre egiten du.']},
 {id:'hpvc',cat:'exp',t:['HPV: válvula de alta presión (CO₂)','HPV: presio altuko balbula (CO₂)'],img:[],
  pri:['En una central de CO₂, es la válvula que hay entre el gas cooler y el depósito. Decide a qué presión trabaja el gas cooler y deja pasar el CO₂ al depósito.','CO₂ zentral batean, gas-hozgailuaren eta biltegiaren artean dagoen balbula da. Gas-hozgailuak zein presiotan lan egiten duen erabakitzen du eta CO₂-a biltegira pasatzen uzten du.'],
  pro:['Válvula motorizada (paso a paso) que, en régimen transcrítico, mantiene la presión óptima del gas cooler calculada por el controlador a partir de la temperatura de salida del gas cooler; en subcrítico mantiene un subenfriamiento mínimo. Expande a la presión del depósito (unos 35 bar). Puede ir con eyectores en paralelo. Una HPV que falla abierta baja demasiado la presión de alta y dispara el gas flash; cerrada, sube la alta hasta las seguridades.','Balbula motorizatua (urrats-motorra), erregimen transkritikoan kontrolagailuak gas-hozgailuaren irteerako tenperaturatik kalkulatutako presio optimoa mantentzen duena; azpikritikoan gutxieneko azpihoztea mantentzen du. Biltegiaren presiora hedatzen du (35 bar inguru). Eiektoreekin paraleloan joan daiteke. Irekita huts egiten duen HPV batek altuko presioa gehiegi jaisten du eta gas flasha igotzen du; itxita, altua segurtasunetaraino igotzen du.'],
  fun:['Controlar la presión del gas cooler para que el CO₂ rinda lo mejor posible.','Gas-hozgailuaren presioa kontrolatzea, CO₂-ak ahalik eta hobekien errendi dezan.'],
  como:['El controlador mide presión y temperatura a la salida del gas cooler y abre o cierra la válvula para llegar a la presión calculada.','Kontrolagailuak gas-hozgailuaren irteerako presioa eta tenperatura neurtzen ditu eta balbula ireki edo ixten du kalkulatutako presiora iristeko.'],
  donde:['Después del gas cooler, antes del depósito de media presión.','Gas-hozgailuaren ondoren, presio ertaineko biltegiaren aurretik.'],
  con:['Entrada desde el gas cooler, salida al depósito y cable del motor al controlador.','Sarrera gas-hozgailutik, irteera biltegira eta motorraren kablea kontrolagailura.'],
  rel:['Gas cooler, depósito, FGBV, transductor de alta y sonda de salida del gas cooler.','Gas-hozgailua, biltegia, FGBV, altuko transduktorea eta gas-hozgailuaren irteerako zunda.'],
  ave:[['Agarrotada abierta: alta baja, mucho gas flash, la positiva no llega con calor.','Irekita trabatuta: altua baxua, gas flash asko, positiboa ez da iristen beroarekin.'],['Agarrotada cerrada: la alta sube hasta el presostato o la válvula de seguridad.','Itxita trabatuta: altua presostatoraino edo segurtasun-balbularaino igotzen da.'],['Sonda o transductor que leen mal.','Gaizki irakurtzen duten zunda edo transduktorea.']],
  chk:[['Apertura de la HPV frente a la presión pedida.','HPVren irekiera eskatutako presioarekin alderatuta.'],['Presión y temperatura a la salida del gas cooler.','Presioa eta tenperatura gas-hozgailuaren irteeran.']],
  seg:['Trabaja a más de 90 bar: nunca abrir sin aislar y despresurizar el tramo, y sin dejar CO₂ líquido atrapado.','90 bar-etik gora lan egiten du: inoiz ez ireki tartea isolatu eta presioa kendu gabe, eta CO₂ likidorik harrapatuta utzi gabe.']},
 {id:'fgbvc',cat:'exp',t:['FGBV: válvula de gas flash (CO₂)','FGBV: gas flash balbula (CO₂)'],img:[],
  pri:['En una central de CO₂, es la válvula que saca el gas que sobra del depósito y lo manda a la aspiración, para que el depósito no suba de presión.','CO₂ zentral batean, biltegitik soberan dagoen gasa atera eta xurgaketara bidaltzen duen balbula da, biltegiaren presioa igo ez dadin.'],
  pro:['Regula la presión del depósito de media presión (≈ 35 bar) enviando el gas flash a la aspiración de positiva. En centrales con compresor de gas flash (paralelo), ese compresor aspira directamente del depósito y la FGBV queda de apoyo. Si se agarrota cerrada, el depósito sube hasta su válvula de seguridad y llega gas a la línea de líquido; abierta, el depósito baja y puede faltar diferencia de presión para las válvulas de los muebles.','Presio ertaineko biltegiaren presioa erregulatzen du (≈ 35 bar), gas flasha positiboko xurgaketara bidaliz. Gas flasheko konpresorea (paraleloa) duten zentraletan, konpresore horrek biltegitik zuzenean xurgatzen du eta FGBV laguntza gisa geratzen da. Itxita trabatzen bada, biltegia bere segurtasun-balbularaino igotzen da eta gasa iristen da likido-lerrora; irekita, biltegia jaisten da eta altzarien balbuletarako presio-aldea falta daiteke.'],
  fun:['Mantener constante la presión del depósito de CO₂.','CO₂ biltegiaren presioa konstante mantentzea.'],
  como:['Mide la presión del depósito y abre más cuando sube por encima de la consigna.','Biltegiaren presioa neurtzen du eta kontsignaren gainetik igotzen denean gehiago irekitzen du.'],
  donde:['En la parte alta del depósito de media presión, hacia la aspiración de positiva.','Presio ertaineko biltegiaren goiko aldean, positiboko xurgaketarantz.'],
  con:['Entrada del gas del depósito, salida a la aspiración MT y motor al controlador.','Biltegiko gasaren sarrera, irteera MT xurgaketara eta motorra kontrolagailura.'],
  rel:['Depósito, HPV, compresores de positiva o de gas flash y válvula de seguridad del depósito.','Biltegia, HPV, positiboko edo gas flasheko konpresoreak eta biltegiaren segurtasun-balbula.'],
  ave:[['Agarrotada cerrada: alarma de presión en el depósito.','Itxita trabatuta: presio-alarma biltegian.'],['Agarrotada abierta: depósito demasiado bajo.','Irekita trabatuta: biltegia baxuegi.']],
  chk:[['Presión del depósito frente a la consigna.','Biltegiaren presioa kontsignarekin alderatuta.'],['Grado de apertura de la FGBV.','FGBVren irekiera-maila.']],
  seg:['Aislar y despresurizar antes de tocarla; el CO₂ que sale enfría mucho y desplaza el oxígeno.','Ukitu aurretik isolatu eta presioa kendu; ateratzen den CO₂-ak asko hozten du eta oxigenoa desplazatzen du.']}
);

// ===== Centro técnico · Averías en 9 pasos (etapa 4) =====
// Cada avería sigue el mismo método: 1 descripción · 2 síntomas · 3 posibles causas · 4 mediciones · 5 comprobaciones ·
// 6 interpretación · 7 diagnóstico (lo elige el alumno) · 8 solución · 9 comprobación final. Enseña a descartar causas con datos.
// Valores orientativos (se indica): dependen de la instalación, del refrigerante y de las condiciones.
const AV=[
 {id:'low',les:'a1',t:['Falta de refrigerante (fuga)','Hozgarri falta (ihesa)'],
  d:['Una central que antes enfriaba bien ahora no llega a temperatura en varios servicios y los compresores no paran.','Lehen ondo hozten zuen zentral batek orain ez du tenperatura lortzen zenbait zerbitzutan, eta konpresoreak ez dira gelditzen.'],
  sin:[['Varios muebles o cámaras por encima de su consigna.','Hainbat altzari edo ganbera beren kontsignatik gora.'],['Burbujas en el visor de líquido.','Burbuilak likido-ikusgailuan.'],['Nivel bajo en el recipiente.','Maila baxua hartzailean.'],['Compresores casi siempre en marcha.','Konpresoreak ia beti martxan.']],
  cau:[[['Fuga de refrigerante','Hozgarri-ihesa'],['Sube el recalentamiento en TODOS los servicios, el recipiente está bajo y el subenfriamiento es casi cero.','Gainberotzea zerbitzu GUZTIETAN igotzen da, hartzailea baxu dago eta azpihoztea ia zero da.']],
       [['Filtro deshidratador obstruido','Iragazki lehorgailua buxatuta'],['También da burbujas, pero el recipiente está lleno y la salida del filtro está más fría que la entrada.','Burbuilak ere ematen ditu, baina hartzailea beteta dago eta iragazkiaren irteera sarrera baino hotzago dago.']],
       [['Una válvula de expansión obstruida','Hedapen-balbula bat buxatuta'],['Solo afecta a UN servicio; los demás van bien y no hay burbujas.','Zerbitzu BAKAR bati eragiten dio; besteak ondo doaz eta ez dago burbuilarik.']],
       [['Demasiada carga térmica (puertas, producto caliente)','Karga termiko gehiegi (ateak, produktu beroa)'],['El recalentamiento es normal y el visor está lleno: el circuito está bien, sobra calor.','Gainberotzea normala da eta ikusgailua beteta dago: zirkuitua ondo dago, beroa soberan dago.']]],ok:0,
  med:[['Recalentamiento de cada servicio (normal orientativo 5-10 K).','Zerbitzu bakoitzaren gainberotzea (normala orientagarri 5-10 K).'],['Subenfriamiento a la salida del condensador o en la línea de líquido.','Azpihoztea kondentsadorearen irteeran edo likido-lerroan.'],['Presión de aspiración y de alta.','Xurgaketa- eta altu-presioa.'],['Temperatura a la entrada y a la salida del filtro.','Tenperatura iragazkiaren sarreran eta irteeran.']],
  chk:[['Nivel del recipiente y visor con la instalación estable.','Hartzailearen maila eta ikusgailua instalazioa egonkor dagoenean.'],['Buscar restos de aceite en uniones, válvulas y evaporadores.','Olio-arrastoak bilatu junturetan, balbuletan eta lurrungailuetan.'],['Detector electrónico de fugas o espuma en los puntos sospechosos.','Ihes-detektagailu elektronikoa edo aparra puntu susmagarrietan.'],['Registro de cargas en el libro de la instalación.','Instalazioaren liburuko karga-erregistroa.']],
  int:{pri:['Si todos los muebles tienen el recalentamiento alto y el recipiente está bajo, al circuito le falta refrigerante. Si solo fallara un mueble, el problema estaría en ese mueble.','Altzari guztiek gainberotze altua badute eta hartzailea baxu badago, zirkuituari hozgarria falta zaio. Altzari bakar batek huts egingo balu, arazoa altzari horretan legoke.'],
       pro:['Recalentamiento alto generalizado + SC ≈ 0 + recipiente bajo = falta de masa en el lado de alta. El filtro queda descartado porque no hay ΔT entre su entrada y salida. Una sola válvula no explica que fallen todos los servicios. La carga térmica tampoco: con exceso de carga el SH sería normal y el visor estaría lleno.','Gainberotze altu orokortua + SC ≈ 0 + hartzaile baxua = masa falta altuko aldean. Iragazkia baztertuta geratzen da, ez baitago ΔT-rik bere sarreraren eta irteeraren artean. Balbula bakar batek ez du azaltzen zerbitzu guztiek huts egitea. Karga termikoak ere ez: karga gehiegirekin SH normala litzateke eta ikusgailua beteta egongo litzateke.']},
  dia:['Falta de refrigerante por una fuga.','Hozgarri falta ihes batengatik.'],
  sol:[['Localizar la fuga (no basta con rellenar).','Ihesa aurkitu (ez da nahikoa betetzea).'],['Aislar y recuperar el tramo, reparar y cambiar el filtro.','Tartea isolatu eta berreskuratu, konpondu eta iragazkia aldatu.'],['Prueba de presión con nitrógeno, vacío y carga por peso.','Presio-proba nitrogenoarekin, hutsa eta karga pisuz.'],['Anotar la fuga, la reparación y la carga en el registro (Reglamento UE 2024/573).','Ihesa, konponketa eta karga erregistroan idatzi (2024/573 EB Erregelamendua).']],
  fin:[['Visor lleno y nivel normal en el recipiente.','Ikusgailua beteta eta maila normala hartzailean.'],['Recalentamientos y subenfriamiento normales.','Gainberotzeak eta azpihoztea normalak.'],['Todos los servicios en consigna.','Zerbitzu guztiak kontsignan.'],['Control de fugas del punto reparado tras la puesta en marcha (en el plazo que fija el reglamento).','Konpondutako puntuaren ihes-kontrola abian jarri ondoren (araudiak finkatzen duen epean).']]},
 {id:'cond',les:'a2',t:['Alta presión elevada (condensador o gas cooler sucio)','Presio altu handia (kondentsadore edo gas-hozgailu zikina)'],
  d:['En verano salta el presostato de alta y la factura eléctrica ha subido mucho.','Udan altuko presostatoak jauzi egiten du eta elektrizitate-faktura asko igo da.'],
  sin:[['Alta presión muy elevada para la temperatura exterior.','Presio altua oso handia kanpoko tenperaturarako.'],['Disparos del presostato de alta en las horas de calor.','Altuko presostatoaren jauziak bero-orduetan.'],['Más consumo eléctrico.','Kontsumo elektriko handiagoa.']],
  cau:[[['Condensador sucio','Kondentsadorea zikin'],['Los ventiladores giran bien, pero el salto condensación-aire es muy grande y las aletas están tapadas.','Haizagailuak ondo dabiltza, baina kondentsazio-aire jauzia oso handia da eta hegalak tapatuta daude.']],
       [['Ventilador del condensador parado','Kondentsadorearen haizagailua geldituta'],['Se ve o se mide: un ventilador no gira o no consume.','Ikusten edo neurtzen da: haizagailu batek ez du biratzen edo ez du kontsumitzen.']],
       [['Incondensables (aire) en el circuito','Kondentsaezinak (airea) zirkuituan'],['El condensador está limpio y los ventiladores bien, pero la presión sigue alta; con la central parada, la presión no coincide con la temperatura.','Kondentsadorea garbi dago eta haizagailuak ondo, baina presioak altua jarraitzen du; zentrala geldituta, presioa ez dator bat tenperaturarekin.']],
       [['Exceso de carga de refrigerante','Hozgarri-karga gehiegi'],['El subenfriamiento es muy alto y el recipiente está casi lleno.','Azpihoztea oso altua da eta hartzailea ia beteta dago.']]],ok:0,
  med:[['Temperatura del aire a la entrada del condensador.','Airearen tenperatura kondentsadorearen sarreran.'],['Presión de alta y su temperatura de condensación.','Altu-presioa eta haren kondentsazio-tenperatura.'],['Subenfriamiento.','Azpihoztea.'],['Consumo de cada ventilador.','Haizagailu bakoitzaren kontsumoa.']],
  chk:[['Mirar las aletas con una linterna.','Hegalak linterna batekin begiratu.'],['Comprobar que giran todos los ventiladores y en su sentido.','Haizagailu guztiak eta beren noranzkoan biratzen direla egiaztatu.'],['Que no haya recirculación de aire caliente ni obstáculos.','Aire beroaren birzirkulaziorik edo oztoporik ez egotea.']],
  int:{pri:['Si el ventilador gira y el condensador está sucio, el aire no puede llevarse el calor. La presión sube porque el gas no consigue enfriarse.','Haizagailuak biratzen badu eta kondentsadorea zikin badago, aireak ezin du beroa eraman. Presioa igo egiten da gasak ezin duelako hoztu.'],
       pro:['Salto condensación-aire de entrada muy por encima del de diseño (8-15 K orientativo) con todos los ventiladores en marcha = transmisión de calor reducida. Con un SC normal se descarta el exceso de carga, y la suciedad visible apunta al condensador. Los incondensables se valorarían con el condensador limpio: presión de parada mayor que la de saturación a la temperatura del refrigerante.','Kondentsazio-sarrerako aire jauzia diseinukoa baino askoz handiagoa (8-15 K orientagarri), haizagailu guztiak martxan = bero-transmisio murriztua. SC normalarekin karga gehiegia baztertzen da, eta zikinkeria ikusgarriak kondentsadorea seinalatzen du. Kondentsaezinak kondentsadorea garbi dagoela baloratuko lirateke: geldialdiko presioa hozgarriaren tenperaturako asetasun-presioa baino handiagoa.']},
  dia:['Condensador (o gas cooler) sucio.','Kondentsadore (edo gas-hozgailu) zikina.'],
  sol:[['Cortar tensión a los ventiladores y bloquear.','Haizagailuei tentsioa moztu eta blokeatu.'],['Limpiar con aire o agua a baja presión desde el lado de salida del aire; enderezar aletas.','Aire edo ur presio baxuarekin garbitu airearen irteerako aldetik; hegalak zuzendu.'],['Revisar la regulación de ventiladores.','Haizagailuen erregulazioa berrikusi.']],
  fin:[['Salto condensación-aire de vuelta a lo normal.','Kondentsazio-aire jauzia normalera itzulita.'],['Sin disparos de alta en las horas de calor.','Altuko jauzirik ez bero-orduetan.'],['Consumo de compresores más bajo.','Konpresoreen kontsumo baxuagoa.']]},
 {id:'fan',les:'a4',t:['Un servicio no enfría: ventilador del evaporador parado','Zerbitzu batek ez du hozten: lurrungailuaren haizagailua geldituta'],
  d:['Una cámara no baja de temperatura aunque el termostato pide frío. Los demás servicios van bien.','Ganbera batek ez du tenperatura jaisten, termostatoak hotza eskatzen badu ere. Gainerako zerbitzuak ondo doaz.'],
  sin:[['La cámara está por encima de la consigna.','Ganbera kontsignatik gora dago.'],['El evaporador está muy escarchado.','Lurrungailua oso izarreztatuta dago.'],['No se nota el aire saliendo del evaporador.','Ez da nabaritzen airea lurrungailutik ateratzen.']],
  cau:[[['Ventilador del evaporador parado','Lurrungailuaren haizagailua geldituta'],['La solenoide abre y llega refrigerante, pero no se mueve el aire: el recalentamiento es bajo y el evaporador se hiela.','Solenoideak irekitzen du eta hozgarria iristen da, baina airea ez da mugitzen: gainberotzea baxua da eta lurrungailua izozten da.']],
       [['Solenoide que no abre','Ireki ez den solenoidea'],['No llegaría refrigerante: el evaporador estaría caliente, sin escarcha, y el recalentamiento sería muy alto.','Ez litzateke hozgarririk iritsiko: lurrungailua bero egongo litzateke, izarrik gabe, eta gainberotzea oso altua izango litzateke.']],
       [['Válvula de expansión obstruida','Hedapen-balbula buxatuta'],['Recalentamiento muy alto y evaporación muy baja, con el ventilador girando.','Gainberotze oso altua eta lurruntze oso baxua, haizagailua biraka dagoela.']],
       [['Falta de refrigerante','Hozgarri falta'],['Afectaría a todos los servicios, no solo a uno.','Zerbitzu guztiei eragingo lieke, ez bakarrari.']]],ok:0,
  med:[['Recalentamiento a la salida del evaporador.','Gainberotzea lurrungailuaren irteeran.'],['Tensión en los bornes del ventilador.','Tentsioa haizagailuaren borneetan.'],['Consumo del motor del ventilador.','Haizagailuaren motorraren kontsumoa.']],
  chk:[['Mirar si el ventilador gira.','Haizagailuak biratzen duen begiratu.'],['Parámetros del termostato que paran los ventiladores (retardo tras desescarche, puerta abierta, temperatura de evaporador).','Haizagailuak gelditzen dituzten termostatoaren parametroak (izotz-kentzearen ondoko atzerapena, atea irekita, lurrungailuaren tenperatura).'],['Que el ventilador no esté bloqueado por hielo.','Haizagailua izotzak blokeatuta ez egotea.']],
  int:{pri:['Llega frío al evaporador (está helado), pero como el aire no pasa, el frío no llega a la cámara. El fallo está en el ventilador, no en el refrigerante.','Hotza lurrungailura iristen da (izoztuta dago), baina airea pasatzen ez denez, hotza ez da ganberara iristen. Akatsa haizagailuan dago, ez hozgarrian.'],
       pro:['SH bajo con el evaporador escarchado indica refrigerante de sobra y poco intercambio por el lado del aire. Eso descarta la solenoide, la válvula y la falta de carga, que darían SH alto. Si hay tensión en los bornes y el motor no consume ni gira, el motor está averiado. Si no hay tensión, revisar el relé del termostato y sus parámetros.','SH baxua lurrungailua izarreztatuta dagoela: hozgarria soberan dago eta aire-aldeko trukea txikia da. Horrek solenoidea, balbula eta karga falta baztertzen ditu, SH altua emango luketelako. Borneetan tentsioa badago eta motorrak ez badu kontsumitzen ezta biratzen ere, motorra matxuratuta dago. Tentsiorik ez badago, berrikusi termostatoaren errelea eta bere parametroak.']},
  dia:['Ventilador del evaporador parado.','Lurrungailuaren haizagailua geldituta.'],
  sol:[['Sin tensión: cambiar el motor del ventilador o reparar su alimentación.','Tentsiorik gabe: haizagailuaren motorra aldatu edo bere elikadura konpondu.'],['Hacer un desescarche manual para quitar el hielo.','Eskuzko izotz-kentzea egin izotza kentzeko.']],
  fin:[['El ventilador gira y el aire sale frío.','Haizagailuak biratzen du eta airea hotz ateratzen da.'],['Recalentamiento de nuevo en su valor.','Gainberotzea berriro bere balioan.'],['La cámara llega a consigna.','Ganbera kontsignara iristen da.']]},
 {id:'filt',les:'a13',t:['Burbujas con el recipiente lleno: filtro obstruido','Burbuilak hartzailea beteta: iragazkia buxatuta'],
  d:['Todos los muebles enfrían algo peor y aparecen burbujas en el visor, pero el recipiente tiene buen nivel.','Altzari guztiek okerrago hozten dute eta burbuilak agertzen dira ikusgailuan, baina hartzaileak maila ona du.'],
  sin:[['Burbujas en el visor.','Burbuilak ikusgailuan.'],['Recalentamiento algo alto en todos los servicios.','Gainberotze altu samarra zerbitzu guztietan.'],['El filtro está frío o escarchado a la salida.','Iragazkia hotz edo izarreztatuta dago irteeran.']],
  cau:[[['Filtro deshidratador obstruido','Iragazki lehorgailua buxatuta'],['Hay diferencia de temperatura entre su entrada y su salida y el recipiente está lleno.','Tenperatura-aldea dago bere sarreraren eta irteeraren artean, eta hartzailea beteta dago.']],
       [['Falta de refrigerante','Hozgarri falta'],['El recipiente estaría bajo.','Hartzailea baxu egongo litzateke.']],
       [['Llave de líquido medio cerrada','Likido-giltza erdi itxita'],['Daría el mismo efecto, pero el salto de temperatura estaría en la llave, no en el filtro.','Efektu bera emango luke, baina tenperatura-jauzia giltzan egongo litzateke, ez iragazkian.']]],ok:0,
  med:[['Temperatura antes y después del filtro (con termómetro de contacto).','Tenperatura iragazkiaren aurretik eta ondoren (kontaktu-termometroarekin).'],['Nivel del recipiente.','Hartzailearen maila.'],['Recalentamientos.','Gainberotzeak.']],
  chk:[['Posición de todas las llaves de la línea de líquido.','Likido-lerroko giltza guztien posizioa.'],['Fecha del último cambio de filtro y si se ha abierto el circuito.','Iragazkiaren azken aldaketaren data eta zirkuitua ireki den.']],
  int:{pri:['Si hay líquido de sobra en el recipiente pero después del filtro salen burbujas, algo frena el líquido en medio. El salto de temperatura dice dónde.','Hartzailean likidoa soberan badago baina iragazkiaren ondoren burbuilak ateratzen badira, zerbaitek likidoa frenatzen du tartean. Tenperatura-jauziak esaten du non.'],
       pro:['Una restricción en la línea de líquido provoca caída de presión y evaporación parcial (flash) justo después del punto obstruido, que se ve como enfriamiento local. Con el recipiente lleno se descarta la falta de carga. Si la ΔT está en el filtro y las llaves están abiertas, el filtro está saturado de suciedad.','Likido-lerroko murrizketa batek presio-jaitsiera eta lurrunketa partziala (flash) eragiten ditu buxatutako puntuaren ondoren, eta tokiko hozte gisa ikusten da. Hartzailea beteta, karga falta baztertzen da. ΔT iragazkian badago eta giltzak irekita badaude, iragazkia zikinkeriaz asea dago.']},
  dia:['Filtro deshidratador obstruido.','Iragazki lehorgailua buxatuta.'],
  sol:[['Aislar el filtro con sus llaves y recuperar el tramo.','Iragazkia bere giltzekin isolatu eta tartea berreskuratu.'],['Cambiar el filtro o el cartucho.','Iragazkia edo kartutxoa aldatu.'],['Vacío del tramo antes de abrir las llaves.','Tartearen hutsa giltzak ireki aurretik.']],
  fin:[['Sin diferencia de temperatura en el filtro.','Tenperatura-alderik ez iragazkian.'],['Visor lleno y recalentamientos normales.','Ikusgailua beteta eta gainberotze normalak.']]},
 {id:'exv',les:'a12',t:['Un mueble no enfría: válvula de expansión obstruida','Altzari batek ez du hozten: hedapen-balbula buxatuta'],
  d:['Un solo mueble enfría poco. La solenoide abre, pero pasa poco refrigerante.','Altzari bakar batek gutxi hozten du. Solenoideak irekitzen du, baina hozgarri gutxi pasatzen da.'],
  sin:[['Ese mueble por encima de la consigna.','Altzari hori kontsignatik gora.'],['Evaporador con escarcha solo en la entrada o sin escarcha.','Lurrungailua izarrarekin sarreran bakarrik edo izarrik gabe.']],
  cau:[[['Válvula de expansión obstruida','Hedapen-balbula buxatuta'],['Recalentamiento muy alto y evaporación muy baja en ese mueble; el resto de la instalación va bien.','Gainberotze oso altua eta lurruntze oso baxua altzari horretan; gainerako instalazioa ondo doa.']],
       [['Solenoide que no abre','Ireki ez den solenoidea'],['No llegaría nada de refrigerante: no habría escarcha en absoluto y la bobina no tendría campo.','Ez litzateke hozgarririk iritsiko: ez legoke izarrik batere eta bobinak ez luke eremurik izango.']],
       [['Ventilador parado','Haizagailua geldituta'],['El recalentamiento sería BAJO, no alto.','Gainberotzea BAXUA izango litzateke, ez altua.']],
       [['Falta de refrigerante','Hozgarri falta'],['Afectaría a todos los muebles y habría burbujas.','Altzari guztiei eragingo lieke eta burbuilak egongo lirateke.']]],ok:0,
  med:[['Recalentamiento y presión (o temperatura) de evaporación de ese mueble.','Altzari horren gainberotzea eta lurruntze-presioa (edo -tenperatura).'],['Visor de la línea general.','Lerro orokorreko ikusgailua.'],['Tensión en la bobina de la solenoide.','Tentsioa solenoidearen bobinan.']],
  chk:[['Que la solenoide abra (campo magnético en la bobina).','Solenoideak irekitzen duela (eremu magnetikoa bobinan).'],['En termostática: bulbo bien sujeto y con carga. En electrónica: grado de apertura en el controlador.','Termostatikoan: bulboa ondo lotuta eta kargarekin. Elektronikoan: irekiera-maila kontrolagailuan.'],['Filtro de entrada de la válvula.','Balbularen sarrerako iragazkia.']],
  int:{pri:['Si al evaporador le llega muy poco refrigerante, se seca enseguida y sale muy recalentado. Como los demás muebles van bien, el problema está en la válvula de este.','Lurrungailura oso hozgarri gutxi iristen bazaio, berehala lehortzen da eta oso gainberotuta ateratzen da. Gainerako altzariak ondo doazenez, arazoa honen balbulan dago.'],
       pro:['SH alto + evaporación baja en un único servicio = alimentación insuficiente local. La línea general está bien (visor lleno, otros SH normales). Con la bobina alimentada y la solenoide abierta, la restricción está en la válvula: orificio o filtro sucios, pérdida de carga del bulbo o, en las electrónicas, motor o configuración.','SH altua + lurruntze baxua zerbitzu bakar batean = tokiko elikadura nahikoa ez. Lerro orokorra ondo dago (ikusgailua beteta, beste SH normalak). Bobina elikatuta eta solenoidea irekita dagoela, murrizketa balbulan dago: orifizio edo iragazki zikinak, bulboaren karga-galera edo, elektronikoetan, motorra edo konfigurazioa.']},
  dia:['Válvula de expansión obstruida (u orificio o filtro de entrada sucio).','Hedapen-balbula buxatuta (edo orifizio edo sarrerako iragazki zikina).'],
  sol:[['Aislar el mueble, recuperar el tramo y limpiar o cambiar el orificio o la válvula.','Altzaria isolatu, tartea berreskuratu eta orifizioa edo balbula garbitu edo aldatu.'],['Vacío y puesta en marcha.','Hutsa eta abiaraztea.']],
  fin:[['Recalentamiento del mueble en su valor.','Altzariaren gainberotzea bere balioan.'],['Escarcha repartida por todo el evaporador.','Izarra lurrungailu osoan banatuta.'],['Mueble en consigna.','Altzaria kontsignan.']]},
 {id:'flood',les:'aflood',t:['Aspiración escarchada: retorno de líquido','Xurgaketa izarreztatuta: likido-itzulera'],
  d:['La tubería de aspiración llega escarchada hasta los compresores y uno de ellos hace un ruido extraño.','Xurgaketa-hodia izarreztatuta iristen da konpresoreetaraino eta horietako batek zarata arraroa egiten du.'],
  sin:[['Aspiración escarchada hasta el compresor.','Xurgaketa izarreztatuta konpresoreraino.'],['Recalentamiento de un mueble cerca de 0 K.','Altzari baten gainberotzea 0 K ingurukoa.'],['Cárter frío y ruido de golpeteo.','Karterra hotz eta kolpe-zarata.']],
  cau:[[['Válvula de expansión abierta de más','Hedapen-balbula gehiegi irekita'],['Ese mueble tiene SH ≈ 0 K con el ventilador girando y el bulbo o la sonda bien puestos.','Altzari horrek SH ≈ 0 K du, haizagailua biraka eta bulboa edo zunda ondo jarrita.']],
       [['Bulbo suelto o sonda mal colocada','Bulboa askatuta edo zunda gaizki jarrita'],['El bulbo «ve» calor que no es real y la válvula abre de más. Se comprueba mirando su montaje.','Bulboak benetakoa ez den beroa «ikusten» du eta balbulak gehiegi irekitzen du. Muntaketa begiratuta egiaztatzen da.']],
       [['Ventilador del evaporador parado','Lurrungailuaren haizagailua geldituta'],['Daría SH bajo, pero se ve que el ventilador no gira.','SH baxua emango luke, baina ikusten da haizagailuak ez duela biratzen.']]],ok:0,
  med:[['Recalentamiento de cada servicio para encontrar el que tiene 0 K.','Zerbitzu bakoitzaren gainberotzea, 0 K duena aurkitzeko.'],['Recalentamiento a la entrada del compresor.','Gainberotzea konpresorearen sarreran.'],['Temperatura de descarga (si es baja, entra líquido).','Deskarga-tenperatura (baxua bada, likidoa sartzen da).']],
  chk:[['Montaje del bulbo o de la sonda de ese mueble.','Altzari horren bulboaren edo zundaren muntaketa.'],['Ajuste de la válvula y, en electrónicas, consigna de SH y lectura del transductor.','Balbularen doikuntza eta, elektronikoetan, SH kontsigna eta transduktorearen irakurketa.'],['Ventilador en marcha.','Haizagailua martxan.']],
  int:{pri:['Si el refrigerante sale del mueble todavía líquido, viaja hasta el compresor, que solo puede comprimir gas. Es peligroso: puede romper el compresor.','Hozgarria altzaritik likido ateratzen bada, konpresoreraino iristen da, eta konpresoreak gasa bakarrik konprimi dezake. Arriskutsua da: konpresorea hauts dezake.'],
       pro:['SH ≈ 0 en un servicio con el ventilador funcionando = sobrealimentación. Si el bulbo está bien sujeto y aislado, la válvula está desajustada o sobredimensionada (o la EEV recibe una presión o temperatura falsas). Descarga fría y aspiración escarchada indican riesgo de golpe de líquido y de dilución del aceite.','SH ≈ 0 zerbitzu batean, haizagailua martxan dagoela = gainelikadura. Bulboa ondo lotuta eta isolatuta badago, balbula desdoituta edo neurriz gainekoa da (edo EEVk presio edo tenperatura faltsuak jasotzen ditu). Deskarga hotza eta xurgaketa izarreztatua: likido-kolpearen eta olioaren diluzioaren arriskua.']},
  dia:['Válvula de expansión abierta de más (retorno de líquido).','Hedapen-balbula gehiegi irekita (likido-itzulera).'],
  sol:[['Proteger el compresor: cerrar el servicio afectado.','Konpresorea babestu: kaltetutako zerbitzua itxi.'],['Recolocar y aislar el bulbo o la sonda; ajustar el SH; cambiar la válvula si está sobredimensionada.','Bulboa edo zunda berriro jarri eta isolatu; SH doitu; balbula aldatu neurriz gainekoa bada.'],['Revisar el nivel y el estado del aceite del compresor.','Konpresorearen olioaren maila eta egoera berrikusi.']],
  fin:[['SH del servicio en 5-10 K (orientativo).','Zerbitzuaren SH 5-10 K-tan (orientagarria).'],['Aspiración sin escarcha a la entrada de los compresores.','Xurgaketa izarrik gabe konpresoreen sarreran.'],['Temperatura de descarga normal.','Deskarga-tenperatura normala.']]},
 {id:'noncond',les:'anoncond',t:['Alta presión alta con el condensador limpio: incondensables','Presio altu handia kondentsadorea garbi: kondentsaezinak'],
  d:['Tras una reparación, la alta presión está siempre más alta de lo normal, aunque el condensador está limpio y los ventiladores van bien.','Konponketa baten ondoren, presio altua beti normala baino handiagoa da, kondentsadorea garbi egon eta haizagailuak ondo ibili arren.'],
  sin:[['Alta presión elevada en cualquier época.','Presio altu handia edozein garaitan.'],['Agujas del manómetro de alta que oscilan.','Altuko manometroaren orratzak oszilatzen.'],['Descarga más caliente.','Deskarga beroagoa.']],
  cau:[[['Incondensables (aire o nitrógeno)','Kondentsaezinak (airea edo nitrogenoa)'],['Con la instalación parada y a temperatura ambiente, la presión es más alta que la de saturación del refrigerante a esa temperatura.','Instalazioa geldituta eta giro-tenperaturan, presioa hozgarriaren asetasun-presioa baino handiagoa da tenperatura horretan.']],
       [['Condensador sucio','Kondentsadorea zikin'],['Se descarta: está limpio.','Baztertzen da: garbi dago.']],
       [['Exceso de carga','Karga gehiegi'],['El subenfriamiento sería muy alto; con incondensables suele ser normal o bajo.','Azpihoztea oso altua izango litzateke; kondentsaezinekin normala edo baxua izan ohi da.']]],ok:0,
  med:[['Con todo parado un buen rato: presión del recipiente o condensador y temperatura ambiente.','Dena denbora luzez geldituta: hartzailearen edo kondentsadorearen presioa eta giro-tenperatura.'],['Comparar con la tabla presión-temperatura del refrigerante.','Hozgarriaren presio-tenperatura taularekin alderatu.'],['Subenfriamiento en marcha.','Azpihoztea martxan.']],
  chk:[['Historial: ¿se abrió el circuito y se hizo bien el vacío?','Historiala: zirkuitua ireki zen eta hutsa ondo egin zen?']],
  int:{pri:['El aire no se convierte en líquido en el condensador: ocupa sitio y suma su presión. Por eso la presión es más alta de lo que le toca a esa temperatura.','Airea ez da likido bihurtzen kondentsadorean: lekua hartzen du eta bere presioa gehitzen du. Horregatik da presioa tenperatura horri dagokiona baino handiagoa.'],
       pro:['Ley de Dalton: P<sub>total</sub> = P<sub>sat</sub>(T) + P<sub>gas no condensable</sub>. En parada estabilizada, cualquier exceso sobre P<sub>sat</sub> a la temperatura del refrigerante es presión parcial de incondensables. El condensador limpio y un SC no alto descartan las otras causas.','Daltonen legea: P<sub>osoa</sub> = P<sub>ase</sub>(T) + P<sub>gas kondentsaezina</sub>. Geldialdi egonkortuan, hozgarriaren tenperaturako P<sub>ase</sub>-ren gaineko edozein soberakin kondentsaezinen presio partziala da. Kondentsadore garbiak eta SC ez altuak beste arrazoiak baztertzen dituzte.']},
  dia:['Incondensables en el circuito.','Kondentsaezinak zirkuituan.'],
  sol:[['Recuperar todo el refrigerante (no se purga a la atmósfera).','Hozgarri guztia berreskuratu (ez da atmosferara purgatzen).'],['Cambiar el filtro, hacer un buen vacío y cargar por peso con refrigerante nuevo o regenerado.','Iragazkia aldatu, huts ona egin eta pisuz kargatu hozgarri berri edo birsortuarekin.']],
  fin:[['Presión de parada igual a la de saturación a la temperatura ambiente.','Geldialdiko presioa giro-tenperaturako asetasun-presioaren berdina.'],['Alta presión y salto del condensador normales en marcha.','Presio altua eta kondentsadorearen jauzia normalak martxan.']]},
 {id:'heater',les:'a11',t:['El evaporador se llena de hielo: resistencias de desescarche quemadas','Lurrungailua izotzez betetzen da: izotz-kentzeko erresistentziak erreta'],
  d:['Un mueble de congelados enfría cada día peor. El evaporador está lleno de hielo aunque los desescarches se hacen.','Izozki-altzari batek egunero okerrago hozten du. Lurrungailua izotzez beteta dago, izotz-kentzeak egiten diren arren.'],
  sin:[['Bloque de hielo en el evaporador.','Izotz-blokea lurrungailuan.'],['Los desescarches terminan siempre por tiempo máximo.','Izotz-kentzeak beti gehieneko denboragatik amaitzen dira.'],['Temperatura del mueble que sube poco a poco.','Altzariaren tenperatura pixkanaka igotzen.']],
  cau:[[['Resistencias de desescarche quemadas','Izotz-kentzeko erresistentziak erreta'],['Durante el desescarche no consumen corriente y la sonda de evaporador no llega a la temperatura de fin.','Izotz-kentzean ez dute korronterik kontsumitzen eta lurrungailuaren zunda ez da amaiera-tenperaturara iristen.']],
       [['Sonda de evaporador averiada','Lurrungailuaren zunda matxuratuta'],['El termostato mostraría error de sonda (p. ej., E2).','Termostatoak zunda-errorea erakutsiko luke (adib., E2).']],
       [['Sin desescarches programados','Izotz-kentzerik programatu gabe'],['En el registro no aparecería ningún desescarche.','Erregistroan ez litzateke izotz-kentzerik agertuko.']],
       [['Desagüe helado','Hustubidea izoztuta'],['Habría hielo en la bandeja y agua en el suelo, pero el desescarche acabaría por temperatura.','Izotza egongo litzateke erretiluan eta ura lurrean, baina izotz-kentzea tenperaturagatik amaituko litzateke.']]],ok:0,
  med:[['Corriente de las resistencias durante un desescarche (pinza).','Erresistentzien korrontea izotz-kentze batean (pintza).'],['Resistencia en ohmios de cada resistencia (sin tensión).','Erresistentzia bakoitzaren ohm-ak (tentsiorik gabe).'],['Temperatura de la sonda de evaporador durante el desescarche.','Lurrungailuaren zundaren tenperatura izotz-kentzean.']],
  chk:[['Registro de desescarches y cómo terminan.','Izotz-kentzeen erregistroa eta nola amaitzen diren.'],['Que el relé del termostato dé tensión a las resistencias.','Termostatoaren erreleak erresistentziei tentsioa ematen diela.']],
  int:{pri:['El desescarche se hace (está programado y el termostato lo manda), pero no calienta. Por eso el hielo no se va y se acumula.','Izotz-kentzea egiten da (programatuta dago eta termostatoak agintzen du), baina ez du berotzen. Horregatik izotza ez da joaten eta metatu egiten da.'],
       pro:['Desescarche activo con 0 A en las resistencias y tensión presente en sus bornes = resistencias abiertas (lo confirma la medida en Ω, infinita). Se descarta la sonda (no hay error) y la programación (hay desescarches en el registro). El fin por tiempo máximo es la consecuencia, no la causa.','Izotz-kentzea aktibo, erresistentzietan 0 A eta borneetan tentsioa = erresistentzia irekiak (Ω neurketak baieztatzen du, infinitua). Zunda baztertzen da (ez dago errorerik) eta programazioa ere bai (izotz-kentzeak daude erregistroan). Gehieneko denboragatiko amaiera ondorioa da, ez arrazoia.']},
  dia:['Resistencias de desescarche quemadas.','Izotz-kentzeko erresistentziak erreta.'],
  sol:[['Cambiar las resistencias (misma potencia y tensión).','Erresistentziak aldatu (potentzia eta tentsio berekoak).'],['Deshielo manual completo antes de volver a poner en marcha.','Eskuzko izotz-kentze osoa berriro abiarazi aurretik.'],['Comprobar el aislamiento: una resistencia dañada puede hacer saltar el diferencial.','Isolamendua egiaztatu: erresistentzia hondatu batek diferentziala jauzarazi dezake.']],
  fin:[['Consumo correcto en el siguiente desescarche.','Kontsumo zuzena hurrengo izotz-kentzean.'],['Desescarche que termina por temperatura.','Tenperaturagatik amaitzen den izotz-kentzea.'],['Evaporador limpio de hielo.','Lurrungailua izotzik gabe.']]},
 {id:'humid',les:'ahumid',t:['Enfría a ratos y el visor está amarillo: humedad','Tarteka hozten du eta ikusgailua horia: hezetasuna'],
  d:['Después de una reparación, algunos muebles de negativa dejan de enfriar a ratos y luego vuelven a funcionar.','Konponketa baten ondoren, negatiboko altzari batzuek tarteka hozteari uzten diote eta gero berriro dabiltza.'],
  sin:[['Indicador de humedad del visor en amarillo.','Ikusgailuaren hezetasun-adierazlea horia.'],['Muebles que enfrían de forma intermitente.','Modu etenean hozten duten altzariak.'],['Recalentamiento que sube de golpe y vuelve a bajar.','Bat-batean igo eta berriro jaisten den gainberotzea.']],
  cau:[[['Humedad en el circuito','Hezetasuna zirkuituan'],['El agua se congela en la válvula y la tapa; al derretirse vuelve a pasar. El visor lo confirma.','Ura balbulan izozten da eta tapatu egiten du; urtzean berriro pasatzen da. Ikusgailuak baieztatzen du.']],
       [['Válvula electrónica oscilando','Balbula elektroniko oszilatzailea'],['El SH oscilaría continuamente en pocos minutos y el visor estaría verde.','SH etengabe oszilatuko litzateke minutu gutxitan eta ikusgailua berdea legoke.']],
       [['Sonda con falso contacto','Zunda falso-kontaktuarekin'],['El termostato mostraría errores de sonda a ratos.','Termostatoak zunda-erroreak erakutsiko lituzke tarteka.']]],ok:0,
  med:[['Color del indicador del visor.','Ikusgailuaren adierazlearen kolorea.'],['Recalentamiento a lo largo del tiempo (registro).','Gainberotzea denboran zehar (erregistroa).'],['Test de acidez del aceite si se sospecha mucha humedad.','Olioaren azidotasun-testa hezetasun handia susmatzen bada.']],
  chk:[['Cómo se hizo el vacío en la última reparación.','Nola egin zen hutsa azken konponketan.'],['Estado del filtro deshidratador.','Iragazki lehorgailuaren egoera.']],
  int:{pri:['El agua dentro del circuito se hiela en el sitio más frío y estrecho: la válvula de expansión. Allí hace de tapón hasta que se derrite.','Zirkuitu barruko ura leku hotzenean eta estuenean izozten da: hedapen-balbulan. Han tapoi gisa egiten du urtu arte.'],
       pro:['Bloqueos intermitentes en las válvulas de negativa + indicador de humedad = agua libre que congela en el orificio. Además, el agua forma ácidos con el aceite POE. Se descarta la EEV y la sonda por la forma de los síntomas y porque no hay alarmas.','Negatiboko balbuletan buxadura etenak + hezetasun-adierazlea = orifizioan izozten den ur librea. Gainera, urak azidoak sortzen ditu POE olioarekin. EEV eta zunda baztertzen dira sintomen formagatik eta alarmarik ez dagoelako.']},
  dia:['Humedad en el circuito.','Hezetasuna zirkuituan.'],
  sol:[['Cambiar el filtro deshidratador (varias veces si hace falta, hasta que el indicador vuelva a verde).','Iragazki lehorgailua aldatu (behar bada behin baino gehiagotan, adierazlea berdera itzuli arte).'],['Si hay mucha agua o ácido: recuperar, cambiar el aceite y hacer un vacío profundo.','Ur edo azido asko badago: berreskuratu, olioa aldatu eta huts sakona egin.']],
  fin:[['Indicador del visor en verde tras unas horas.','Ikusgailuaren adierazlea berdea ordu batzuen ondoren.'],['Recalentamientos estables y muebles en consigna.','Gainberotze egonkorrak eta altzariak kontsignan.']]},
 {id:'comp',les:'a3',t:['Un compresor en fallo: guardamotor disparado','Konpresore bat hutsean: motor-babeslea jauzita'],
  d:['El controlador de la central marca un compresor en fallo. Con mucha demanda, la aspiración sube.','Zentralaren kontrolagailuak konpresore bat hutsean markatzen du. Eskari handiarekin, xurgaketa igotzen da.'],
  sin:[['Alarma de fallo de compresor en el controlador.','Konpresore-hutsegitearen alarma kontrolagailuan.'],['Guardamotor de ese compresor disparado.','Konpresore horren motor-babeslea jauzita.'],['Presión de aspiración por encima de la consigna en horas punta.','Xurgaketa-presioa kontsignatik gora punta-orduetan.']],
  cau:[[['Sobrecarga del motor','Motorraren gainkarga'],['Intensidad alta en las tres fases (alta presión elevada, compresor forzado).','Intentsitate altua hiru faseetan (presio altu handia, konpresorea behartuta).']],
       [['Falta de fase','Fase falta'],['Una fase sin tensión o con mucha menos intensidad que las otras.','Fase bat tentsiorik gabe edo besteek baino intentsitate askoz txikiagoarekin.']],
       [['Motor derivado a tierra o con devanado dañado','Motorra lurrera deribatuta edo harilkatua hondatuta'],['Aislamiento bajo con el megóhmetro o resistencias de devanado desiguales.','Isolamendu baxua megohmetroarekin edo harilkatu-erresistentzia desberdinak.']],
       [['Guardamotor mal ajustado','Motor-babeslea gaizki doituta'],['El ajuste está por debajo de la intensidad nominal de la placa.','Doikuntza plakako intentsitate nominaletik behera dago.']]],ok:-1,
  med:[['Tensión entre fases a la entrada del guardamotor.','Faseen arteko tentsioa motor-babeslearen sarreran.'],['Resistencia de los devanados y aislamiento a tierra (sin tensión).','Harilkatuen erresistentzia eta lurrarekiko isolamendua (tentsiorik gabe).'],['Intensidad de las tres fases al rearmar.','Hiru faseen intentsitatea berrarmatzean.'],['Presiones de trabajo.','Lan-presioak.']],
  chk:[['Ajuste del guardamotor frente a la placa.','Motor-babeslearen doikuntza plakarekin alderatuta.'],['Bornes del contactor y del compresor (apriete, color).','Kontaktorearen eta konpresorearen borneak (estutzea, kolorea).'],['Historial de alarmas: ¿desde cuándo, cuántas veces?','Alarma-historiala: noiztik, zenbat aldiz?']],
  int:{pri:['El guardamotor salta para proteger el motor. No basta con subirlo: hay que medir para saber POR QUÉ ha saltado. Cada causa deja una «huella» distinta en las medidas.','Motor-babesleak motorra babesteko jauzi egiten du. Ez da nahikoa igotzea: neurtu egin behar da ZERGATIK jauzi egin duen jakiteko. Arrazoi bakoitzak «arrasto» desberdina uzten du neurketetan.'],
       pro:['Método: primero la tensión (fases presentes y equilibradas), después el motor sin tensión (Ω entre bornes iguales; aislamiento correcto) y, por último, la carga (presiones e intensidad frente a la placa). Solo con todas las medidas se puede concluir; por eso este caso no tiene una única respuesta: el diagnóstico depende de lo que midas. En el simulador, la práctica a3 te deja medir y decidir.','Metodoa: lehenengo tentsioa (faseak egon eta orekatuta), gero motorra tentsiorik gabe (borneen arteko Ω berdinak; isolamendu zuzena) eta, azkenik, karga (presioak eta intentsitatea plakarekin alderatuta). Neurketa guztiekin bakarrik atera daiteke ondorioa; horregatik kasu honek ez du erantzun bakarra: diagnostikoa neurtzen duzunaren araberakoa da. Simulagailuan, a3 praktikak neurtzen eta erabakitzen uzten dizu.']},
  dia:['Depende de las medidas: con tensión equilibrada, motor sano y ajuste correcto, la causa es una sobrecarga (revisar la alta presión). Con una fase caída, es la falta de fase.','Neurketen araberakoa: tentsio orekatuarekin, motor osasuntsuarekin eta doikuntza zuzenarekin, arrazoia gainkarga da (presio altua berrikusi). Fase bat eroriz gero, fase falta da.'],
  sol:[['Corregir la causa encontrada (alimentación, motor, ajuste o presiones).','Aurkitutako arrazoia zuzendu (elikadura, motorra, doikuntza edo presioak).'],['Rearmar solo cuando la causa esté resuelta.','Arrazoia konponduta dagoenean bakarrik berrarmatu.']],
  fin:[['Intensidades equilibradas y por debajo de la nominal.','Intentsitate orekatuak eta nominaletik behera.'],['El compresor responde a las órdenes del controlador.','Konpresoreak kontrolagailuaren aginduei erantzuten die.'],['Aspiración en consigna.','Xurgaketa kontsignan.']]}
];
KT.acur='low'; KT.astep=1; KT.aq=null;
const AVS=[['Descripción','Deskribapena'],['Síntomas','Sintomak'],['Posibles causas','Arrazoi posibleak'],['Mediciones','Neurketak'],['Comprobaciones','Egiaztapenak'],['Interpretación','Interpretazioa'],['Diagnóstico','Diagnostikoa'],['Solución','Konponbidea'],['Comprobación final','Azken egiaztapena']];
function avRender(main){ const a=AV.find(x=>x.id===KT.acur)||AV[0]; const pro=nvPro(); const ul=l=>`<ul>${l.map(x=>`<li>${KL(...x)}</li>`).join('')}</ul>`;
  const n=pro?9:Math.max(1,Math.min(9,KT.astep));
  const body=i=>{ switch(i){
    case 0: return `<p>${KL(...a.d)}</p>`;
    case 1: return ul(a.sin);
    case 2: return `<table class="av-t"><thead><tr><th>${KL('Causa posible','Arrazoi posiblea')}</th><th>${KL('Cómo se confirma o se descarta','Nola baieztatzen edo baztertzen den')}</th></tr></thead><tbody>${a.cau.map(c=>`<tr><td><b>${KL(...c[0])}</b></td><td>${KL(...c[1])}</td></tr>`).join('')}</tbody></table>`;
    case 3: return ul(a.med)+`<p class="av-n">${KL('Los valores normales son orientativos: dependen de la instalación y del refrigerante. Puedes usar las calculadoras (recalentamiento, subenfriamiento, presión-temperatura).','Balio normalak orientagarriak dira: instalazioaren eta hozgarriaren araberakoak. Kalkulagailuak erabil ditzakezu (gainberotzea, azpihoztea, presioa-tenperatura).')} <button class="av-lk" data-ak="sh">${KL('Abrir calculadoras','Ireki kalkulagailuak')}</button></p>`;
    case 4: return ul(a.chk);
    case 5: return pro?`<div class="nv-box pro" style="margin-top:0">${KL(...a.int.pro)}</div><details class="nv-box pri"><summary>💡 ${KL('Ver la explicación sencilla','Ikusi azalpen erraza')}</summary><div>${KL(...a.int.pri)}</div></details>`:`<div class="nv-box pri" style="margin-top:0">${KL(...a.int.pri)}</div><details class="nv-box pro"><summary>🔧 ${KL('Ampliar: explicación profesional','Zabaldu: azalpen profesionala')}</summary><div>${KL(...a.int.pro)}</div></details>`;
    case 6: { const q=KT.aq; const opts=a.cau.map((c,k)=>`<button class="av-op${q!==null&&q.k===k?(a.ok===-1||k===a.ok?' ok':' no'):''}" data-aq="${k}">${KL(...c[0])}</button>`).join('');
      let fb=''; if(q!==null){ fb= a.ok===-1?`<p class="av-fb ok">${KL('Aquí no hay una única respuesta: depende de lo que midas. Fíjate en la tabla del paso 3.','Hemen ez dago erantzun bakarrik: neurtzen duzunaren araberakoa da. Begiratu 3. urratseko taula.')}</p>`
        : q.k===a.ok?`<p class="av-fb ok">✔ ${KL('Correcto.','Zuzena.')} ${KL(...a.cau[q.k][1])}</p>`:`<p class="av-fb no">✘ ${KL('No encaja con los datos:','Ez dator bat datuekin:')} ${KL(...a.cau[q.k][1])}</p>`; }
      return `<p>${KL('Con los síntomas y las medidas, ¿cuál es la causa?','Sintomekin eta neurketekin, zein da arrazoia?')}</p><div class="av-ops">${opts}</div>${fb}${(q!==null&&(a.ok===-1||q.k===a.ok))||pro?`<p class="av-dg"><b>${KL('Diagnóstico','Diagnostikoa')}:</b> ${KL(...a.dia)}</p>`:''}`; }
    case 7: return ul(a.sol);
    case 8: return ul(a.fin); } };
  const steps=AVS.slice(0,n).map((s,i)=>`<section class="av-s"><h3><span>${i+1}</span>${KL(...s)}</h3>${body(i)}</section>`).join('');
  const lesson=a.les&&typeof TRAIN!=='undefined'&&TRAIN.find(l=>l.id===a.les);
  main.innerHTML=`<div class="av"><h2>${KL(...a.t)}</h2>
   <ol class="av-bar">${AVS.map((s,i)=>`<li class="${i<n?'on':''}">${i+1}</li>`).join('')}</ol>
   ${steps}
   <div class="av-nav">${!pro&&n<9?`<button class="kt-b av-next" data-an="1">${KL('Siguiente paso','Hurrengo urratsa')} (${n+1}/9) →</button>`:''}${!pro&&n>1?`<button class="kt-b" data-an="0">${KL('Volver a empezar','Berriro hasi')}</button>`:''}
   ${lesson?`<button class="kt-b av-sim" data-asim="${a.les}">🎮 ${KL('Practicar esta avería en el simulador','Matxura hau simulagailuan praktikatu')}</button>`:''}</div>
   ${pro?'':`<p class="cp-tip">${KL('En el modo Principiante los pasos se abren de uno en uno, para pensar antes de ver la respuesta. En Profesional se ven todos.','Hasiberri moduan urratsak banan-banan irekitzen dira, erantzuna ikusi aurretik pentsatzeko. Profesionalean denak ikusten dira.')}</p>`}</div>`; }
KTABS.aver={t:['Averías','Matxurak'],ph:['Buscar avería o síntoma…','Bilatu matxura edo sintoma…'],
  list:q=>AV.filter(a=>!q||(KL(...a.t)+' '+a.sin.map(s=>KL(...s)).join(' ')).toLowerCase().includes(q)).map(a=>`<button class="kt-li${a.id===KT.acur?' on':''}" data-av="${a.id}">${KL(...a.t)}</button>`).join(''),
  render:main=>avRender(main)};
document.addEventListener('click',e=>{ if(!KT.open||!e.target.closest) return; const t=e.target;
  const b=t.closest('#kt [data-av]'); if(b){ KT.acur=b.dataset.av; KT.astep=1; KT.aq=null; ktRender(); const m=document.querySelector('#kt .kt-main'); if(m&&window.innerWidth<900) m.scrollIntoView({behavior:'smooth'}); return; }
  const n=t.closest('#kt [data-an]'); if(n){ const m=document.querySelector('#kt .kt-main'); if(n.dataset.an==='1'){ KT.astep++; avRender(m); const s=m.querySelectorAll('.av-s'); if(s.length) s[s.length-1].scrollIntoView({behavior:'smooth',block:'start'}); } else { KT.astep=1; KT.aq=null; avRender(m); m.scrollTop=0; } return; }
  const q=t.closest('#kt [data-aq]'); if(q){ KT.aq={k:+q.dataset.aq}; const m=document.querySelector('#kt .kt-main'); const y=m.scrollTop; avRender(m); m.scrollTop=y; return; }
  const k=t.closest('#kt [data-ak]'); if(k){ KT.tab='calc'; KT.cur=k.dataset.ak; ktRender(); return; }
  const s=t.closest('#kt [data-asim]'); if(s){ const id=s.dataset.asim; ktClose(); try{ if(typeof trStart==='function') trStart(id); }catch(_){} } });
