  async function logout(){ await push(true); await fb.auth.signOut(); try{ sessionStorage.removeItem('sfCloudApplied'); }catch(e){} toast(L('Sesión cerrada. Tu progreso sigue en este navegador.','Saioa itxita. Zure aurrerapenak nabigatzaile honetan jarraitzen du.')); }
  async function borrar(){ if(!user) return; try{ await ref().delete(); toast(L('Tus datos se han borrado de la nube.','Zure datuak hodeitik ezabatu dira.')); }catch(e){ toast(L('No se han podido borrar.','Ezin izan dira ezabatu.')); } }
  // ---- interfaz: botón junto al selector de nivel e idioma
