  KC.forEach(k=>{ if(has(KL(...k.t)+' '+KL(...k.pri))) R.push({g:'calc',at:`data-bk="${k.id}"`,t:KL(...k.t),s:KL(...k.pri),w:has(KL(...k.t))?2:1}); });
