  if(k.startsWith('ss')&&was&&v3Open('sl'+k.slice(2))) logA('warn',`${S.svcs[+k.slice(2)].name}: has cerrado la aspiración antes que el líquido; el evaporador se llena de líquido.`);
  if(k==='ihx'){ S.hx=!was?true:false; const c=$('chkHx'); if(c){ c.checked=S.hx; c.dispatchEvent(new Event('change')); } }
