  const bu=S.v3&&S.v3.bu; if(bu&&(c==='acoA'||c==='acoB'||c==='mfail')){ if(c==='acoA'){ bu.A=!bu.A; logA(bu.A?'ok':'bad',bu.A?'Vuelve la acometida A (central principal).':'Sin tensión en la acometida A (central principal).'); } if(c==='acoB'){ bu.B=!bu.B; logA(bu.B?'ok':'bad',bu.B?'Vuelve la acometida B (central de backup).':'Sin tensión en la acometida B (central de backup).'); } if(c==='mfail'){ bu.fail=!bu.fail; logA(bu.fail?'bad':'ok',bu.fail?'Avería en la central principal (controlador).':'Central principal reparada.'); }
    const blk=!bu.A&&!bu.B; if(blk&&!S.pwrOff){ if(typeof pwrCut==='function') pwrCut(); else S.pwrOff=true; } else if(!blk&&S.pwrOff){ if(typeof pwrOn==='function') pwrOn(); else S.pwrOff=false; } S.cache=highSide(); }
  if(c==='pwr'&&bu){ bu.A=bu.B=!!S.pwrOff; }
