// ---------- andar por la instalación ----------
const MV={x:0,z:2,yaw:0,pitch:-.15,keys:{},joy:{x:0,y:0},tw:null,fov:60};
const REACH=5.2, PR=.28;
function v3Blocked(x,z){ const B=V3.bounds; if(B&&(x<B.x0||x>B.x1||z<B.z0||z>B.z1)) return true; for(const b of V3.col){ if(x>b.x0-PR&&x<b.x1+PR&&z>b.z0-PR&&z<b.z1+PR) return true; } return false; }
function v3Walk(dt){ if(V3.R.dev&&!V3.R.dev.hidden) return; const k=MV.keys; let f=0,s=0; if(k.KeyW||k.ArrowUp) f+=1; if(k.KeyS||k.ArrowDown) f-=1; if(k.KeyA||k.ArrowLeft) s-=1; if(k.KeyD||k.ArrowRight) s+=1; f-=MV.joy.y; s+=MV.joy.x;
  const L=Math.hypot(f,s); if(L<.05) return; if(L>1){ f/=L; s/=L; } MV.tw=null; const v=(k.ShiftLeft||k.ShiftRight?3.4:1.8)*dt, si=Math.sin(MV.yaw), co=Math.cos(MV.yaw);
  const dx=(-si*f+co*s)*v, dz=(-co*f-si*s)*v; if(!v3Blocked(MV.x+dx,MV.z)) MV.x+=dx; if(!v3Blocked(MV.x,MV.z+dz)) MV.z+=dz; }
function v3Cam(){ const c=V3.R.cam; if(MV.tw){ const t=Math.min(1,(performance.now()-MV.tw.s)/650), e=t<.5?2*t*t:1-Math.pow(-2*t+2,2)/2, a=MV.tw.a, b=MV.tw.b; MV.x=a.x+(b.x-a.x)*e; MV.z=a.z+(b.z-a.z)*e; let dy=b.yaw-a.yaw; dy=Math.atan2(Math.sin(dy),Math.cos(dy)); MV.yaw=a.yaw+dy*e; MV.pitch=a.p+(b.p-a.p)*e; if(t>=1) MV.tw=null; }
  c.position.set(MV.x,1.65,MV.z); c.rotation.order='YXZ'; c.rotation.y=MV.yaw; c.rotation.x=MV.pitch; if(Math.abs(c.fov-MV.fov)>.01){ c.fov=MV.fov; c.updateProjectionMatrix(); } }
function v3Go(k){ const p=V3.spots[k]; if(!p) return; MV.tw={a:{x:MV.x,z:MV.z,yaw:MV.yaw,p:MV.pitch},b:{x:p.x,z:p.z,yaw:p.yaw,p:p.p},s:performance.now()}; v3MenuShow(false); }
