// ================= Moverse como en el «Taller 3D»: vista general, planta, caminar (ratón bloqueado + punto de mira) y girar =================
const NV3={mode:'walk',oc:null,lock:false,lockFail:false,fine:!!(window.matchMedia&&matchMedia('(pointer: fine)').matches),cutKey:'',tipT:0};
const navCSS=`.v3-dock{position:absolute;top:12px;left:50%;transform:translateX(-50%);display:flex;gap:6px;padding:6px;border-radius:16px;background:rgba(14,20,27,.82);box-shadow:0 6px 20px rgba(0,0,0,.25);z-index:3}
.v3-dock button{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:3px;width:64px;height:52px;border:1px solid #22303c;border-radius:12px;background:#16202a;color:#c5d1dc;font:600 11px system-ui,sans-serif;cursor:pointer;padding:0}
.v3-dock button svg{width:20px;height:20px}
.v3-dock button:hover{border-color:#5ee0c3;color:#fff}
.v3-dock button.on{background:#11302a;color:#5ee0c3;border-color:#5ee0c3;box-shadow:0 0 0 3px rgba(94,224,195,.14)}
.v3-lockmsg{position:absolute;left:50%;top:calc(50% + 22px);transform:translateX(-50%);background:rgba(20,28,36,.85);color:#fff;font:600 13px system-ui,sans-serif;padding:6px 14px;border-radius:999px;pointer-events:none;white-space:nowrap}
#v3d.v3-orbit .v3-cross,#v3d.v3-orbit .v3-joy{display:none!important}
@media (max-width:820px){.v3-dock{top:auto;bottom:auto;left:auto;right:10px;top:50%;transform:translateY(-50%);flex-direction:column}.v3-dock button{width:52px;height:48px;font-size:10px}}`;
const navIco={iso:'<path d="M12 2.5 3.5 7v10l8.5 4.5 8.5-4.5V7z"/><path d="M3.5 7 12 11.5 20.5 7M12 11.5v10"/>',top:'<rect x="3" y="3" width="18" height="18" rx="2"/><path d="M3 10h8v11M11 3v3M15 10h6M15 10v4"/>',walk:'<circle cx="13.5" cy="4" r="1.8"/><path d="m8 21 3-6.5 3 2.5v4M7 12.5l2.5-3.5 4-.5 2 3.5 2.5 1M11 14.5l1.5-6"/>',rot:'<path d="M20.5 12a8.5 8.5 0 1 1-2.6-6.1"/><path d="M20.5 3.5v5h-5"/>'};
function navSetup(){ const R=V3.R; if(!R||R.fail||R.dock) return; const st=document.createElement('style'); st.textContent=navCSS; document.head.appendChild(st);
  const d=document.createElement('div'); d.className='v3-dock'; const B=(k,t)=>`<button type="button" data-nav="${k}" title="${t}"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round">${navIco[k]}</svg>${t}</button>`;
  d.innerHTML=B('iso',x3('General','Orokorra'))+B('top',x3('Planta','Oinplanoa'))+B('walk',x3('Caminar','Ibili'))+B('rot',x3('Girar','Biratu')); R.o.appendChild(d); R.dock=d;
  const m=document.createElement('div'); m.className='v3-lockmsg'; m.hidden=true; m.textContent=x3('Clic en un sitio vacío para mirar con el ratón · Esc para soltarlo','Klik leku huts batean saguarekin begiratzeko · Esc askatzeko'); R.wrap.appendChild(m); R.lockMsg=m;
  d.addEventListener('click',e=>{ const b=e.target.closest('[data-nav]'); if(!b) return; const k=b.dataset.nav;
    if(k==='walk') return navMode('walk'); if(k==='rot'){ if(NV3.mode==='walk') navMode('iso'); NV3.oc.autoRotate=!NV3.oc.autoRotate; return navBtns(); } navMode(k); });
  document.addEventListener('pointerlockchange',()=>{ NV3.lock=document.pointerLockElement===R.cv; if(!NV3.lock) R.tip.hidden=true; navBtns(); });
  document.addEventListener('pointerlockerror',()=>{ NV3.lockFail=true; navBtns(); });
  document.addEventListener('mousemove',e=>{ if(!V3.on||!NV3.lock) return; MV.yaw-=(e.movementX||0)*.0024; MV.pitch=Math.max(-1.25,Math.min(1.1,MV.pitch-(e.movementY||0)*.0024)); MV.tw=null; });
  navBtns(); }
function navBtns(){ const R=V3.R; if(!R||!R.dock) return; R.dock.querySelectorAll('[data-nav]').forEach(b=>{ const k=b.dataset.nav; b.classList.toggle('on',k==='rot'?!!(NV3.oc&&NV3.oc.autoRotate&&NV3.mode!=='walk'):k===NV3.mode); });
  R.o.classList.toggle('v3-orbit',NV3.mode!=='walk'); if(R.lockMsg) R.lockMsg.hidden=!(NV3.mode==='walk'&&NV3.fine&&!NV3.lock&&!NV3.lockFail&&R.help.hidden&&V3.on); }
function navCenter(){ const B=V3.bounds||{x0:-8,x1:8,z0:-4,z1:6}; return {x:(B.x0+B.x1)/2,z:(B.z0+B.z1)/2,span:Math.max(B.x1-B.x0,B.z1-B.z0)}; }
function navMode(k){ const R=V3.R; if(!R||R.fail) return; if(NV3.lock&&document.exitPointerLock) document.exitPointerLock();
  if(k==='walk'){ if(NV3.oc){ NV3.oc.enabled=false; NV3.oc.autoRotate=false; } NV3.mode='walk'; NV3.mode0='walk'; navCut(); navBtns(); return; }
  if(!NV3.oc){ NV3.oc=new T3.OrbitControls(R.cam,R.cv); NV3.oc.enableDamping=true; NV3.oc.dampingFactor=.08; NV3.oc.minDistance=1.5; NV3.oc.maxDistance=70; NV3.oc.maxPolarAngle=Math.PI/2-.04; NV3.oc.autoRotateSpeed=.6; NV3.oc.screenSpacePanning=true; }
  const C=navCenter(), cam=R.cam, fw=new T3.Vector3(-Math.sin(MV.yaw),0,-Math.cos(MV.yaw)); NV3.mode=k; NV3.oc.enabled=true; cam.fov=45; cam.updateProjectionMatrix();
  const tgt=new T3.Vector3(C.x,.8,C.z), pos=k==='top'?new T3.Vector3(C.x,C.span*1.15,C.z+.01):tgt.clone().addScaledVector(fw,-C.span*.62).add(new T3.Vector3(-C.span*.25,C.span*.55,0));
  NV3.tw={a:cam.position.clone(),b:pos,ta:NV3.mode0==='walk'||!NV3.oc.target?tgt.clone():NV3.oc.target.clone(),tb:tgt,s:performance.now()}; NV3.oc.target.copy(NV3.tw.ta); NV3.mode0=k;
  navCut(); navBtns(); }
// paredes cortadas a media altura y sin techo en las vistas desde fuera (como una maqueta)
function navCut(){ const R=V3.R; if(!R||!R.scene) return; const cut=NV3.mode!=='walk'; NV3.cutKey=(cut?'c':'w')+R.scene.children.length+'|'+(V3.S?1:0);
  R.scene.traverse(o=>{ const w=o.userData&&o.userData.wall; if(w){ const s=cut?(w.y0>0?0.001:Math.min(1,1.1/w.h)):1; o.scale.y=s; o.position.y=w.y0+w.h*s/2; o.visible=!(cut&&w.y0>0); } if(o.userData&&o.userData.ceil) o.visible=!cut; }); }
// caminar: W/S adelante y atrás, A/D de lado, flechas izquierda/derecha para girar
v3Walk=function(dt){ if(NV3.mode!=='walk') return; if(V3.R.dev&&!V3.R.dev.hidden) return; const k=MV.keys; let f=0,s=0,turn=0; if(k.KeyW||k.ArrowUp) f+=1; if(k.KeyS||k.ArrowDown) f-=1; if(k.KeyA) s-=1; if(k.KeyD) s+=1; if(k.ArrowLeft) turn+=1; if(k.ArrowRight) turn-=1; f-=MV.joy.y; s+=MV.joy.x;
  if(turn){ MV.yaw+=turn*1.8*dt; MV.tw=null; } const L=Math.hypot(f,s); if(L<.05) return; if(L>1){ f/=L; s/=L; } MV.tw=null; const v=(k.ShiftLeft||k.ShiftRight?3.4:1.8)*dt, si=Math.sin(MV.yaw), co=Math.cos(MV.yaw);
  const dx=(-si*f+co*s)*v, dz=(-co*f-si*s)*v; if(!v3Blocked(MV.x+dx,MV.z)) MV.x+=dx; if(!v3Blocked(MV.x,MV.z+dz)) MV.z+=dz; };
(function(){ const _cam=v3Cam; v3Cam=function(){ const R=V3.R; const key=(NV3.mode!=='walk'?'c':'w')+R.scene.children.length+'|'+(V3.S?1:0); if(key!==NV3.cutKey) navCut();
    if(NV3.mode==='walk') { _cam(); if(NV3.lock){ const now=performance.now(); if(now-NV3.tipT>120){ NV3.tipT=now; const r=R.cv.getBoundingClientRect(), h=v3HitAt(r.left+r.width/2,r.top+r.height/2); R.tip.hidden=!h; if(h){ R.tip.style.left=(r.width/2+14)+'px'; R.tip.style.top=(r.height/2+12)+'px'; R.tip.innerHTML=`${v3Name(h.p)}${h.d>REACH?`<small>${x3('Acércate para usarlo','Hurbildu erabiltzeko')}</small>`:''}`; } } } return; }
    if(NV3.tw){ const t=Math.min(1,(performance.now()-NV3.tw.s)/700), e=t<.5?2*t*t:1-Math.pow(-2*t+2,2)/2; R.cam.position.lerpVectors(NV3.tw.a,NV3.tw.b,e); NV3.oc.target.lerpVectors(NV3.tw.ta,NV3.tw.tb,e); if(t>=1) NV3.tw=null; }
    NV3.oc.update(); };
  // con el ratón bloqueado se usa lo que hay en el punto de mira
  const _hit=v3HitAt; v3HitAt=function(cx,cy){ if(NV3.lock&&V3.R){ const r=V3.R.cv.getBoundingClientRect(); return _hit(r.left+r.width/2,r.top+r.height/2); } return _hit(cx,cy); };
  const _use=v3Use; v3Use=function(h){ const R=V3.R;
    if(NV3.mode!=='walk'){ if(!h||!h.pt) return; // en la vista general: pulsar una pieza te lleva andando delante de ella
      const P=h.pt, c=R.cam.position, ray=new T3.Raycaster(); let best=null; const a0=Math.atan2(c.x-P.x,c.z-P.z);
      for(const dist of [1.5,2,2.6,3.3]) for(let i=0;i<16;i++){ const a=a0+(i%2?1:-1)*Math.ceil(i/2)*Math.PI/8, x=P.x+Math.sin(a)*dist, z=P.z+Math.cos(a)*dist; if(v3Blocked(x,z)) continue;
        const E=new T3.Vector3(x,1.65,z), dir=P.clone().sub(E), L=dir.length(); ray.set(E,dir.normalize()); ray.far=L+.5; const hit=ray.intersectObjects(R.scene.children,true).find(q=>q.object.visible&&!(q.object.material&&q.object.material.transparent)&&!(q.object.userData&&q.object.userData.ceil));
        const vis=!hit||hit.distance>L-.35; const sc=(vis?0:100)+dist*2+Math.abs(Math.ceil(i/2))*.6; if(!best||sc<best.sc) best={x,z,sc}; }
      let x,z; if(best){ x=best.x; z=best.z; } else { const S0=V3.spots.rack; x=S0.x; z=S0.z; } const yaw=Math.atan2(-(P.x-x),-(P.z-z)), p=Math.atan2(P.y-1.65,Math.hypot(P.x-x,P.z-z));
      MV.x=x; MV.z=z; MV.yaw=yaw; MV.pitch=Math.max(-1.1,Math.min(.9,p)); MV.tw=null; navMode('walk'); V3.sel=h.p; V3.lastP=''; v3Card(true); return; }
    if(!h){ if(NV3.fine&&!NV3.lock&&!NV3.lockFail&&R.cv.requestPointerLock&&R.help.hidden&&R.dev.hidden){ try{ const q=R.cv.requestPointerLock(); if(q&&q.catch) q.catch(()=>{ NV3.lockFail=true; navBtns(); }); }catch(e){ NV3.lockFail=true; } } return; }
    _use(h); if(NV3.lock&&((R.dev&&!R.dev.hidden))) document.exitPointerLock(); };
  const _init=v3Init; v3Init=function(){ const had=!!V3.R; const r=_init(); if(r&&V3.R&&!V3.R.fail&&!had){ navSetup(); V3.R.o.addEventListener('click',()=>setTimeout(navBtns,0)); } return r; };
  const _close=v3Close; v3Close=function(){ if(NV3.lock&&document.exitPointerLock) document.exitPointerLock(); if(NV3.mode!=='walk') navMode('walk'); return _close.apply(this,arguments); };
  const _go=v3Go; v3Go=function(k){ if(NV3.mode!=='walk') navMode('walk'); return _go(k); };
})();

const MEDIA=[{"id": "comp_0", "cat": "pieza", "keys": ["comp"], "les": ["b5"], "t": ["Compresor alternativo abierto", "Konpresore alternatibo irekia"], "d": ["Compresor de pistones de una instalación frigorífica industrial, movido por un motor eléctrico aparte. En supermercados se usan sobre todo semiherméticos (motor y compresor en la misma carcasa) y scroll.", "Instalazio industrial bateko pistoi-konpresorea, aparteko motor elektriko batek mugitua. Supermerkatuetan batez ere erdi-hermetikoak (motorra eta konpresorea karkasa berean) eta scroll-ak erabiltzen dira."], "img": "data:image/jpeg;base64,", "author": "Endora6398", "lic": "CC BY-SA 4.0", "url": "https://commons.wikimedia.org/wiki/File%3AReciprocating_Compressor_from_an_Industrial_Refrigeration_System.jpg"}, {"id": "comp_1", "cat": "pieza", "keys": ["comp"], "les": ["b5"], "t": ["Compresor hermético pequeño", "Konpresore hermetiko txikia"], "d": ["Compresor de un frigorífico o de un equipo pequeño: motor y compresor van soldados dentro de la misma carcasa y no se pueden abrir.", "Hozkailu edo ekipo txiki bateko konpresorea: motorra eta konpresorea karkasa beraren barruan soldatuta doaz eta ezin dira ireki."], "img": "data:image/jpeg;base64,", "author": "ErRizzo", "lic": "CC BY 4.0", "url": "https://commons.wikimedia.org/wiki/File%3ANecchi-Americold_M2010_fridge_compressor.jpg"}, {"id": "cond_1", "cat": "equipo", "keys": ["gc", "comp", "filtro"], "les": ["u1", "b6"], "t": ["Unidad condensadora abierta", "Kondentsazio-unitatea irekita"], "d": ["Equipo pequeño de cámara: compresor hermético, condensador con ventilador, presostato y filtro secador (el cilindro blanco).", "Ganbera-ekipo txikia: konpresore hermetikoa, kondentsadorea haizagailuarekin, presostatoa eta iragazki lehorgailua (zilindro zuria)."], "img": "data:image/jpeg;base64,", "author": "AnyNameWillExpire", "lic": "CC BY-SA 4.0", "url": "https://commons.wikimedia.org/wiki/File%3ACondensing_Unit.jpg"}, {"id": "cond_2", "cat": "equipo", "keys": ["comp", "gc"], "les": ["u1", "b11"], "t": ["Unidades condensadoras con compresores semiherméticos", "Kondentsazio-unitateak konpresore erdi-hermetikoekin"], "d": ["Unidades para cámaras frigoríficas: abajo los compresores semiherméticos y los manómetros; arriba los ventiladores del condensador.", "Hozkailu-ganberetarako unitateak: behean konpresore erdi-hermetikoak eta manometroak; goian kondentsadorearen haizagailuak."], "img": "data:image/jpeg;base64,", "author": "Mesadbal", "lic": "CC BY 4.0", "url": "https://commons.wikimedia.org/wiki/File%3ACold_Room_Condensing_Unit_-_Bitzer_Compressor.jpg"}, {"id": "evap_0", "cat": "pieza", "keys": ["evap", "evaps"], "les": ["u1"], "t": ["Evaporadores de cámara antes de montarlos", "Ganberako lurrungailuak muntatu aurretik"], "d": ["Evaporadores con sus ventiladores, junto a paneles y puertas de cámara frigorífica.", "Lurrungailuak bere haizagailuekin, hozkailu-ganberaren panelen eta ateen ondoan."], "img": "data:image/jpeg;base64,", "author": "Mesadbal", "lic": "CC BY 4.0", "url": "https://commons.wikimedia.org/wiki/File%3ACold_Room_Products_-_Mix_-_Door_-_Refrigeration_-_Evaporator_-_Panel.jpg"}, {"id": "evap_2", "cat": "equipo", "keys": ["evap", "evaps"], "les": ["u1", "m5"], "t": ["Cámara frigorífica con sus evaporadores", "Hozkailu-ganbera bere lurrungailuekin"], "d": ["Los evaporadores van colgados del techo y soplan el aire frío a lo largo de la cámara.", "Lurrungailuak sabaitik zintzilik doaz eta aire hotza ganberan zehar putz egiten dute."], "img": "data:image/jpeg;base64,", "author": "Ostar dcsf", "lic": "CC BY-SA 3.0", "url": "https://commons.wikimedia.org/wiki/File%3ACold_Room.jpg"}, {"id": "evap_3", "cat": "equipo", "keys": [], "les": ["m5", "u1"], "t": ["Puerta corredera de cámara frigorífica", "Hozkailu-ganberaren ate irristagarria"], "d": ["Las puertas de cámara cierran con juntas; en las de congelados el marco lleva resistencia para que la junta no se hiele.", "Ganberako ateak juntekin ixten dira; izoztuetakoetan markoak erresistentzia du junta izoz ez dadin."], "img": "data:image/jpeg;base64,", "author": "Mesadbal", "lic": "CC BY 4.0", "url": "https://commons.wikimedia.org/wiki/File%3ACold_Room_Door_-_Sliding_Door.jpg"}, {"id": "txv_2", "cat": "pieza", "keys": ["valv"], "les": ["b7", "m4"], "t": ["Válvula de expansión termostática montada", "Espantsio-balbula termostatikoa muntatuta"], "d": ["Se ve el cuerpo de la válvula y el tubo capilar enrollado que va al bulbo, que se fija a la salida del evaporador.", "Balbularen gorputza eta bulbora doan hodi kapilar kiribildua ikusten dira; bulboa lurrungailuaren irteeran finkatzen da."], "img": "data:image/jpeg;base64,", "author": "UL Ospala", "lic": "CC BY-SA 3.0", "url": "https://commons.wikimedia.org/wiki/File%3AVET_250px.jpg"}, {"id": "txv_3", "cat": "teoria", "keys": ["valv"], "les": ["b7", "m4"], "t": ["Esquema de una válvula termostática", "Balbula termostatiko baten eskema"], "d": ["El bulbo mide la salida del evaporador y empuja la membrana; el husillo ajusta el recalentamiento.", "Bulboak lurrungailuaren irteera neurtzen du eta mintza bultzatzen du; ardatzak gainberotzea doitzen du."], "img": "data:image/jpeg;base64,", "author": "Neurotronix", "lic": "CC BY-SA 4.0", "url": "https://commons.wikimedia.org/wiki/File%3AEsquema_VET.jpg"}, {"id": "txv_1", "cat": "teoria", "keys": ["valv"], "les": ["b7"], "t": ["Partes de la válvula termostática", "Balbula termostatikoaren zatiak"], "d": ["Diafragma, asiento, muelle de ajuste del recalentamiento, compensación externa y bulbo.", "Diafragma, eserlekua, gainberotzea doitzeko malgukia, kanpoko konpentsazioa eta bulboa."], "img": "data:image/jpeg;base64,", "author": "MasterTriangle12", "lic": "CC BY 4.0", "url": "https://commons.wikimedia.org/wiki/File%3AThermostatic_expansion_valve-es.png"}, {"id": "sol_5", "cat": "pieza", "keys": ["sol"], "les": ["b8", "e21"], "t": ["Válvula solenoide con su bobina", "Solenoide-balbula bere bobinarekin"], "d": ["La bobina (azul) va encima del cuerpo de la válvula. Con tensión abre el paso; sin tensión se cierra.", "Bobina (urdina) balbularen gorputzaren gainean doa. Tentsioarekin pasoa irekitzen du; tentsiorik gabe ixten da."], "img": "data:image/jpeg;base64,", "author": "InterCity(IC)", "lic": "CC BY-SA 4.0", "url": "https://commons.wikimedia.org/wiki/File%3AM%C3%A1gnesszelep.jpg"}, {"id": "sol_2", "cat": "teoria", "keys": ["sol"], "les": ["b8"], "t": ["Solenoide cerrada (sin tensión)", "Solenoidea itxita (tentsiorik gabe)"], "d": ["Sin corriente en la bobina, el muelle empuja el núcleo y tapa el paso.", "Bobinan korronterik gabe, malgukiak nukleoa bultzatzen du eta pasoa estaltzen du."], "img": "data:image/jpeg;base64,", "author": "User:Sparpo", "lic": "CC BY-SA 4.0", "url": "https://commons.wikimedia.org/wiki/File%3ASolenoid_Valve_Closed.png"}, {"id": "sol_3", "cat": "teoria", "keys": ["sol"], "les": ["b8"], "t": ["Solenoide abierta (con tensión)", "Solenoidea irekita (tentsioarekin)"], "d": ["Con corriente, la bobina levanta el núcleo y deja pasar el fluido.", "Korrontearekin, bobinak nukleoa altxatzen du eta fluidoa pasatzen uzten du."], "img": "data:image/jpeg;base64,", "author": "User:Sparpo", "lic": "CC BY-SA 4.0", "url": "https://commons.wikimedia.org/wiki/File%3ASolenoid_Valve_Open.png"}, {"id": "hx_2", "cat": "pieza", "keys": ["hx"], "les": ["f12"], "t": ["Intercambiador de placas", "Plaka-trukagailua"], "d": ["Muchas placas apretadas entre dos chapas: por un lado pasa un fluido y por el otro, el otro, sin mezclarse.", "Bi xaflaren artean estututako plaka asko: alde batetik fluido bat pasatzen da eta bestetik bestea, nahastu gabe."], "img": "data:image/jpeg;base64,", "author": "Gerritse at Dutch Wikipedia (Original text: Gerritse)", "lic": "CC BY-SA 3.0", "url": "https://commons.wikimedia.org/wiki/File%3APlatenwarmtewisselaar.jpg"}, {"id": "hx_0", "cat": "teoria", "keys": ["hx"], "les": ["f12"], "t": ["Esquema de un intercambiador de placas", "Plaka-trukagailu baten eskema"], "d": ["Las placas forman canales alternos para los dos fluidos.", "Plakek bi fluidoentzako kanal txandakatuak osatzen dituzte."], "img": "data:image/jpeg;base64,", "author": "Armchoir at Croatian Wikipedia", "lic": "Public domain", "url": "https://commons.wikimedia.org/wiki/File%3APlate_heat_exchanger_LS.JPG"}, {"id": "presos_0", "cat": "pieza", "keys": ["ePS", "presos"], "les": ["f8", "u3"], "t": ["Presostato doble de alta y baja", "Altuko eta baxuko presostato bikoitza"], "d": ["Un solo aparato con dos presostatos: el de baja controla o protege por baja presión y el de alta para el compresor si la presión sube demasiado.", "Bi presostato dituen aparatu bakarra: baxukoak presio baxuagatik kontrolatzen edo babesten du eta altukoak konpresorea gelditzen du presioa gehiegi igotzen bada."], "img": "data:image/jpeg;base64,", "author": "UL adrianed", "lic": "CC BY-SA 4.0", "url": "https://commons.wikimedia.org/wiki/File%3APRESOSTATO_ALTA-BAIXA.jpg"}, {"id": "presos_1", "cat": "pieza", "keys": ["ePS", "presos"], "les": ["u3"], "t": ["Presostato de baja", "Baxuko presostatoa"], "d": ["En la escala de delante se ajustan la presión de paro y el diferencial.", "Aurreko eskalan geldialdi-presioa eta diferentziala doitzen dira."], "img": "data:image/jpeg;base64,", "author": "UL adrianed", "lic": "CC BY-SA 4.0", "url": "https://commons.wikimedia.org/wiki/File%3APRESOSTATO_BAIXA.jpg"}, {"id": "presos_3", "cat": "pieza", "keys": ["presos"], "les": ["u3"], "t": ["Presostato por dentro", "Presostatoa barrutik"], "d": ["El muelle y la escala en bar con los que se ajusta a qué presión abre y cierra el contacto.", "Kontaktua zein presiotan ireki eta ixten den doitzeko malgukia eta bar-etako eskala."], "img": "data:image/jpeg;base64,", "author": "Sarah Adrita", "lic": "CC BY-SA 4.0", "url": "https://commons.wikimedia.org/wiki/File%3APressure_switch_1.jpg"}, {"id": "sonda_0", "cat": "elec", "keys": [], "les": ["e12"], "t": ["Termistor NTC", "NTC termistorea"], "d": ["La pieza que hay dentro de muchas sondas de temperatura: su resistencia baja cuando sube la temperatura.", "Tenperatura-zunda askoren barruan dagoen pieza: bere erresistentzia jaitsi egiten da tenperatura igotzen denean."], "img": "data:image/jpeg;base64,", "author": "Soumyapatra13", "lic": "CC BY-SA 4.0", "url": "https://commons.wikimedia.org/wiki/File%3ANTC_Thermistor.jpg"}, {"id": "sonda_2", "cat": "elec", "keys": [], "les": ["e12", "b25"], "t": ["Termistores NTC de varios tipos", "Hainbat motatako NTC termistoreak"], "d": ["Diferentes formatos de NTC. En las sondas de frío van encapsulados en una punta metálica o de plástico con su cable.", "NTC formatu desberdinak. Hotz-zundetan punta metaliko edo plastikozko batean kapsulatuta doaz bere kablearekin."], "img": "data:image/jpeg;base64,", "author": "José Carlos González Sánchez", "lic": "Public domain", "url": "https://commons.wikimedia.org/wiki/File%3ATermistor_perla.jpg"}, {"id": "sonda_1", "cat": "teoria", "keys": [], "les": ["e12"], "t": ["Curva de una NTC", "NTC baten kurba"], "d": ["Resistencia medida frente a la temperatura: cuanto más caliente, menos ohmios.", "Neurtutako erresistentzia tenperaturaren arabera: zenbat eta beroago, orduan eta ohm gutxiago."], "img": "data:image/jpeg;base64,", "author": "Giro720", "lic": "CC BY-SA 3.0 / CC BY 2.5", "url": "https://commons.wikimedia.org/wiki/File%3ANTC_resistance-temperature_curve.png"}, {"id": "mural_0", "cat": "equipo", "keys": ["svcs"], "les": ["b10"], "t": ["Murales de lácteos en un supermercado", "Esnekien muralak supermerkatu batean"], "d": ["Muebles abiertos de positiva con cortina de aire, alimentados por la central.", "Positiboko altzari irekiak aire-gortinarekin, zentralak elikatuak."], "img": "data:image/jpeg;base64,", "author": "Nielsoncaetanosalmeron", "lic": "CC BY 4.0", "url": "https://commons.wikimedia.org/wiki/File%3APublix_dairy_section.jpg"}, {"id": "mural_1", "cat": "equipo", "keys": ["svcs"], "les": ["b10"], "t": ["Vitrina de bebidas con puerta de cristal", "Edarien erakusmahaia kristalezko atearekin"], "d": ["Mueble enchufable: lleva su propio equipo de frío dentro, sin central.", "Entxufatzeko altzaria: bere hotz-ekipo propioa du barruan, zentralik gabe."], "img": "data:image/jpeg;base64,", "author": "Maksym Kozlenko", "lic": "CC BY-SA 4.0", "url": "https://commons.wikimedia.org/wiki/File%3AFridge_with_milk_products%2C_Singapore.jpg"}, {"id": "isla_0", "cat": "equipo", "keys": ["svcs"], "les": ["b10"], "t": ["Islas de congelados y murales de puertas", "Izoztuen uharteak eta ateak dituzten muralak"], "d": ["Supermercado vacío: a la derecha islas de congelados y a la izquierda murales con puertas de cristal.", "Supermerkatu hutsa: eskuinean izoztuen uharteak eta ezkerrean kristalezko ateak dituzten muralak."], "img": "data:image/jpeg;base64,", "author": "Dave Hitchborne", "lic": "CC BY-SA 2.0", "url": "https://commons.wikimedia.org/wiki/File%3ASomerfield%2C_Spilsby_-_geograph.org.uk_-_1424426.jpg"}, {"id": "isla_1", "cat": "equipo", "keys": ["svcs"], "les": ["b10"], "t": ["Pasillo de supermercado con congelados", "Supermerkatuko pasilloa izoztuekin"], "d": ["Muebles de negativa junto a la zona de carne. Todos van conectados a la central de la sala de máquinas.", "Negatiboko altzariak haragiaren gunearen ondoan. Guztiak makina-gelako zentralera konektatuta daude."], "img": "data:image/jpeg;base64,", "author": "MatthewHoobin", "lic": "CC0", "url": "https://commons.wikimedia.org/wiki/File%3AArea_with_freezer_displays_near_meat_and_poultry_section_and_product_aisles_in_Lotte_Plaza_Market%2C_Tampa%2C_Florida%2C_on_15_January_2025.jpg"}, {"id": "manif_1", "cat": "herr", "keys": ["gauges"], "les": ["h1", "h2"], "t": ["Analizador digital conectado", "Analizagailu digitala konektatuta"], "d": ["Latiguillo azul a la baja, rojo a la alta y amarillo al servicio, conectados a la unidad exterior de un equipo.", "Mahuka urdina baxura, gorria altura eta horia zerbitzura, ekipo baten kanpoko unitateari konektatuta."], "img": "data:image/jpeg;base64,", "author": "U.S. Air Force photo by Senior Airman Grace Turpin", "lic": "Public domain", "url": "https://commons.wikimedia.org/wiki/File%3A332nd_Expeditionary_CE_Squadron_HVAC-R_operations_%289305714%29.jpg"}, {"id": "manif_0", "cat": "herr", "keys": ["gauges"], "les": ["h1", "h2"], "t": ["Técnicos midiendo con el puente de manómetros", "Teknikariak manometro-zubiarekin neurtzen"], "d": ["Comprobación de presiones en un equipo de climatización.", "Presioen egiaztapena klimatizazio-ekipo batean."], "img": "data:image/jpeg;base64,", "author": "U.S. Air Force photo by Senior Airman Mark Colmenares", "lic": "Public domain", "url": "https://commons.wikimedia.org/wiki/File%3ACool_under_pressure-_386th_ECES_HVAC_technicians_in_action_%289047740%29.jpg"}, {"id": "manif_2", "cat": "herr", "keys": ["gauges"], "les": ["h2"], "t": ["Conectando latiguillos a las tomas de servicio", "Mahukak zerbitzu-hartuneetara konektatzen"], "d": ["Antes de conectar se comprueba que las llaves del analizador están cerradas.", "Konektatu aurretik analizagailuaren giltzak itxita daudela egiaztatzen da."], "img": "data:image/jpeg;base64,", "author": "U.S. Air Force AFCENT by Senior Airman Grace Turpin", "lic": "Public domain", "url": "https://commons.wikimedia.org/wiki/File%3A332nd_Expeditionary_CE_Squadron_HVAC-R_operations_%289305716%29.jpg"}, {"id": "vacpump_3", "cat": "herr", "keys": [], "les": ["h4", "h5", "b17"], "t": ["Bomba de vacío de paletas de dos etapas", "Bi etapako paleta-huts-ponpa"], "d": ["Bomba rotativa de aceite como las que se usan para hacer el vacío en circuitos frigoríficos. Hay que cambiarle el aceite a menudo.", "Hozte-zirkuituetan hutsa egiteko erabiltzen direnen moduko olio-ponpa birakaria. Olioa sarri aldatu behar zaio."], "img": "data:image/jpeg;base64,", "author": "Kitmondo Marketplace", "lic": "CC BY 2.0", "url": "https://commons.wikimedia.org/wiki/File%3AEdwards_E2M2_2-Stage_Rotary_Vane_Vacuum_Pump_%2815957733526%29.jpg"}, {"id": "vacpump_1", "cat": "teoria", "keys": [], "les": ["h4"], "t": ["Despiece de una bomba de vacío", "Huts-ponpa baten zatiak"], "d": ["Bomba, junta, acople de caucho y tornillos de ajuste al motor.", "Ponpa, junta, kautxuzko akoplamendua eta motorrerako doikuntza-torlojuak."], "img": "data:image/jpeg;base64,", "author": "Wichita1984", "lic": "CC BY-SA 4.0", "url": "https://commons.wikimedia.org/wiki/File%3AINTERIOR_DE_UNA_BOMBA_DE_VACIO.jpg"}, {"id": "botella_0", "cat": "herr", "keys": [], "les": ["h6", "b19"], "t": ["Botella de refrigerante recargable", "Hozgarri-botila birkargagarria"], "d": ["Para cargar por peso se pone sobre la báscula. Las botellas de recuperación no se llenan más del 80 %.", "Pisuz kargatzeko baskularen gainean jartzen da. Berreskuratze-botilak ez dira %80tik gora betetzen."], "img": "data:image/jpeg;base64,", "author": "Лобачев Владимир", "lic": "CC BY-SA 4.0", "url": "https://commons.wikimedia.org/wiki/File%3ARefillable_refrigerant_cylinder.png"}, {"id": "n2_0", "cat": "herr", "keys": [], "les": ["h8", "m6"], "t": ["Botella de nitrógeno con manorreductor", "Nitrogeno-botila presio-erreduktorearekin"], "d": ["El manorreductor baja la presión de la botella a la de prueba o a un caudal pequeño para soldar.", "Presio-erreduktoreak botilaren presioa proba-presiora edo soldatzeko emari txiki batera jaisten du."], "img": "data:image/jpeg;base64,", "author": "Sarathkumaran Ranganathan", "lic": "CC BY-SA 4.0", "url": "https://commons.wikimedia.org/wiki/File%3ANitrogen_cilinder.jpg"}, {"id": "n2_1", "cat": "herr", "keys": [], "les": ["h8", "m6"], "t": ["Regulador de nitrógeno", "Nitrogeno-erregulagailua"], "d": ["Dos manómetros: uno marca la presión de la botella y otro la de salida.", "Bi manometro: batek botilaren presioa markatzen du eta besteak irteerakoa."], "img": "data:image/jpeg;base64,", "author": "Rifleman 82", "lic": "Public domain", "url": "https://commons.wikimedia.org/wiki/File%3AGas_regulator.jpg"}, {"id": "pinza_0", "cat": "elec", "keys": ["meter"], "les": ["e7"], "t": ["Pinza amperimétrica", "Pintza amperemetrikoa"], "d": ["Mide la corriente sin cortar el cable. Con ella se comprueba el consumo de compresores y resistencias.", "Korrontea kablea moztu gabe neurtzen du. Harekin konpresoreen eta erresistentzien kontsumoa egiaztatzen da."], "img": "data:image/jpeg;base64,", "author": "K. Krallis SV1XV", "lic": "CC0", "url": "https://commons.wikimedia.org/wiki/File%3AClamp-on_ammeter.jpg"}, {"id": "poli_0", "cat": "elec", "keys": ["meter"], "les": ["e4", "e6"], "t": ["Polímetro digital", "Polimetro digitala"], "d": ["Mide tensión (V), resistencia (Ω) y continuidad. La resistencia siempre se mide sin tensión.", "Tentsioa (V), erresistentzia (Ω) eta jarraitutasuna neurtzen ditu. Erresistentzia beti tentsiorik gabe neurtzen da."], "img": "data:image/jpeg;base64,", "author": "Anselm Schüler", "lic": "CC BY-SA 4.0", "url": "https://commons.wikimedia.org/wiki/File%3AUT61D_digital_multimeter_front.jpg"}, {"id": "poli_1", "cat": "elec", "keys": ["meter"], "les": ["e4"], "t": ["Polímetro con sus puntas", "Polimetroa bere puntekin"], "d": ["Punta negra en COM y roja en V/Ω para medir tensión y resistencia.", "Punta beltza COM-en eta gorria V/Ω-n tentsioa eta erresistentzia neurtzeko."], "img": "data:image/jpeg;base64,", "author": "oomlout", "lic": "CC BY-SA 2.0", "url": "https://commons.wikimedia.org/wiki/File%3ADigital_Multimeter.jpg"}, {"id": "megger_0", "cat": "elec", "keys": [], "les": ["e11"], "t": ["Medidor de aislamiento antiguo", "Isolamendu-neurgailu zaharra"], "d": ["Megóhmetro de manivela. Los actuales son electrónicos, pero miden lo mismo: el aislamiento a tierra en megaohmios.", "Bira-eskuneko megaohmetroa. Gaur egungoak elektronikoak dira, baina gauza bera neurtzen dute: lurrarekiko isolamendua megaohmetan."], "img": "data:image/jpeg;base64,", "author": "Liftarn", "lic": "CC BY-SA 3.0", "url": "https://commons.wikimedia.org/wiki/File%3AInsulationTester.jpg"}, {"id": "abocardar_0", "cat": "trabajo", "keys": [], "les": ["m7"], "t": ["Herramienta de abocardar", "Abokardatzeko tresna"], "d": ["El tubo se aprieta en la regleta y el cono forma el abocardado.", "Hodia regletan estutzen da eta konoak abokardatua egiten du."], "img": "data:image/jpeg;base64,", "author": "Münchner Kältetechnik", "lic": "CC0", "url": "https://commons.wikimedia.org/wiki/File%3AB%C3%B6rdelger%C3%A4t.jpg"}, {"id": "abocardar_1", "cat": "trabajo", "keys": [], "les": ["m7"], "t": ["Tubo abocardado con su tuerca", "Hodi abokardatua bere azkoinarekin"], "d": ["La tuerca se mete en el tubo antes de abocardar. Luego se aprieta con llave dinamométrica.", "Azkoina hodian sartzen da abokardatu aurretik. Gero giltza dinamometrikoarekin estutzen da."], "img": "data:image/jpeg;base64,", "author": "Mortezarahimi3rd", "lic": "CC BY-SA 4.0", "url": "https://commons.wikimedia.org/wiki/File%3AFlare_Fitting_2.jpg"}, {"id": "abocardar_2", "cat": "teoria", "keys": [], "les": ["m7"], "t": ["Corte de una unión abocardada", "Lotura abokardatu baten ebakidura"], "d": ["La cara cónica del tubo hace de junta contra el racor: no lleva junta de goma.", "Hodiaren aurpegi konikoak junta-lana egiten du errakorraren kontra: ez du gomazko juntarik."], "img": "data:image/jpeg;base64,", "author": "LaurensvanLieshout", "lic": "CC BY-SA 3.0", "url": "https://commons.wikimedia.org/wiki/File%3AFlare_koppeling.png"}, {"id": "cortatubos_0", "cat": "trabajo", "keys": [], "les": ["m6", "b16"], "t": ["Cortatubos en un tubo de cobre", "Hodi-ebakigailua kobrezko hodi batean"], "d": ["Se gira alrededor del tubo apretando poco a poco. Después se quita la rebaba con el escariador.", "Hodiaren inguruan biratzen da pixkanaka estutuz. Gero bizarra zabalgailuarekin kentzen da."], "img": "data:image/jpeg;base64,", "author": "Tomwsulcer", "lic": "CC0", "url": "https://commons.wikimedia.org/wiki/File%3ATube_cutter_cutting_three_fourths_inch_copper_pipe.jpg"}, {"id": "soldar_2", "cat": "trabajo", "keys": [], "les": ["m6", "b16"], "t": ["Soldando tubo de cobre con soplete", "Kobrezko hodia sopletearekin soldatzen"], "d": ["En frío se suelda con soldadura fuerte (varilla de plata) y pasando nitrógeno por dentro para que no se forme cascarilla.", "Hotzean soldadura gogorrarekin (zilarrezko hagaxka) soldatzen da eta barrutik nitrogenoa pasatuz ezkatarik sor ez dadin."], "img": "data:image/jpeg;base64,", "author": "U.S. Navy photo", "lic": "Public domain / PDM", "url": "https://commons.wikimedia.org/wiki/File%3AUS_Navy_060528-N-1332Y-022_Hull_Maintenance_Technician_Fireman_Bob_Chambers_uses_a_brazing_torch_to_weld_a_one-and-a-half-inch_copper-nickel_pipe_in_the_pipe_shop_aboard_USS_Kitty_Hawk_%28CV_63%29.jpg"}, {"id": "soldar_1", "cat": "trabajo", "keys": [], "les": ["m6"], "t": ["Equipo de soldadura fuerte", "Soldadura gogorreko ekipoa"], "d": ["Soplete, varillas, decapante, gafas de protección y mascarilla.", "Sopletea, hagaxkak, desugergarria, babes-betaurrekoak eta maskara."], "img": "data:image/jpeg;base64,", "author": "Phil Gradwell from Culcheth, England", "lic": "CC BY 2.0", "url": "https://commons.wikimedia.org/wiki/File%3ABrazing_Equipment.jpg"}, {"id": "soldar_0", "cat": "trabajo", "keys": [], "les": ["m6"], "t": ["Soplete calentando una unión", "Sopletea lotura bat berotzen"], "d": ["Se calienta la unión de forma uniforme antes de aportar la varilla.", "Lotura modu uniformean berotzen da hagaxka gehitu aurretik."], "img": "data:image/jpeg;base64,", "author": "neffk (talk)", "lic": "CC BY 2.0", "url": "https://commons.wikimedia.org/wiki/File%3APropane_torch_soldering_copper_pipe.jpg"}, {"id": "aislam_1", "cat": "trabajo", "keys": ["asp"], "les": ["m8", "b16"], "t": ["Tubos de cobre con y sin aislamiento", "Kobrezko hodiak isolamenduarekin eta gabe"], "d": ["Las tuberías frías se aíslan enteras para que no condensen agua ni pierdan frío.", "Hodi hotzak osorik isolatzen dira ura kondentsa ez dezaten eta hotza gal ez dezaten."], "img": "data:image/jpeg;base64,", "author": "Achim Hering", "lic": "CC BY 3.0", "url": "https://commons.wikimedia.org/wiki/File%3ACopper_pipes_with_and_without_fibreglass_insulation_asj.jpg"}, {"id": "aislam_0", "cat": "trabajo", "keys": ["asp"], "les": ["m8"], "t": ["Líneas frigoríficas aisladas", "Hozte-lerro isolatuak"], "d": ["Tubos aislados con coquilla entre las unidades exteriores y el edificio.", "Koskarekin isolatutako hodiak kanpoko unitateen eta eraikinaren artean."], "img": "data:image/jpeg;base64,", "author": "Achim Hering", "lic": "CC BY 3.0", "url": "https://commons.wikimedia.org/wiki/File%3AAir_conditioner_armaflex_insulation.jpg"}, {"id": "contactor_0", "cat": "elec", "keys": ["eKM", "eKMc"], "les": ["e2", "b22"], "t": ["Contactor desmontado", "Kontaktorea desmuntatuta"], "d": ["Bobina, armadura móvil, muelle de retorno, contactos principales y auxiliares.", "Bobina, armadura mugikorra, itzulera-malgukia, kontaktu nagusiak eta laguntzaileak."], "img": "data:image/jpeg;base64,", "author": "Saguzar1", "lic": "CC0", "url": "https://commons.wikimedia.org/wiki/File%3ADespiece_contactor.jpg"}, {"id": "contactor_1", "cat": "elec", "keys": ["eKM"], "les": ["e2", "e15"], "t": ["Contactor en carril DIN", "Kontaktorea DIN errailean"], "d": ["Arriba los bornes de entrada y abajo los de salida al motor; A1-A2 son los de la bobina.", "Goian sarrera-borneak eta behean motorrerako irteerakoak; A1-A2 bobinarenak dira."], "img": "data:image/jpeg;base64,", "author": "Kae", "lic": "CC BY-SA 3.0", "url": "https://commons.wikimedia.org/wiki/File%3AContactor_DIN_IEK.jpg"}, {"id": "contactor_3", "cat": "elec", "keys": ["eKM"], "les": ["e16"], "t": ["Contactos de un contactor quemados", "Kontaktore baten kontaktu erreak"], "d": ["Así quedan los contactos después de mucho tiempo con arranques continuos o bornes flojos.", "Horrela geratzen dira kontaktuak denbora luzez abiarazte jarraituekin edo borne lasaiekin."], "img": "data:image/jpeg;base64,", "author": "Asurnipal", "lic": "CC BY-SA 4.0", "url": "https://commons.wikimedia.org/wiki/File%3ABurned_Contactor-01ASD.jpg"}, {"id": "guardamotor_0", "cat": "elec", "keys": ["eQ1"], "les": ["e2", "e10"], "t": ["Guardamotor y su símbolo", "Motor-babeslea eta bere ikurra"], "d": ["Protege el motor contra sobrecargas y cortocircuitos; se ajusta a la intensidad de la placa.", "Motorra gainkargen eta zirkuitulaburren aurka babesten du; plakako intentsitatera doitzen da."], "img": "data:image/jpeg;base64,", "author": "Dmitry G", "lic": "CC BY-SA 3.0", "url": "https://commons.wikimedia.org/wiki/File%3AMotor_protective_circuit_breaker_with_symbol.JPG"}, {"id": "guardamotor_1", "cat": "elec", "keys": ["eQ1"], "les": ["e2"], "t": ["Guardamotor con rueda de ajuste", "Motor-babeslea doikuntza-gurpilarekin"], "d": ["La rueda marca el margen de corriente (en amperios) en el que se ajusta.", "Gurpilak doitzen den korronte-tartea (amperetan) markatzen du."], "img": "data:image/jpeg;base64,", "author": "No machine-readable author provided. Fluppe37 assumed (based on copyright claims).", "lic": "CC0", "url": "https://commons.wikimedia.org/wiki/File%3AMCB_GV2ME08.jpg"}, {"id": "fusible_0", "cat": "elec", "keys": ["eF1"], "les": ["e2", "e6"], "t": ["Portafusibles seccionable en carril DIN", "Fusible-euskarri seksionagarria DIN errailean"], "d": ["Se abre para cambiar el fusible o para cortar el circuito de mando.", "Fusiblea aldatzeko edo agintzirkuitua mozteko irekitzen da."], "img": "data:image/jpeg;base64,", "author": "Dmitry G", "lic": "CC BY-SA 3.0", "url": "https://commons.wikimedia.org/wiki/File%3AFuse_disconnector_for_DIN_rail.JPG"}, {"id": "variador_0", "cat": "elec", "keys": [], "les": ["e14", "f15"], "t": ["Variador de frecuencia", "Maiztasun-bihurgailua"], "d": ["Cambia los hercios que llegan al motor para que el compresor gire más o menos rápido.", "Motorrera iristen diren hertzak aldatzen ditu konpresoreak azkarrago edo motelago bira dezan."], "img": "data:image/jpeg;base64,", "author": "Rahat (Talk * Contributions) 11:43, 6 April 2015 (UTC)", "lic": "CC BY-SA 4.0", "url": "https://commons.wikimedia.org/wiki/File%3AVariable_frequency_drive.jpg"}, {"id": "variador_1", "cat": "elec", "keys": [], "les": ["e14"], "t": ["Variador de frecuencia compacto", "Maiztasun-bihurgailu trinkoa"], "d": ["En su pantalla se leen la frecuencia y los códigos de error cuando falla.", "Bere pantailan maiztasuna eta errore-kodeak irakurtzen dira huts egiten duenean."], "img": "data:image/jpeg;base64,", "author": "C J Cowie", "lic": "CC BY-SA 3.0", "url": "https://commons.wikimedia.org/wiki/File%3ASmall_variable-frequency_drive.jpg"}, {"id": "cuadro_1", "cat": "elec", "keys": ["elec"], "les": ["e2"], "t": ["Cuadro eléctrico de maniobra", "Maniobra-koadro elektrikoa"], "d": ["Magnetotérmicos, bornes, cableado y pulsadores con pilotos dentro de un armario eléctrico.", "Magnetotermikoak, borneak, kableatua eta argi pilotudun pultsadoreak armairu elektriko baten barruan."], "img": "data:image/jpeg;base64,", "author": "Shixart1985", "lic": "CC BY 2.0", "url": "https://commons.wikimedia.org/wiki/File%3AControl_panel_with_electrical_components_and_buttons.jpg"}, {"id": "ciclo_3", "cat": "teoria", "keys": [], "les": ["b4"], "t": ["El ciclo frigorífico", "Hozte-zikloa"], "d": ["Evaporador, compresor, condensador y válvula de expansión: el refrigerante da vueltas sin parar.", "Lurrungailua, konpresorea, kondentsadorea eta espantsio-balbula: hozgarriak etengabe ematen ditu bueltak."], "img": "data:image/jpeg;base64,", "author": "National Institute of Standards and Technology", "lic": "CC BY 4.0", "url": "https://commons.wikimedia.org/wiki/File%3ARefrigeration_%285888007815%29-es.png"}, {"id": "co2_0", "cat": "teoria", "keys": [], "les": ["f3"], "t": ["CO₂ cerca de su punto crítico", "CO₂-a bere puntu kritikotik gertu"], "d": ["Tubo de vidrio con CO₂: cerca de 31 °C y 74 bar desaparece la separación entre líquido y gas.", "CO₂-dun beirazko hodia: 31 °C eta 74 bar inguruan likidoaren eta gasaren arteko bereizketa desagertzen da."], "img": "data:image/jpeg;base64,", "author": "Critical_carbon_dioxide.jpg: Bernhard Kuemel derivative work: Regi51", "lic": "CC BY-SA 2.0 at", "url": "https://commons.wikimedia.org/wiki/File%3ACritical_carbon_dioxide-2.jpg"}, {"id": "co2_3", "cat": "equipo", "keys": [], "les": ["b9"], "t": ["Depósito de CO₂ líquido", "CO₂ likidoaren biltegia"], "d": ["El CO₂ se transporta y almacena líquido a presión. En las instalaciones se carga desde botellas o depósitos así.", "CO₂-a likido-egoeran garraiatu eta biltegiratzen da presiopean. Instalazioetan horrelako botila edo biltegietatik kargatzen da."], "img": "data:image/jpeg;base64,", "author": "Whoisjohngalt", "lic": "CC BY-SA 4.0", "url": "https://commons.wikimedia.org/wiki/File%3AA_container_of_liquid_carbon_dioxide.jpg"}, {"id": "scroll_0", "cat": "teoria", "keys": [], "les": ["b5"], "t": ["Cómo comprime un scroll (animación)", "Scroll batek nola konprimatzen duen (animazioa)"], "d": ["Una espiral fija y otra que se mueve: el gas queda atrapado y se va comprimiendo hacia el centro.", "Espiral finko bat eta mugitzen den beste bat: gasa harrapatuta geratzen da eta erdirantz konprimitzen doa."], "img": "data:image/gif;base64,", "author": "Cacycle", "lic": "Public domain / CC BY-SA 3.0 / CC BY-SA 2.5", "url": "https://commons.wikimedia.org/wiki/File%3ATwo_moving_spirals_scroll_pump.gif"}, {"id": "pinza_2", "cat": "elec", "keys": ["meter"], "les": ["e7"], "t": ["Pinza amperimétrica midiendo un cable", "Pintza amperemetrikoa kable bat neurtzen"], "d": ["La pinza se cierra alrededor de un solo conductor. Si abrazas fase y neutro juntos, marca 0.", "Pintza eroale bakar baten inguruan ixten da. Fasea eta neutroa batera hartzen badituzu, 0 markatzen du."], "img": "data:image/jpeg;base64,", "author": "INSA-4GP-gr6", "lic": "CC BY-SA 4.0", "url": "https://commons.wikimedia.org/wiki/File%3APince_amp%C3%A8rm%C3%A9trique.jpg"}, {"id": "n_screw_0", "cat": "pieza", "keys": [], "les": ["in4"], "t": ["Rotores de un compresor de tornillo", "Torloju-konpresore baten errotoreak"], "d": ["Los dos rotores helicoidales (macho y hembra) comprimen el gas al girar engranados. Entre ellos y la carcasa se inyecta aceite para sellar, enfriar y lubricar.", "Bi errotore helikoidalek (arra eta emea) gasa konprimitzen dute elkarri lotuta biratzean. Haien eta karkasaren artean olioa injektatzen da zigilatzeko, hozteko eta lubrifikatzeko."], "img": "data:image/jpeg;base64,", "author": "Motorhead at English Wikipedia", "lic": "CC BY-SA 2.5", "url": "https://commons.wikimedia.org/wiki/File:Lysholm_screw_rotors.jpg"}, {"id": "n_evapc_0", "cat": "equipo", "keys": [], "les": ["in7"], "t": ["Condensadores evaporativos en una cubierta", "Kondentsadore lurrunkorrak estalki batean"], "d": ["Varios condensadores evaporativos en un tejado: arriba, los ventiladores; dentro, la batería que se moja con agua pulverizada. Necesitan tratamiento del agua y limpieza periódica por la legionela.", "Zenbait kondentsadore lurrunkor teilatu batean: goian, haizagailuak; barruan, ur ihinztatuarekin bustitzen den bateria. Ura tratatu eta aldizka garbitu behar dira legionelagatik."], "img": "data:image/jpeg;base64,", "author": "Patrick Mackie", "lic": "CC BY-SA 2.0", "url": "https://commons.wikimedia.org/wiki/File:Evaporative_condensers_at_Tate_Modern_-_geograph.org.uk_-_1955938.jpg"}, {"id": "n_chiller_0", "cat": "equipo", "keys": [], "les": ["ch1"], "t": ["Enfriadora de agua condensada por aire", "Airez kondentsatutako ur-hozgailua"], "d": ["Enfriadora en una cubierta: abajo, detrás de la rejilla, los compresores; arriba, las baterías del condensador con sus ventiladores. El agua fría va con una bomba a los fancoils del edificio.", "Hozgailua estalki batean: behean, saretaren atzean, konpresoreak; goian, kondentsadorearen bateriak haizagailuekin. Ur hotza ponpa batekin eraikineko fancoiletara doa."], "img": "data:image/jpeg;base64,", "author": "Saud", "lic": "CC BY-SA 4.0", "url": "https://commons.wikimedia.org/wiki/File:Air_Cooled_Liquid_Chiller.jpg"}, {"id": "n_txv_0", "cat": "pieza", "keys": [], "les": ["mq10"], "t": ["Válvula de expansión termostática en corte", "Hedapen-balbula termostatikoa ebakita"], "d": ["El bulbo (izquierda) y su capilar llegan a la cabeza, donde la presión del bulbo empuja la membrana. La conexión pequeña de la derecha es el igualador externo. El refrigerante entra por la izquierda (flecha) y sale por la derecha.", "Bulboa (ezkerrean) eta bere kapilarra bururaino iristen dira; han bulboaren presioak mintza bultzatzen du. Eskuineko konexio txikia kanpo-berdingailua da. Hozgarria ezkerretik sartzen da (gezia) eta eskuinetik irteten da."], "img": "data:image/jpeg;base64,", "author": "Neurotronix", "lic": "CC BY-SA 4.0", "url": "https://commons.wikimedia.org/wiki/File:Thermostatic_Expansion_Valve_PHT.jpg"}, {"id": "n_ctower2_0", "cat": "equipo", "keys": [], "les": ["in7"], "t": ["Relleno de una torre de refrigeración", "Hozte-dorre baten betegarria"], "d": ["El agua cae sobre el relleno y una parte se evapora con el aire. El agua tibia y las gotitas son el sitio donde crece la legionela: por eso se trata el agua, se limpia y se revisan los separadores de gotas.", "Ura betegarriaren gainera erortzen da eta zati bat airearekin lurruntzen da. Ur epela eta tantatxoak dira legionela hazten den lekua: horregatik ura tratatzen da, garbitzen da eta tanta-bereizgailuak berrikusten dira."], "img": "data:image/jpeg;base64,", "author": "SAF", "lic": "CC BY-SA 4.0", "url": "https://commons.wikimedia.org/wiki/File:Cooling_Tower_Fill_Material.jpg"}, {"id": "n_pump_0", "cat": "pieza", "keys": [], "les": ["in3"], "t": ["Rodetes de bomba", "Ponpa-errotoreak"], "d": ["De izquierda a derecha, un rodete de flujo axial, uno mixto y dos centrífugos. Las bombas de refrigerante suelen ser centrífugas: el rodete lanza el líquido hacia fuera y la voluta convierte esa velocidad en presión.", "Ezkerretik eskuinera, fluxu axialeko errotore bat, misto bat eta bi zentrifugo. Hozgarri-ponpak zentrifugoak izan ohi dira: errotoreak likidoa kanpora jaurtitzen du eta bolutak abiadura hori presio bihurtzen du."], "img": "data:image/jpeg;base64,", "author": "Meisam", "lic": "CC BY-SA 3.0", "url": "https://commons.wikimedia.org/wiki/File:Pump_Impellers-1.jpg"}, {"id": "n_ice_0", "cat": "teoria", "keys": [], "les": ["k2"], "t": ["Hielo seco (CO₂ sólido)", "Izotz lehorra (CO₂ solidoa)"], "d": ["A presión atmosférica el CO₂ sólido está a −78 °C y pasa directamente a gas. En una instalación se forma si el CO₂ líquido baja de 5,2 bar absolutos: puede taponar válvulas y tubos.", "Presio atmosferikoan CO₂ solidoa −78 °C-tan dago eta zuzenean gas bihurtzen da. Instalazio batean CO₂ likidoa 5,2 bar absolututik behera jaisten bada sortzen da: balbulak eta hodiak buxa ditzake."], "img": "data:image/jpeg;base64,", "author": "Richard Wheeler (Zephyris) at en.wikipedia", "lic": "CC BY-SA 3.0", "url": "https://commons.wikimedia.org/wiki/File:Dry_Ice_Pellets_Subliming.jpg"}, {"id": "v_frigorifico", "cat": "video", "keys": [], "les": ["b4", "b2"], "t": ["Las piezas de un frigorífico, explicadas (en inglés)", "Hozkailu baten piezak, azalduta (ingelesez)"], "d": ["Dibuja el ciclo y luego lo enseña en un frigorífico real: compresor, condensador, capilar y evaporador. Aunque no entiendas el inglés, se sigue por la imagen.", "Zikloa marrazten du eta gero benetako hozkailu batean erakusten du: konpresorea, kondentsadorea, kapilarra eta lurrungailua. Ingelesa ulertu ez arren, irudiari jarraituz ulertzen da."], "video": "videos/frigorifico.webm", "img": "data:image/jpeg;base64,", "dur": "2:17", "author": "CPitaz108", "lic": "CC BY-SA 3.0", "url": "https://commons.wikimedia.org/wiki/File%3AIntroduction_to_the_Process_and_Components_of_a_Conventional_Refrigerator.ogv"}, {"id": "v_hervir_vacio", "cat": "video", "keys": [], "les": ["b2", "b17", "f10"], "t": ["El agua hierve a temperatura ambiente si bajas la presión", "Urak giro-tenperaturan irakiten du presioa jaisten baduzu"], "d": ["Al hacer el vacío, el agua del vaso hierve sin calentarla. Es lo mismo que hace el refrigerante en el evaporador y lo que pasa con la humedad cuando haces el vacío.", "Hutsa egitean, basoko urak irakiten du berotu gabe. Hozgarriak lurrungailuan egiten duen gauza bera da, eta hutsa egitean hezetasunarekin gertatzen dena."], "video": "videos/hervir_vacio.webm", "img": "data:image/jpeg;base64,", "dur": "0:27", "author": "Alejandro Garcia", "lic": "CC BY 3.0", "url": "https://commons.wikimedia.org/wiki/File%3AWater_Boiling_in_a_Vacuum_Chamber.webm"}, {"id": "v_scroll", "cat": "video", "keys": [], "les": ["b5"], "t": ["Animación de un compresor scroll", "Scroll konpresore baten animazioa"], "d": ["La espiral móvil gira sin dar vueltas sobre sí misma y empuja el gas hacia el centro, donde sale comprimido.", "Espiral mugikorrak bere buruari buelta eman gabe biratzen du eta gasa erdirantz bultzatzen du; han konprimituta ateratzen da."], "video": "videos/scroll.webm", "img": "data:image/jpeg;base64,", "dur": "0:20", "author": "Air Squared", "lic": "CC BY-SA 4.0", "url": "https://commons.wikimedia.org/wiki/File%3ASpinning_Scroll_Animation_looped.webm"}, {"id": "v_tornillo", "cat": "video", "keys": [], "les": ["b5"], "t": ["Animación de un compresor de tornillo", "Torloju-konpresore baten animazioa"], "d": ["Dos rotores engranan y el gas se comprime entre sus lóbulos. Se usan en potencias grandes.", "Bi errotorek engranatzen dute eta gasa haien lobuluen artean konprimitzen da. Potentzia handietan erabiltzen dira."], "video": "videos/tornillo.webm", "img": "data:image/jpeg;base64,", "dur": "0:09", "author": "Slashme", "lic": "CC BY-SA 4.0", "url": "https://commons.wikimedia.org/wiki/File%3AScrewCompressorCompression.webm"}, {"id": "v_ud_exterior", "cat": "video", "keys": [], "les": ["b6"], "t": ["Ventilador de una unidad exterior en marcha", "Kanpoko unitate baten haizagailua martxan"], "d": ["El ventilador saca el aire caliente a través del condensador. Si se para o la batería está sucia, sube la alta.", "Haizagailuak aire beroa kondentsadorearen bidez ateratzen du. Gelditzen bada edo bateria zikin badago, altua igotzen da."], "video": "videos/ud_exterior.webm", "img": "data:image/jpeg;base64,", "dur": "0:10", "author": "FASTILY", "lic": "CC BY-SA 4.0", "url": "https://commons.wikimedia.org/wiki/File%3AAir_conditioner_1_2019-09-13.webm"}, {"id": "v_tecnico_hvacr", "cat": "video", "keys": [], "les": ["b12", "e4"], "t": ["Un día de trabajo de un técnico de frío y clima (en inglés)", "Hotz eta klima teknikari baten lanegun bat (ingelesez)"], "d": ["Técnicos revisando enfriadoras, midiendo en el cuadro eléctrico con el polímetro y trabajando con tubería.", "Teknikariak hozgailuak berrikusten, koadro elektrikoan polimetroarekin neurtzen eta hodiekin lanean."], "video": "videos/tecnico_hvacr.webm", "img": "data:image/jpeg;base64,", "dur": "1:00", "author": "U.S. Navy AFN-T by Airman 1st Class Ferald Isidore Jude Dublado", "lic": "Public domain", "url": "https://commons.wikimedia.org/wiki/File%3AHVAC-R_Craftsman_Spotlight_%281019906%29.webm"}];

// ================= Fotos y vídeos reales (Wikimedia Commons, licencias libres) =================
// MEDIA viene de media_data.js: {id,cat,keys,les,t:[es,eu],d:[es,eu],img,author,lic,url,video,dur}
const MDL=(es,eu)=>(typeof LANG!=='undefined'&&LANG==='eu')?eu:es;
const MDT=o=>Array.isArray(o)?MDL(o[0],o[1]):o;
const MCAT={pieza:['Piezas del circuito','Zirkuituaren piezak'],equipo:['Centrales, muebles y cámaras','Zentralak, altzariak eta ganberak'],herr:['Herramientas del frigorista','Hozkilariaren tresnak'],elec:['Electricidad','Elektrizitatea'],trabajo:['Trabajos de montaje','Muntaketa-lanak'],teoria:['Esquemas y teoría','Eskemak eta teoria'],video:['Vídeos','Bideoak']};
const mdById=id=>MEDIA.find(m=>m.id===id);
function mdFor(keys,les){ const out=[]; MEDIA.forEach(m=>{ if(m.video) return; if((les&&m.les&&m.les.includes(les))||(m.keys||[]).some(k=>keys.includes(k))) out.push(m); }); return out.slice(0,6); }
// ---------- visor a pantalla completa
let MDLB=null;
function mdOpen(list,i){ mdClose(); MDLB={list,i}; const o=document.createElement('div'); o.className='md-lb'; o.setAttribute('role','dialog'); o.setAttribute('aria-modal','true'); document.body.appendChild(o); mdShow(); o.addEventListener('click',e=>{ if(e.target===o||e.target.closest('[data-md=x]')) mdClose(); else if(e.target.closest('[data-md=p]')) mdStep(-1); else if(e.target.closest('[data-md=n]')) mdStep(1); }); }
function mdShow(){ const o=document.querySelector('.md-lb'); if(!o||!MDLB) return; const m=MDLB.list[MDLB.i], n=MDLB.list.length;
  const media=m.video?`<video controls autoplay playsinline preload="metadata" ${m.img?`poster="${m.img}"`:''}><source src="${m.video}" type="video/webm"></video><p class="md-vmiss" hidden>${MDL('No encuentro el vídeo. Tiene que estar en la carpeta «videos», junto al programa (simulador.html).','Ez dut bideoa aurkitzen. «videos» karpetan egon behar du, programaren ondoan (simulador.html).')}</p>`:`<img src="${m.img}" alt="${MDT(m.t)}">`;
  o.innerHTML=`<figure class="md-fig"><button class="md-x" data-md="x" aria-label="${MDL('Cerrar','Itxi')}">✕</button>${media}<figcaption><b>${MDT(m.t)}</b>${m.d?`<p>${MDT(m.d)}</p>`:''}<small>${MDL('Autor','Egilea')}: ${m.author||'—'} · ${m.lic} · <a href="${m.url}" target="_blank" rel="noopener">Wikimedia Commons</a></small></figcaption>${n>1?`<button class="md-nav p" data-md="p" aria-label="${MDL('Anterior','Aurrekoa')}">‹</button><button class="md-nav n" data-md="n" aria-label="${MDL('Siguiente','Hurrengoa')}">›</button><span class="md-cnt">${MDLB.i+1} / ${n}</span>`:''}</figure>`;
  const v=o.querySelector('video'); if(v) v.addEventListener('error',()=>{ o.querySelector('.md-vmiss').hidden=false; },true); }
function mdStep(d){ if(!MDLB) return; MDLB.i=(MDLB.i+d+MDLB.list.length)%MDLB.list.length; mdShow(); }
function mdClose(){ const o=document.querySelector('.md-lb'); if(o){ const v=o.querySelector('video'); if(v) v.pause(); o.remove(); } MDLB=null; }
document.addEventListener('keydown',e=>{ if(!MDLB) return; if(e.key==='Escape') mdClose(); else if(e.key==='ArrowLeft') mdStep(-1); else if(e.key==='ArrowRight') mdStep(1); });
const mdThumbs=list=>list.map((m,i)=>`<button class="md-th" data-mdi="${i}" title="${MDT(m.t)}"><img src="${m.img}" alt="${MDT(m.t)}" loading="lazy"></button>`).join('');
function mdRowHTML(list){ return `<div class="md-row"><span class="md-lbl">📷 ${MDL('Fotos reales','Benetako argazkiak')}</span><div class="md-ths">${mdThumbs(list)}</div></div>`; }
function mdBind(el,list){ el.querySelectorAll('[data-mdi]').forEach(b=>b.onclick=e=>{ e.stopPropagation(); mdOpen(list,+b.dataset.mdi); }); }
// ---------- en las lecciones (ventana de la lección)
(function(){ const p=$('trPanel'); if(!p) return; let busy=false; new MutationObserver(()=>{ if(busy||p.hidden||!TRN.L) return; if(p.querySelector('.md-row')) return; const txt=p.querySelector('.tr-txt,.tr-why'); if(!txt) return;
    const keys=[...new Set([...p.querySelectorAll('[data-hl]')].map(e=>e.dataset.hl))]; const list=mdFor(keys,TRN.L.id); if(!list.length) return;
    busy=true; const wrap=document.createElement('div'); wrap.innerHTML=mdRowHTML(list); const row=wrap.firstChild; const look=p.querySelector('.tr-look'); (look||txt).insertAdjacentElement('afterend',row); mdBind(row,list); busy=false; }).observe(p,{childList:true,subtree:true}); })();
// ---------- en las prácticas (al pulsar una pieza del dibujo)
const MDPOP={manif:{comp:['comp'],cond:['cond'],pump:['vacpump'],bot:['botella'],recup:['botella'],n2:['n2'],pinza:['pinza'],tdisp:['manif'],hoses:['manif'],pasp:['aislam'],pliq:['visor']},unit:{comp:['comp'],cond:['cond'],evap:['evap'],sol:['sol'],pres:['presos'],cam:['evap'],pipes:['aislam']}};
if(typeof tpPop==='function'){ const _tpPop=tpPop; tpPop=function(k,ev){ _tpPop(k,ev); const page=TP.L&&TP.L.page; const keys=(MDPOP[page]||{})[k]; if(!keys) return; const list=mdFor(keys); if(!list.length) return; const pop=document.querySelector('#tpTool .tp-pop'); if(!pop||pop.querySelector('.md-row')) return; pop.insertAdjacentHTML('beforeend',mdRowHTML(list.slice(0,4))); mdBind(pop,list.slice(0,4)); }; }
// ---------- galería
NAV.gal=false;
function renderGallery(main){ const w=pkEl2('div','md-gal'); const n=MEDIA.filter(m=>!m.video).length, nv=MEDIA.filter(m=>m.video).length;
  w.appendChild(pkEl2('div','sh-hero',`<small class="q1-eye">${MDL('Escuela de centrales','Zentralen eskola')}</small><h2>${MDL('Fotos y vídeos reales','Benetako argazkiak eta bideoak')}</h2><p>${MDL(`${n} fotos y ${nv} vídeos de piezas, herramientas y trabajos reales, para reconocerlos cuando los veas en una instalación. Pulsa una foto para verla en grande. Todas tienen licencia libre y vienen de Wikimedia Commons (abajo están los autores). Funcionan sin internet.`,`${n} argazki eta ${nv} bideo benetako pieza, tresna eta lanei buruz, instalazio batean ikusten dituzunean ezagutzeko. Sakatu argazki bat handian ikusteko. Guztiek lizentzia librea dute eta Wikimedia Commons-etik datoz (behean daude egileak). Internetik gabe dabiltza.`)}</p>`));
  Object.keys(MCAT).forEach(c=>{ const L=MEDIA.filter(m=>m.cat===c); if(!L.length) return; const s=pkEl2('section','md-sec',`<h3>${MDT(MCAT[c])}</h3>`); const g=pkEl2('div','md-grid');
    L.forEach((m,i)=>{ const b=pBtn('md-card'+(m.video?' vid':''),`<span class="md-im">${m.img?`<img src="${m.img}" alt="" loading="lazy">`:''}${m.video?`<i class="md-play">▶</i>`:''}</span><b>${MDT(m.t)}</b>${m.d?`<small>${MDT(m.d)}</small>`:''}${m.dur?`<em>${m.dur}</em>`:''}`,()=>mdOpen(L,i)); g.appendChild(b); });
    s.appendChild(g); w.appendChild(s); });
  if(MEDIA.some(m=>m.video)) w.appendChild(pkEl2('p','md-note',MDL('Los vídeos están en la carpeta «videos» que va junto al programa. Si copias el programa a otro ordenador, copia también esa carpeta.','Bideoak programaren ondoan doan «videos» karpetan daude. Programa beste ordenagailu batera kopiatzen baduzu, kopiatu karpeta hori ere.')));
  const cr=pkEl2('details','md-cred',`<summary>${MDL('Autores y licencias','Egileak eta lizentziak')} (${MEDIA.length})</summary><ul>${MEDIA.map(m=>`<li><b>${MDT(m.t)}</b> — ${m.author||'—'} · ${m.lic} · <a href="${m.url}" target="_blank" rel="noopener">${MDL('ficha original','jatorrizko fitxa')}</a></li>`).join('')}</ul><p>${MDL('Las fotos se han reducido de tamaño para el programa. Licencias CC BY / CC BY-SA: se pueden usar y compartir citando al autor y con la misma licencia.','Argazkiak txikitu egin dira programarako. CC BY / CC BY-SA lizentziak: erabili eta parteka daitezke egilea aipatuz eta lizentzia berarekin.')}</p>`);
  w.appendChild(cr); main.appendChild(w); }
function galOpen(){ if(typeof openStart==='function'&&$('start').hidden) openStart(); NAV.alone=false; stSel.mode='train'; TRN.view=null; NAV.gal=true; renderStart(); window.scrollTo(0,0); }
(function(){ const _rs=renderStart; renderStart=function(){ _rs.apply(this,arguments); const nav=document.querySelector('#stBody .sc-nav .sc-box'); if(nav&&!nav.querySelector('.sc-gal')){ const b=pBtn('sc-rep sc-gal'+(NAV.gal?' on':''),`📷 ${MDL('Fotos y vídeos reales','Benetako argazkiak eta bideoak')}`,galOpen); const rep=nav.querySelector('.sc-rep'); if(rep) rep.after(b); else nav.prepend(b); }
    if(NAV.gal&&stSel.mode==='train'&&!TRN.view){ const main=document.querySelector('#stBody .sc-main'); if(main){ main.innerHTML=''; renderGallery(main); } }
    // tarjeta en el inicio de la escuela
    const sh=document.querySelector('#stBody .sh-band,#stBody .sh'); if(!NAV.gal&&stSel.mode==='train'&&!TRN.view&&sh&&!document.querySelector('#stBody .md-promo')){ const c=pBtn('md-promo',`<span class="md-pi">📷</span><span><b>${MDL('Fotos y vídeos reales','Benetako argazkiak eta bideoak')}</b><small>${MDL('Piezas, herramientas y trabajos de verdad para reconocerlos en la instalación','Benetako piezak, tresnak eta lanak instalazioan ezagutzeko')}</small></span><span class="md-ar">→</span>`,galOpen); const band=document.querySelector('#stBody .sh-band'); (band||sh).insertAdjacentElement('afterend',c); }
}; })();
document.addEventListener('click',e=>{ const b=e.target.closest&&e.target.closest('#stBody .sc-nav button, #stBody .q1-top button'); if(b&&!b.classList.contains('sc-gal')) NAV.gal=false; },true);
// ---------- lecciones de teoría (página de prácticas sin ejercicio): dibujo + fotos a la izquierda; si no hay nada, sin hueco vacío
(function(){ if(typeof TOOLSIM==='undefined'||!TOOLSIM.mont) return; const r0=TOOLSIM.mont.render;
  TOOLSIM.mont.render=function(el,st){ r0.call(this,el,st); if(st.lay||st.spot) return; const L=TP.L; const list=L?mdFor([],L.id):[];
    const fig=list.map((m,i)=>`<figure class="tp-ph"><button data-mdi="${i}" title="${MDL('Ver grande','Handiago ikusi')}"><img src="${m.img}" alt="${MDT(m.t)}" loading="lazy"></button><figcaption><b>${MDT(m.t)}</b>${m.d?` ${MDT(m.d)}`:''}<small>${m.author||'—'} · ${m.lic} · Wikimedia Commons</small></figcaption></figure>`).join('');
    if(fig) el.insertAdjacentHTML('beforeend',`<div class="tp-phs"><p class="md-lbl">📷 ${MDL('Fotos reales','Benetako argazkiak')}</p>${fig}</div>`); mdBind(el,list);
    const has=!!(st.pic&&DR[st.pic])||!!fig, left=el.closest('.tp-left'), grid=el.closest('.tp-grid'); if(left) left.style.display=has?'':'none'; if(grid) grid.classList.toggle('tp-solo',!has);
    const dr=el.querySelector('.tr-dr'); if(dr&&!dr.innerHTML.trim()) dr.remove(); }; })();

// ===== idioma: selector en las pantallas de inicio y palabras clave en euskera =====
(function(){ const _rs=renderStart; renderStart=function(){ _rs.apply(this,arguments); document.querySelectorAll('#stBody .q1-top').forEach(h=>{ if(h.querySelector('.lang-sw')) return; h.appendChild(i18nToggle()); }); }; })();
if(I18N.on){
  // palabras del texto que marcan piezas en el esquema
  const EUW={hx:'plaka-trukagailu\\w*',sep:'olio-bereizgailu\\w*',gc:'gas-hozgailu\\w*|kondentsadore\\w*',rec:'biltegi\\w*|hartzaile\\w*|deposit\\w*',hpv:'goi-balbula\\w*|altuko balbula\\w*',fg:'gas flash\\w*',filtro:'iragazki\\w*',visor:'ikusgailu\\w*',gauges:'manometro\\w*',gHP:'presio altu\\w*',dis:'deskarga\\w*|isurketa\\w*',gco:'gas-hozgailuaren irteera\\w*',asp:'xurgapen\\w*|xurgatze\\w*',liq:'likido-lerro\\w*',sh:'gainberotze\\w*',valv:'espantsio-balbul\\w*|hedapen-balbul\\w*',sol:'solenoide\\w*',evap:'lurrungailu\\w*',comp:'konpresore\\w*',central:'kontrolagailu\\w*',thermo:'termostato\\w*',tparams:'termostatoaren parametro\\w*',sim:'kanpoko tenperatura\\w*',ph:'P-h diagram\\w*',log:'alarmen erregistro\\w*|alarmen zerrenda\\w*',reg:'erregistragailu\\w*',svcs:'altzari\\w*',
    eQ0:'seksionagailu\\w*|etengailu nagusi\\w*',eQ1:'motor-babesle\\w*',eKMc:'bobina\\w*',eKM:'kontaktore\\w*',eF1:'fusible\\w*',eR1:'errele\\w*',ePS:'presostato\\w*',eM:'motor\\w*',meter:'polimetro\\w*|pintza\\w*',elec:'koadro elektriko\\w*'};
  HLW.forEach(x=>{ const e=EUW[x[1]]; if(e) x[0]=new RegExp(e+'|'+x[0].source,'i'); });
  const EUL={pantalla:'pantaila',puerta:'ate',luz:'argi',impres:'inprima'}; Object.values(LNK).forEach(L=>L.forEach(x=>{ const s=x[0].source; Object.entries(EUL).forEach(([es,eu])=>{ if(s.includes(es)) x[0]=new RegExp(x[0].source+'|'+eu,x[0].flags); }); }));
}

init(); openStart();
